// CPC Transport Manager (Passenger) - Question bank
// Generado a partir de CPC-tests/*.txt. Se va ampliando tema a tema.
window.CPC_TEMAS = {
"02": { title: "Tema 2 - Business Law", questions: [
{q:"In contract law the term 'consideration' means:", options:["Each party must behave fairly to the other","The parties must take legal advice before entering into the contract","A 14-day period following the signing of a contract","A right or benefit accruing to each party from the contract"], correct:3, exp:"'Consideration' es uno de los 4 elementos esenciales de un contrato válido (oferta, aceptación, consideration, intención de crear relación legal). Significa que cada parte debe dar o recibir algo de valor a cambio de lo que promete la otra."},
{q:"Which of the following statements relating to a public limited company are correct? 1. Minimum of two directors. 2. Not necessary to appoint a company secretary. 3. All PLCs must have accounts externally audited. 4. Nominal share capital not less than €25,000. 5. Cannot begin business until a Trading Certificate is issued.", options:["2 and 3 only","1 and 4 only","1, 3 and 5 only","2, 3 and 4 only"], correct:2, exp:"Una PLC necesita mínimo 2 directores, debe auditar sus cuentas externamente, y no puede operar hasta que la CRO emita el Trading Certificate. La 2 es falsa (sí necesita Company Secretary)."},
{q:"Which of the following items of information must a limited company display on all its business letters?", options:["Authorised share capital","Name of the Company Secretary","Name of managing director","The address of the company's registered office"], correct:3, exp:"La ley exige mostrar nombre legal, número de registro y la dirección del domicilio social en toda la papelería comercial."},
{q:"Which items must be submitted to the Companies Registration Office when forming a limited company? 1. Statement of compliance 2. Statement of capital 3. Name of accountants 4. Memorandum of association 5. Articles of association 6. Corporation Tax registration.", options:["2, 3, 5","1, 4, 6","3, 4, 5, 6","1, 2, 4 and 5 only"], correct:3, exp:"Se presentan: declaración de cumplimiento, capital inicial, Memorandum y Articles. El nombre de contables y el alta de Corporation Tax no forman parte de la constitución."},
{q:"When satisfied that the requirements of the Companies Act 2014 have been met, the Companies Registration Office will issue a new company with:", options:["A memorandum of association","A certificate of incorporation","A prospectus","The articles of association"], correct:1, exp:"El Certificate of Incorporation confirma que la empresa existe legalmente — es su 'partida de nacimiento'."},
{q:"Which statements concerning private limited companies are correct? 1. Trading name ends with PLC. 2. Must be at least one director. 3. May invite public to buy shares. 4. May invite public to invest in debentures. 5. Trading name ends with Limited.", options:["2 and 4","2 and 5","1 and 3","1, 3 and 4"], correct:1, exp:"Una Ltd privada necesita solo 1 director y su nombre termina en 'Limited'. No puede ofrecer acciones ni debentures al público."},
{q:"In the event of a members voluntary winding up of a limited company, the directors must file with the Companies Registration Office a declaration of:", options:["Total debt","Bankruptcy","Solvency","Insolvency"], correct:2, exp:"Es una liquidación VOLUNTARIA porque la empresa puede pagar sus deudas — los directores firman una Declaration of Solvency."},
{q:"An operator advertises a vehicle at €8500 ono. Offers are received between €8000 and €8800. Legally, the operator:", options:["Must accept first offer of €8500","Can accept or reject any offer","Must accept first over €8500","Must accept highest offer"], correct:1, exp:"Un anuncio es una 'invitation to treat', no una oferta vinculante — el vendedor puede aceptar o rechazar libremente cualquier oferta."},
{q:"For a valid contract to exist, which of the following factors must be present?", options:["Verbal offer and written acceptance","Written offer and written acceptance","Written offer, acceptance, consideration","Offer, acceptance and consideration"], correct:3, exp:"Los 3 elementos esenciales son oferta, aceptación y consideration — no hace falta que sea por escrito."},
{q:"Under the Companies Act 2014, a private limited company:", options:["Is not permitted to offer either shares or debentures to the public for cash","May offer shares but not debentures to the public","May offer debentures but not shares","May offer both"], correct:0, exp:"Una Ltd privada tiene prohibido ofrecer al público tanto acciones como debentures a cambio de dinero."},
{q:"A partnership which is created to give members the benefit of limited liability must have:", options:["One general partner only","One limited partner only","One general partner and one limited partner","Two general and two limited"], correct:2, exp:"Una limited partnership necesita al menos un general partner (gestiona, responde con su patrimonio) y un limited partner (solo invierte)."},
{q:"The most common remedy for a breach of contract is:", options:["Damages","An injunction","Imprisonment","A fine"], correct:0, exp:"El remedio civil habitual por incumplimiento de contrato es 'damages' (indemnización económica)."},
{q:"When creating a limited company a statement confirming that shareholders have limited liability can be found in the company's:", options:["Certificate of Incorporation","Memorandum of Association","Statement of Capital","Articles of Association"], correct:3, exp:"Los Articles of Association recogen que la responsabilidad de los socios está limitada a lo invertido."},
{q:"A company's articles of association must contain details of which of the following? 1. Authorised share capital 2. Rules governing appointment of directors 3. Company registration number 4. Rights of shareholders at general meetings 5. Names of founding members.", options:["1 only","2 and 3","2 and 4 only","1, 3 and 5"], correct:2, exp:"Los Articles regulan cómo se nombran los directores y los derechos de voto de los socios en las juntas."},
{q:"Which position is required by a public limited company but is optional for a private limited company?", options:["Chief Executive Officer","Company Secretary","Company Director","Chairman of the board"], correct:1, exp:"Una PLC siempre necesita Company Secretary; en una Ltd pequeña puede ser más flexible."},
{q:"For how many years does the Companies Act require a limited company to maintain copies of their accounting records?", options:["3 years","5 years","6 years","10 years"], correct:2, exp:"El Companies Act 2014 exige conservar los registros contables 6 años."},
{q:"If directors deliberately set out to defraud creditors, they could face terms of imprisonment of up to 10 years. This criminal offence is known as:", options:["Insider trading","Reckless trading","Fraudulent trading","Breach of contract"], correct:2, exp:"'Fraudulent trading' es dirigir el negocio con intención deliberada de estafar a los acreedores."},
{q:"When distributing money raised by the disposal of assets during a liquidation, which of the following has the highest priority for payment?", options:["Unsecured debts","Liquidator's fees and expenses","Preferential debts (wages)","Fixed-Charge (secured) creditors"], correct:3, exp:"Orden de prelación: 1º acreedores con garantía real (fixed-charge), 2º gastos del liquidador, 3º deudas preferentes (salarios), 4º garantía flotante, 5º sin garantía."},
{q:"What is the main difference in the internal structure between a Sole Trader and a Limited Company?", options:["Sole traders must file accounts with the CRO","Sole traders have unlimited liability for business debts","Sole traders pay Corporation Tax","Sole traders must have a Memorandum of Association"], correct:1, exp:"El autónomo responde de las deudas con todo su patrimonio personal (responsabilidad ilimitada); en una Ltd los socios solo arriesgan lo invertido."},
{q:"At what point does a contract acceptance sent by post become legally complete?", options:["When the letter is received by the offeror","When the letter is read","On posting the letter","24 hours after posting"], correct:2, exp:"La 'postal rule': el contrato se perfecciona en el momento de echar la carta al correo, no cuando se recibe."},
{q:"Which group of people do not have full contractual capacity under Irish law?", options:["Company directors","People under 18 (minors)","Shareholders","Sole traders"], correct:1, exp:"Los menores de 18 años no tienen capacidad contractual plena — sus contratos son en general anulables."},
{q:"What is the key rule regarding dividend payments for ordinary and preference shares?", options:["Both are paid equally","Ordinary shareholders are paid first","Ordinary shareholders will not receive any dividend until preference shareholders have been paid","Preference shares do not receive dividends"], correct:2, exp:"Las preference shares tienen preferencia de cobro; los accionistas ordinarios solo cobran si sobra beneficio después."},
{q:"A Designated Activity Company (DAC) must:", options:["Have a minimum of 149 members","Only trade within the parameters of the designated activities listed in its objects clause","Have its name ending in PLC","Issue shares to the general public"], correct:1, exp:"Una DAC mantiene una cláusula de objeto social limitado, a diferencia de la Ltd normal (capacidad ilimitada)."},
{q:"When an external auditor examines a company's accounts, who is their primary duty towards?", options:["The directors","The company secretary","The Companies Registration Office","The shareholders"], correct:3, exp:"El deber principal del auditor es hacia los accionistas, para protegerlos de posibles irregularidades de los directores."},
{q:"What is the fundamental difference between a debenture holder and a shareholder?", options:["Debenture holders are paid interest, not dividends, and have no voting rights","Debenture holders own the company","Shareholders receive interest","Debenture holders vote at the AGM"], correct:0, exp:"Un debenture holder es un acreedor (le prestó dinero a la empresa), cobra interés fijo y no vota."},
{q:"If a shareholder cannot attend a general meeting, how can they legally pass their voting rights to someone else?", options:["By calling the company secretary","By appointing a proxy","By selling their shares","By emailing the director"], correct:1, exp:"Puede nombrar un 'proxy' (representante) mediante un formulario formal para votar en su nombre."},
{q:"Which type of company is legally obliged to hold an Annual General Meeting (AGM) each year?", options:["A sole trader","A partnership","A Public Limited Company (PLC)","A Private Limited Company"], correct:2, exp:"Las PLC están obligadas a celebrar AGM anual; muchas Ltd pequeñas pueden estar exentas si todos los socios lo acuerdan."},
{q:"At what stage is an offer no longer possible to withdraw?", options:["After 24 hours","After the offeree has accepted it","Once it is written down","Before the offeree reads it"], correct:1, exp:"Una oferta se puede retirar libremente antes de la aceptación; una vez aceptada, ya existe contrato vinculante."}
]},
"04": { title: "Tema 4 - Health and Safety", questions: [
{q:"When was the current general framework of health and safety legislation in Ireland introduced via the Safety, Health and Welfare at Work Act?", options:["1996","2005","2014","2020"], correct:1, exp:"La ley marco actual es de 2005 (sustituyó a la de 1989)."},
{q:"How many General Principles of Prevention form the central thrust of the Safety, Health and Welfare at Work Act 2005?", options:["5","7","9","12"], correct:2, exp:"Son 9 principios (evitar riesgos, evaluar los que no se pueden evitar, combatirlos en origen, etc.)."},
{q:"According to the general principles of prevention, what type of protective measures should be given priority over individual measures?", options:["Cost-effective measures","Temporary administrative measures","Collective protective measures","Emergency backup measures"], correct:2, exp:"La jerarquía de prevención prioriza medidas COLECTIVAS sobre las individuales (como el EPI)."},
{q:"What key qualifying phrase recurs throughout the 2005 Act regarding an employer's duty to ensure health and safety?", options:["As cheaply as possible","Without exception or delay","So far as is reasonably practicable","Subject to union approval"], correct:2, exp:"El empleador debe actuar 'en la medida en que sea razonablemente practicable', no de forma absoluta e ilimitada."},
{q:"What is the maximum number of employees an enterprise may have for the employer to use a Code of Practice as an alternative to a written safety statement?", options:["1","3","5","10"], correct:1, exp:"Empresas de hasta 3 empleados pueden usar un código de práctica simplificado en vez de un safety statement completo."},
{q:"Which of the following is a statutory right of a safety representative under the 2005 Act?", options:["To unilaterally alter company work schedules","To accompany a Health and Safety Authority Inspector on a site inspection","To impose financial fines on non-compliant colleagues","To hire and fire internal safety personnel"], correct:1, exp:"Puede acompañar al inspector de la HSA durante una inspección."},
{q:"If a Health and Safety Inspector serves an Improvement Plan on an employer, what is the maximum time allowed for the employer to respond with remedial measures?", options:["14 days","One month","Three months","Six months"], correct:1, exp:"El plazo máximo para responder a un Improvement Plan es de 1 mes."},
{q:"What is the legal distinction regarding an employer's duty of care under Irish health and safety law?", options:["Employers are only responsible for full-time permanent staff","Employers must protect their employees and other persons who may be affected by their work activities","Employers have no duty toward external contractors visiting a site","Employers are solely liable for public highways outside the depot"], correct:1, exp:"El deber de cuidado se extiende a cualquiera afectado por la actividad de la empresa, no solo a la plantilla."},
{q:"Which state body is explicitly responsible for the enforcement of workplace health and safety legislation in Ireland?", options:["Road Safety Authority (RSA)","Health and Safety Authority (HSA)","Workplace Relations Commission (WRC)","Environmental Protection Agency (EPA)"], correct:1, exp:"La HSA es el organismo estatal que hace cumplir la legislación de seguridad laboral."},
{q:"Within how many days must a non-fatal accident at work be reported if it disables the worker?", options:["1 day","3 days","10 days","30 days"], correct:2, exp:"Un accidente no mortal que incapacita al trabajador debe reportarse en 10 días."},
{q:"To which entities must a fatal workplace accident be reported immediately?", options:["The Revenue Commissioners and local council","The Gardaí and the Health and Safety Authority","The Department of Transport only","The Coroners Court and trade union representatives"], correct:1, exp:"Un accidente mortal se reporta de inmediato a la Garda y a la HSA."},
{q:"What is the minimum period of work incapacity required for a non-fatal workplace accident to become officially reportable?", options:["More than 1 consecutive day excluding the day of the accident","More than 3 consecutive days excluding the day of the accident","Exactly 5 consecutive days including the day of the accident","More than 7 consecutive days"], correct:1, exp:"Debe incapacitar más de 3 días consecutivos (sin contar el día del accidente) para ser reportable."},
{q:"What is the maximum fine a court can impose on an employer for serious health and safety breaches prosecuted on indictment?", options:["€100,000","€1 million","€3 million","€5 million"], correct:2, exp:"El tope legal para infracciones graves procesadas por acusación formal es €3 millones."},
{q:"At what continuous noise exposure action value must an employer provide personal hearing protectors and ensure they are worn?", options:["80 dB(A)","85 dB(A)","90 dB(A)","100 dB(A)"], correct:1, exp:"A partir de 85 dB(A) el empleador debe dar protección auditiva y asegurar que se use."},
{q:"How frequently must vehicle tail lifts or lifting equipment used to lift personnel undergo a thorough statutory examination?", options:["Every 3 months","Every 6 months","Annually","Every 2 years"], correct:1, exp:"Al usarse para elevar PERSONAS, la inspección exigida es cada 6 meses."},
{q:"How frequently must standard lifting equipment (like standard forklifts not carrying personnel) undergo a thorough examination and report?", options:["Every 3 months","Every 6 months","Annually","Every 3 years"], correct:2, exp:"El equipo de elevación de carga estándar (sin personas) se inspecciona anualmente."},
{q:"According to standard manual handling guidance tables for women, what is the maximum recommended weight limit at knuckle height close to the body?", options:["7 kg","10 kg","16 kg","25 kg"], correct:2, exp:"Límite recomendado a la altura de los nudillos, cerca del cuerpo, para mujeres: 16 kg."},
{q:"According to standard manual handling guidance tables for men, what is the maximum recommended weight limit at knuckle height close to the body?", options:["15 kg","20 kg","25 kg","30 kg"], correct:2, exp:"El mismo límite para hombres es 25 kg."},
{q:"What is the first foundational step when carrying out any structured risk assessment?", options:["Record the findings in writing","Identify potential hazards","Appoint an external auditor","Notify the HSA inspectors"], correct:1, exp:"Primero se identifican los peligros; solo después se evalúa el riesgo y se documenta."},
{q:"What is the legal definition of a 'hazard' in health and safety terminology?", options:["The mathematical probability that an accident will occur","Anything that can cause harm, such as chemicals, electricity, or working at height","The financial cost resulting from a workplace injury","An unexpected delay in transport delivery schedules"], correct:1, exp:"'Hazard' = cualquier cosa que pueda causar daño."},
{q:"What does 'risk' mean in the context of workplace safety assessments?", options:["The physical weight of materials being handled","The chance, high or low, that someone will actually be harmed by a hazard","The insurance premium paid by a transport company","The statutory penalty issued by the District Court"], correct:1, exp:"'Risk' = la probabilidad de que ese daño ocurra realmente."},
{q:"What enforcement notice can an HSA Inspector issue to demand the immediate cessation of a work activity involving risk of serious personal injury?", options:["Improvement Plan","Improvement Notice","Prohibition Notice","Advisory Warning Notice"], correct:2, exp:"El Prohibition Notice se usa para riesgo grave e inminente; el Improvement Notice da un plazo mínimo de 14 días."},
{q:"What is the minimum ambient air temperature required by workplace regulations for sedentary office work environments?", options:["15.0 °C","17.5 °C","20.0 °C","21.5 °C"], correct:1, exp:"Temperatura mínima para trabajo de oficina sedentario: 17.5°C."},
{q:"Where do Personal Protective Equipment (PPE) requirements rank in terms of hazard control methods?", options:["As the primary and preferred method of eliminating risk","As the absolute last line of defence when risks cannot otherwise be eliminated","As an optional administrative recommendation","As a substitute for safety statements"], correct:1, exp:"El EPI es siempre el último recurso, no el primero, en la jerarquía de control de riesgos."},
{q:"Which of the following regulatory areas specifically governs screen equipment in office administration, while excluding vehicle cab screens?", options:["Chemical Agents Regulations","Display Screen Equipment Regulations","Pressure Systems Regulations","Explosive Atmospheres Regulations"], correct:1, exp:"Display Screen Equipment Regulations cubre pantallas de oficina, no las de cabina de vehículo."},
{q:"Who carries primary responsibility for preparing and revising the company's safety statement?", options:["The Safety Representative","The Employer","The HSA Inspector","External trade union officials"], correct:1, exp:"El empleador es responsable de redactar y revisar el safety statement."},
{q:"How frequently must an employer review and bring the safety statement to the attention of employees?", options:["At least weekly","Every six months","At least annually, or when amended","Only after a fatal accident occurs"], correct:2, exp:"Debe revisarse al menos anualmente, o cuando se modifique."},
{q:"What are the legal responsibilities of employees under the Safety, Health and Welfare at Work Act 2005?", options:["Employees have no legal duties; safety is exclusively management's role","Take reasonable care for their own safety and cooperate with the employer","Fund all necessary PPE and medical checkups out of pocket","Conduct independent HSA prosecutions in the District Court"], correct:1, exp:"Los empleados deben cuidar razonablemente de su propia seguridad y cooperar con el empleador."},
{q:"What type of creditor or notice is issued when an inspector requires an employer to remedy a legislative contravention within a specified period (not less than 14 days)?", options:["Improvement Notice","Prohibition Notice","Statutory Liquidation Demand","Summary Indictment Warrant"], correct:0, exp:"El Improvement Notice da un plazo mínimo de 14 días para corregir el incumplimiento."},
{q:"Under the General Application Regulations, what specific document must employers maintain and consult regarding workplace chemical hazards?", options:["Commercial Invoice and Packing List","Safety Data Sheets (SDS) obtained from suppliers","Annual Corporation Tax returns","Vehicle tachograph calibration charts"], correct:1, exp:"Las Safety Data Sheets (SDS) del proveedor deben conservarse y consultarse."},
{q:"Which hazard is recognized as a major risk factor specifically concerning freight transport yards and depots?", options:["Interaction between moving heavy commercial vehicles and pedestrians","High-altitude atmospheric pressure changes","Sub-sea maritime navigation hazards","Commercial airline runway clearances"], correct:0, exp:"La interacción vehículos pesados-peatones es un riesgo mayor en patios y depósitos de carga."},
{q:"What control measure is strongly recommended in transport depots to minimize vehicle-pedestrian conflicts?", options:["Allowing unrestricted random foot traffic across parking bays","Implementing designated walkways and one-way traffic management systems","Removing all exterior yard lighting to save electricity","Banning high-visibility vests entirely"], correct:1, exp:"Se recomiendan pasillos peatonales señalizados y tráfico de sentido único."},
{q:"What is the primary objective of establishing a Safety Committee within a larger enterprise?", options:["To negotiate executive salary packages and bonuses","To review safety audit reports, study accident data, and develop safe systems of work","To handle direct commercial contract pricing with clients","To replace the legal authority of the Health and Safety Authority"], correct:1, exp:"El comité de seguridad revisa auditorías, estudia accidentes y desarrolla sistemas de trabajo seguros."},
{q:"Are occupational illnesses, mental health impairments, or diseases reportable under standard workplace accident reporting rules?", options:["Yes, they must be reported within 24 hours","No, they are not reportable under standard workplace injury report criteria","Yes, but only if they last more than 30 days","Only if certified by the Supreme Court"], correct:1, exp:"Las enfermedades ocupacionales no son reportables bajo los criterios estándar de accidente."},
{q:"What specialized medical check must an employer make available to workers exposed to noise levels exceeding upper exposure action values?", options:["Complete optical laser surgery","A hearing check carried out under the responsibility of a registered medical practitioner","Mandatory pulmonary lung function testing","Full orthopedic spinal realignment"], correct:1, exp:"Chequeo auditivo bajo responsabilidad de un médico colegiado."},
{q:"Which of the following is considered a primary duty of an employer regarding workplace welfare facilities?", options:["Providing luxury company vehicles for all staff members","Providing adequate washing facilities, toilets, and changing/locker rooms","Subsidizing private gym memberships outside working hours","Providing daily catered gourmet lunches"], correct:1, exp:"El empleador debe dar aseos, duchas y vestuarios adecuados."},
{q:"When must an employer review an existing risk assessment?", options:["Only once every ten years","On an ongoing basis, particularly following a serious accident or operational change","Never, once a safety statement is printed","Only when instructed in writing by company shareholders"], correct:1, exp:"Debe revisarse continuamente, sobre todo tras un accidente grave o cambio operativo."},
{q:"What are the requirements for emergency exits in workplaces under safety regulations?", options:["They must be securely locked from the outside to prevent theft","They must be kept unblocked, unlocked, and open outwards","They must be camouflaged for security purposes","They only need to be accessible during daytime shifts"], correct:1, exp:"Las salidas de emergencia deben estar sin obstáculos, sin llave y abrir hacia fuera."},
{q:"Under the Safety, Health and Welfare at Work Act, what right does a safety representative have following an accident or dangerous occurrence?", options:["To immediately inspect the scene, provided it does not disturb physical evidence before an HSA inspector arrives","To unilaterally issue criminal prosecution indictments","To seize company bank accounts for compensation","To dismiss the company director on the spot"], correct:0, exp:"Puede inspeccionar la escena de inmediato sin alterar pruebas antes de que llegue el inspector."},
{q:"What must an employer do if a chemical hazard in the workplace cannot be entirely eliminated?", options:["Ignore it if workers do not complain","Prevent exposure where possible, or reduce and adequately control it using proper measures","Increase room temperatures to evaporate the chemical","Rely solely on verbal warnings without safety data sheets"], correct:1, exp:"Debe prevenir la exposición donde sea posible, o reducirla y controlarla adecuadamente."},
{q:"Which of the following hazards is explicitly addressed under the 'Work at Height' regulations in the freight sector?", options:["Standard office desk configuration","Working on trailer beds for sheeting loads or accessing warehouse upper levels","Driving on flat asphalt motorways","Operating administrative computer terminals"], correct:1, exp:"Trabajar sobre la caja del tráiler o en niveles altos de almacén está cubierto por 'Work at Height'."},
{q:"What is the legal status of summary safety offences prosecuted by the HSA in the District Court?", options:["They deal with less serious offences carrying fines or summary penalties","They carry automatic life imprisonment sentences","They can only be initiated by the European Court of Justice","They bypass judicial review entirely"], correct:0, exp:"Son delitos menores con multas o sanciones sumarias."},
{q:"Who is legally authorized to initiate a prosecution on indictment for major health and safety offences in Ireland?", options:["Any individual employee on their own initiative","The Director of Public Prosecutions (DPP) or someone acting on their behalf","The local municipal town clerk","Private insurance corporate brokers"], correct:1, exp:"El DPP (Fiscal General) o alguien en su nombre inicia el procesamiento por acusación formal."},
{q:"What is a key requirement for employers regarding the communication of the safety statement to workers?", options:["It must be written in Latin and kept locked in a safe","It must be brought to employees' attention in a form, manner, and language reasonably likely to be understood","It only needs to be shown to retiring staff members","It is classified and restricted from general employee view"], correct:1, exp:"Debe comunicarse en forma, manera e idioma razonablemente comprensible."},
{q:"What training and time-off rights must an employer grant to a designated safety representative?", options:["Zero time off; training must occur entirely on unpaid weekends","Reasonable paid time off to acquire knowledge, train, and carry out safety representative functions","Mandatory full-time exemption from all operational duties permanently","Unpaid leave subject to company profitability"], correct:1, exp:"Tiempo libre remunerado razonable para formarse y ejercer sus funciones."},
{q:"Which of the following is an example of technical control for airborne noise reduction?", options:["Increasing vehicle engine RPM limits","Using shields, enclosures, and sound-absorbent coverings","Removing all building insulation","Eliminating rest breaks entirely"], correct:1, exp:"Pantallas, encapsulados y revestimientos absorbentes de sonido."},
{q:"What duty does an employer have regarding persons outside their direct employment (such as visitors or contractors)?", options:["Zero liability; visitors enter entirely at their own risk","To conduct operations so that other people are not exposed to health and safety risks","To employ them on permanent contracts immediately","To provide them with company shares"], correct:1, exp:"Debe operar de forma que otras personas no queden expuestas a riesgos."},
{q:"What must an employer provide free of charge to employees when workplace risks cannot be otherwise eliminated?", options:["Personal Protective Equipment (PPE) and proper maintenance","Personal commercial vehicles","Residential housing near the depot","Premium private healthcare insurance"], correct:0, exp:"El EPI y su mantenimiento deben darse gratis."},
{q:"What is a primary legal power of an HSA Inspector upon entering a workplace premises?", options:["To seize personal property unrelated to work","To order work areas to be left undisturbed, remove items, and interrogate persons","To manage corporate payroll accounts directly","To alter company directors' board voting rights"], correct:1, exp:"Puede ordenar que un área no se toque, retirar objetos y entrevistar a personas."},
{q:"Why must risk assessments always be formally recorded and documented?", options:["To increase administrative paperwork without practical purpose","To satisfy statutory requirements and prove that a diligent approach was taken to handle risks","To satisfy tax deduction quotas set by Revenue","To publish commercial secrets online for competitors"], correct:1, exp:"Para cumplir requisitos legales y demostrar diligencia en la gestión de riesgos."}
]},
"11": { title: "Tema 11 - Driver Hours and Records", questions: [
{q:"What international set of regulations governs drivers' hours for journeys outside the EU, aligned with EU Regulation 561/2006?", options:["The AETR Agreement","The Vienna Convention","The SEPA Framework","The Dublin Protocol"], correct:0, exp:"El acuerdo internacional AETR está alineado con el Reglamento 561/2006."},
{q:"Which passenger vehicles are generally exempt from EU Regulation 561/2006?", options:["All coaches seating more than 50 passengers","Passenger vehicles constructed or permanently adapted to carry not more than nine persons including the driver","Vehicles operating international regular services over 100 km","Double-decker buses used for city tours"], correct:1, exp:"Vehículos diseñados/adaptados para máximo 9 personas incluido el conductor están exentos."},
{q:"Under EU Regulation 561/2006, what is the maximum continuous or aggregated driving time permitted before a driver must take a break?", options:["3 hours","4 hours","4.5 hours","5.5 hours"], correct:2, exp:"4.5 horas de conducción continua/acumulada antes de un descanso obligatorio."},
{q:"What is the mandatory minimum duration of a break required after reaching the maximum driving limit under EU rules?", options:["15 minutes","30 minutes","45 minutes","60 minutes"], correct:2, exp:"El descanso mínimo obligatorio es de 45 minutos."},
{q:"How may a 45-minute EU driving break be split?", options:["Into two breaks: the first of at least 15 minutes and the second of at least 30 minutes","Into three equal 15-minute breaks","Into a 20-minute break and a 25-minute break","It cannot be split under any circumstances"], correct:0, exp:"Se divide como 15 min primero y 30 min después, en ese orden."},
{q:"What is the maximum permitted daily driving time under EU rules?", options:["8 hours","9 hours","10 hours","11 hours"], correct:1, exp:"Máximo de conducción diaria: 9 horas."},
{q:"On how many occasions per week may daily driving time be extended to 10 hours?", options:["Once per week","Twice per week","Three times per week","It can never be extended"], correct:1, exp:"Puede ampliarse a 10 horas hasta dos veces por semana."},
{q:"How does EU Regulation 561/2006 define the working week?", options:["From 00.00 hours on Monday to 24.00 hours on Sunday","Any rolling 7-day period","From Sunday midnight to Sunday midnight","A fixed 40-hour period determined by the employer"], correct:0, exp:"La semana va de las 00:00 del lunes a las 24:00 del domingo."},
{q:"What is the maximum permitted weekly driving time?", options:["45 hours","48 hours","56 hours","60 hours"], correct:2, exp:"Máximo de conducción semanal: 56 horas."},
{q:"What is the maximum total driving time permitted in any two consecutive working weeks (fortnightly limit)?", options:["80 hours","90 hours","96 hours","112 hours"], correct:1, exp:"Máximo en dos semanas consecutivas: 90 horas."},
{q:"What is the standard regular daily rest period required under EU rules within any 24-hour period?", options:["At least 9 consecutive hours","At least 10 consecutive hours","At least 11 consecutive hours","At least 12 consecutive hours"], correct:2, exp:"Descanso diario regular: al menos 11 horas consecutivas."},
{q:"To what minimum number of hours may a daily rest be reduced, and on how many occasions between two weekly rests?", options:["Reduced to 8 hours, up to twice per week","Reduced to 9 hours, up to three times between two weekly rest periods","Reduced to 10 hours, unlimited times","Reduced to 8.5 hours, once per week"], correct:1, exp:"Puede reducirse a 9 horas, hasta 3 veces entre dos descansos semanales."},
{q:"What are the daily rest requirements for a multi-manned vehicle under EU rules?", options:["Each driver must take a rest period of at least 9 hours in a 30-hour period","Each driver must take 11 hours in a 24-hour period","A joint rest of 12 hours is mandatory","Rest rules do not apply to multi-manned vehicles"], correct:0, exp:"Con doble tripulación, cada conductor debe descansar al menos 9h en un periodo de 30h."},
{q:"What is the duration of a regular weekly rest period under EU rules?", options:["At least 24 consecutive hours","At least 36 consecutive hours","At least 45 consecutive hours","Exactly 48 consecutive hours"], correct:2, exp:"Descanso semanal regular: al menos 45 horas consecutivas."},
{q:"To what minimum duration may a weekly rest period be reduced?", options:["12 hours","24 hours","30 hours","36 hours"], correct:1, exp:"Puede reducirse a 24 horas."},
{q:"Within how many weeks must any reduction in a weekly rest period be compensated en bloc?", options:["Before the end of the next week following","Before the end of the second week following","Before the end of the third week following the week in question","Within six months"], correct:2, exp:"Debe compensarse en bloque antes de que acabe la 3ª semana siguiente."},
{q:"What special concession on weekly rest applies to coach drivers undertaking a single international journey?", options:["They are exempt from taking weekly rests entirely","They are able to postpone their weekly rest period until the end of the twelfth day instead of the sixth","They can reduce weekly rests to 10 hours permanently","They only need to take a rest once a month"], correct:1, exp:"La 'regla de los 12 días' permite posponer el descanso semanal hasta el día 12."},
{q:"How must a daily rest be interrupted when a driver is travelling by train or ferry boat?", options:["It may be interrupted not more than twice, with total interruptions not exceeding one hour, and access to a bunk","It cannot be interrupted under any circumstances","Interruptions can last up to 4 hours","Ferry travel counts entirely as working time without rest"], correct:0, exp:"Máximo 2 veces, sin superar 1h en total, con acceso a litera."},
{q:"What is the maximum average weekly working time limit under the Road Transport (Working Time) Regulations?", options:["40 hours","48 hours","56 hours","60 hours"], correct:1, exp:"Media semanal máxima: 48 horas."},
{q:"Over what standard reference period is the average 48-hour working week calculated?", options:["4 weeks","13 weeks","17 weeks","26 weeks"], correct:2, exp:"El periodo de referencia normal es de 17 semanas, ampliable a 26 por acuerdo colectivo."},
{q:"What is the absolute maximum number of hours that may be worked in any single week under working time rules?", options:["48 hours","56 hours","60 hours","72 hours"], correct:2, exp:"Máximo absoluto en una semana: 60 horas."},
{q:"Under Working Time rules, what break must be taken if a driver works for between 6 and 9 hours in a day?", options:["15 minutes","30 minutes","45 minutes","60 minutes"], correct:1, exp:"Pausa de 30 min si se trabaja entre 6 y 9 horas."},
{q:"What total working time break is required if a driver's working day exceeds 9 hours?", options:["30 minutes","45 minutes","60 minutes","90 minutes"], correct:1, exp:"Pausa de 45 min si el día supera las 9 horas."},
{q:"How are 'Periods of Availability' treated under the Road Transport (Working Time) Regulations?", options:["They count fully as working time","They do not count towards working time limits","They count as mandatory driving breaks","They are classified as daily rest periods"], correct:1, exp:"Los POA NO cuentan para los límites de tiempo de trabajo."},
{q:"What defines a 'Period of Availability'?", options:["Time spent actively driving on public motorways","A period of waiting time known in advance by the driver during which they have a reasonable degree of freedom","Uninterrupted off-duty sleep time in a hotel","Mandatory vehicle maintenance checks performed at base"], correct:1, exp:"Tiempo de espera conocido de antemano, con un grado razonable de libertad."},
{q:"When does a driver qualify as a 'night worker' under working time regulations?", options:["If they drive between 22.00 and 06.00","If they work for any time at all between 01.00 and 05.00","If their shift exceeds 12 hours ending past midnight","If they perform more than 4 hours of night driving per week"], correct:1, exp:"Se considera 'night worker' si trabaja cualquier tiempo entre la 01:00 y las 05:00."},
{q:"What is the limit on hours worked in a 24-hour period for a designated night worker (unless modified by collective agreement)?", options:["8 hours","9 hours","10 hours","11 hours"], correct:2, exp:"Límite de 10 horas en 24h para un 'night worker' designado."},
{q:"For how long must employers retain records of working time under the regulations?", options:["At least 1 year","At least 2 years","At least 3 years","At least 6 years"], correct:1, exp:"Los registros de tiempo de trabajo se conservan al menos 2 años."},
{q:"Which organization is responsible for the enforcement of Working Time provisions in Ireland?", options:["An Garda Síochána","The Road Safety Authority (RSA)","The Workplace Relations Commission (WRC)","The Department of Transport"], correct:2, exp:"La WRC hace cumplir las normas de Working Time en Irlanda."},
{q:"Under Irish Domestic Regulations (Transport Act 1961/1968), what is the maximum driving time permitted without a break?", options:["4.5 hours","5.0 hours","5.5 hours","6.0 hours"], correct:2, exp:"Máximo de conducción sin pausa bajo normativa doméstica: 5.5 horas."},
{q:"What is the maximum daily driving time under Domestic Regulations?", options:["9 hours","10 hours","11 hours","16 hours"], correct:1, exp:"Máximo de conducción diaria doméstica: 10 horas."},
{q:"What is the maximum length of the working day (spreadover) under Domestic Regulations?", options:["12 hours","14 hours","16 hours","18 hours"], correct:2, exp:"Spreadover máximo doméstico: 16 horas."},
{q:"What is the minimum daily rest period required under Domestic Regulations?", options:["8.5 hours","9 hours","10 hours","11 hours"], correct:2, exp:"Descanso diario mínimo doméstico: 10 horas."},
{q:"Under Domestic Regulations, to what minimum duration may the 10-hour daily rest be reduced three times a week?", options:["8 hours","8 hours and 30 minutes","9 hours","No reduction is permitted"], correct:1, exp:"Puede reducirse a 8h30min, hasta 3 veces por semana."},
{q:"Under Domestic Regulations, what part-time driving exemption applies?", options:["Drivers who drive for not more than 2 hours a day are exempt from all rules","Drivers who drive for not more than 4 hours a day are exempt from drivers' hours regulations (subject to weekly limits and rest conditions)","Part-time drivers are subject to EU Regulation 561/2006 automatically","There is no part-time exemption under Irish law"], correct:1, exp:"Quienes conducen máximo 4h/día están exentos de las reglas de horas domésticas."},
{q:"When a driver undertakes mixed EU and Domestic driving, how should time spent driving under Domestic rules be recorded when keeping records for the EU operation?", options:["As rest time","As other work","As a period of availability","It is omitted from records entirely"], correct:1, exp:"Se registra como 'other work' en el tacógrafo de la operación UE."},
{q:"Can time spent driving under Domestic rules be counted as break or rest under EU rules during mixed driving?", options:["Yes, provided a tachograph is installed","No, time spent driving under Domestic rules cannot be counted as break or rest under EU rules","Yes, if approved by the RSA in advance","Only during weekend shifts"], correct:1, exp:"Nunca puede contar como pausa o descanso UE."},
{q:"What authority do Gardai and RSA examiners have when they stop a moving vehicle?", options:["They can only inspect vehicle tax discs","They have the right to inspect drivers' hours records and prohibit drivers from continuing if rules have been or will be breached","They must issue a WRC compliance certificate before proceeding","They are restricted to checking passenger ticket numbers"], correct:1, exp:"Pueden inspeccionar registros de horas y prohibir continuar si hay incumplimiento."},
{q:"Under EU Regulation 561/2006, what action must a driver take if delayed due to an unforeseeable emergency (e.g., motorway blockage after a major accident)?", options:["Abandon the vehicle immediately and walk to the nearest exit","Depart from the hours regulations only to the extent necessary to reach a suitable stopping place, and record the reasons on their tachograph chart or printout upon arrival","Continue driving until the normal weekly rest is reached regardless of limits","File a written report to the European Commission within 24 hours"], correct:1, exp:"Puede desviarse de las normas solo lo necesario para llegar a un lugar seguro, anotando el motivo al llegar."},
{q:"What does EU Regulation 561/2006 prohibit regarding driver remuneration and bonus schemes?", options:["Paying hourly wages higher than the national minimum wage","Bonus schemes related to distances travelled, number of passengers carried, or time taken if they endanger road safety","Providing overtime pay for weekend shifts","Offering performance-related bonuses based on vehicle fuel efficiency"], correct:1, exp:"Prohíbe bonos ligados a distancia/pasajeros/tiempo que pongan en riesgo la seguridad vial."}
]},
"13": { title: "Tema 13 - Preventive Maintenance", questions: [
{q:"What is the primary responsibility of a transport operator regarding vehicle maintenance?", options:["To inspect vehicles only when defects are noticed by drivers","To ensure all vehicles and trailers are in a safe and roadworthy condition at all times","To rely entirely on the annual CVRT test for roadworthiness checks","To delegate all legal liability to external maintenance contractors"], correct:1, exp:"Debe garantizar que todos los vehículos estén en condición segura y apta en TODO momento."},
{q:"According to Irish regulations, who must carry out vehicle safety maintenance inspections?", options:["Any licensed commercial driver","A suitably qualified and technically competent person","Only RSA-certified vehicle examiners","The transport manager personally"], correct:1, exp:"Una persona adecuadamente cualificada y técnicamente competente."},
{q:"What is one of the possible legal repercussions of operating an unroadworthy vehicle?", options:["Mandatory reduction of driving licence points","Revocation, suspension, or curtailment of the operator licence","Immediate confiscation of all company financial assets","Cancellation of the company's business registration"], correct:1, exp:"Revocación, suspensión o restricción de la licencia de operador."},
{q:"What is the top priority in a planned preventive maintenance system?", options:["Maximizing fleet mileage","Minimizing fuel consumption","Welfare and safety of road users, pedestrians, and crew members","Reducing workshop labor costs"], correct:2, exp:"La seguridad de usuarios de la vía, peatones y tripulación es la prioridad principal."},
{q:"Which of the following is considered a general business benefit of well-maintained vehicles?", options:["Automatic exemption from roadside inspections","Protection of company reputation and maximum vehicle availability","Lower motor tax rates","Exemption from tachograph calibration"], correct:1, exp:"Proteger la reputación de la empresa y maximizar la disponibilidad de vehículos."},
{q:"Which factor MUST be considered when deciding the frequency of maintenance inspections?", options:["The number of drivers employed by the company","Vehicle age, mileage, type of operation, and terrain","The purchase price of the vehicles","The location of the nearest motor tax office"], correct:1, exp:"Edad del vehículo, kilometraje, tipo de operación y terreno."},
{q:"What is the key primary objective of any planned maintenance programme?", options:["Ensuring zero operational costs","Ensuring safe operation of all vehicles with minimum disruption","Eliminating the need for daily driver checks","Replacing vehicles every two years"], correct:1, exp:"Garantizar operación segura con mínima interrupción."},
{q:"According to the RSA Guide, how should safety inspection intervals be scheduled?", options:["Based strictly on distance covered (kilometres)","Based on time intervals (weeks)","Based on fuel consumption","Based on driver shift patterns"], correct:1, exp:"Por intervalos de TIEMPO (semanas), no solo por distancia."},
{q:"Who is legally responsible for the roadworthy condition of a vehicle when it is being used on a public road?", options:["The transport manager only","The vehicle manufacturer only","Both the operator and the driver","The RSA inspector who last tested the vehicle"], correct:2, exp:"Tanto el operador como el conductor son responsables."},
{q:"When must a driver carry out a daily walkaround check?", options:["At the end of every weekly rest period","Every time before a vehicle is used on a public road","Once a week during fuel stops","Only when requested by an enforcement officer"], correct:1, exp:"Antes de cada uso del vehículo en vía pública."},
{q:"What must be done if multiple drivers use the same vehicle during a single day?", options:["Only the first driver needs to perform a walkaround check","Each subsequent driver must carry out a walkaround check before using the vehicle","No walkaround checks are needed after the morning check","The transport manager must perform the check between shifts"], correct:1, exp:"Cada conductor siguiente debe hacer su propia revisión."},
{q:"What is a 'Nil' defect reporting system?", options:["A system where drivers only report defects when a breakdown occurs","A system requiring drivers to submit a daily report confirming no defects were found","A policy of ignoring minor bodywork scratches","An automated computer diagnostic system with zero error codes"], correct:1, exp:"El conductor confirma por escrito a diario que no encontró defectos."},
{q:"Which document contains official tolerance limits and criteria for specific vehicle component defects in Ireland?", options:["The Drivers' Hours Regulations handbook","The RSA publication 'Categorisation of Defects'","The Commercial Court Rules","The Vehicle Registration Certificate"], correct:1, exp:"La publicación de la RSA 'Categorisation of Defects'."},
{q:"What is meant by a 'red line item' defect found during a daily walkaround check?", options:["A minor cosmetic flaw that can be repaired at the next annual service","A defect that means the vehicle is not roadworthy and must not be used until repaired","A defect that only requires verbal notification to the workshop manager","A tachograph error that resets at midnight"], correct:1, exp:"Un defecto que hace que el vehículo no sea apto hasta repararlo."},
{q:"What is the minimum legal tread depth requirement for commercial vehicle tyres in Ireland?", options:["1.0 mm across the entire tyre surface","1.6 mm in a continuous band throughout the central three-quarters of the tread breadth","2.0 mm across half of the tyre width","3.0 mm for front steer axles and 1.6 mm for rear axles"], correct:1, exp:"1.6mm en una banda continua en las 3/4 partes centrales del neumático."},
{q:"Which tyre condition is illegal on a commercial vehicle?", options:["Tread depth of 2.5 mm","Mixing radial and cross-ply tyres on the same axle","Original tread pattern visible in grooves","Tyres inflated to manufacturer recommended pressures"], correct:1, exp:"Mezclar neumáticos radiales y diagonales en el mismo eje es ilegal."},
{q:"Which of the following methods can drivers use to check wheel nut security during a walkaround inspection?", options:["Tapping wheel nuts with a hammer to listen for a dull sound","Inspecting wheel nut indicators (tear drops) for misalignment","Looking for bright metal or rust marks around wheel nuts","All of the above"], correct:3, exp:"Todos los métodos son válidos: golpear con martillo, indicadores, marcas de óxido/metal."},
{q:"All goods vehicles with a gross weight exceeding 7,500 kg must be fitted with:", options:["A rear-view camera only","An additional front mirror giving a view across the front of the vehicle","Three spare tyres on board","A secondary emergency braking lever in the cab"], correct:1, exp:"Un espejo frontal adicional con vista a través del frente."},
{q:"All goods vehicles with a gross weight exceeding 3,500 kg must be fitted with:", options:["Close proximity (pedestrian blind spot) and wide-angle mirrors","A front cross-view mirror","Tinted side windows","Automatic air suspension dump valves"], correct:0, exp:"Espejos de proximidad (punto ciego) y gran angular."},
{q:"What type of glass must be used for windscreens and windows on either side of the driver's seat?", options:["Laminated acoustic glass only","Standard toughened plate glass","Safety glass","Polycarbonate plastic"], correct:2, exp:"Cristal de seguridad."},
{q:"Under what activity category on the tachograph must a driver record the time spent conducting a daily walkaround check?", options:["Rest / Break","Availability","Other Work","Driving"], correct:2, exp:"Se registra como 'Other Work'."},
{q:"For how long must an operator retain vehicle defect reports and defect rectification records?", options:["6 months","12 months","At least 15 months (or 2 years depending on specific enforcement guidelines)","5 years"], correct:2, exp:"Al menos 15 meses (o 2 años según guías específicas)."},
{q:"What is recommended for a general haulage vehicle travelling 120,000 km per year regarding safety inspection frequency?", options:["Every 12 weeks","Every 6 weeks","Every 2 weeks","Once per year during the CVRT"], correct:1, exp:"Cada 6 semanas para un vehículo con ese kilometraje anual."},
{q:"Regardless of distance travelled, what is the maximum recommended inspection interval for vehicles and trailers that are 12 years or older?", options:["Every 10 weeks","Every 8 weeks","Every 6 weeks","Every 4 weeks"], correct:2, exp:"Cada 6 semanas para vehículos de 12+ años, sin importar el kilometraje."},
{q:"What is the primary duty of technically competent staff conducting safety inspections?", options:["To carry out full engine rebuilds during the check","To inspect the vehicle against roadworthiness standards without being expected to carry out repairs simultaneously","To clean and detail the vehicle interior","To issue motor tax discs directly"], correct:1, exp:"Inspeccionar contra los estándares de aptitud, sin reparar a la vez."},
{q:"Annual Commercial Vehicle Roadworthiness Testing (CVRT) is mandatory for goods vehicles over 3,500 kg MAM:", options:["Every 2 years from registration","Annually from the date of first registration","Only after reaching 100,000 km","Every 6 months after 5 years of age"], correct:1, exp:"Anualmente desde la primera matriculación."},
{q:"Who is legally responsible for vehicle roadworthiness when maintenance is contracted out to an third-party garage?", options:["The third-party repairer exclusively","The transport operator","The driver who delivers the vehicle to the garage","The vehicle leasing company"], correct:1, exp:"El operador de transporte sigue siendo responsable, aunque subcontrate el mantenimiento."},
{q:"How far in advance should an operator's preventive maintenance plan cover inspection and servicing dates?", options:["At least 1 month","At least 3 months","At least 6 months","At least 24 months"], correct:2, exp:"Al menos 6 meses por adelantado."},
{q:"Which of the following items of workshop equipment is specifically recommended for an in-house maintenance facility?", options:["Roller brake tester equipment","Headlamp adjustment test equipment","Ramps, hoists, or inspection pits","All of the above"], correct:3, exp:"Todo: banco de frenos, ajuste de faros, rampas/elevadores/fosos."},
{q:"Which document forms part of a vehicle's history file to prove defects were fixed?", options:["Certificate of Incorporation","Job card or defect rectification sheet","Driver's CPC card","Operator licence disc"], correct:1, exp:"Job card o ficha de reparación de defectos."},
{q:"How often must digital tachographs undergo full recalibration?", options:["Every 1 year","Every 2 years","Every 3 years","Every 6 years"], correct:1, exp:"Cada 2 años."},
{q:"How often must analogue tachographs undergo inspection/recalibration?", options:["Every 2 years (minor) / 6 years (full calibration)","Every 1 year","Every 5 years","Only when broken"], correct:0, exp:"Cada 2 años (menor) / 6 años (completa)."},
{q:"Which authorities have the legal right to inspect and seize vehicle maintenance records?", options:["An Garda Síochána and RSA examiners","Revenue Commissioners and Customs","Health and Safety Authority (HSA) only","Local County Council officials"], correct:0, exp:"An Garda Síochána y examinadores de la RSA."},
{q:"What system rates transport operators based on risk and compliance findings over a rolling period?", options:["Operator Financial Standing Index","Commercial Vehicle Risk Rating (CVRR / Risk Rating)","Driver Points System","National Transport Authority Tariff Rating"], correct:1, exp:"Commercial Vehicle Risk Rating (CVRR)."},
{q:"How long is the rolling period used to calculate an operator's Risk Rating?", options:["6 months","1 year","2 years","5 years"], correct:2, exp:"Un periodo continuo de 2 años."},
{q:"What is the impact of an 'Amber' or 'Red' Risk Rating on an operator?", options:["Immediate revocation of business license","Increased frequency of inspections by the RSA","Automatic doubling of motor tax fees","Mandatory replacement of the transport manager within 7 days"], correct:1, exp:"Más inspecciones de la RSA."},
{q:"What is an advantage of maintaining fleet vehicles in-house rather than contracting out?", options:["Eliminates the need for any written records","Direct control, flexibility, and avoiding third-party profit margins","Exemption from roadside Garda inspections","Exemption from annual CVRT tests"], correct:1, exp:"Control directo, flexibilidad y evitar el margen de un tercero."},
{q:"If an operator hires a trailer, who holds the legal responsibility for ensuring its roadworthiness on the road?", options:["The trailer manufacturer","The hire company exclusively","The operator and driver using the trailer","The insurance broker"], correct:2, exp:"El operador y el conductor que lo usan."},
{q:"What type of report form must be used by drivers operating vehicle-mounted cranes or specialized ancillary equipment?", options:["Standard car logbook","Dedicated ancillary / daily shift inspection check sheet (covering hydraulic systems, hooks, outriggers)","Goods Delivery Note","Bill of Lading"], correct:1, exp:"Hoja de inspección dedicada (hidráulicos, ganchos, estabilizadores)."},
{q:"What action should a Transport Manager take if an audit reveals repeated unrecorded vehicle defects?", options:["Ignore the finding if no accidents occurred","Review driver training, enforce daily walkaround reporting, and audit maintenance procedures","Reduce the frequency of safety inspections","Cancel the operator licence voluntarily"], correct:1, exp:"Revisar formación, reforzar el reporte diario y auditar procedimientos."}
]},
"15": { title: "Tema 15 - Vehicle Taxation", questions: [
{q:"Which factor is used to determine annual motor tax for a commercial goods vehicle (HGV / LGV) in Ireland?", options:["Engine cubic capacity (cc)","CO2 emissions rating","Unladen weight of the vehicle","Overall length of the vehicle"], correct:2, exp:"El peso en vacío determina el impuesto de un vehículo de mercancías."},
{q:"Unlike goods vehicles, how is motor tax calculated for passenger buses and coaches (PSVs) in Ireland?", options:["Unladen weight","Number of passenger seats (seating capacity)","Engine power output (kW)","Annual vehicle mileage"], correct:1, exp:"Para PSV se calcula por el número de asientos."},
{q:"Motor tax for commercial goods vehicles or passenger buses in Ireland may be paid for which of the following time periods?", options:["1 month, 2 months, or 12 months","3 months, 6 months, or 12 months","6 months or 12 months only","4 months or 8 months"], correct:1, exp:"Se puede pagar por 3, 6 o 12 meses."},
{q:"What tax rate applies to a goods vehicle between 4,001 kg and 12,000 kg unladen weight?", options:["€333","€420","€500","€900"], correct:2, exp:"€500 para ese tramo de peso."},
{q:"What is the annual motor tax rate for a goods vehicle exceeding 12,000 kg unladen weight?", options:["€420","€500","€750","€900"], correct:3, exp:"€900 para vehículos de más de 12,000 kg."},
{q:"What is the annual motor tax rate for a small bus/minibus with 9 to 20 seats?", options:["€133 (or €154)","€202","€349","€403"], correct:0, exp:"€133 (o €154) para minibús de 9-20 asientos."},
{q:"For an articulated vehicle combination (tractor unit and semi-trailer), how is motor tax calculated in Ireland?", options:["On the unladen weight of the tractor unit together with the heaviest trailer normally used","On the combined Gross Vehicle Weight (GVW)","On the tractor unit engine size only","On the length of the trailer"], correct:0, exp:"Sobre el peso en vacío de la tractora junto con el remolque más pesado que use habitualmente."},
{q:"When a new or imported vehicle is first brought into the State or used in Ireland, it must be registered with Revenue and:", options:["Pay Vehicle Registration Tax (VRT) where applicable","Pay excise duty","Obtain an EU Community Licence immediately","Be inspected by the NTA within 24 hours"], correct:0, exp:"Debe pagar el VRT (Vehicle Registration Tax) si aplica."},
{q:"Where is vehicle registration for imported commercial vehicles normally completed in Ireland?", options:["Local Garda station","An authorised National Car Testing Service (NCTS) centre","Department of Transport headquarters","Local Motor Tax Office"], correct:1, exp:"En un centro NCTS autorizado."},
{q:"To qualify for the commercial (goods) rate of motor tax, a vehicle must be: 1. Constructed or adapted for the carriage of goods 2. Used solely in the course of a trade or business 3. Declared for goods-only use on the RF111A form 4. Used occasionally for private family transport", options:["1 only","1 and 2 only","1, 2, and 3 only","1, 2, 3, and 4"], correct:2, exp:"Debe cumplir 1, 2 y 3 (construido para mercancías + uso exclusivo de negocio + declarado en RF111A). La 4 es incompatible."},
{q:"If a vehicle taxed at the commercial goods rate is used for private purposes (even occasionally), what is the legal requirement?", options:["It must be taxed at the private motor tax rate (which is usually higher)","It remains at the commercial rate provided private use is less than 10%","It becomes completely exempt from motor tax","The operator must pay double VAT on fuel"], correct:0, exp:"Debe pagar la tarifa privada (normalmente más alta) si se usa para fines privados."},
{q:"Which of the following documents is required when taxing a commercial goods vehicle for the FIRST time in Ireland?", options:["1 and 2 only","3 and 4 only","1, 2, 3, and 4 only","1, 2, 3, 4, and 5"], correct:3, exp:"Todos: RF100/RF100A, RF111A, seguro comercial válido, CRW, y ticket de báscula (para HGV)."},
{q:"What document serves as a legal prerequisite confirming a commercial vehicle meets minimum mechanical safety standards before it can be taxed?", options:["Certificate of Roadworthiness (CRW) issued following a CVRT","Tachograph Calibration Certificate","Driving Licence Category C/D","Operator Licence Transport Disc"], correct:0, exp:"El CRW (tras el CVRT) es el requisito legal previo."},
{q:"Commercial goods vehicles and passenger buses over one year old must undergo Commercial Vehicle Roadworthiness Testing (CVRT):", options:["Every 6 months","Annually (every 12 months)","Every 2 years","Every 5 years"], correct:1, exp:"Anualmente."},
{q:"Where may applications for FIRST motor tax discs for Public Service Vehicles (PSVs) be made in Ireland?", options:["Local Motor Tax Office only","Local Garda station","Post Office","NTA online portal"], correct:0, exp:"Solo en la Oficina Local de Impuesto de Circulación."},
{q:"If a vehicle will NOT be used or kept in a public place for a period, what action must the registered owner take?", options:["Simply stop paying motor tax and inform the council afterwards","Submit an Off-Road / Non-Use Declaration in advance to avoid arrears","Transfer ownership to a family member temporarily","Park the vehicle on a public road untaxed"], correct:1, exp:"Presentar por adelantado una Declaración de No-Uso."},
{q:"What happens if an operator fails to submit a Non-Use Declaration in advance for an untaxed vehicle?", options:["Motor tax arrears will accrue for the untaxed period","The vehicle registration is permanently cancelled","The operator licence is automatically revoked","The vehicle is declared scrap"], correct:0, exp:"Se acumulan atrasos del impuesto."},
{q:"What restriction applies to a vehicle that is subject to an active Non-Use Declaration?", options:["It may be driven on public roads on weekends only","It must NOT be used or parked in a public place for the duration of the declaration","It can be driven within 5 km of the depot","It can carry goods but not passengers"], correct:1, exp:"No puede usarse ni aparcarse en vía pública mientras dure la declaración."},
{q:"Which of the following penalties may apply if an untaxed vehicle is used or kept in a public place?", options:["1 and 2 only","3 and 4 only","1, 2, and 3 only","1, 2, 3, and 4"], correct:3, exp:"Todas: multas fijas, procesamiento, incautación y pago de atrasos."},
{q:"What is the standard rate of Value Added Tax (VAT) applied to commercial transport services, vehicle purchases, fuel, and repairs in Ireland?", options:["9%","13.5%","21%","23%"], correct:3, exp:"El tipo estándar de IVA es 23%."},
{q:"Under what condition can a VAT-registered transport operator reclaim VAT paid on commercial vehicles, fuel, and maintenance?", options:["If the vehicle is used exclusively or primarily for business purposes","If the vehicle is driven by a part-time driver","If the company operates more than 10 vehicles","VAT on commercial vehicles can never be reclaimed"], correct:0, exp:"Si el vehículo se usa exclusiva o principalmente para el negocio."},
{q:"Which authority in Ireland issues Public Service Vehicle (PSV) licences for buses and coaches?", options:["Revenue Commissioners","Road Safety Authority (RSA)","National Transport Authority (NTA)","Health and Safety Authority (HSA)"], correct:2, exp:"La NTA emite las licencias PSV."},
{q:"Which core responsibility lies with the Transport Manager regarding vehicle taxation?", options:["Inspecting tyres every morning personally","Ensuring all fleet vehicles are continuously taxed, insured, and hold valid CRWs without lapses","Conducting driver licence driving tests","Issuing VAT invoices to fuel suppliers"], correct:1, exp:"Garantizar que la flota esté siempre con impuesto, seguro y CRW en vigor."},
{q:"What is the minimum period for which a motor tax disc can be purchased for a passenger coach (PSV)?", options:["1 month","3 months","6 months","12 months"], correct:1, exp:"Mínimo 3 meses."},
{q:"What documentation is required to re-tax a passenger bus online or at the motor tax office?", options:["Vehicle Registration Certificate, valid commercial motor insurance, and current Certificate of Roadworthiness","Driver's CPC card and tachograph charts","Company annual accounts and VAT returns","Passport of the Transport Manager"], correct:0, exp:"Certificado de matriculación, seguro válido y CRW vigente."},
{q:"If an operator's coach tax disc expires at the end of October and the vehicle will be stored until March, what is the proper procedure?", options:["Pay the tax for November and December only","Submit a Non-Use / Off-Road Declaration to the local motor tax office in advance","Leave the vehicle untaxed without notifying anyone","Sell the vehicle to another company"], correct:1, exp:"Presentar por adelantado una Declaración de No-Uso."},
{q:"What declaration form must be completed to declare that a light goods vehicle will be used strictly for commercial goods transport?", options:["Form RF100","Form RF111A (Goods Only Declaration)","Form CRW1","Form VRT2"], correct:1, exp:"Formulario RF111A."},
{q:"Under what tax classification must a vehicle be registered if it is built on a standard truck chassis and used to carry goods?", options:["Goods Machinery","Commercial Goods Vehicle","Private Passenger Car","Agricultural Tractor"], correct:1, exp:"Commercial Goods Vehicle."},
{q:"What is required if an operator imports a commercial vehicle from the UK or an EU Member State?", options:["Arrange a VRT inspection at an NCTS centre within statutory time limits, provide proof of purchase, and pay any VRT due","Drive the vehicle immediately on foreign plates for 12 months","Pay no taxes under any circumstances","Register the vehicle with An Garda Síochána only"], correct:0, exp:"Inspección VRT en NCTS, prueba de compra y pago del VRT correspondiente."},
{q:"How are electric goods vehicles under 1,500 kg treated for motor tax in Ireland?", options:["They pay the same rate as a 12-tonne diesel truck","They qualify for a reduced annual motor tax rate (e.g. €120)","They are completely exempt from all road traffic laws","They do not require a Certificate of Roadworthiness"], correct:1, exp:"Tarifa anual reducida (ej. €120)."},
{q:"Can an untaxed commercial vehicle be legally parked on a public street outside the depot?", options:["Yes, provided it is not driven","Yes, if parked overnight only","No, it is an offence to use OR keep an untaxed vehicle in a public place","Yes, if it has valid insurance"], correct:2, exp:"Es delito usarlo O tenerlo en vía pública sin impuesto."},
{q:"What is the consequence of making a false declaration on a Goods-Only Motor Tax Declaration form (RF111A)?", options:["A verbal warning from the motor tax clerk","Penalties, prosecution, and backdated tax liabilities at higher private rates","Automatic suspension of driving licence for 5 years","Exemption from future VAT returns"], correct:1, exp:"Sanciones, procesamiento y atrasos retroactivos a la tarifa privada."},
{q:"Which document confirms the official unladen weight of a heavy goods vehicle for tax purposes?", options:["A weight docket from an authorised weighbridge","The driver's logbook","A fuel receipt from a service station","The vehicle's service history sheet"], correct:0, exp:"Un ticket de báscula autorizada."},
{q:"How often must a commercial vehicle over 1 year old obtain a Certificate of Roadworthiness (CRW)?", options:["Every 6 months","Every 12 months (Annually)","Every 24 months","Only upon change of ownership"], correct:1, exp:"Cada 12 meses."},
{q:"Is a Certificate of Roadworthiness (CRW) required before a commercial vehicle can be issued a motor tax disc?", options:["No, CRW is completely optional for motor tax","Yes, a valid CRW is a mandatory legal prerequisite for taxing commercial vehicles","Only for vehicles carrying hazardous goods","Only for vehicles over 20 years old"], correct:1, exp:"Sí, es requisito legal obligatorio."},
{q:"Which entity collects Vehicle Registration Tax (VRT) in Ireland?", options:["Road Safety Authority (RSA)","Revenue Commissioners","Department of Transport","National Transport Authority (NTA)"], correct:1, exp:"Revenue Commissioners recauda el VRT."},
{q:"If a transport company operates a coach carrying passengers for hire and reward, what additional licence is required besides Motor Tax and Operator Licence?", options:["Large Public Service Vehicle (LPSV) / PSV licence requirements","Heavy Machinery Permit","Local Council Parking Permit","Customs Clearance Certificate"], correct:0, exp:"Licencia LPSV/PSV."},
{q:"What is the annual motor tax rate for a large passenger coach with 53 seats?", options:["€133","€202","€349 - €403 band","€900"], correct:2, exp:"Banda €349-€403."},
{q:"What must a Transport Manager do to manage vehicle taxation effectively across a fleet?", options:["Keep a register monitoring motor tax expiry dates, insurance renewals, and CVRT test due dates","Pay motor tax out of personal bank accounts","Tax vehicles only after receiving a Garda warning","Keep tax discs stored in a safe rather than displaying them"], correct:0, exp:"Llevar un registro de vencimientos de impuesto, seguro y CVRT."},
{q:"What is the legal status of an operator licence if fleet vehicles are repeatedly operated untaxed and without valid CRWs?", options:["The licence is unaffected as long as drivers hold CPCs","The operator's good repute and professional standing may be compromised, leading to licence suspension or revocation","The NTA will pay the motor tax arrears on behalf of the operator","The vehicles are automatically upgraded to zero-tax status"], correct:1, exp:"Puede comprometer la buena reputación del operador, con riesgo de suspensión/revocación."}
]},
"21": { title: "Tema 21 - Speed Limiters and Traffic", questions: [
{q:"Which vehicle category is legally required to have a speed limiter fitted in Ireland and across the EU?", options:["All passenger cars (M1)","All buses and coaches with more than 8 passenger seats (categories M2 and M3) and goods vehicles exceeding 3.5 tonnes MAM (categories N2 and N3)","Motorcycles over 250cc","Agricultural tractors only"], correct:1, exp:"Buses/autocares de +8 asientos y mercancías de +3.5t deben llevar limitador."},
{q:"What is the maximum calibrated set speed for a speed limiter fitted to a passenger bus or coach (category M2/M3)?", options:["80 km/h","90 km/h","100 km/h","110 km/h"], correct:2, exp:"100 km/h para buses/autocares."},
{q:"What is the maximum calibrated set speed for a speed limiter fitted to a heavy goods vehicle (goods vehicle > 3,500 kg MAM)?", options:["80 km/h","90 km/h","100 km/h","110 km/h"], correct:1, exp:"90 km/h para mercancías pesadas — tus furgonetas de +3,500kg."},
{q:"What is the maximum statutory speed limit on Irish motorways for a bus or coach NOT designed for standing passengers (and not towing a trailer)?", options:["80 km/h","90 km/h","100 km/h","120 km/h"], correct:2, exp:"100 km/h en autopista para bus sin plazas de pie."},
{q:"What is the maximum statutory speed limit on Irish motorways for a bus or coach designed for standing passengers (urban/city bus)?", options:["50 km/h","65 km/h","80 km/h","100 km/h"], correct:1, exp:"65 km/h para bus urbano con plazas de pie."},
{q:"What is the speed limit on Irish motorways for ANY vehicle (including buses/coaches) towing a trailer, caravan, or horsebox?", options:["65 km/h","80 km/h","90 km/h","100 km/h"], correct:1, exp:"80 km/h para cualquier vehículo remolcando algo."},
{q:"What is the general speed limit for a bus/coach (not designed for standing passengers) on a dual carriageway in Ireland?", options:["80 km/h","90 km/h","100 km/h (unless a lower local speed limit applies)","120 km/h"], correct:2, exp:"100 km/h en doble calzada, salvo límite local inferior."},
{q:"What is the speed limit for a bus/coach on single-carriageway national, regional, or local roads ('Other Roads') in Ireland?", options:["65 km/h","80 km/h","90 km/h","100 km/h"], correct:1, exp:"80 km/h en carreteras de calzada única."},
{q:"What is the general default speed limit in built-up urban areas in Ireland?", options:["30 km/h","50 km/h","60 km/h","80 km/h"], correct:1, exp:"50 km/h por defecto en zonas urbanas."},
{q:"In Germany, passenger coaches that meet strict safety and technical requirements can obtain a certificate to operate at 100 km/h on motorways. What is this certificate called?", options:["Vitesse 100","Tempo 100","Autobahn 100","SpeedCert 100"], correct:1, exp:"Certificado 'Tempo 100' en Alemania."},
{q:"In France, what certificate permits a qualified bus or coach to travel at speeds up to 100 km/h on motorways and dual carriageways?", options:["Vitesse 100","Tempo 100","Autoroute 100","Express 100"], correct:0, exp:"Certificado 'Vitesse 100' en Francia."},
{q:"What is a 'Dual purpose vehicle' as defined in Irish traffic regulations?", options:["A vehicle powered by both diesel and electricity","A vehicle constructed or adapted to carry both goods and passengers (e.g., an estate car or crew-cab van)","A bus fitted with both analogue and digital tachographs","A vehicle licensed for both domestic and international routes"], correct:1, exp:"Vehículo construido/adaptado para llevar mercancías y pasajeros."},
{q:"How are speeding offences generally penalised for commercial vehicle drivers in Ireland?", options:["Fixed charge penalty notice (typically €160 fine and 3 penalty points) or court prosecution with higher fines","Mandatory 3-month suspension of driving licence for first offence","Instant impoundment of the vehicle by Gardaí","Automatic revocation of the operator licence on first offence"], correct:0, exp:"Multa fija (típicamente €160 y 3 puntos) o procesamiento judicial."},
{q:"What plaque or plate must be affixed to a vehicle fitted with a mandatory speed limiter?", options:["Manufacturer weight plate only","Speed Limiter Calibration Plaque / Seal showing details of calibration date, set speed, tyre size, and workshop details","RSA Green Compliance Badge on the front grille","Tax disc holder sticker"], correct:1, exp:"Placa/sello de calibración del limitador."},
{q:"Who is legally authorised to calibrate, seal, and issue calibration plaques for vehicle speed limiters?", options:["Any licensed commercial vehicle driver","An authorised speed limiter workshop / technician certified by the RSA","The Transport Manager using a laptop","Local Garda stations"], correct:1, exp:"Un taller/técnico autorizado y certificado por la RSA."},
{q:"Operating a commercial vehicle with a defective, tampered, or uncalibrated speed limiter is classified as:", options:["A minor administrative oversight","A serious legal breach under Road Traffic Regulations leading to fines, court prosecution, and loss of good repute","Permissible during peak travel hours","Allowed if driving on local roads under 50 km/h"], correct:1, exp:"Infracción legal grave con multas, procesamiento y pérdida de buena reputación."},
{q:"Where is parking strictly prohibited for ALL vehicles under Irish Traffic Regulations?", options:["Clearways, motorways, bus lanes, pedestrian crossings, and yellow lines","Off-street designated parking bays","Depot parking spaces","Hotel coach bays"], correct:0, exp:"Vías rápidas, autopistas, carriles bus, pasos de peatones y líneas amarillas."},
{q:"What do double continuous yellow lines along the edge of a kerb/roadway signify?", options:["Parking restricted during business hours only","No parking 24 hours a day","Free parking for commercial vehicles","Loading bay for goods vehicles only"], correct:1, exp:"Prohibido aparcar 24 horas al día."},
{q:"What does a single continuous yellow line along a roadway indicate?", options:["No parking 24 hours a day","No parking during specified hours (indicated by nearby time plates)","Bus parking only","Parking permitted for electric vehicles only"], correct:1, exp:"Prohibido aparcar en horas específicas (indicadas en placas cercanas)."},
{q:"Are Large Public Service Vehicles (over 3.5 tonnes unladen weight) allowed to park on public roads at night in urban residential areas?", options:["Yes, anywhere along public streets","No, night-time parking of large PSVs on public roads is heavily restricted by law","Yes, provided hazard lights are kept on","Yes, if parked on the footpath"], correct:1, exp:"Muy restringido de noche en zonas residenciales."},
{q:"On European roads, what international road sign is represented by a yellow diamond with a broad white border?", options:["Priority Road sign (vehicles on this road have right of way at intersections)","End of speed limit zone","Hazardous materials route","No entry for commercial vehicles"], correct:0, exp:"Señal de 'Priority Road' (prioridad de paso)."},
{q:"What item of equipment is mandatory for drivers travelling in France?", options:["Approved breathalyser kit (and authenticated copy of any medical prescription for medication)","Fire extinguisher in every passenger seat","Spare engine oil container","Written permission from the French Embassy"], correct:0, exp:"Kit de etilómetro homologado."},
{q:"When travelling through France under conditions requiring snow chains ('équipements spéciaux obligatoires'), when must snow chains be fitted?", options:["Only after a breakdown occurs","Whenever the official 'équipements spéciaux obligatoires' road signs are displayed or directed by police","Constantly throughout the winter season regardless of weather","Only when driving above 80 km/h"], correct:1, exp:"Cuando se muestran esas señales oficiales o lo indica la policía."},
{q:"Which European countries strictly require drivers who wear spectacles/corrective lenses to carry a SPARE PAIR in the vehicle?", options:["France and Belgium","Germany and Spain","Netherlands and Denmark","UK and Ireland"], correct:1, exp:"Alemania y España exigen gafas de repuesto."},
{q:"In most European countries, what safety equipment must be carried in commercial vehicles/coaches for crew members exiting the vehicle on highways?", options:["Warning triangles and high-visibility reflective clothing (hi-viz)","First aid kits only","Spare engine belts","Flashlights with red filters"], correct:0, exp:"Triángulos de advertencia y ropa reflectante de alta visibilidad."},
{q:"Can a bus designed to carry standing passengers operate at 100 km/h on a motorway?", options:["Yes, if traffic is light","No, its maximum motorway speed limit is strictly restricted to 65 km/h","Yes, provided all passengers are holding handrails","Yes, if operating on an express interurban route"], correct:1, exp:"No, limitado estrictamente a 65 km/h."},
{q:"What is the legal speed limit for a heavy goods vehicle (> 3,500 kg MAM) on an Irish motorway?", options:["80 km/h","90 km/h","100 km/h","120 km/h"], correct:1, exp:"90 km/h en autopista para tu furgoneta pesada."},
{q:"What is the maximum speed limit for a heavy goods vehicle (> 3,500 kg MAM) on dual carriageways and single-carriageway national roads in Ireland?", options:["70 km/h","80 km/h","90 km/h","100 km/h"], correct:1, exp:"80 km/h en doble calzada y nacionales de calzada única."},
{q:"What type of penalty points accumulation leads to a driver qualification suspension in Ireland?", options:["6 points within 3 years for full licence holders","12 points within a 3-year period for full licence holders (7 points for learner/novice drivers)","20 points within 5 years","Any 2 points automatically suspends the licence"], correct:1, exp:"12 puntos en 3 años (o 7 para noveles) suspenden la cualificación."},
{q:"If a Transport Manager discovers a driver has tampered with a vehicle speed limiter to bypass the 100 km/h max setting:", options:["It is a minor internal issue with no legal liability","The Transport Manager must immediately remove the vehicle from service, rectify the limiter at an authorised workshop, and discipline the driver","Allow the driver to finish the week's shift","Increase passenger ticket prices"], correct:1, exp:"Retirar el vehículo de inmediato, corregir el limitador y disciplinar al conductor."},
{q:"Why are speed limiters compulsory on heavy passenger and goods vehicles?", options:["To reduce fuel consumption, lower exhaust emissions, improve road safety, and minimise collision severity","To extend tyre tread life only","To reduce toll fees on motorways","To simplify driver tachograph recording"], correct:0, exp:"Reducir combustible/emisiones, mejorar la seguridad y minimizar la gravedad de colisiones."},
{q:"What is the impact of speeding convictions on a transport operator's Commercial Vehicle Risk Rating (CVRR)?", options:["No impact at all","Repeated speeding offences and speed limiter tampering degrade the operator's risk score, triggering RSA audits","It improves the risk rating score","It cancels motor tax obligations"], correct:1, exp:"Degrada el rating de riesgo, provocando auditorías de la RSA."},
{q:"When a bus is fitted with a speed limiter set to 100 km/h, can downhill gradient forces cause the vehicle to temporarily exceed 100 km/h?", options:["No, speed limiters apply service brakes automatically on downhill slopes","Yes, gravity on steep declines can cause overrun unless the driver uses secondary retarders or brakes","Speed limiters prevent gravity acceleration completely","Downhill overrun is illegal and triggers automatic engine shutdown"], correct:1, exp:"En bajadas pronunciadas puede haber 'overrun' salvo uso de retardadores/frenos."},
{q:"Under Irish law, what is the consequence for an operator who knowingly permits a vehicle with a disabled speed limiter to carry passengers?", options:["Verbal warning from local council","Severe fines, potential court prosecution, vehicle prohibition, and risk of licence suspension/revocation by the Dept of Transport","Re-registration of the vehicle as a taxi","Free recalibration by the RSA"], correct:1, exp:"Multas graves, procesamiento, prohibición del vehículo y riesgo de suspensión de licencia."},
{q:"What document must be carried on an international coach journey through Germany to prove authorization for 100 km/h travel?", options:["Tempo 100 Certificate","Green Card Insurance","Community Licence original","Driver CPC Qualification Card only"], correct:0, exp:"Certificado 'Tempo 100'."},
{q:"What document must be carried on an international coach journey through France to prove authorization for 100 km/h travel?", options:["Vitesse 100 Certificate","French Route Map","Letter of Attestation","Driver Logbook"], correct:0, exp:"Certificado 'Vitesse 100'."},
{q:"What is the maximum speed limit for a coach towing a 1-tonne luggage trailer on an Irish motorway?", options:["100 km/h","90 km/h","80 km/h","65 km/h"], correct:2, exp:"80 km/h remolcando, en autopista."},
{q:"Can a passenger coach driver overtake in the outside (third) lane of a three-lane motorway in Ireland?", options:["Yes, anytime if traffic is slow","No, heavy commercial vehicles and buses over 3.5 tonnes MAM are prohibited from using the outside right-hand lane of a multi-lane motorway","Yes, if traveling at 100 km/h","Only on weekends"], correct:1, exp:"Prohibido para vehículos pesados/buses de +3.5t usar el carril exterior derecho."},
{q:"What is the primary responsibility of a Transport Manager regarding fleet speed limiters?", options:["Ensuring all applicable vehicles are fitted with functional, correctly calibrated speed limiters with valid plaques and intact seals","Personally driving test vehicles every month","Adjusting speed limiters depending on weather","Inspecting driver personal hand luggage"], correct:0, exp:"Garantizar limitadores funcionales, calibrados, con placas y sellos válidos."},
{q:"How often should speed limiter seals and plaques be inspected during fleet maintenance checks?", options:["During every periodic safety inspection to ensure seals are intact, un-tampered, and calibration is valid","Only during initial vehicle purchase","Every 10 years","Never, speed limiters require no ongoing checks"], correct:0, exp:"En cada inspección periódica de seguridad."}
]},
"05": { title: "Tema 5 - Financial Management", questions: [
{q:"What is the primary motive for commercial business enterprises?", options:["To employ drivers","To make profits","To collect VAT","To issue debentures"], correct:1, exp:"Obtener beneficios."},
{q:"How is capital defined in financial management?", options:["The total annual turnover of a business","The amount of money invested in a business to enable it to function","The net profit after corporation tax","The market value of all company vehicles"], correct:1, exp:"Dinero invertido para que el negocio funcione."},
{q:"Which of the following are classified as fixed assets?", options:["Fuel stocks and spare parts","Cash in bank and debtors","Buildings, plant, and company vehicles","Bank overdrafts and creditors"], correct:2, exp:"Edificios, maquinaria y vehículos."},
{q:"What distinguishes current assets from fixed assets?", options:["Current assets are used in day-to-day trading and fluctuate","Current assets are always financed by share capital","Fixed assets are never depreciated","Fixed assets include trade debtors and bank deposits"], correct:0, exp:"Los corrientes se usan día a día y fluctúan."},
{q:"How are long-term liabilities defined?", options:["Debts owed to local suppliers due within 30 days","Liabilities that will continue beyond the end of the financial year, such as bank mortgages","Provisions for quarterly VAT payments","Unpaid drivers' wages at the end of a week"], correct:1, exp:"Continúan más allá del cierre del ejercicio, ej. hipoteca bancaria."},
{q:"What is the definition of debtors in business accounts?", options:["People or businesses who owe money to the company","Suppliers who have delivered goods on credit","Shareholders who have unpaid share capital","Financial institutions holding bank loans"], correct:0, exp:"Quien debe dinero a la empresa."},
{q:"What does a trading account calculate?", options:["The net profit after all overhead expenses","The gross profit by deducting direct costs of sales from turnover","The total capital employed in fixed assets","The cash flow movements for the month"], correct:1, exp:"El beneficio BRUTO, restando el coste directo de ventas de la facturación."},
{q:"Where is the gross profit transferred to calculate net profit?", options:["The balance sheet","The profit and loss account","The cash budget","The revenue reserve fund"], correct:1, exp:"A la cuenta de pérdidas y ganancias."},
{q:"What is a balance sheet?", options:["A record of turnover over a 12-month period","A statement of assets, liabilities, and capital at a given point in time","A forecast of cash receipts and payments","A calculation of direct vehicle running costs"], correct:1, exp:"Foto de activos, pasivos y capital en un momento dado."},
{q:"How is liquidity defined in financial management?", options:["The total market value of freehold property","The measure of money in current assets that can quickly be utilized to pay debts","The percentage return on capital employed","The ratio of share capital to long-term loans"], correct:1, exp:"Dinero en activos corrientes disponible rápido para pagar deudas."},
{q:"Which of the following is a major source of long-term funds?", options:["Bank overdraft","Trade creditors","Share capital","Unpaid taxation due"], correct:2, exp:"El capital social (share capital)."},
{q:"What is a debenture?", options:["A short-term loan repayable in 30 days","A long-term loan carrying a fixed rate of interest, usually secured on company assets","A class of ordinary share with voting rights","A temporary bank overdraft facility"], correct:1, exp:"Préstamo a largo plazo con interés fijo, normalmente con garantía sobre activos."},
{q:"What is a 'revenue reserve' in financial management?", options:["Money raised by issuing new shares to the public","The total of profits generated by the company and reinvested into the business","A government grant for purchasing green vehicles","A short-term cash deposit account"], correct:1, exp:"Beneficios acumulados reinvertidos en el negocio."},
{q:"Which of the following is considered a short-term source of funds?", options:["Debentures","Ordinary shares","Bank overdrafts","Freehold property mortgages"], correct:2, exp:"El descubierto bancario."},
{q:"Do hire vehicles form part of the fixed assets of a transport business?", options:["Yes, all vehicles operated must be listed as fixed assets","No, hire vehicles do not form part of the fixed assets","Only if the hire period exceeds 5 years","Yes, if they are used for international transport"], correct:1, exp:"No, no forman parte de los activos fijos propios."},
{q:"Which of the following expenses is classified as a direct cost (cost of sales) in a transport trading account?", options:["Directors' remuneration","Office heating and lighting","Drivers' wages","Audit and accountancy fees"], correct:2, exp:"Sueldo de conductores."},
{q:"Which of the following is an example of an indirect cost (overhead) in a profit and loss account?", options:["Vehicle fuel and lubricants","Vehicle excise duty and operator licenses","Advertising and website costs","Vehicle maintenance and repairs"], correct:2, exp:"Publicidad y web."},
{q:"What is a primary limitation of trading and profit and loss accounts?", options:["They are confidential and never reviewed by banks","The information is historical and may come too late to remedy serious situations","They include future cash flow projections","They do not record turnover accurately"], correct:1, exp:"La información es histórica y puede llegar tarde."},
{q:"Under the Companies Act 2014 in Ireland, what is the turnover threshold for a small company to qualify for audit exemption?", options:["Not exceeding €5 million","Not exceeding €10 million","Not exceeding €15 million","Not exceeding €20 million"], correct:2, exp:"No superar €15 millones."},
{q:"How is Working Capital calculated?", options:["Fixed Assets minus Current Liabilities","Current Assets less Current Liabilities","Total Assets plus Long-term Liabilities","Current Assets plus Stock"], correct:1, exp:"Activo corriente menos pasivo corriente."},
{q:"What is the formula for the Current Ratio (Working Capital Ratio)?", options:["Current Assets divided by Current Liabilities","Current Liabilities divided by Current Assets","Fixed Assets divided by Working Capital","Net Profit divided by Turnover"], correct:0, exp:"Activo corriente ÷ pasivo corriente."},
{q:"What is considered an ideal benchmark for a healthy Current Ratio?", options:["0.5:1","1:1","2:1","5:1"], correct:2, exp:"2:1."},
{q:"How is the Acid Test Ratio (Quick Assets Ratio) calculated?", options:["Current Assets divided by Current Liabilities","(Current Assets less value of Stock) divided by Current Liabilities","Fixed Assets divided by Current Liabilities","Cash divided by Total Liabilities"], correct:1, exp:"(Activo corriente − stock) ÷ pasivo corriente."},
{q:"Why is stock subtracted from current assets when calculating the acid test ratio?", options:["Because stock is a fixed asset","Because stock may take time to convert into cash","Because stock has no monetary value","Because stock is owned by creditors"], correct:1, exp:"Porque el stock puede tardar en convertirse en efectivo."},
{q:"How is Total Capital Employed calculated?", options:["Fixed Assets plus Current Assets","Total (Fixed and Current) Assets less Current Liabilities","Share Capital plus Revenue Reserves only","Current Assets less Long-term Liabilities"], correct:1, exp:"Activo total (fijo+corriente) − pasivo corriente."},
{q:"What does the Return on Capital Employed (ROCE) measure?", options:["The gross profit percentage on turnover","The net profit before tax expressed as a percentage of total capital employed","The speed at which debtors pay their invoices","The ratio of short-term loans to overdrafts"], correct:1, exp:"Beneficio neto antes de impuestos como % del capital total empleado."},
{q:"What is the definition of a budget in financial management?", options:["A rough estimate of random cash income","A financial plan for the future to control expenditure and plan ahead","A historical record of past losses","An audited balance sheet statement"], correct:1, exp:"Plan financiero de futuro para controlar gastos."},
{q:"What is Cash Flow defined as?", options:["The total annual turnover of invoiced sales","The actual movement of cash into and out of a business","The net profit after corporation tax","The accumulation of trade creditors"], correct:1, exp:"Movimiento real de efectivo dentro y fuera del negocio."},
{q:"What is Debt Factoring?", options:["A method of securing long-term bank loans against property","Passing sales invoices to a factoring organisation for immediate cash advancement and debt collection","A discount given to customers who pay within 7 days","A government tax rebate scheme for transport operators"], correct:1, exp:"Ceder facturas a una empresa de factoring por dinero inmediato y gestión de cobro."},
{q:"What is Cash Budgeting?", options:["Forecasting anticipated cash flows showing differences between expected receipts and payments","Calculating annual depreciation on motor vehicles","Auditing past profit and loss accounts","Determining corporate tax liability"], correct:0, exp:"Prever flujos de caja esperados con diferencias entre cobros y pagos."},
{q:"What is the primary objective of a stock control system?", options:["To maximize the amount of cash tied up in spare parts","To have stocks available within an acceptable time and at an acceptable cost","To eliminate the need for vehicle maintenance records","To store obsolete parts indefinitely"], correct:1, exp:"Tener stock disponible en tiempo y coste aceptables."},
{q:"Who should agree minimum safety levels for stock holdings?", options:["The storekeeper","A senior manager","The external auditor","The junior mechanics"], correct:1, exp:"Un directivo senior."},
{q:"What is meant by 'lead time' in purchasing and stock control?", options:["The lifespan of a commercial vehicle tyre","The time that elapses between placing an order for parts and actually receiving them","The credit period allowed by fuel suppliers","The time taken to train new drivers"], correct:1, exp:"Tiempo entre pedir una pieza y recibirla."},
{q:"How frequently should a physical stock count of parts and materials be made for effective control?", options:["At least once every year","At least four times a year","Only when an audit is requested by Revenue","Once every month"], correct:1, exp:"Al menos 4 veces al año."},
{q:"What action should be taken with stock items that are in good condition but moving slowly or becoming obsolete?", options:["Store them securely until market prices rise","Convert them to cash as quickly as possible, either to someone who can use them or as scrap","Write them off as fixed assets","Include them in the share capital valuation"], correct:1, exp:"Convertirlos en efectivo cuanto antes (vender o como chatarra)."},
{q:"If a company's turnover is €550,000 this year compared to €500,000 last year, what is the percentage increase?", options:["5.0%","9.1%","10.0%","11.0%"], correct:2, exp:"(550,000-500,000)/500,000 = 10%."},
{q:"Which of the following items would appear as current liabilities on a balance sheet?", options:["Freehold property and plant","Trade creditors, corporation tax due, and bank overdrafts","Share capital and revenue reserves","Long-term bank loans"], correct:1, exp:"Acreedores comerciales, impuesto de sociedades pendiente y descubierto."},
{q:"Why is a bank overdraft classified as a current liability rather than a long-term liability?", options:["Because banks can technically demand that an overdraft be settled at any time","Because overdrafts never incur interest charges","Because overdrafts are used exclusively to purchase fixed assets","Because the amount owed never changes"], correct:0, exp:"El banco puede exigir su devolución en cualquier momento."},
{q:"What does the term 'depreciation' represent in financial accounts?", options:["An unexpected cash injection from shareholders","A provision for the decline in value of an asset over time","The increase in market value of freehold property","The reduction in trade debtors"], correct:1, exp:"Provisión por la pérdida de valor de un activo con el tiempo."},
{q:"Which of the following groups uses trading and profit and loss accounts to judge the wisdom of making loans?", options:["Potential lenders","Drivers and mechanics","Competitors in the transport sector","Vehicle manufacturers"], correct:0, exp:"Posibles prestamistas."},
{q:"What is the financial effect if increased costs for overheads (like rent and rates) are not passed on to customers?", options:["Gross profit will be reduced","Net profit will be reduced","Turnover will automatically increase","Working capital will become zero"], correct:1, exp:"Baja el beneficio NETO (no el bruto)."},
{q:"What is the definition of total liabilities of a company?", options:["Long-term liabilities less current assets","Long-term and current liabilities combined","Current liabilities less fixed assets","Total assets minus share capital"], correct:1, exp:"Pasivo a largo + pasivo corriente combinados."},
{q:"Who receives annual fixed interest payments from a limited company?", options:["Ordinary shareholders","Preference shareholders","Debenture holders","Trade creditors"], correct:2, exp:"Titulares de debentures."},
{q:"What type of financial document is drawn up to plan intended income and expenditure for the next 12 months?", options:["Balance Sheet","Trading Account","Budget","Capital Account"], correct:2, exp:"Un Budget (presupuesto)."},
{q:"When reconciling fuel stocks, what physical check should support the closing stock balance figure?", options:["A check of bank statements","A tank dip","An inspection of vehicle tachographs","A count of spare tyres"], correct:1, exp:"Medición del tanque ('tank dip')."},
{q:"What is positive cash flow defined as?", options:["Payments made by a business to its suppliers","Receipts coming into a business from its customers","Invoiced sales that have not yet been paid","Outstanding corporation tax provisions"], correct:1, exp:"Cobros que entran de los clientes."},
{q:"What is the consequence if a company has high profitability on paper but poor cash flow control?", options:["It will automatically qualify for government subsidies","It may fail to meet debts when due, leading creditors to take legal action and potential liquidation","Its fixed assets will automatically increase in value","Its working capital ratio will exceed 3:1"], correct:1, exp:"Puede no pagar sus deudas a tiempo, con riesgo de acciones legales y liquidación."},
{q:"Under what heading on the balance sheet are share capital and revenue reserves displayed?", options:["Current Liabilities","Fixed Assets","\"Financed by\"","Long-term Liabilities"], correct:2, exp:"Bajo el epígrafe 'Financed by'."},
{q:"What is a key advantage of using a debt factoring service?", options:["It eliminates all vehicle maintenance costs","It brings an immediate influx of cash and can reduce internal credit control workload","It increases the gross profit margin on transport contracts","It completely exempts the company from corporation tax"], correct:1, exp:"Liquidez inmediata y reduce la carga de gestión de cobros."},
{q:"Why must transport managers monitor budget variances (differences between actual and budgeted figures)?", options:["To ensure vehicle drivers work unlimited overtime hours","To identify potential financial problems early and take swift remedial action","To calculate annual depreciation on office furniture","To determine the market value of freehold property"], correct:1, exp:"Detectar problemas financieros pronto y actuar a tiempo."}
]},
"03": { title: "Tema 3 - Industrial Relations", questions: [
{q:"The WRC has the power to hear cases connected with which of the following workplace issues? 1. Employees' rights to time off work to carry out trade union duties 2. Alleged discrimination on the basis of sexual orientation 3. PAYE contributions 4. Failure to report an accident to the HSA 5. Equal pay complaints", options:["1 and 4 only","2 and 3 only","1, 2 and 5 only","3, 4 and 5 only"], correct:2, exp:"La WRC resuelve permisos sindicales, discriminación e igualdad salarial; no PAYE ni accidentes sin reportar (eso es Revenue/HSA)."},
{q:"Under the general Working Time Regulations as they apply to non-driving employees of a transport company, which of the following statements are correct? 1. Employees are entitled to a minimum period of 13 hours uninterrupted rest each day 2. The working week should not exceed an average of 48 hours over the agreed reference period 3. All employees, irrespective of occupation, are entitled to free eyesight checks 4. Employees may not work for more than 6 continuous hours before a break is taken 5. A weekly rest of not less than 45 consecutive hours must be taken", options:["1 and 3 only","2 and 4 only","2, 4 and 5 only","1, 3 and 5 only"], correct:1, exp:"Máximo medio de 48h/semana y descanso tras 6h seguidas. El descanso diario general es 11h (no 13), y los chequeos de vista gratis solo para trabajos con pantallas."},
{q:"Jack Smith is 48 and has been employed by the Ace Transport Company for 7½ years. What is Jack's minimum period of notice from the company?", options:["4 weeks","7 weeks","7½ weeks","10 weeks"], correct:0, exp:"De 5 a 10 años de servicio continuo, el preaviso mínimo legal es 4 semanas."},
{q:"Which of the following items must be included in the written statement of the terms of employment given to employees? 1. Job title 2. Starting date 3. Pension provisions 4. Place of work 5. Detailed job description", options:["1, 2, 3 and 4 only","3, 4 and 5 only","2, 3, 4 and 5 only","All items"], correct:0, exp:"Puesto, fecha de inicio, lugar de trabajo y condiciones de pensión — no exige una descripción detallada del puesto."},
{q:"Which of the following is legally entitled to picket at the premises of an employer other than their own?", options:["Any member of the main trade union representing workers at that place of work","A trade union member from a different works in the same town","A trade union official accompanying employees from that workplace","An official from ICTU"], correct:2, exp:"Solo es legal si lo hace un representante sindical acompañando a trabajadores del centro afectado."},
{q:"An employee who is pregnant is:", options:["Entitled to reasonable time off with pay to receive ante-natal care once she has completed 2 years' service","Not entitled to any time off for ante-natal care","Entitled to reasonable time off without pay to receive ante-natal care, irrespective of length of service","Entitled to reasonable time off with pay to receive ante-natal care, irrespective of length of service"], correct:3, exp:"Derecho a permiso RETRIBUIDO inmediato, sin exigir antigüedad."},
{q:"A driver has been employed by the Ace Transport company for 15 years. Their contract of employment states that all periods of notice will be the minimum laid down by law. The driver wishes to leave to take up another job. How much notice must they give as a minimum?", options:["None","One week","Twelve weeks","Fifteen weeks"], correct:1, exp:"El preaviso mínimo del EMPLEADO al dimitir es siempre 1 semana, tras 13 semanas iniciales, sin importar la antigüedad."},
{q:"Jack Smith has worked for Bloggs Limited for ten years. Bloggs Limited is then bought by Lax Transport plc. With regard to the legal provisions concerning continuous employment, Jack's service will be calculated from when:", options:["Lax Transport took control of Bloggs Limited","Bloggs Limited was officially removed from the Register of Companies","Lax Transport issued him with a new contract of employment","He started work for Bloggs Limited"], correct:3, exp:"Un traspaso de empresa no resetea la antigüedad — se computa desde que empezó a trabajar originalmente."},
{q:"Changes to an employee's terms and conditions of employment must be confirmed in writing by the employer no later than:", options:["1 month before the changes come into effect","No later than the date of when the changes come into effect","3 months of when the changes come into effect","4 months of when the changes come into effect"], correct:1, exp:"A más tardar el mismo día en que el cambio entra en vigor."},
{q:"Which of the following statements relating to Statutory Sick Pay in Ireland are correct? 1. Statutory sick pay is currently payable for a maximum of 5 days per calendar year. 2. An employee must have at least 13 weeks' continuous service with the employer to qualify. 3. Statutory sick pay is not payable for the first 3 working days of illness. 4. Statutory sick pay is payable at 70% of the employee's normal daily pay, subject to a daily maximum limit.", options:["2 and 4 only","1, 2 and 4 only","2, 3 and 4 only","1 and 3 only"], correct:1, exp:"El SSP cubre hasta 5 días/año, exige 13 semanas de antigüedad, y paga al 70% con tope diario. La 3 no aplica al SSP."},
{q:"A pregnant employee who has been employed by the same company for six months is entitled to: 1. Maternity benefit irrespective of the length of service 2. Take maternity leave for up to a maximum of 42 weeks 3. Share their maternity leave with their partner 4. Shared parental leave for up to a maximum of 26 weeks", options:["2 and 4 only","1 and 3 only","2, and 3 only","1, 3, 4 only"], correct:2, exp:"Hasta 42 semanas de baja y puede compartir parte con su pareja. El Maternity Benefit sí exige cotización PRSI."},
{q:"When was the Workplace Relations Commission (WRC) established as an independent, statutory body?", options:["1st January 2002","1st October 2015","1st August 2019","1st January 2024"], correct:1, exp:"1 de octubre de 2015."},
{q:"Which organisation serves as the primary forum for the adjudication of industrial disputes and appeals from WRC Adjudication Officer decisions?", options:["The Workplace Relations Commission","The Labour Court","The Employment Appeals Tribunal","The Supreme Court"], correct:1, exp:"The Labour Court es el tribunal de apelación."},
{q:"Within how many days must an employer notify a new employee of their core terms of employment via the 'Day 5 Statement'?", options:["Within 5 days of commencement","Within 14 days","Within 1 month","Within 3 months"], correct:0, exp:"Dentro de los primeros 5 días de empleo."},
{q:"What is the statutory deadline for an employer to provide the full written statement of terms of employment to a new employee?", options:["Within 5 days","Within 14 days","Within 1 month","Within 6 months"], correct:2, exp:"El resto de condiciones, dentro del primer mes."},
{q:"What information must every itemized statement of wages (payslip) explicitly show alongside deductions?", options:["The employer's net profit margin","The gross amount of wages payable to the employee","The employee's home address and tax band","The company's annual turnover"], correct:1, exp:"El importe bruto del salario."},
{q:"Under Irish employment legislation, how many weeks of standard statutory maternity leave are qualifying employees entitled to?", options:["16 weeks","24 weeks","26 weeks","42 weeks"], correct:2, exp:"26 semanas básicas (el total con la adicional llega a 42)."},
{q:"Are employees entitled to paid time off for ante-natal care medical appointments regardless of their length of service?", options:["No, they require at least 12 months of continuous service","Yes, all pregnant employees are entitled to paid time off regardless of length of service","Only if approved in writing by the Minister","No, ante-natal care is entirely unpaid"], correct:1, exp:"Este derecho es inmediato, sin requisito de antigüedad."},
{q:"How many weeks of statutory Parent's Leave are available to each relevant parent within the first two years of a child's life (or adoption placement)?", options:["2 weeks","5 weeks","9 weeks","26 weeks"], correct:2, exp:"9 semanas por cada progenitor."},
{q:"What is the minimum continuous service requirement for an employee to be eligible to apply for unpaid Carer's Leave?", options:["6 months","12 months","2 years","5 years"], correct:1, exp:"12 meses continuos de servicio."},
{q:"How many days of paid domestic violence leave is an employee legally entitled to take in any 12-month period?", options:["1 day","3 days","5 days","10 days"], correct:2, exp:"5 días pagados al año."},
{q:"What is the minimum continuous service required for an employee to qualify for statutory redundancy payments upon dismissal due to redundancy?", options:["6 months","1 year","2 years","5 years"], correct:2, exp:"2 años continuos de servicio."},
{q:"For how many days per calendar year is Statutory Sick Pay (SSP) established under current Irish regulations (following the 2025 pause)?", options:["3 days","5 days","7 days","10 days"], correct:1, exp:"5 días al año."},
{q:"What percentage of normal daily earnings is paid under Statutory Sick Pay (SSP), subject to a daily cap?", options:["50%","60%","70%","100%"], correct:2, exp:"70% del salario diario normal."},
{q:"What is the maximum daily monetary cap applicable to Statutory Sick Pay (SSP) payments?", options:["€50 per day","€80 per day","€110 per day","€150 per day"], correct:2, exp:"€110 por día."},
{q:"What is the statutory minimum notice period required for an employee who has continuous service between 2 years and 5 years?", options:["1 week","2 weeks","4 weeks","6 weeks"], correct:1, exp:"2 semanas para el tramo de 2-5 años."},
{q:"How much notice must an employee give to their employer if they choose to resign after completing at least one month of service (unless a contract states longer)?", options:["24 hours","3 days","1 week","2 weeks"], correct:2, exp:"1 semana como mínimo legal."},
{q:"At what employment size threshold must companies include a statement regarding employee involvement in their annual report?", options:["More than 50 employees","More than 100 employees","More than 250 employees","More than 500 employees"], correct:2, exp:"Más de 250 empleados."},
{q:"What is the National Minimum Wage hourly rate for experienced adult workers aged 20 and over (as of 1 January 2026)?", options:["€12.74","€13.50","€14.15","€15.00"], correct:2, exp:"€14.15/hora."},
{q:"How many specific grounds of discrimination are prohibited under Ireland's Employment Equality Acts 1998-2015?", options:["5 grounds","7 grounds","9 grounds","12 grounds"], correct:2, exp:"9 motivos: género, estado civil, familia, orientación sexual, religión, edad, discapacidad, raza y comunidad Traveller."},
{q:"What age bracket defines the eligibility criteria for automatic enrolment into the 'My Future Fund' state retirement savings system introduced in January 2026?", options:["Aged 18 to 65","Aged 21 to 65","Aged 23 to 60","Aged 25 to 66"], correct:2, exp:"De 23 a 60 años."},
{q:"What is the minimum annual earnings threshold required for an employee to be automatically enrolled in the new auto-enrolment pension system?", options:["€10,000 per year","€15,000 per year","€20,000 per year","€30,000 per year"], correct:2, exp:"€20,000/año."},
{q:"Under the auto-enrolment structure, for every €3 contributed by the employee, how much does the employer contribute?", options:["€1","€2","€3","€7"], correct:2, exp:"€3, igualando la aportación del empleado."},
{q:"What is the maximum number of working hours allowed in an average working week under working time regulations, calculated over a reference period?", options:["40 hours","48 hours","50 hours","60 hours"], correct:1, exp:"48 horas de media."},
{q:"What mandatory rest break must be provided to a worker scheduled for a shift lasting 6 hours or more?", options:["15 minutes","20 minutes","30 minutes","60 minutes"], correct:2, exp:"30 minutos a partir de 6 horas seguidas."},
{q:"How many consecutive hours of daily rest is each worker entitled to within every 24-hour period?", options:["8 consecutive hours","11 consecutive hours","12 consecutive hours","24 consecutive hours"], correct:1, exp:"11 horas consecutivas."},
{q:"How many statutory public holidays are employees in Ireland generally entitled to receive?", options:["7 public holidays","9 public holidays","10 public holidays","12 public holidays"], correct:2, exp:"10 festivos estatutarios."},
{q:"What foundational law, supported by WRC codes of practice, establishes the framework for workplace disciplinary and grievance procedures?", options:["The Industrial Relations Act 1990","The Workplace Relations Act 2015","The Unfair Dismissals Act 1977","The Payment of Wages Act 1991"], correct:0, exp:"Industrial Relations Act 1990."},
{q:"Who is an employee legally entitled to be accompanied by during a formal internal disciplinary meeting?", options:["A practicing barrister only","A work colleague or a trade union official","A local Garda inspector","A WRC Adjudication Officer"], correct:1, exp:"Un compañero de trabajo o un representante sindical."},
{q:"What is the general continuous service requirement for an employee to bring an ordinary claim of unfair dismissal to the WRC?", options:["1 month","6 months","1 year","2 years"], correct:2, exp:"1 año continuo de servicio."},
{q:"What term describes a form of dismissal where the employer's conduct forces the employee to resign?", options:["Summary dismissal","Constructive dismissal","Wrongful redundancy","Industrial lockout"], correct:1, exp:"'Constructive dismissal'."},
{q:"Within how many days must an employer provide a written statement of reasons for dismissal after receiving a valid request from a qualifying employee?", options:["7 days","14 days","21 days","30 days"], correct:1, exp:"14 días."},
{q:"Which of the following is recognized as one of the five fair statutory reasons for dismissing an employee?", options:["Joining an independent trade union","Capability or qualifications of the employee","Taking maternity leave","Asserting statutory employment rights"], correct:1, exp:"Capacidad/cualificación del empleado."},
{q:"Dismissal of an employee on what grounds is automatically deemed 'unfair' by the WRC, regardless of length of service?", options:["Incompetence after training","Redundancy through a fair selection process","Trade union membership and activities","Retirement at age 65 with objective justification"], correct:2, exp:"Afiliación y actividad sindical."},
{q:"What is the standard statutory time limit within which a complaint of unfair dismissal must be received by the WRC from the date of dismissal?", options:["3 months","6 months","12 months","2 years"], correct:1, exp:"6 meses."},
{q:"Under what circumstances can the normal 6-month time limit for submitting a WRC complaint be extended up to 12 months?", options:["If the employer agrees in writing","Where reasonable circumstances have prevented referral within the normal time limit","Automatically for all trade union members","If the claim involves more than €10,000 in damages"], correct:1, exp:"Si hubo una razón justificada para no reclamar a tiempo."},
{q:"What is the maximum financial compensation an Adjudication Officer can award in an unfair dismissal case where the employee incurred financial loss?", options:["26 weeks' remuneration","52 weeks' remuneration","104 weeks' remuneration","Unlimited financial damages"], correct:2, exp:"104 semanas de remuneración."},
{q:"What is the maximum compensation limit if an unfairly dismissed employee incurred *no* financial loss?", options:["1 week's remuneration","4 weeks' remuneration","10 weeks' remuneration","No compensation can be awarded"], correct:1, exp:"4 semanas de remuneración."},
{q:"What is the minimum threshold of proposed redundancies over a 30-day period that triggers collective redundancy rules in an establishment of 50 to 99 employees?", options:["3 or more redundancies","5 or more redundancies","10 or more redundancies","30 or more redundancies"], correct:2, exp:"10 o más despidos en 30 días."},
{q:"For how many minimum days must an employer engage in an information and consultation process with employee representatives during collective redundancies?", options:["14 days","21 days","30 days","60 days"], correct:2, exp:"30 días mínimo."},
{q:"To which government minister must an employer formally notify proposed collective redundancies?", options:["Minister for Transport","Minister for Enterprise, Tourism and Employment","Minister for Social Protection","Minister for Finance"], correct:1, exp:"Ministerio de Empresa, Turismo y Empleo."},
{q:"What protection does a temporary replacement worker have if hired to cover an employee on maternity leave?", options:["They are automatically entitled to permanent status after 6 months","They can only be fairly dismissed if informed in writing at engagement about the temporary nature of the role","They cannot be dismissed under any circumstances","They hold equal redundancy rights from day one"], correct:1, exp:"Solo puede despedirse si se le informó por escrito de la naturaleza temporal al contratarlo."},
{q:"What legal status does industrial action have if it is lawfully organized by a trade union following a proper ballot?", options:["It is classed as a 'wildcat strike' and unprotected","It is regarded as 'protected' under the Unfair Dismissals Acts","It is automatically prohibited by the WRC","It converts employee contracts into fixed-term agreements"], correct:1, exp:"Acción 'protegida' — no pueden despedir a los huelguistas por participar."},
{q:"Who pays the State Maternity Benefit during the 26 weeks of statutory maternity leave (assuming PRSI conditions are met)?", options:["The employer directly via payroll","The Department of Social Protection","The Workplace Relations Commission","The Labour Court"], correct:1, exp:"El Departamento de Protección Social."},
{q:"What is the legal definition of 'night work' under Irish working time regulations?", options:["Work done between 8:00 PM and 4:00 AM","Work done between midnight and 7:00 AM","Any shift exceeding 10 hours in length","Work performed on weekends and public holidays"], correct:1, exp:"Entre medianoche y las 7:00 de la mañana."},
{q:"What key requirement governs employment agencies regarding charging job-seekers fees?", options:["Agencies can charge a standard registration fee of €50","Agencies can deduct 5% from first-month earnings","An employment agency cannot charge an individual a fee for seeking or finding employment","Agencies can charge fees only for executive recruitment"], correct:2, exp:"No pueden cobrar al candidato por buscarle/encontrarle empleo."},
{q:"Which category of workers is explicitly excluded from coverage under the National Minimum Wage legislation?", options:["Part-time and temporary retail assistants","Close relatives of the employer where the employer is a Sole Trader","Foreign nationals working under work permits","Seasonal agricultural workers"], correct:1, exp:"Familiares cercanos si el empleador es autónomo."},
{q:"What principle does the Protection of Employees (Temporary Agency Work) Act 2012 guarantee for temporary agency workers compared to direct hires?", options:["Guaranteed permanent contracts after 3 months","Equal treatment in respect of pay, working time, and rest periods","Exemption from taxation on agency earnings","Priority over all internal candidates for promotions"], correct:1, exp:"Igualdad de trato en salario, jornada y descansos."},
{q:"What is the maximum duration generally permitted for successive fixed-term contracts before objective justification is required to prevent abuse?", options:["1 year","2 years","4 years","5 years"], correct:2, exp:"4 años."},
{q:"Under the Work Life Balance and Miscellaneous Provisions Act 2023, what must an employee complete before an approved flexible or remote working arrangement can actually start?", options:["A minimum of 6 months continuous employment with their employer","At least 1 year of service","A certified training course approved by the WRC","A formal interview with company directors"], correct:0, exp:"6 meses de empleo continuo."},
{q:"What is the role of WRC Adjudication Officers when handling complaints referred to them?", options:["To act as private mediators and compromise settlements","To hold a hearing where parties present evidence and issue a written decision or recommendation","To prosecute employers criminally in the District Court","To inspect workplace safety equipment directly on site"], correct:1, exp:"Celebran una vista y emiten una decisión o recomendación por escrito."}
]},
"06": { title: "Tema 6 - Commercial Conduct", questions: [
{q:"What is the correct chronological sequence of commercial documents in a transport transaction?", options:["Invoice, Order, Quotation, Estimate","Estimate, Quotation, Order, Invoice","Quotation, Estimate, Invoice, Order","Order, Estimate, Quotation, Invoice"], correct:1, exp:"Primero una estimación, luego una cotización formal, el cliente confirma con un pedido, y al final se factura."},
{q:"Which document is typically used to provide a rough or approximate cost for a particular job, often given verbally?", options:["Quotation","Estimate","Pro-forma invoice","Statement of account"], correct:1, exp:"Un 'estimate' es orientativo y no vinculante."},
{q:"What does a formal written quotation normally contain?", options:["Only the total price without terms","A specification of services meeting customer requirements and terms of business","Bank overdraft details and tax numbers","A request for advance cash payment"], correct:1, exp:"Detalla qué se ofrece exactamente y en qué términos."},
{q:"When must the existence of exemption or liability limitation clauses be brought to a customer's attention?", options:["After the invoice is paid","Before the contract is formed","Within 14 days of delivery","Only if requested in writing"], correct:1, exp:"Antes de formar el contrato, o no son vinculantes."},
{q:"When is a pro-forma invoice issued by a transport operator?", options:["To correct an overcharge on a completed job","When the operator wishes to be paid in advance for a job","At the end of the month as a statement of account","When goods are sent carriage forward"], correct:1, exp:"Cuando el operador quiere cobrar por adelantado."},
{q:"What does the term 'carriage paid' mean on a transport quotation?", options:["Transport costs will be paid by the receiver of the goods","Transport costs will be paid by the sender of the goods (consignor)","Transport costs are waived by the operator","Payment must be made via bank draft"], correct:1, exp:"Paga el transporte el remitente (consignor)."},
{q:"What does the term 'carriage forward' mean?", options:["Transport charges must be paid by the receiver of the goods (consignee)","Transport charges are paid in advance by the sender","Delivery is postponed to a future date","Invoicing takes place after 14 days"], correct:0, exp:"Paga el transporte el destinatario (consignee)."},
{q:"How is an 'order' defined in commercial transactions?", options:["A rough cost estimate","A request from a customer to be supplied with a specified product or service","A document correcting an invoice error","A monthly summary of accounts"], correct:1, exp:"Petición del cliente de que se le suministre un producto/servicio concreto."},
{q:"What is the tax point rule regarding VAT invoices?", options:["It is always the date the order is placed","If invoicing takes place within 14 days of the date of supply, the invoice date is accepted as the tax point","It must be exactly 30 days after delivery","It is the date a credit note is issued"], correct:1, exp:"Si se factura dentro de 14 días desde el suministro, la fecha de factura vale como tax point."},
{q:"Which of the following must be shown on invoices issued by a VAT-registered transport company?", options:["The operator's VAT number, VAT rate, amount of VAT, and tax point","Only the net total and customer's bank details","The driver's personal salary details","The company's profit and loss account"], correct:0, exp:"Número de IVA, tipo, importe y tax point."},
{q:"What is the purpose of a credit note?", options:["To correct an undercharge on an invoice","To confirm that an amount shown on an original invoice has been reduced due to an overcharge","To request payment in advance","To serve as a bank overdraft facility"], correct:1, exp:"Confirma que se ha reducido un importe por haber cobrado de más."},
{q:"What is a debit note used for?", options:["To correct an undercharge on an invoice","To give a cash discount for prompt payment","To withdraw money via direct debit","To close a bank account"], correct:0, exp:"Corrige un cobro de MENOS (undercharge)."},
{q:"What information does a statement of account typically summarize?", options:["Opening balance, payments received, invoices completed during the month, and closing balance","Vehicle maintenance schedules and fuel consumption","Corporation tax returns and shareholder dividends","Daily driver working hours"], correct:0, exp:"Saldo inicial, pagos recibidos, facturas del mes y saldo final."},
{q:"What do the letters 'DR' mean on a statement of account?", options:["Direct remittance","Deferred revenue","Debit (meaning the customer owes money)","Discount received"], correct:2, exp:"'Debit' — el cliente debe dinero."},
{q:"How can an operator encourage customers to pay their accounts more promptly?", options:["By charging high interest rates on debit notes","By offering a small cash discount for immediate settlement","By issuing pro-forma invoices exclusively","By refusing to issue statements of account"], correct:1, exp:"Ofreciendo un descuento por pronto pago."},
{q:"Why is the use of cash for settling business invoices declining?", options:["Because counting cash is fast and efficient","Due to time spent counting/banking, high bank charges, and money laundering concerns","Because banks pay high interest on cash deposits","Because cash is illegal in commercial transport"], correct:1, exp:"Tiempo de contar/ingresar, comisiones altas y riesgo de blanqueo."},
{q:"Why are cheques declining rapidly as a payment method?", options:["Alternative methods like debit cards and credit transfers are quicker, cheaper, and more secure","Cheques can no longer be processed by High Street banks","The government banned cheques completely","Cheques do not require bank accounts"], correct:0, exp:"Alternativas más rápidas, baratas y seguras."},
{q:"When using debit or credit card electronic terminals, when is the business typically credited with the funds?", options:["Exactly 30 days later","The following day at the latest","After the annual audit","Instantly before authorisation"], correct:1, exp:"Como muy tarde, al día siguiente."},
{q:"Which card payment method generally incurs higher commission charges for businesses?", options:["Debit cards","Credit cards","Chip and PIN cards","Store cards"], correct:1, exp:"Las tarjetas de crédito."},
{q:"What system is used in Ireland for electronic credit transfers across the SEPA zone?", options:["SEPA Credit Transfer system using an IBAN","National Clearing Cheque System","Merchant Bank Direct Wire","Postal Money Order Network"], correct:0, exp:"SEPA Credit Transfer, usando IBAN."},
{q:"What document is normally sent by a paying organisation to a supplier when paying by credit transfer to detail the invoices being paid?", options:["A debit note","A remittance advice","A bank draft application","A pro-forma invoice"], correct:1, exp:"Remittance advice."},
{q:"What makes a bank draft a secure method of transferring money?", options:["It can be collected by anyone holding the paper slip","It is paid for in advance and only the named payee can collect payment (as good as cash)","It is backed by merchant bank share capital","It never requires an application form"], correct:1, exp:"Pagado por adelantado, solo el beneficiario nombrado puede cobrarlo."},
{q:"What are High Street banks also commonly called?", options:["Merchant banks or investment trusts","Clearing banks or joint stock banks","Central reserve banks","Factoring institutions"], correct:1, exp:"Clearing banks o joint stock banks."},
{q:"What is the primary function of merchant banks?", options:["Providing daily cheque books for retail shops","Offering services for major financial projects like share issues, takeovers, and mergers","Managing personal current accounts and overdrafts","Issuing debit card terminals"], correct:1, exp:"Grandes operaciones financieras: emisión de acciones, fusiones, adquisiciones."},
{q:"What is the main difference between current accounts and deposit accounts?", options:["Current accounts earn high interest, while deposit accounts charge flat fees","Current accounts are used for day-to-day trading (incur charges/no interest), whereas deposit accounts are interest-bearing for surplus funds","Deposit accounts provide cheque books for weekly supplier payments","Current accounts are restricted to merchant banks"], correct:1, exp:"Corriente = uso diario, con comisiones y sin interés; Depósito = interés sobre fondos excedentes."},
{q:"What is a 'stale cheque'?", options:["A cheque that has bounced due to insufficient funds","A cheque more than 6 months old which will not be paid by a bank","A cheque issued by a defunct company","A cheque written in pencil"], correct:1, exp:"Cheque de más de 6 meses que el banco ya no paga."},
{q:"How does a standing order operate?", options:["A third party withdraws varying amounts at will","The customer instructs their bank to pay specified sums into certain accounts on regular dates, retaining full control","The bank automatically issues a loan when funds run low","Invoices are factored automatically"], correct:1, exp:"El cliente ordena pagos fijos en fechas fijas, manteniendo el control."},
{q:"Who initiates and controls a direct debit arrangement?", options:["The bank customer exclusively","A third-party organisation (such as a utility or fuel supplier) given a mandate to take sums directly","The High Street clearing manager","The Revenue Commissioners"], correct:1, exp:"Un tercero con mandato para cobrar directamente."},
{q:"For what common purpose do transport operators frequently favor direct debits?", options:["Paying annual corporation tax","Purchasing bulk loads of fuel where suppliers withdraw funds prior to delivery","Disbursing weekly driver overtime pay","Issuing credit notes to debtors"], correct:1, exp:"Compras grandes de combustible, cobradas por el proveedor antes de entregar."},
{q:"What is the fundamental difference between a standing order and a direct debit?", options:["Standing orders are for fixed amounts controlled by the customer; direct debits allow third parties to take varying amounts","Standing orders are electronic, while direct debits require cash","Direct debits are only used by merchant banks","Standing orders cannot be cancelled by the customer"], correct:0, exp:"Standing order = importe fijo, cliente controla; direct debit = tercero cobra importes variables."},
{q:"How do High Street banks typically classify 'small' business loans?", options:["Loans up to €5,000","Loans up to €25,000","Loans up to €100,000","Loans up to €500,000"], correct:1, exp:"Hasta €25,000."},
{q:"What is a key characteristic of a formal business loan once established?", options:["Complete flexibility in altering repayment dates","Fixed repayment amounts and dates, often with penalties for early repayment","Zero interest rates for transport operators","Automatic conversion into a current account overdraft"], correct:1, exp:"Cuotas y fechas fijas, con penalización por pago anticipado."},
{q:"What is a bank overdraft primarily used for by a transport operator?", options:["Purchasing freehold properties","Paying for short-term, unexpected items of expenditure","Issuing long-term debentures","Financing multi-year fleet replacements"], correct:1, exp:"Gastos imprevistos a corto plazo."},
{q:"What are the main disadvantages of using an overdraft for financing?", options:["Banks charge high interest rates and arrangement fees, and technically can demand settlement at any time","Overdrafts take months to set up compared to loans","Overdrafts require a merchant banking license","Overdraft funds cannot be used for wages"], correct:0, exp:"Interés y comisiones altas, y el banco puede exigir su devolución en cualquier momento."},
{q:"What alternative funding methods have developed to bridge gaps left by restrictive bank lending?", options:["Venture capitalists and peer-to-peer lending forums","Government-mandated credit notes","Mandatory pro-forma invoicing","High street deposit freezing"], correct:0, exp:"Capital riesgo y plataformas de préstamo entre particulares."},
{q:"If a company's customers take too long to pay their bills, what commercial measure can be used to encourage quicker payment?", options:["Offer a cash discount","Offer a trade discount","Issue a credit note","Issue a cash flow budget"], correct:0, exp:"Ofrecer un descuento por pronto pago."},
{q:"What document should a transport company issue when it requires payment in advance for a job?", options:["An advice note","A statement of account","A delivery note","A pro-forma invoice"], correct:3, exp:"Una pro-forma invoice."},
{q:"Under 'carriage paid', who pays the transport costs?", options:["The receiver of the goods (consignee)","The sender of the goods (consignor)","The High Street bank","The factoring organisation"], correct:1, exp:"El remitente (consignor)."},
{q:"Under 'carriage forward', who pays the transport charges?", options:["The sender","The receiver of the goods (consignee)","The operator","The driver"], correct:1, exp:"El destinatario (consignee)."},
{q:"What is a debit note used to correct?", options:["An overcharge on an invoice","An undercharge on an invoice","A stale cheque","A direct debit mandate"], correct:1, exp:"Un cobro de menos (undercharge)."},
{q:"What is a credit note used to confirm?", options:["That an invoice amount has been reduced due to an overcharge","That a loan has been approved by a merchant bank","That goods were sent carriage forward","That a standing order has been cancelled"], correct:0, exp:"Que se ha reducido un importe por sobrecarga."},
{q:"What is the correct chronological sequence for a credit-based transaction involving an invoice, quotation, order, and estimate?", options:["Invoice, quotation, order, estimate","Estimate, quotation, order, invoice","Quotation, order, invoice, estimate","Order, estimate, invoice, quotation"], correct:1, exp:"Estimate, quotation, order, invoice."},
{q:"What document would you use to convey a formal price and conditions for a large, complex journey?", options:["An invoice","An order form","A consignment note","A quotation"], correct:3, exp:"Una quotation formal."},
{q:"How can a company settle multiple invoices by paying funds directly into suppliers' bank accounts?", options:["Standing orders","Credit transfers","Direct debits","Letters of credit"], correct:1, exp:"Credit transfers (transferencias bancarias)."},
{q:"Which element is mandatory on a sales invoice from a VAT-registered transport company?", options:["The customer's home address","The tax point (date)","The driver's license number","The bank overdraft limit"], correct:1, exp:"El tax point (la fecha)."},
{q:"What does a closing statement balance indicated as €4,000 (DR) mean?", options:["The customer is owed €4,000 by the operator","The customer currently owes the operator €4,000","The bank account has a positive credit balance","All invoices have been settled in cash"], correct:1, exp:"El cliente debe €4,000 al operador."},
{q:"Which term best describes an approximate costing of a job given to a potential customer?", options:["A quotation","An estimate","An invoice","A statement"], correct:1, exp:"An estimate."},
{q:"How is an 'order' accurately described?", options:["A communication from a customer asking to be provided with certain goods or services","A detailed costing provided by an operator","An advice of outstanding debts","A formal bank draft application"], correct:0, exp:"Comunicación del cliente pidiendo que se le suministren ciertos bienes/servicios."},
{q:"What is a bank draft considered to be in terms of security and reliability?", options:["Unreliable and prone to bouncing like a cheque","As good as cash and more secure since only the named payee can collect payment","Equivalent to a high-interest commercial loan","Restricted solely to merchant bank transactions"], correct:1, exp:"Tan bueno como el efectivo, más seguro."},
{q:"What is the primary function of a remittance advice sent with a credit transfer?", options:["To detail the specific invoice or invoices being paid","To request a cash discount from the supplier","To set up a direct debit mandate","To apply for a small business loan"], correct:0, exp:"Detallar qué facturas se están pagando."}
]},
"07": { title: "Tema 7 - Marketing", questions: [
{q:"How is marketing officially defined in business management?", options:["The process of maximizing retail prices","The management process responsible for identifying, anticipating and satisfying customer requirements profitably","The department responsible for filing tax returns with Revenue","The administration of transport logistics and routing"], correct:1, exp:"Proceso de gestión que identifica, anticipa y satisface necesidades del cliente de forma rentable."},
{q:"What does SWOT stand for in strategic business analysis?", options:["Sales, Workloads, Operations, Tariffs","Strengths, Weaknesses, Opportunities, Threats","Systems, Workers, Orders, Transport","Suppliers, Wealth, Organization, Taxes"], correct:1, exp:"Fortalezas, Debilidades, Oportunidades, Amenazas."},
{q:"What are the traditional '4 Ps' of the standard marketing mix?", options:["Profit, People, Process, Place","Product, Price, Place, Promotion","Planning, Production, Packaging, Publicity","Performance, Purchasing, Public relations, Pricing"], correct:1, exp:"Product, Price, Place, Promotion."},
{q:"Which three extra elements are added to create the 'Extended Marketing Mix' (the 7 Ps) for service industries like road transport?", options:["Profit, Productivity, Position","People, Process, Physical evidence","Packaging, Public relations, Partners","Planning, Performance, Portfolios"], correct:1, exp:"People, Process, Physical evidence — al ser un servicio, no un producto físico."},
{q:"What does the 'Process' element in the service marketing mix primarily focus on?", options:["The physical weight of goods transported","Being easy to do business with and having an uncomplicated path for the customer","The calculation of vehicle depreciation","The manufacturing process of transport trucks"], correct:1, exp:"Ser fácil de tratar y tener un camino sencillo para el cliente."},
{q:"What does 'Physical evidence' refer to when marketing a service like road transport?", options:["The physical weight limits of a vehicle bridge","All tangible, visible touch points a customer encounters before purchasing, such as reception areas and corporate logos","The physical delivery receipt signed by the consignee","The mechanical condition of brake pads"], correct:1, exp:"Puntos de contacto visibles/tangibles antes de comprar."},
{q:"What are the sequential stages of the product life cycle?", options:["Introduction, Expansion, Peak, Decline","Development, Growth, Maturity, Saturation, Decline","Design, Testing, Launch, Retirement","Growth, Maturity, Profit, Loss"], correct:1, exp:"Development, Growth, Maturity, Saturation, Decline."},
{q:"During which stage of the product life cycle are development costs high, little income generated, and no profits made?", options:["Growth","Development","Maturity","Saturation"], correct:1, exp:"Etapa 'Development'."},
{q:"What happens to sales and profitability during the 'Maturity' stage of a product life cycle?", options:["Sales increase more slowly as initial demand is met, and profits begin to decline","Sales reach zero immediately","Profits rise exponentially with zero competition","Development costs are incurred for the first time"], correct:0, exp:"Las ventas crecen más despacio y el beneficio empieza a bajar."},
{q:"How is market segmentation defined?", options:["Calculating the total national turnover of a company","Dividing an overall potential market into smaller, identifiable sub-markets with similar service requirements","Merging competing transport firms into a single conglomerate","Splitting company shares among shareholders"], correct:1, exp:"Dividir el mercado potencial en sub-mercados con necesidades similares."},
{q:"Which of the following is an example of market segmentation in the road freight industry?", options:["Specialized hanging garment transport for retailers","Filing corporation tax returns","Issuing bank overdraft instructions","Calculating working capital ratios"], correct:0, exp:"Transporte especializado de ropa colgada para minoristas."},
{q:"What is the primary purpose of conducting marketing research?", options:["To eliminate all company taxes","To ensure marketing decisions are based on as much fact and as little guesswork as possible","To recruit qualified truck drivers","To establish trade union agreements"], correct:1, exp:"Basar decisiones en hechos, no en suposiciones."},
{q:"What is secondary data in marketing research?", options:["Information collected via brand-new postal surveys","Information that already exists internally or externally that needs to be extracted","Confidential data stored exclusively by the Revenue Commissioners","Unverified rumors about competitors"], correct:1, exp:"Información que ya existe y solo hay que extraerla."},
{q:"What are key internal sources of secondary marketing data?", options:["Government census reports","Sales records, sales staff reports, and advertising response logs","University academic studies","International trade directories"], correct:1, exp:"Registros de ventas, informes comerciales, respuesta a publicidad."},
{q:"What is another common term for research using secondary data?", options:["Field research","Desk research or non-reactive survey","Primary interview analysis","Pilot testing"], correct:1, exp:"Desk research (investigación de escritorio)."},
{q:"When an organisation needs specific new data (e.g., customer reactions to a proposed service), what type of research does it conduct?", options:["Secondary research","Primary research","Historical desk research","Statutory financial auditing"], correct:1, exp:"Primary research."},
{q:"What is a major disadvantage of using postal questionnaires for primary research?", options:["They are extremely expensive compared to personal interviews","Response rates are usually very low, which can introduce response bias","They can only be conducted via telephone","They require real-time GPS tracking"], correct:1, exp:"Tasa de respuesta muy baja, lo que genera sesgo."},
{q:"Why is a 'pilot study' conducted prior to launching a full survey?", options:["To test questions and format on a small sample to remove misunderstandings and ensure the survey works","To calculate the company's annual profit and loss account","To train drivers in vehicle maintenance","To register the company with the Companies Registration Office"], correct:0, exp:"Probar preguntas y formato en una muestra pequeña."},
{q:"What is the fundamental role of Public Relations (PR) in business?", options:["Direct face-to-face selling of commercial freight contracts","Presenting the business in the most favourable way to customers, media, and the public","Managing corporate tax payments and payroll deductions","Negotiating trade union wage agreements"], correct:1, exp:"Presentar el negocio de la forma más favorable posible."},
{q:"What is a cost-effective way for a transport company to publicize a new contract or major vehicle order to trade magazines without paying for advertising?", options:["Sending a professional press release","Launching a national television campaign","Issuing credit notes to debtors","Distributing postal questionnaires"], correct:0, exp:"Un comunicado de prensa (press release)."},
{q:"Why is face-to-face selling primarily reserved for large contracts?", options:["Because it is an expensive operation and only viable for high-value negotiations","Because travelling salesmen are legally required for retail shops","Because phone selling is prohibited by the WRC","Because direct mail has a 100% conversion rate"], correct:0, exp:"Es caro, solo rentable para negociaciones de alto valor."},
{q:"What characterizes direct mail as a sales approach?", options:["It has a high conversion rate and is universally read by senior executives","It involves sending written material to target decision-makers, though it has a low conversion rate","It replaces all digital marketing and website optimization","It is managed exclusively through phone call centres"], correct:1, exp:"Material escrito a decisores concretos, con baja conversión."},
{q:"What does SEO stand for in the context of digital marketing for transport operators?", options:["Secure Earnings Operation","Search Engine Optimisation","Standard Economic Outlay","Social Employee Organisation"], correct:1, exp:"Search Engine Optimisation."},
{q:"How can transport operators optimize their online presence for Artificial Intelligence (AI) agentic search?", options:["By removing all website text content","By implementing structured data (Schema.org), ensuring real-time data accuracy, and using natural language","By relying exclusively on printed newspaper advertisements","By avoiding mobile and voice search optimization"], correct:1, exp:"Datos estructurados (Schema.org), información precisa y lenguaje natural."},
{q:"What does a 'service blueprint' identify in modern service-sector marketing?", options:["The architectural plans of a warehouse building","Front-stage interactions seen by the customer and back-stage supporting processes","Vehicle routing maps for international freight","Shareholder dividend payout structures"], correct:1, exp:"Interacciones visibles para el cliente y procesos de apoyo internos."},
{q:"What does 'Market share' measure?", options:["The physical weight capacity of a vehicle fleet","The percentage of the total national or regional market that a business currently holds","The proportion of share capital owned by directors","The ratio of fixed assets to current liabilities"], correct:1, exp:"El % del mercado total que tiene la empresa."},
{q:"Why is national television advertising generally unsuitable for regional road transport companies?", options:["It is too expensive and poorly targeted on potential business decision-makers","Television broadcasting is illegal for transport operators in Ireland","Television ads cannot display vehicle license plates","It is classified as a non-reactive survey"], correct:0, exp:"Es cara y mal dirigida a los decisores de negocio."},
{q:"How do trade fairs and exhibitions assist transport businesses?", options:["They serve as useful sources of potential customer leads by targeting specific market segments","They replace the need for annual financial audits","They automatically provide statutory sick pay exemptions","They act as direct debt factoring agencies"], correct:0, exp:"Buena fuente de contactos potenciales."},
{q:"What is a key marketing consideration when managing public relations after an environmental incident involving a vehicle?", options:["Denying that the company owns the vehicle","Managing communications to highlight the rarity of the event, safety records, and empathy while minimizing long-term reputational damage","Immediately increasing freight prices to cover legal fees","Terminating all customer contracts without notice"], correct:1, exp:"Comunicar destacando lo excepcional del hecho, el historial de seguridad y empatía."},
{q:"What does General Transit Feed Specification (GTFS) data provide for public transport operators?", options:["Financial balance sheet audits for the Revenue Commissioners","Accurate schedule and route data feeds so third-party mapping apps show correct travel options","Driver tachograph calibration logs","Direct debit mandates for fuel purchases"], correct:1, exp:"Datos precisos de horarios/rutas para apps de mapas de terceros."}
]},
"08": { title: "Tema 8 - Organisation Charts, KPIs and Work Plans", questions: [
{q:"What type of organisational structure is exemplified by a Police Force, the Armed Forces, the NHS, and the Civil Service?", options:["A flat hierarchy","A matrix organization","A tall hierarchy","A project-based network"], correct:2, exp:"Jerarquía 'tall' (alta, con muchos niveles)."},
{q:"How many layers or levels are in a classic Police Force tall hierarchy model as presented in the text?", options:["5 layers","8 layers","11 layers","15 layers"], correct:2, exp:"11 niveles."},
{q:"Who sits at the very top of the 11-layer Police Force hierarchy example?", options:["Chief Superintendent","Commissioner","Deputy Commissioner","Commander"], correct:1, exp:"Commissioner."},
{q:"What rank immediately follows the Commissioner in the Police Force hierarchy?", options:["Assistant Commissioner","Deputy Commissioner","Chief Superintendent","Commander"], correct:1, exp:"Deputy Commissioner."},
{q:"What rank is at the bottom (level 11) of the Police Force hierarchy?", options:["Sergeant","Inspector","Constable","Chief Inspector"], correct:2, exp:"Constable."},
{q:"Which of the following is considered an advantage of a tall hierarchy?", options:["Excellent vertical communication across all levels","Clear lines of responsibility and close supervision","Low employment costs","Rapid capacity to adapt to market changes"], correct:1, exp:"Líneas claras de responsabilidad y supervisión cercana."},
{q:"What is a notable disadvantage of a tall hierarchy?", options:["Wide spans of control for every supervisor","Poor horizontal communication","Poor vertical communication through the various levels","Lack of promotion opportunities"], correct:2, exp:"Mala comunicación vertical a través de los niveles."},
{q:"Why do some organisations choose to eliminate layers of management to create a 'flat' hierarchy?", options:["To increase the total number of supervisory tiers","To improve vertical communication, reduce costs, and become more responsive to customer needs","To eliminate all delegation of authority","To lengthen the chain of command for security reasons"], correct:1, exp:"Mejorar la comunicación vertical, reducir costes y responder mejor al cliente."},
{q:"What is a primary disadvantage of a flat hierarchy?", options:["Excessive administrative employment costs","Each manager or supervisor handles a large span of control","Too many opportunities for vertical promotion causing confusion","Overly rigid resistance to structural alterations"], correct:1, exp:"Cada mando gestiona un tramo de control muy amplio."},
{q:"What does an organisation chart primarily illustrate?", options:["Daily fuel consumption and vehicle mileage","How staff are organised in terms of role, status, lines of reporting, and communication","The exact annual profit and loss statements","Customer satisfaction ratings"], correct:1, exp:"Cómo se organiza el personal: rol, estatus, reporte y comunicación."},
{q:"In a standard hierarchical transport organisation chart, where are management staff and operatives positioned?", options:["Operatives at the top, management at the bottom","Management at the top and operative levels at the bottom","Both are placed on equal horizontal coordinates","Management in the centre with operatives surrounding them in a matrix"], correct:1, exp:"Gestión arriba, operativos abajo."},
{q:"How are support staff, such as a Clerical Assistant or Stores Person, typically depicted on a hierarchical organisation chart?", options:["As vertical senior directors","As horizontal branches connected to a specific department (like the Depot Engineer)","At the very top of the pyramid structure","Completely separate from any reporting lines"], correct:1, exp:"Como ramas horizontales conectadas a un departamento concreto."},
{q:"When are matrix organisation structures most commonly utilized?", options:["For permanent, routine day-to-day administrative processing","During the duration of a project (e.g., implementing a new depot, product, service, or system)","Only when liquidating a company","For calculating statutory redundancy payments"], correct:1, exp:"Durante la duración de un proyecto."},
{q:"What is a defining characteristic of a matrix structure for an individual worker?", options:["They report to no one and operate autonomously","They have two bosses: a line manager from their regular work area and a project manager","They are employed by an external employment agency exclusively","They change employers every week"], correct:1, exp:"Tiene dos jefes: un mando de línea y un jefe de proyecto."},
{q:"What is an acknowledged disadvantage of a matrix organisation structure?", options:["Total absence of project teamwork","Potential conflict of interest between line managers and project managers regarding staff resource allocation","Inability to communicate horizontally","Excessive number of hierarchical vertical layers"], correct:1, exp:"Conflicto de intereses entre mando de línea y jefe de proyecto por recursos."},
{q:"What does the acronym KPI stand for in business management?", options:["Key Personnel Insurance","Kilometres Per Investment","Key Performance Indicator","Known Procedural Incident"], correct:2, exp:"Key Performance Indicator."},
{q:"Why is a KPI on its own generally considered insufficient for an operator?", options:["Because KPIs are illegal under Irish company law","Because a KPI does not tell an operator much unless targets are set and actual performance is regularly measured against them","Because KPIs apply only to passenger transport vehicles","Because KPIs change daily without warning"], correct:1, exp:"No dice mucho a menos que se fijen objetivos y se mida el rendimiento real."},
{q:"In a transport logistics business, which operational factor typically represents the single largest cost?", options:["Office stationery","Uniform laundering","Fuel","Building insurance"], correct:2, exp:"El combustible."},
{q:"What technological advancements have enabled transport operators to closely monitor individual driver behaviour and fuel economy?", options:["Computerised fuel issuing records and onboard telematics","Manual paper logbooks completed weekly","Bank direct debit mandates","Postal survey questionnaires"], correct:0, exp:"Registros informatizados de combustible y telemática a bordo."},
{q:"Which of the following is listed as a relevant KPI for a logistics operation?", options:["Number of registered shareholders","Weekly costs/profit per vehicle","Authorised share capital total","Number of trade union officials employed"], correct:1, exp:"Coste/beneficio semanal por vehículo."},
{q:"What does a vehicle 'downtime percentage' measure in fleet management KPIs?", options:["The percentage of time vehicles spend running empty","The percentage of time that vehicles are unfit for service","The time drivers spend resting on ferries","The speed limit on regional motorways"], correct:1, exp:"El % de tiempo que los vehículos no están aptos para el servicio."},
{q:"What does the acronym SMART stand for in the context of setting work plans and targets?", options:["Systematic, Meaningful, Analytical, Reliable, Timely","Specific, Measurable, Achievable, Relevant, Timed","Structured, Managed, Accountable, Resourceful, Thorough","Standard, Monitored, Active, Realistic, Total"], correct:1, exp:"Specific, Measurable, Achievable, Relevant, Timed."},
{q:"What is 'benchmarking' used for by commercial managers?", options:["Calculating vehicle gross weight limits","Comparing company performance in key areas against the performances of competitors in similar operations","Testing the physical strength of warehouse shelving","Establishing direct debit mandates with fuel suppliers"], correct:1, exp:"Comparar el rendimiento frente a competidores similares."},
{q:"What is a primary objective of designing structured work plans?", options:["To eliminate all supervision layers instantly","To utilise staff time in a cost-effective way by setting stretching yet realistic completion targets","To replace management accounts entirely","To increase vehicle fuel consumption"], correct:1, exp:"Usar el tiempo del personal de forma rentable, con objetivos realistas."},
{q:"What saying is frequently cited regarding the necessity of measurement in effective management?", options:["\"Without profit there is no business.\"","\"Without measurement there can be no effective management.\"","\"Tall structures always outperform flat structures.\"","\"Matrix management eliminates all conflict.\""], correct:1, exp:"'Sin medición no puede haber gestión eficaz'."},
{q:"How do 'tall' and 'flat' hierarchical structures differ in their physical representation or 'footprint'?", options:["Tall structures have a broad base and few layers; flat structures have a narrow base.","Tall structures have a narrow footprint with many layers; flat structures have a broad base with fewer layers","Both share identical pyramid dimensions.","Flat structures are represented as inverted triangles."], correct:1, exp:"'Tall' = base estrecha, muchos niveles; 'flat' = base ancha, pocos niveles."},
{q:"What is an advantage commonly associated with a 'flat' hierarchy?", options:["Close, multi-layered supervision of every task","Delegation is encouraged and vertical communication is better","Unlimited opportunities for vertical promotion","Zero span of control issues"], correct:1, exp:"Se fomenta la delegación y mejora la comunicación vertical."},
{q:"Which of the following is listed as a disadvantage of a 'flat' hierarchy?", options:["Excessive administrative salary overheads","Motivation of the large group of staff at the bottom can be a problem","Inability to modify corporate structures when markets change","Complete absence of horizontal communication"], correct:1, exp:"La motivación del gran grupo de personal en la base puede ser un problema."},
{q:"In a matrix organisation chart, how are normal lines of reporting versus project communications typically represented?", options:["Vertical lines show normal reporting to line managers, while horizontal lines show project team communication","Horizontal lines show line managers; vertical lines show project managers","Diagonal lines represent all communication channels","Circular charts replace all linear lines"], correct:0, exp:"Verticales = reporte normal; horizontales = comunicación de proyecto."},
{q:"Why are transport organisations overwhelmingly structured hierarchically?", options:["Because legislation mandates exactly eleven management layers for all hauliers","So that all staff know their place in the system, who to report to, and who they are responsible for","To prevent the use of onboard telematics","To eliminate the need for financial accounting records"], correct:1, exp:"Para que todo el personal sepa su lugar, a quién reportar y de quién es responsable."},
{q:"If a transport company operates a fleet of 50 articulated trucks, each covering 200,000 km per year (total 10 million km), what financial impact does a small percentage improvement in fuel economy have?", options:["It has zero impact on operating costs.","A small overall percentage improvement can remove significant amounts of fuel cost (e.g., 1% saves €48,000 annually at €1.20/litre)","It doubles the vehicle downtime percentage.","It increases maintenance staff requirements."], correct:1, exp:"Una pequeña mejora % puede ahorrar cantidades significativas de combustible."},
{q:"Which department or role is typically shown at the top of a standard commercial transport organisation chart?", options:["General Manager or Managing Director","Lead Workshop Fitter","Traffic Office Supervisor","Stores Person"], correct:0, exp:"General Manager o Managing Director."},
{q:"What does 'span of control' refer to in management structures?", options:["The geographic distance a truck travels per delivery route","How many people are answerable directly to each manager or supervisor","The duration of a project team's existence in a matrix structure","The total number of layers in a tall hierarchy"], correct:1, exp:"Cuántas personas responden directamente ante cada mando."},
{q:"Which of the following is an example of an external or comparative performance evaluation method mentioned in the text?", options:["Benchmarking","Matrix auditing","Pyramid flattening","Tall consolidation"], correct:0, exp:"Benchmarking."},
{q:"What is a key feature of the 'Smart' criteria in work planning regarding time?", options:["Targets must be open-ended with no deadlines.","Targets must be Timed","Targets must take at least 5 years to complete.","Timelines should be ignored during project phases."], correct:1, exp:"Los objetivos deben tener plazo (Timed)."},
{q:"What organisational problem can arise from having too many layers in a tall hierarchy?", options:["Spans of control become impossibly wide for single supervisors.","Built-in resistance to change and poor vertical communication","Complete elimination of administrative costs","Immediate reduction in staff numbers at the bottom"], correct:1, exp:"Resistencia al cambio integrada y mala comunicación vertical."},
{q:"How do weekly, monthly, and annual reports assist operators using KPIs?", options:["They allow the business to monitor progress and see which areas need the greatest improvement","They replace the requirement for annual statutory audits","They automatically adjust driver salary scales","They convert tall hierarchies into flat structures"], correct:0, exp:"Permiten monitorizar el progreso y ver qué áreas necesitan más mejora."},
{q:"Which KPI metric evaluates safety performance in road transport?", options:["Accidents per driver per 100,000 km","Percentage of kilometres run empty","Average office stationery cost per month","Number of direct debit transactions processed"], correct:0, exp:"Accidentes por conductor cada 100,000 km."},
{q:"What is indicated when a transport company measures the percentage of total kilometres run whilst empty?", options:["Vehicle utilisation efficiency","Total corporation tax liability","Staff sickness rates","Workshop fitter productivity"], correct:0, exp:"Eficiencia de utilización del vehículo."},
{q:"Why are graphical representations or charts often utilized alongside KPI reports?", options:["They are legally mandated by the Workplace Relations Commission.","They are effective ways of showing performance progress over time","They eliminate the need for fuel telematics.","They replace financial management accounts entirely"], correct:1, exp:"Son una forma efectiva de mostrar el progreso del rendimiento."}
]},
"09": { title: "Tema 9 - Business Taxation", questions: [
{q:"What is corporation tax in Ireland?", options:["A direct tax paid by sole traders on business turnover","The tax payable by limited companies on the net profits they make each year, adjusted for allowances","A national property tax levied on commercial depots","A fixed municipal tax paid monthly by partnerships"], correct:1, exp:"Impuesto que pagan las sociedades limitadas sobre el beneficio neto anual."},
{q:"Which organisation controls the collection of corporation tax, PAYE, PRSI, and VAT in Ireland?", options:["The Companies Registration Office (CRO)","Revenue Irish Tax and Customs (Revenue)","The Workplace Relations Commission (WRC)","Transport Infrastructure Ireland (TII)"], correct:1, exp:"Revenue."},
{q:"Under Section 288 of the Companies Act 2014, what is the maximum initial period that a company's first financial statements can cover?", options:["12 months","18 months","24 months","6 months"], correct:1, exp:"18 meses."},
{q:"What is the standard rate of Corporation Tax in Ireland for trading income?", options:["12.5%","15%","23%","25%"], correct:0, exp:"12.5% para ingresos comerciales."},
{q:"What higher rate of Corporation Tax applies to non-trading income, such as rental and investment income?", options:["12.5%","15%","20%","25%"], correct:3, exp:"25% para ingresos no comerciales."},
{q:"Within what timeframe after the end of the company's financial year must Corporation Tax be paid?", options:["3 months","6 months","9 months","12 months"], correct:2, exp:"9 meses tras el cierre del ejercicio."},
{q:"What tax advantage can small and medium transport businesses use when purchasing new energy-efficient vehicles?", options:["A 50% standard depreciation write-off","An Accelerated Capital Allowance of 100%","A complete exemption from vehicle registration tax","A direct cash subsidy from the Department of Transport"], correct:1, exp:"Amortización Acelerada del 100%."},
{q:"Under 'Real Time Reporting' introduced in January 2019, when must employers report payroll tax deductions (PAYE and PRSI) to Revenue?", options:["Quarterly, at the end of each tax period","Annually on October 31","On or before the date the payroll payment is made","Within 14 days of the end of the month"], correct:2, exp:"En la fecha (o antes) del pago de nómina."},
{q:"What class of PRSI do self-employed individuals pay in Ireland?", options:["Class A","Class J","Class S","Class P"], correct:2, exp:"Clase S."},
{q:"What is the tax year period for self-employed individuals in Ireland?", options:["6 April to 5 April (UK system)","1 January to 31 December (calendar year)","1 July to 30 June","1 October to 30 September"], correct:1, exp:"1 enero a 31 diciembre."},
{q:"What is the standard annual Pay and File deadline for self-employed individuals filing via Revenue Online Service (ROS)?", options:["30 September","31 October","Mid-November","31 December"], correct:2, exp:"Mediados de noviembre, para presentación vía ROS."},
{q:"How long are self-employed individuals and companies legally required to retain tax and accounting records?", options:["At least 3 years","At least 5 years","At least 6 years","At least 10 years"], correct:2, exp:"Al menos 6 años."},
{q:"What is the primary risk of 'false self-employment' in the road transport sector?", options:["Loss of annual vehicle registration tags","Revenue reclassifying workers as employees, leading to backdated PAYE/PRSI liabilities, interest, and penalties","Mandatory conversion to an annual VAT accounting scheme","Automatic suspension of international operating licenses"], correct:1, exp:"Revenue puede reclasificar a los trabajadores como empleados, con deudas retroactivas."},
{q:"How does Revenue treat nightly subsistence expense payments made to HGV drivers that comply with published Civil Service Rates?", options:["They are fully taxable as benefit in kind","They incur no tax liability","They must be reported under Class S PRSI","They are deductible only under flat-rate VAT rules"], correct:1, exp:"No generan ninguna obligación fiscal."},
{q:"What is the standard rate of Value Added Tax (VAT) in Ireland?", options:["9%","13.5%","21%","23%"], correct:3, exp:"23%."},
{q:"What is the VAT registration threshold for businesses supplying services only in Ireland (as of January 2025)?", options:["€20,000 per year","€37,500 per year","€42,500 per year","€85,000 per year"], correct:2, exp:"€42,500/año."},
{q:"What is the VAT registration threshold for businesses supplying goods in Ireland?", options:["€42,500 per year","€65,000 per year","€75,000 per year","€85,000 per year"], correct:3, exp:"€85,000/año."},
{q:"How is the net VAT payable to Revenue calculated under the standard VAT accounting system?", options:["Output VAT minus input VAT","Input VAT minus output VAT","Total turnover multiplied by the flat-rate percentage","Gross profit minus allowable business expenses"], correct:0, exp:"IVA repercutido menos IVA soportado."},
{q:"How should an Irish VAT-registered haulier handle VAT when delivering a B2B transport service to a business customer established in another EU Member State?", options:["Charge the standard Irish VAT rate of 23%","Do not charge Irish VAT; the customer accounts for VAT under the reverse-charge mechanism","Apply Norwegian export duty rates","Register for VAT locally in every transit country"], correct:1, exp:"No cobra IVA irlandés; el cliente lo autoliquida (reverse-charge)."},
{q:"How are transport services directly connected with exports to non-EU countries (e.g., Ireland to Kazakhstan) treated for VAT purposes?", options:["Charged at the standard 23% rate","Zero-rated (0%), provided required documentary evidence is held","Exempt from VAT with no input recovery allowed","Subject to local EU import tariffs"], correct:1, exp:"Tipo cero (0%), con la documentación exigida."},
{q:"How can an Irish VAT-registered transport operator recover foreign VAT incurred on fuel and tolls in other EU countries?", options:["By deducting it directly from their Irish corporation tax return","By making an electronic application to the foreign VAT reclaim portal via the ROS website","By submitting paper receipts to the Department of Transport","Foreign VAT cannot be reclaimed under any circumstances"], correct:1, exp:"Solicitud electrónica vía ROS."},
{q:"What barrier-free electronic toll system operates on the M50 motorway around Dublin?", options:["GO-Maut","eFlow","AutoPASS","HGS"], correct:1, exp:"eFlow."},
{q:"What is the toll rule for heavy goods vehicles using the Dublin Port Tunnel?", options:["They are charged peak-hour congestion rates","They are permitted to use the tunnel toll-free at all times","They must pay double the standard car toll","They are prohibited from entering the tunnel"], correct:1, exp:"Gratis en todo momento para vehículos pesados."},
{q:"Which goods vehicles are subject to the United Kingdom's Heavy Goods Vehicle (HGV) Road User Levy?", options:["All vehicles exceeding 3.5 tonnes","All goods vehicles with a gross weight of 12 tonnes or more","Only foreign-registered vehicles under 7.5 tonnes","Vehicles operating exclusively within Greater London"], correct:1, exp:"Vehículos de 12+ toneladas."},
{q:"Which three EU Member States participate in the joint time-based road-charging system known as the Eurovignette?", options:["France, Germany, and Italy","Luxembourg, the Netherlands, and Sweden","Austria, Belgium, and Denmark","Spain, Portugal, and Ireland"], correct:1, exp:"Luxemburgo, Países Bajos y Suecia (con calendarios de transición para los dos últimos)."},
{q:"What electronic on-board unit is required for heavy vehicles exceeding 3.5 tonnes using Austria's distance-based toll system?", options:["Telepass","GO-Box","AutoPASS tag","HGS sticker"], correct:1, exp:"GO-Box, en Austria."},
{q:"What is the name of the kilometre-based electronic tolling system introduced in Belgium in 2016?", options:["LKW Maut","Belgian Kilometer Charge (administered by Viapass)","LSVA III","KmToll"], correct:1, exp:"Belgian Kilometer Charge, administrado por Viapass."},
{q:"What distance-based electronic tolling system is operated in Germany for commercial goods vehicles exceeding 3.5 tonnes?", options:["LKW-Maut (Toll Collect)","Eurovignette","AutoPASS","Rovinieta"], correct:0, exp:"LKW-Maut (Toll Collect) en Alemania."},
{q:"What is the official acronym for Switzerland's nationwide distance- and performance-related heavy vehicle fee?", options:["HGS","LSVA","KmToll","OBU"], correct:1, exp:"LSVA, en Suiza."},
{q:"What is the maximum fuel allowance that foreign vehicles may bring into Turkey within standard manufacturer-fitted running tanks without incurring customs duties?", options:["200 litres","400 litres","550 litres","1,000 litres"], correct:2, exp:"550 litros."},
{q:"Under the cash (moneys received) basis of accounting for VAT in Ireland, when does output VAT become payable?", options:["When the sales invoice is issued","When payment is actually received from the customer","At the end of the financial year","When goods are loaded onto the vehicle"], correct:1, exp:"Cuando se recibe realmente el pago del cliente."},
{q:"What is a key drawback of the cash basis of accounting for VAT in the transport sector?", options:["It prohibits the use of international fuel cards","Major costs like fuel, tolls, and maintenance require immediate payment, delaying the recovery of input VAT","It doubles the standard corporation tax rate","It is mandatory for all large multinational transport groups"], correct:1, exp:"Los grandes costes se pagan al momento, retrasando la recuperación del IVA soportado."},
{q:"What scheme is designed to reduce VAT bookkeeping for small businesses by paying Revenue a fixed percentage of gross turnover instead of calculating individual input VAT?", options:["Annual Accounting Scheme","Flat-Rate VAT Scheme","Cash Basis Accounting","Reverse-Charge Mechanism"], correct:1, exp:"Flat-Rate VAT Scheme."},
{q:"What is the penalty for failing to pay the M50 barrier-free toll on time?", options:["Immediate confiscation of the operating license","Penalty charges that escalate rapidly","A mandatory 3-month driving ban for the company director","Automatic conversion to a quarterly VAT audit"], correct:1, exp:"Recargos que escalan rápidamente."},
{q:"What pricing element has been introduced across major European toll systems (such as Germany, Austria, and Switzerland) to increase costs for older diesel vehicles?", options:["Axle-spacing surcharges","CO2 emission class pricing","Weekend driving bans","Mandatory overnight parking fees"], correct:1, exp:"Precio por clase de emisiones CO2."},
{q:"What electronic toll system is utilized in Norway for commercial vehicles exceeding 3.5 tonnes?", options:["Telepass","AutoPASS","HGS","GO-Box"], correct:1, exp:"AutoPASS, en Noruega."},
{q:"What happens if a vehicle passes through Turkish toll points (HGS) without sufficient credit?", options:["The vehicle is impounded permanently at the roadside","A toll violation occurs, which must be settled within a grace period to avoid substantial fines and exit blockages","The debt is automatically transferred to the Irish Revenue Commissioners","The driver's personal income tax is increased"], correct:1, exp:"Infracción de peaje, a saldar en un plazo de gracia."},
{q:"What is the daily standard charge for the London Congestion Charge (rising to £18 from January 2026)?", options:["£10","£12.50","£15","£20"], correct:2, exp:"£15."},
{q:"What daily charge applies to vehicles not meeting minimum emission standards within London's Ultra Low Emission Zone (ULEZ)?", options:["£10","£12.50","£15","£25"], correct:1, exp:"£12.50."},
{q:"What is the primary purpose of preliminary tax payments for self-employed individuals in Ireland?", options:["To pay projected income tax for the current year in advance","To cover historical VAT liabilities from previous trading years","To fund local authority road maintenance directly","To secure Class A social insurance benefits"], correct:0, exp:"Pagar por adelantado el impuesto sobre la renta estimado del año en curso."}
]},
"10": { title: "Tema 10 - Operating Licensing", questions: [
{q:"For what duration is a Road Passenger Transport Operator Licence normally valid?", options:["1 year","3 years","5 years","10 years"], correct:2, exp:"5 años."},
{q:"Which division is responsible for issuing the Road Passenger Transport Operator Licence and the Community Licence?", options:["National Transport Authority (NTA)","An Garda Síochána","Road Transport Operator Licensing Division (RTOL) of the Department of Transport","Road Safety Authority (RSA)"], correct:2, exp:"RTOL del Dept. of Transport."},
{q:"Who issues the Large Public Service Vehicle (LPSV) Licence for the registered owner of the vehicle?", options:["A PSV Officer of An Garda Síochána","The Minister for Transport","The National Transport Authority (NTA)","The Driver and Vehicle Computer Services Division"], correct:0, exp:"Un PSV Officer de An Garda Síochána."},
{q:"What type of licence is required to provide a regular public passenger service between specified terminal points or along a specified route?", options:["An International Road Passenger Transport Operator Licence","A Large Public Service Vehicle Licence","A Public Bus Passenger Service Licence (formerly Route Licence)","An Event-Specific PSV Licence"], correct:2, exp:"Public Bus Passenger Service Licence."},
{q:"Who is the issuing authority for the Public Bus Passenger Service Licence?", options:["An Garda Síochána","The National Transport Authority (NTA)","The Department of Transport","Local County Councils"], correct:1, exp:"NTA."},
{q:"What four core criteria must an applicant satisfy to obtain a Road Passenger Transport Operator Licence under EU Regulations?", options:["Good repute, appropriate financial standing, professional competence, and a stable and effective establishment in Ireland","Irish citizenship, a minimum of 10 vehicles, 5 years of driving experience, and a tax clearance certificate","Local authority planning permission, a clean driving licence, public liability insurance, and a C-class driver","An annual profit of €50,000, zero traffic offences, ISO 9001 certification, and a contracted mechanic"], correct:0, exp:"Buena reputación, solvencia financiera, competencia profesional, establecimiento estable."},
{q:"What constitutes a 'Large Public Service Vehicle' (LPSV)?", options:["Any vehicle used for hire or reward","A vehicle equipped to carry more than 8 passengers, not including the driver","A vehicle with a gross weight exceeding 3.5 tonnes","Any multi-purpose vehicle (MPV) used for airport transfers"], correct:1, exp:"Más de 8 pasajeros, sin contar al conductor."},
{q:"Which of the following operations is exempt from requiring a Road Passenger Transport Operator Licence?", options:["Transporting passengers for a fare between Dublin and Cork on a scheduled bus service","A hotel offering a complimentary transport service to its guests without charging them","Hiring a 50-seater coach to a sports club for a fee","Providing daily commuter services to a business park for paying passengers"], correct:1, exp:"Un hotel que ofrece transporte gratuito, sin cobrar."},
{q:"What happens if a road transport undertaking loses its tax clearance status from the Revenue Commissioners?", options:["The operator is fined €5,000 but the licence remains valid","The undertaking must apply for a temporary UK operator licence","The Minister may suspend or withdraw the operator licence because tax clearance is a good repute requirement","The National Transport Authority takes over the company's financial management"], correct:2, exp:"El Ministro puede suspender/retirar la licencia."},
{q:"How soon must the holder of a Road Passenger Transport Operator Licence notify the Minister in writing of a relevant conviction against any relevant person?", options:["Within 1 month of the conviction","Within 3 months of the expiry of the time allowed for appealing such conviction, or the determination/withdrawal of the appeal","Within 6 months of the original court date","Notification is only required upon licence renewal"], correct:1, exp:"Dentro de 3 meses desde que expira el plazo de apelación."},
{q:"What financial standing threshold must an applicant demonstrate to authorize vehicles on their Road Passenger Transport Operator Licence?", options:["€10,000 for the first vehicle and €2,000 for each additional vehicle","€9,000 for the first vehicle and €5,000 for each additional vehicle","A flat rate of €50,000 regardless of fleet size","€5,000 per vehicle across the entire fleet"], correct:1, exp:"€9,000 primer vehículo, €5,000 por cada adicional."},
{q:"How must an established business (trading for more than 1 year) demonstrate financial standing?", options:["By submitting a bank statement from the last 30 days","By submitting annual accounts (including a Balance Sheet and Profit and Loss Account) certified by a duly accredited person, with a year-end date no more than 18 months prior","By providing a letter of credit from an Irish bank","By submitting a Statement of Affairs"], correct:1, exp:"Cuentas anuales certificadas, cierre de no más de 18 meses."},
{q:"How does a new business (trading for less than 1 year) demonstrate its financial standing?", options:["By providing three months of projected cash flows","By submitting a Statement of Affairs as at a date no more than 1 month prior to the date of submission, certified by a duly accredited person","By submitting the founder's personal tax returns","Financial standing is waived for the first year of operation"], correct:1, exp:"Un 'Statement of Affairs' certificado, de fecha no anterior a 1 mes."},
{q:"To satisfy the requirement of 'professional competence,' an undertaking must designate a Transport Manager who holds what specific document?", options:["A Category D Driving Licence","An Irish University Degree in Logistics","A Certificate of Professional Competence (CPC) in Road Passenger Transport issued by an EU authority","A Certificate of Roadworthiness (CRW)"], correct:2, exp:"Un CPC en Road Passenger Transport, de una autoridad de la UE."},
{q:"If a transport manager ceases to act in that role, what is the maximum period the Department of Transport may allow to designate a replacement?", options:["1 month","3 months","6 months","12 months"], correct:2, exp:"6 meses."},
{q:"What are the strict limitations placed on a 'Contracted Transport Manager' regarding the number of undertakings and vehicles they can manage?", options:["They can manage unlimited undertakings up to 100 vehicles total","They may not manage more than 4 undertakings, with a combined maximum total fleet of not more than 50 authorised vehicles","They may only manage 2 undertakings with a maximum of 25 vehicles each","They are restricted to a single undertaking with up to 10 vehicles"], correct:1, exp:"Máximo 4 empresas, con un total combinado de no más de 50 vehículos."},
{q:"What does the requirement of a 'stable and effective establishment' strictly prohibit?", options:["Operating vehicles over 10 years old","So-called 'letterbox' undertakings that exist via a mailing address only","Employing part-time drivers","Parking vehicles at a residential driveway overnight"], correct:1, exp:"Empresas 'buzón' que solo existen como dirección postal."},
{q:"To maintain a stable and effective establishment, an operator must always have at least how many compliant vehicles at its disposal?", options:["One","Two","Three","Five"], correct:0, exp:"Al menos uno."},
{q:"What documents must be carried on board a vehicle operating nationally under a Road Passenger Transport Operator Licence?", options:["The original Operator Licence and a photocopy of the Transport Manager's CPC","A vehicle-specific Certified Copy of the Licence and a displayed Transport Disc","A blank Journey Form and the company's annual accounts","The vehicle's original logbook (VLC) and the driver's birth certificate"], correct:1, exp:"Copia certificada de la licencia específica del vehículo y el Transport Disc."},
{q:"For international road passenger operations within the EU, what additional licensing document is issued to the operator to be kept at the base of operations?", options:["A Journey Form booklet","A Community Licence","A European Route Authorisation","A Eurovignette"], correct:1, exp:"Community Licence."},
{q:"What document must be carried on board a vehicle operating internationally under an International Road Passenger Transport Operator Licence?", options:["The original Community Licence","A Certified True Copy of the Community Licence (in addition to the Certified Copy of the Operator Licence and Transport Disc)","A translation of the driver's CPC in all EU languages","The operator's original Certificate of Incorporation"], correct:1, exp:"Copia auténtica certificada de la Community Licence."},
{q:"What is 'Bus Cabotage'?", options:["Driving a bus without passengers across an international border","The point-to-point carriage of passengers within another Member State, allowed only within the context of International passenger services","Operating a regular urban bus route exclusively within Ireland","Hiring a foreign-registered bus to operate a local school run"], correct:1, exp:"Transporte punto a punto dentro de otro Estado, en el contexto de un servicio internacional."},
{q:"In the context of International Services, what defines a 'Regular International Service'?", options:["A service carrying closed groups of tourists on an ad-hoc basis","A service providing for the carriage of passengers at specified intervals along a specified route, with predetermined stopping points, open to all","A service used exclusively by soldiers travelling between barracks","A service operating only on weekends and public holidays"], correct:1, exp:"Intervalos fijos, ruta y paradas predeterminadas, abierto a todos."},
{q:"How is an 'Occasional International Service' characterized?", options:["By adhering strictly to a published timetable and predetermined stops","By carrying groups of passengers assembled on the initiative of the customer or the carrier (e.g., closed group tours), and not meeting the definition of a Regular Service","By operating daily commuter routes across borders","By requiring individual transport tickets for every passenger boarding"], correct:1, exp:"Grupos formados por iniciativa del cliente/transportista."},
{q:"What specific document must cover an Occasional International Service?", options:["A Route Authorisation Certificate","A Journey Form (formerly called a waybill)","A Special Regular Service Contract","A Cabotage Permit"], correct:1, exp:"Journey Form (Waybill)."},
{q:"Who supplies the books of Journey Forms required for Occasional International Services in Ireland?", options:["The Road Safety Authority (RSA)","The National Transport Authority (NTA)","An Garda Síochána","The European Commission"], correct:1, exp:"NTA."},
{q:"Within what timeframe must a completed Journey Form be returned to the NTA after the journey is finished?", options:["Within 7 days","Within 14 days","Within 30 days","Within 60 days"], correct:2, exp:"30 días."},
{q:"What characterizes a 'Special Regular International Service'?", options:["Services open to the general public with compulsory reservations","Services wholly for the carriage of specific persons under a contract (e.g., workers to work, students to school), to the exclusion of all others","Hop-on hop-off tourist services","Services operated using vintage buses"], correct:1, exp:"Personas específicas bajo contrato, excluyendo a otros."},
{q:"What documentation must be carried on board for a Special Regular Service?", options:["A book of blank Journey Forms","A copy of the contract concluded between the relevant parties (organizer and carrier)","Individual transport tickets for all passengers","A letter from the Department of Education"], correct:1, exp:"Copia del contrato entre las partes."},
{q:"If an operator wishes to substitute or remove a vehicle from their licence, how must the application be made?", options:["By writing a letter to the local Garda station","Through the online licensing portal on www.rtol.ie","By emailing the NTA route licensing division","By visiting the Department of Transport in person"], correct:1, exp:"A través del portal online www.rtol.ie."},
{q:"When removing a vehicle from an Operator Licence via the RTOL portal, what must be done with the vehicle's licensing documents (Transport Disc, Certified Copies)?", options:["They must be transferred to the replacement vehicle immediately","They are to be shredded and securely disposed of","They must be returned by registered post to the Department of Transport","They must be handed into the nearest Garda station"], correct:1, exp:"Deben triturarse de forma segura."},
{q:"Under the Public Bus Passenger Service Licence categories, what is a 'Commuter Service'?", options:["A service that operates exclusively between small rural villages","An interurban service with no intermediate stops","Services to centres of employment or education provided predominantly in peak travel periods (e.g., arriving 7-10 a.m., returning 4-7 p.m.)","A hop-on hop-off tourist route operating mid-day"], correct:2, exp:"A centros de trabajo/estudio, predominantemente en horas punta."},
{q:"For how long are Regular Service Licences (issued by the NTA) typically granted?", options:["1 year","3 years","5 years","Indefinitely"], correct:1, exp:"3 años."},
{q:"What is the validity period for Demand-responsive Service Licences issued by the NTA?", options:["1 year","3 years","5 years","6 months"], correct:0, exp:"1 año."},
{q:"What is a 'Shadow Operator' in the context of the Road Transport Act 2011?", options:["A transport manager who works part-time","A person who is not the named operator but who enjoys the profits, controls, or conducts the activities of the operator directly or indirectly","An operator who only runs services at night","A sub-contractor hired for a specific school run"], correct:1, exp:"Persona que sin ser el operador nombrado, controla la actividad directa o indirectamente."},
{q:"Which of the following is considered a 'Serious Conviction' that must be notified to the Minister?", options:["A parking ticket received in a loading bay","Murder, manslaughter, drug trafficking, or money laundering","A minor speeding offence caught on camera","Failing to display a valid tax disc"], correct:1, exp:"Asesinato, homicidio, tráfico de drogas o blanqueo de capitales."},
{q:"If a driver of a Large Public Service Vehicle is directed to stop by a passenger intending to alight at a lawful stopping point, what must the driver do?", options:["Stop only if it aligns with the driver's schedule","Stop at the next point where the vehicle can lawfully be stopped for setting down passengers","Ignore the request if running late","Stop immediately in the middle of the road"], correct:1, exp:"Parar en el siguiente punto legal para dejar pasajeros."},
{q:"Under the regulations for drivers of LPSVs, what power does a driver have regarding offensive passengers?", options:["The driver can impose an on-the-spot fine","The driver has the power to exclude or request to leave any person who is in a condition likely to be offensive to passengers","The driver can arrest the passenger","The driver must ignore the situation and continue driving"], correct:1, exp:"Puede excluirlo o pedirle que se baje."},
{q:"What must the driver of an omnibus NOT do while the vehicle is moving or stopped in traffic?", options:["Check the mirrors","Enter into conversation with any other person","Announce the next stop","Operate the door controls"], correct:1, exp:"Entablar conversación con cualquier otra persona."},
{q:"What is required for an operator to carry out 'Own Account' International Transport Operations?", options:["An International Road Passenger Transport Operator Licence is strictly required","They are exempt from licensing requirements, provided the transport is an ancillary activity, non-commercial, non-profit, using owned/leased vehicles driven by staff","A Route Authorisation must be issued by the European Commission","They must submit Journey Forms for every trip"], correct:1, exp:"Exento de licencia si es actividad accesoria, no comercial, sin ánimo de lucro."},
{q:"In an application for a Regular International Service Authorisation, how long do the authorities of consulted Member States have to notify their decision?", options:["1 month","2 months","4 months","6 months"], correct:1, exp:"2 meses."},
{q:"What happens if a consulted Member State authority does not reply within the specified 2-month limit regarding an International Route Authorisation?", options:["The application is automatically rejected","The authorities consulted shall be deemed to have given their agreement","The application is suspended indefinitely","The operator is heavily fined"], correct:1, exp:"Se considera que han dado su conformidad."},
{q:"Who evaluates and manages the Garda vetting process required for establishing the 'good repute' of relevant persons in a transport undertaking?", options:["The National Transport Authority (NTA)","The Road Transport Operator Licensing Division (RTOL) / Department of Transport in conjunction with An Garda Síochána","The Revenue Commissioners","The Road Safety Authority (RSA)"], correct:1, exp:"RTOL/Dept. of Transport junto con An Garda Síochána."},
{q:"Under Statutory Instrument 265 of 2018, which of the following records must an operator keep at their business address?", options:["Only the financial accounts from the last decade","Tachograph records, working pattern records, P45s for drivers, vehicle maintenance records, and digital tachograph data for the previous 12 months","Original birth certificates of all passengers carried","Copies of every Journey Form submitted over the last 10 years"], correct:1, exp:"Registros de tacógrafo, patrones de trabajo, P45, mantenimiento y datos digitales de los últimos 12 meses."},
{q:"If the overall number of vehicles on a licence is being increased through the RTOL portal, what must be done if the previously notified financial standing does not support the additional vehicles?", options:["The operator can add the vehicles immediately and provide financial proof at the next renewal","A new financial standing document must be submitted demonstrating that the operator meets the requirements for the new total fleet size","The operator must pay a financial penalty to the Department of Transport","The operator must switch to an International Licence"], correct:1, exp:"Debe presentarse nueva prueba de solvencia para el nuevo tamaño de flota."},
{q:"Is holding a Road Passenger Transport Operator Licence proof that the holder continuously fulfills the conditions of the licence?", options:["Yes, it is absolute proof for the full 5-year term","No, holding a licence does not of itself constitute proof that the holder continues to fulfil any or all of the conditions","Yes, provided the operator has a valid tax clearance certificate","Yes, but only for National licences"], correct:1, exp:"No, tener la licencia no demuestra por sí mismo que se sigan cumpliendo las condiciones."},
{q:"Are Road Passenger Transport Operator Licences transferable to another person or company?", options:["Yes, they can be sold freely on the open market","Yes, but only to immediate family members","The licence is personal to the holder and is not transferable except when authorised by the Department of Transport","No, they must be surrendered immediately upon any change of management"], correct:2, exp:"Es personal del titular y no transferible, salvo autorización expresa."},
{q:"Which entity may direct the Road Safety Authority (RSA) to conduct a premises inspection to verify a declared address meets the 'stable and effective establishment' conditions?", options:["An Garda Síochána","The Department of Transport","The National Transport Authority (NTA)","The Revenue Commissioners"], correct:1, exp:"El Department of Transport."},
{q:"What must an operator do by the 31st of March each year regarding their establishment?", options:["Renew their Operator Licence completely","Inform the licensing authority of the number of employees in the undertaking as at 31 December of the previous year","Submit all tachograph charts to the RSA for auditing","Pay an annual franchise fee to the NTA"], correct:1, exp:"Informar del número de empleados a 31 diciembre del año anterior."},
{q:"Under the Road Traffic (Public Service Vehicles) Regulations 1963, how long is a Large Public Service Vehicle (LPSV) Licence issued by An Garda Síochána valid for?", options:["1 year","3 years","5 years","10 years"], correct:1, exp:"3 años."}
]},
"12": { title: "Tema 12 - Drivers' Records / Tachograph", questions: [
{q:"When must drivers of 'out of scope' vehicles use a tachograph?", options:["Whenever they exceed 3.5 tonnes PMW","Never; drivers of out-of-scope vehicles do not need to keep any records at all","Only when crossing international borders","Whenever operating on routes over 50 km"], correct:1, exp:"Nunca — no necesitan llevar ningún registro."},
{q:"What is the scope of EU Regulation 165/2014 regarding goods vehicles?", options:["It applies to all vehicles regardless of weight","It applies to most goods vehicles having a permissible maximum weight exceeding 3,500 kg (including any trailer)","It applies exclusively to passenger vehicles with over 16 seats","It applies only to vehicles under 3,500 kg"], correct:1, exp:"Aplica a vehículos de mercancías con MMA superior a 3,500 kg."},
{q:"How long can data relating to the use of a vehicle be stored in the mass memory of a digital tachograph Vehicle Unit (VU)?", options:["Up to 28 days","Up to 90 days","Up to one year","Up to five years"], correct:2, exp:"Hasta 1 año."},
{q:"What colour is the driver card used in digital tachographs?", options:["Yellow","Red","Blue","White"], correct:3, exp:"Blanca."},
{q:"How many days of activity can the silicon chip on a driver card hold before overwriting old data?", options:["14 days","28 days","42 days","90 days"], correct:1, exp:"28 días."},
{q:"What is the standard validity period for a driver card and a company card issued by the RSA?", options:["1 year","2 years","3 years","5 years"], correct:3, exp:"5 años."},
{q:"Within what timeframe must the RSA be informed if a driver card is lost, stolen, or damaged?", options:["Within 24 hours","As soon as possible, but certainly within a maximum of 7 days","Within 15 days","Within 28 days"], correct:1, exp:"Cuanto antes, máximo 7 días."},
{q:"What is the maximum time permitted for a driver to drive without a card if it is lost, stolen, or damaged, provided they produce manual records?", options:["Up to 15 calendar days (or longer if necessary to return to base where impossible)","Exactly 7 days","28 days","90 days"], correct:0, exp:"Hasta 15 días naturales (o más si es imposible volver a la base)."},
{q:"What must a driver do if they simply forget to bring their driver card to work on a particular day?", options:["Take manual printouts all day","They must not drive","Use a spare company card instead","Record activities on the back of an analogue chart"], correct:1, exp:"No debe conducir (olvidarla no es lo mismo que perderla)."},
{q:"What colour is the company card, and what is its primary purpose?", options:["Red; used exclusively by workshop calibration fitters","Blue; used by police enforcement officers","Yellow; acts as a 'key' to allow the operator to download VU memory and lock in/out data","White; issued to individual drivers"], correct:2, exp:"Amarilla; es la 'llave' para descargar la memoria de la VU."},
{q:"What colour is the workshop card, and who receives it?", options:["Blue; issued to RSA examiners","Red; issued to qualified individuals at approved tachograph installation and calibration centres","Yellow; issued to fleet transport managers","White; issued to trainee mechanics"], correct:1, exp:"Roja; para personal cualificado en centros autorizados."},
{q:"What colour is the control card, and what is its function?", options:["Red; used for emergency vehicle overrides","Yellow; used for remote company downloading","Blue; issued to enforcement officials (Gardai and RSA staff) to access compliance data","White; used for digital tachograph firmware updates"], correct:2, exp:"Azul; para agentes de control (Garda y RSA)."},
{q:"How frequently must digital tachographs be fully recalibrated?", options:["Every 6 months","Every year","At intervals not exceeding two years","Every five years"], correct:2, exp:"Máximo cada 2 años."},
{q:"In a digital tachograph, which card slot must the main driver use?", options:["Slot 2","Slot 1","Either slot interchangeably","The printer drawer slot"], correct:1, exp:"Ranura 1."},
{q:"How is a co-driver's activity automatically recorded on a digital tachograph when the vehicle is in motion during a double-manned operation?", options:["As driving time","As a break","As a period of availability","As other work"], correct:2, exp:"Como 'period of availability'."},
{q:"What time standard do digital tachographs use to record all activities across Europe?", options:["Local Irish Standard Time (IST)","Universal Time Co-ordinated (UTC)","Central European Time (CET)","Greenwich Mean Time minus one hour"], correct:1, exp:"UTC."},
{q:"At maximum intervals of how many days must an operator download data from the mass memory of a digital tachograph Vehicle Unit (VU)?", options:["Every 28 days","Every 42 days","Every 90 days","Every 365 days"], correct:2, exp:"Cada 90 días."},
{q:"How frequently must an operator copy data from drivers' digital tachograph cards?", options:["At least every 28 days","Every 50 days","Every 90 days","Once a year"], correct:0, exp:"Al menos cada 28 días."},
{q:"What does each completed 'V' stroke produced by the innermost distance trace on an analogue tachograph chart indicate?", options:["1 kilometre","5 kilometres","10 kilometres","20 kilometres"], correct:2, exp:"10 kilómetros."},
{q:"What does the thickest activity trace line represent on an analogue tachograph chart?", options:["Break or rest period","Other work","Driving","Period of availability"], correct:2, exp:"Conducción."},
{q:"What does the thinnest activity trace line represent on an analogue tachograph chart?", options:["Driving","Other work","Break or rest period","Vehicle acceleration"], correct:2, exp:"Pausa o descanso."},
{q:"What does the medium-thickness activity trace line represent on an analogue tachograph chart?", options:["Break","Other work (such as loading and unloading)","Maximum speed limit","Engine idling"], correct:1, exp:"Otro trabajo (ej. carga y descarga)."},
{q:"Within how many days must drivers return completed analogue tachograph charts to their employers?", options:["14 days","28 days","42 days","90 days"], correct:2, exp:"42 días."},
{q:"For how long must operators retain completed analogue tachograph charts under standard EU regulations?", options:["6 months","12 months (1 year)","2 years","5 years"], correct:1, exp:"12 meses (si se usan para Working Time, 2 años)."},
{q:"If tachograph records are also relied upon for Working Time compliance, what is the minimum retention period required?", options:["1 year","2 years","3 years","5 years"], correct:1, exp:"2 años."},
{q:"What must happen if an analogue or digital tachograph breaks down or malfunctions on a journey?", options:["The vehicle must be abandoned immediately","Manual records of work activity must be kept, and the tachograph repaired on return to base (or en route if unable to return within one week)","The driver can continue driving without records for up to 30 days","The driver must report it to the WRC within 24 hours"], correct:1, exp:"Registros manuales y reparación al volver a la base (o en ruta si no puede en 1 semana)."},
{q:"Within what operational accuracy limits must an analogue tachograph operate regarding speed?", options:["Within ±2 kph of real speed","Within ±6 kph of real speed","Within ±10 kph of real speed","Exact match with zero tolerance"], correct:1, exp:"±6 km/h."},
{q:"What is the permitted tolerance for distance recording accuracy on an analogue tachograph?", options:["Within ±1% of real distance","Within ±2% of real distance","Within ±4% of real distance","Within ±10% of real distance"], correct:2, exp:"±4%."},
{q:"What is the permitted time accuracy tolerance for a tachograph?", options:["Within ±1 minute per day","Within ±2 minutes per day, or ±10 minutes per 7 days","Within ±30 minutes per week","Zero tolerance"], correct:1, exp:"±2 min/día, o ±10 min/7 días."},
{q:"When an electronic tachograph experiences a power interruption, what does it record on the speed trace area as a warning?", options:["A blank white space","A vertical line traced right to the outer edge of the chart","A horizontal wavy line","A continuous error code number"], correct:1, exp:"Una línea vertical hasta el borde exterior del disco."},
{q:"Under Irish Domestic regulations, when are drivers completely exempt from keeping any hours of work records?", options:["When driving any vehicle over 3.5 tonnes","When the vehicle is not 'O' licensed (e.g. ≤ 3,500 kg PMW) or when driven for not more than 4 hours per day within a 50 km radius of base","When operating passenger vehicles with over 50 seats","When driving on private haulage depots"], correct:1, exp:"Vehículo sin licencia 'O' (≤3,500kg) o máximo 4h/día en 50km de radio."},
{q:"What is the basic form of record keeping required under Irish Domestic regulations when records are necessary?", options:["A digital smartcard reader","A weekly record book with duplicate pages and daily lines","Standard EU analogue tachograph charts","Monthly electronic spreadsheets submitted to the WRC"], correct:1, exp:"Libro de registro semanal con páginas duplicadas."},
{q:"For how long must employers retain domestic weekly record books?", options:["1 year","2 years","3 years","6 years"], correct:2, exp:"3 años."},
{q:"Within how many days must operators produce requested tachograph records when asked by Gardai or RSA examiners?", options:["Within 24 hours","Within 7 days","Within 10 days","Within 28 days"], correct:2, exp:"10 días."},
{q:"For how long can enforcement authorities (Gardai or RSA) retain seized driver records that they believe to be false or fraudulent?", options:["Up to 1 month","Up to 3 months","Up to six months","Up to one year"], correct:2, exp:"Hasta 6 meses."},
{q:"What is the maximum statutory court fine for record-keeping offences under transport legislation?", options:["€1,000","€3,000","€5,000","€10,000"], correct:2, exp:"€5,000."},
{q:"What severe legal charge can be brought against drivers and operators who have conspired to produce fraudulent tachograph records?", options:["Tax evasion","'Conspiracy' offences, which carry long terms of imprisonment on conviction","Reckless endangerment of aircraft","Corporate fraud under the Companies Act"], correct:1, exp:"Delito de 'conspiración', con penas largas de prisión."},
{q:"When asked by an Irish enforcement official on the road, how many preceding days must a driver be able to produce tachograph records for?", options:["Current day plus the preceding 7 days","Current day plus the preceding 14 days","Current day plus the preceding 28 calendar days","Current day plus the preceding 56 days"], correct:2, exp:"El día actual más los 28 días naturales anteriores."},
{q:"What details must a driver fill in on the centre field of an analogue tachograph chart at the *beginning* of each working day?", options:["Surname and forename, place where work began, date work began, vehicle registration number, and opening odometer reading","Only the driver's licence number and destination","The employer's tax number and total driving hours for the week","The vehicle's insurance policy number and fuel level"], correct:0, exp:"Nombre, lugar y fecha de inicio, matrícula, y cuentakilómetros inicial."},
{q:"What details must a driver enter on the centre field of an analogue tachograph chart at the *end* of the working day?", options:["Total fuel consumed and rest breaks taken","Place where work finished, date work finished, and closing odometer reading","The names of all passengers carried","The signature of the company transport manager"], correct:1, exp:"Lugar, fecha de fin, y cuentakilómetros final."}
]},
"14": { title: "Tema 14 - Vehicle Costing", questions: [
{q:"Why is historical financial accounting (such as annual profit & loss accounts) alone insufficient for vehicle costing purposes?", options:["It is rejected by Revenue Commissioners","It provides historical data long after operations end and does not pinpoint where specific profits or losses occur","It cannot be used to calculate VAT liability","It only records driver overtime expenses"], correct:1, exp:"Llega tarde y no indica DÓNDE se genera el beneficio/pérdida concreto."},
{q:"What is a 'cost unit' in transport costing?", options:["The total annual administration overhead of a fleet","An expression used to measure cost, such as cost per kilometre run or cost per tonne carried","The accounting software used by a transport manager","A specific depot location"], correct:1, exp:"Unidad de medida del coste, ej. coste por km o por tonelada."},
{q:"What is a 'cost centre'?", options:["A single gas station used for fleet refueling","An entire fleet, a particular group of vehicles, or an individual vehicle to which costs can be identified and allocated","The central administration office in Dublin","The bank account holding working capital"], correct:1, exp:"La flota, un grupo o un vehículo individual al que se le asignan costes."},
{q:"Which of the following is classified as a DIRECT cost in vehicle costing?", options:["Office staff salaries and rent","Vehicle fuel, tyres, driver wages, and vehicle insurance","Executive directors' bonuses","Office heating and lighting"], correct:1, exp:"Combustible, neumáticos, salario del conductor y seguro."},
{q:"Which of the following is an INDIRECT cost (overhead / establishment charge)?", options:["Diesel fuel","Drivers' basic wages","Office rent, rates, telephone, and administrative salaries","Vehicle tyres"], correct:2, exp:"Alquiler de oficina, tasas, teléfono, salarios administrativos."},
{q:"How are FIXED costs (standing costs) defined?", options:["Costs that vary directly with kilometres driven","Costs that do not normally vary over a given time period regardless of vehicle mileage or activity","Costs incurred only on international journeys","Fuel and lubricant expenses"], correct:1, exp:"No varían normalmente sin importar el kilometraje o actividad."},
{q:"Which of the following is a VARIABLE cost (running cost)?", options:["Vehicle motor tax","Vehicle annual depreciation","Diesel fuel and lubricants","Vehicle comprehensive insurance"], correct:2, exp:"Diésel y lubricantes."},
{q:"Which cost item is both a DIRECT cost and a VARIABLE cost?", options:["Vehicle insurance","Driver basic wage","Tyre wear","Depot property rates"], correct:2, exp:"Desgaste de neumáticos."},
{q:"Which cost item is both a DIRECT cost and a FIXED cost?", options:["Diesel fuel","Vehicle motor tax","Spare parts used in repairs","Toll charges"], correct:1, exp:"Impuesto de circulación del vehículo."},
{q:"Which five main items make up Vehicle Standing Costs?", options:["Fuel, tyres, lubricants, repairs, tolls","Vehicle tax, insurance, drivers' basic wages, depreciation, and administration costs","Drivers' overtime, ferry costs, parking, fines, tax","Rent, rates, heating, telephone, advertising"], correct:1, exp:"Impuesto, seguro, salario base, depreciación y administración."},
{q:"According to Irish commercial vehicle taxation rates for goods vehicles based on unladen weight, what is the annual tax for a vehicle over 12,001 kg unladen weight?", options:["€333","€420","€500","€900"], correct:3, exp:"€900."},
{q:"For passenger vehicles in Ireland, motor tax rates are calculated based on:", options:["Engine cubic capacity (cc)","Gross vehicle weight","Number of seats","Overall vehicle length"], correct:2, exp:"Número de asientos."},
{q:"Which insurance premium is included under Vehicle Standing Costs?", options:["Goods in Transit insurance","Motor insurance premium (Third party or Comprehensive cover for the vehicle)","Public Liability insurance for the office premises","Employer's Liability insurance for warehouse staff"], correct:1, exp:"Seguro del vehículo."},
{q:"How should initial tyre equipment supplied with a new vehicle be treated when calculating vehicle depreciation?", options:["Included fully in the vehicle purchase price for depreciation","Treated as a running cost and ALWAYS deducted from the vehicle purchase price before calculating depreciation","Written off as an administrative expense","Added to driver wages"], correct:1, exp:"Se resta del precio de compra antes de calcular la depreciación."},
{q:"An operator buys a vehicle for €85,000. The initial tyre equipment is valued at €6,875 and the estimated residual value after 5 years is €25,625. Using the straight-line method, what is the annual depreciation charge?", options:["€10,500","€11,875","€15,625","€17,000"], correct:0, exp:"(85,000−6,875−25,625)÷5 = 52,500÷5 = €10,500."},
{q:"What is the key characteristic of the Straight-Line Depreciation method?", options:["Higher depreciation charges in early years, reducing over time","An equal amount of annual depreciation is written off each year over the expected life","Depreciation is calculated solely on annual kilometres driven","Depreciation changes based on fuel price fluctuations"], correct:1, exp:"La misma cantidad cada año durante la vida útil esperada."},
{q:"What is the key characteristic of the Reducing Balance Depreciation method?", options:["Equal depreciation each year","Higher depreciation in earlier years when the vehicle drops value quickly, and less in later years","Depreciation is zero in the first year","It ignores the initial purchase price"], correct:1, exp:"Más en los primeros años, menos después."},
{q:"If 6 semi-trailers with an annual depreciation of €1,800 each are operated with 4 articulated tractor units, how much trailer depreciation is allocated to each tractor unit annually?", options:["€1,800","€2,700","€3,600","€10,800"], correct:1, exp:"6×1,800=10,800 ÷ 4 = €2,700."},
{q:"An operator has total administration overheads of €120,000 and a fleet of 15 identical vehicles. Using the Number of Vehicles basis, what is the overhead allocation per vehicle?", options:["€4,000","€6,000","€8,000","€10,000"], correct:2, exp:"120,000÷15 = €8,000."},
{q:"When allocating administration overheads using the Payload (Carrying Capacity) basis across a mixed fleet, larger capacity vehicles bear:", options:["A smaller proportion of overheads than small vans","An equal amount of overheads as small vans","A larger proportion of overheads based on their carrying capacity in tonnes","Zero overheads"], correct:2, exp:"Una proporción mayor, según su capacidad de carga."},
{q:"What is a potential drawback of allocating administration overheads solely on a Distance (Kilometre) basis?", options:["Small vans covering high mileage bear a larger share of overheads than heavy 40-tonne trucks running lower mileage","It is illegal under transport law","It overcharges heavy trucks","It cannot be calculated mathematically"], correct:0, exp:"Furgonetas pequeñas con mucho km cargan con más overhead que camiones pesados con menos km."},
{q:"Which four main components comprise Vehicle Running Costs?", options:["Tax, insurance, depreciation, admin","Fuel, lubricants, tyres, and repairs/maintenance","Overtime, tolls, ferries, subsistence","Rent, light, heat, telephone"], correct:1, exp:"Combustible, lubricantes, neumáticos y reparaciones/mantenimiento."},
{q:"Diesel fuel costs €36,000 for a group of vehicles over a month during which they cover 90,000 km. What is the fuel cost per kilometre?", options:["25 c / km","36 c / km","40 c / km (€0.40/km)","50 c / km"], correct:2, exp:"36,000÷90,000 = €0.40/km."},
{q:"A vehicle has a fuel consumption of 3 km per litre and pre-VAT diesel costs €1.20 per litre. What is the fuel cost per km?", options:["25 c / km","36 c / km","40 c / km (€0.40/km)","48 c / km"], correct:2, exp:"1.20÷3 = €0.40/km."},
{q:"A 10-wheeled vehicle requires 10 tyres costing €340 each. The estimated life of each tyre is 50,000 km. What is the tyre cost in cents per kilometre?", options:["3.4 c / km","6.8 c / km (€0.068/km)","10.0 c / km","12.0 c / km"], correct:1, exp:"(10×340)÷50,000 = €0.068/km."},
{q:"An 18-tonne vehicle incurs €60,000 for fuel, €1,000 for lubricants, €12,000 for maintenance, and €3,000 for tyres over 200,000 km. What is the total running cost in cents per kilometre?", options:["32.0 c / km","36.0 c / km","38.0 c / km (€0.38/km)","40.0 c / km"], correct:2, exp:"76,000÷200,000 = €0.38/km."},
{q:"How should drivers' overtime, night-out subsistence allowances, and toll charges generally be treated in quotation calculations?", options:["Expressed as a standard cents-per-km running cost","Added separately to the quotation as specific additional expenses","Subtracted from vehicle standing costs","Deducted from company profit margin"], correct:1, exp:"Se añaden por separado como gastos adicionales específicos."},
{q:"How is Return on Capital Employed (ROCE) calculated?", options:["(Gross Profit / Turnover) x 100","(Net Profit before tax x 100) / Capital Employed","Total Assets / Current Liabilities","Annual Standing Costs / Total Kilometres"], correct:1, exp:"Beneficio neto antes de impuestos × 100 ÷ Capital Empleado."},
{q:"A transport business has capital employed of €500,000 and total vehicle costs of €800,000. If the required profit on capital employed is 20% (€100,000), what percentage profit mark-up must be added to vehicle costs?", options:["10.0%","12.5%","15.0%","20.0%"], correct:1, exp:"100,000÷800,000 = 12.5%."},
{q:"Why is a vehicle assumed to operate for 225 days per year (45 weeks at 5 days/week) rather than 365 days when calculating daily standing costs?", options:["Due to weekend breaks, public holidays, driver annual leave, CVRT testing, and maintenance downtime","Because Irish law restricts all commercial vehicles to 225 days maximum","To artificially increase profit margins","Because fuel is not available on weekends"], correct:0, exp:"Fines de semana, festivos, vacaciones, ITV y paradas de mantenimiento."},
{q:"An operator has total annual standing costs of €58,500. Based on a vehicle utilisation of 225 working days per year, what is the daily standing cost?", options:["€160.27 / day","€225.00 / day","€260.00 / day","€300.00 / day"], correct:2, exp:"58,500÷225 = €260.00/día."},
{q:"An operator purchases a new vehicle for €52,000 with initial tyres valued at €4,000. If estimated resale value in 5 years is €6,000, what is the annual straight-line depreciation?", options:["€7,000","€8,000","€8,400","€10,400"], correct:2, exp:"(52,000−4,000−6,000)÷5 = €8,400."},
{q:"Estimated annual kilometres for a vehicle are 45,000 km and vehicle utilisation is 225 days. What is the minimum daily distance needed to recover full standing costs?", options:["150 km per day","200 km per day","225 km per day","300 km per day"], correct:1, exp:"45,000÷225 = 200 km/día."},
{q:"What is an 'Open Book' or 'Cost Plus' contract?", options:["A contract where the operator works for free","A contract where actual costs are made available in detail to the customer, who pays costs plus an agreed separate management fee","A fixed-rate cash payment contract without receipts","A contract with variable fuel pricing only"], correct:1, exp:"Costes reales visibles + una comisión de gestión pactada aparte."},
{q:"What is the primary purpose of drawing up a Rate Quotation Schedule in a transport office?", options:["To submit to the RSA for licence approval","To provide up-to-date, accurate standing and running cost rates for traffic office staff to quote profitable prices to customers","To calculate driver PAYE tax deductions","To register for VAT"], correct:1, exp:"Dar tarifas actualizadas para cotizar precios rentables."},
{q:"For a passenger coach operator selling individual tickets on an excursion, how should ticket prices be calculated if 53 seats are available but expected occupancy is 35 passengers?", options:["Divide total costs plus profit mark-up by 53","Divide total costs plus profit mark-up by 35 to ensure cost recovery and target profit","Charge double the standard train fare","Sell tickets at cost price with zero profit"], correct:1, exp:"Dividir entre 35 (ocupación esperada), no entre 53."},
{q:"What is the risk of using an arbitrary percentage surcharge on operating costs to cover administration overheads without detailed calculation?", options:["It guarantees maximum profit","It is unwise and potentially dangerous as it may under-recover actual overheads and lead to trading losses","It automatically reduces motor tax","It is prohibited by the NTA"], correct:1, exp:"Puede no cubrir los overheads reales y generar pérdidas."}
]},
"16": { title: "Tema 16 - Transport Ancillaries & Contracts of Carriage", questions: [
{q:"When an organisation wishes to transport passengers, what are the two broad options available?", options:["Domestic transport and international transport","Owned transport and hired transport","Public scheduled services and private charter only","Registered transport and unregistered transport"], correct:1, exp:"Transporte propio (owned) o contratado (hired)."},
{q:"Owned transport acquired through a hire purchase agreement legally belongs to the operator:", options:["On the day the agreement is signed","When half of the instalments are paid","When the final payment is made to the finance organisation","Only if it is registered as a goods vehicle"], correct:2, exp:"Cuando se hace el pago FINAL a la financiera."},
{q:"Which of the following is an advantage of owned transport?", options:["Complete control over vehicle specification, construction, and disposal","Avoiding tying up company capital in fixed assets","Exemption from operator licensing requirements","Elimination of maintenance costs"], correct:0, exp:"Control total sobre especificación, construcción y venta."},
{q:"What is the main financial disadvantage of owned transport?", options:["Inability to apply vehicle livery or branding","Capital of the company is tied up in fixed assets, which may cause cash flow difficulties","Inability to claim capital tax allowances","Requirement to pay double motor tax rates"], correct:1, exp:"El capital queda inmovilizado en activos fijos, causando problemas de liquidez."},
{q:"What is the simplest way for a business to obtain passenger transport without investing in vehicles or staff?", options:["Contracting out (using a professional passenger transport operator)","Purchasing vehicles on hire purchase","Operating an own-account fleet","Buying secondhand minibuses"], correct:0, exp:"Subcontratar a un operador profesional."},
{q:"Under a straightforward finance lease agreement for transport vehicles, who retains ownership of the vehicles?", options:["The transport operator","The finance / leasing organisation","The National Transport Authority (NTA)","The driver"], correct:1, exp:"La entidad financiera/de leasing."},
{q:"What is 'Contract Hire' in commercial passenger transport?", options:["A short-term daily vehicle rental without maintenance","A specialized form of leasing where the hire company provides additional services such as vehicle management, maintenance, and roadside assistance","A contract between a driver and a passenger","An agreement to sub-contract route licensing"], correct:1, exp:"Leasing con servicios añadidos: gestión, mantenimiento, asistencia."},
{q:"The legal terms and conditions under which a passenger transport operator agrees to carry passengers are known as:", options:["Articles of Association","Conditions of Carriage","Bill of Lading","Standard Operating Procedures"], correct:1, exp:"Conditions of Carriage."},
{q:"For an operator's Conditions of Carriage to be legally enforceable against a passenger, they MUST be:", options:["Sent to the Department of Transport for registration","Drawn to the attention of potential customers before the contract is formed","Printed on the back of every driver's CPC card","Approved by An Garda Síochána"], correct:1, exp:"Puestas en conocimiento del cliente ANTES de formar el contrato."},
{q:"Can an operator include a clause in their Conditions of Carriage excluding liability for personal injury or death caused to passengers?", options:["Yes, provided it is printed in bold lettering","No, operators cannot override legal statutory obligations or limit liability for passenger injury","Yes, if agreed by the local authority","Only on international journeys"], correct:1, exp:"No, no puede excluir/limitar esa responsabilidad."},
{q:"How does liability for damaged passenger luggage differ from liability for passenger injury under Conditions of Carriage?", options:["There are no statutory legal requirements limiting an operator's ability to specify their liability regarding damaged luggage","Luggage liability is unlimited by EU law","Operators are prohibited from accepting any liability for luggage","Luggage is covered by the Road Traffic Act 1961 automatically up to €10,000"], correct:0, exp:"No hay requisitos legales que limiten cómo especificar la responsabilidad sobre el equipaje."},
{q:"Which statute governs how passenger transport operators in Ireland must deal with lost property found on vehicles?", options:["Transport Act 1950","Road Traffic Act 1961","Consumer Protection Act 2007","Data Protection Act 2018"], correct:1, exp:"Road Traffic Act 1961."},
{q:"What is a 'Sub-contractor' in passenger transport operations?", options:["An agent paid a commission to find customers","An operator who enters into an agreement with another operator to fulfil part or all of that operator's contract","A driver employed on a part-time basis","A vehicle maintenance garage"], correct:1, exp:"Operador que acuerda con otro cumplir parte/todo su contrato."},
{q:"If Operator A sub-contracts a school transport contract to Operator B, and Operator B fails to run the service, who remains legally liable to the local authority client?", options:["Operator B only","Operator A (the original contractor) remains wholly responsible and liable to the client","Neither operator, as sub-contracting cancels liability","The driver assigned to the vehicle on that day"], correct:1, exp:"A (el contratista original) sigue siendo totalmente responsable."},
{q:"Does the main operator have a legal duty to disclose to a sub-contractor the price being charged to the end customer?", options:["Yes, full financial transparency is required by law","No, the operator has no need to reveal the amount charged to the customer","Only if the sub-contract value exceeds €50,000","Only if requested by the National Transport Authority"], correct:1, exp:"No, no tiene obligación legal de revelarlo."},
{q:"If a sub-contractor (Operator B) fails to complete a journey, can they sub-contract the work further to Operator C?", options:["No, sub-contracting a sub-contract is strictly illegal","Yes, sub-contractors may sub-contract to another operator unless prohibited by contract, but remain liable to the original operator","Yes, and all liability transfers automatically to Operator C","Only with written permission from the Minister for Transport"], correct:1, exp:"Sí, salvo que el contrato lo prohíba — pero B sigue siendo responsable ante A."},
{q:"Can an operator hold a Restricted PSV Licence and hire in a vehicle larger than 16 seats?", options:["Yes, provided it is hired with a driver (which constitutes standard sub-contracting)","Yes, without any restrictions or drivers","No, restricted licence holders cannot operate large vehicles under any circumstances","Only on public holidays"], correct:0, exp:"Sí, siempre que se alquile CON conductor."},
{q:"What is the legal definition of an 'Agent' in transport contracts?", options:["A person employed to drive passenger vehicles","A person who possesses authority to act on behalf of another person (the principal) to establish contractual relationships with third parties","An official from the Road Safety Authority","A sub-contractor providing extra coaches"], correct:1, exp:"Persona con autoridad para actuar en nombre de otra (el principal)."},
{q:"How is an agent normally compensated for contract-making duties on behalf of a principal?", options:["Fixed monthly salary from the State","Payment of a commission","Direct shareholding in the principal's company","Exemption from road tolls"], correct:1, exp:"Con una comisión."},
{q:"If an agent acts OUTSIDE the scope of their delegated authority when making a contract with a third party:", options:["The principal is automatically bound to honour the contract anyway","The principal is NOT bound to honour the contract, and the agent may be sued by the third party for breach of warranty of authority","The contract is transferred to the RSA","The third party receives double compensation from the government"], correct:1, exp:"El principal NO está obligado, y el agente puede ser demandado."},
{q:"If an agent makes secret profits behind the back of the principal while carrying out activities on their behalf:", options:["The agent is entitled to keep the profits as bonus pay","The principal may sue the agent to recover the secret profits","The profit must be paid as corporate tax to Revenue","The contract becomes automatically void for the third party"], correct:1, exp:"El principal puede demandarlo para recuperar esos beneficios."},
{q:"Ace Transport contracts to carry sea anglers for Jack Ltd, but has no vehicles available and hires Ridgeway to do the work. Ridgeway is:", options:["A common carrier","An authorised agent","An alternative contractor","A sub-contractor"], correct:3, exp:"Un subcontratista."},
{q:"Principals may reject a contract agreed by their authorised agents if:", options:["The principal does not wish to be bound by that particular contract","The agent acts outside his or her authority","The principal did not sign the contract before it was agreed","Whenever the principal wishes to"], correct:1, exp:"Si el agente actuó fuera de su autoridad."},
{q:"Social Club B hires Operator A to carry passengers to a theatre. Operator A sub-contracts to Operator C, who fails to pick up the passengers. What is the legal position?", options:["B should sue A, who was the original contractor","B should sue C, who should have completed the work","B can sue both A and C since both were party to the movement","B will rely on A to sue C to recover damages"], correct:0, exp:"B debe demandar a A (el contratista original)."},
{q:"A main contractor who sub-contracts work to a third party:", options:["Is not liable if the sub-contractor undertakes full responsibility","Remains fully liable to the customer for the completion of the contract","Is no longer liable to the customer","Is liable only if the sub-contract is in writing"], correct:1, exp:"Sigue siendo totalmente responsable ante el cliente."},
{q:"A local supporters' club hires 15 coaches from Bloggs Coaches. Bloggs sub-contracts 7 coaches to another operator, who fails to supply 4 coaches. The supporters' club has legal redress against:", options:["The football club","Bloggs Coaches","The sub-contractor directly","Both Bloggs Coaches and the sub-contractor"], correct:1, exp:"Contra Bloggs Coaches (no relación contractual directa con el subcontratista)."},
{q:"Operator Smith contracts with Jones for a journey at €300. Jones sub-contracts to Green at €220. Green discovers Jones was paid €300. Green:", options:["Has grounds to sue Jones for a secret profit","Has grounds to claim another €80 from Jones","Has grounds to claim another €80 from Smith","Has no grounds to claim against Jones"], correct:3, exp:"No tiene ningún derecho a reclamar (no hay obligación de transparencia de precios)."},
{q:"If an operator's fleet is fully committed but additional work is accepted:", options:["The operator may sub-contract without informing the sub-contracted operator of the price obtained from the customer","The operator must inform the sub-contractor of the customer price","The operator must advise the customer of the sub-contractor's price","The job cannot be sub-contracted"], correct:0, exp:"Puede subcontratar sin informar de ese precio."},
{q:"An agent appointed to arrange carriage in the Midlands makes an unauthorized contract in Connaught for the operator. The operator:", options:["Must honour the contract","Need only honour it if in writing","Cannot sub-contract the work","Need not honour the contract because the agent exceeded authority"], correct:3, exp:"No tiene por qué cumplirlo, porque el agente excedió su autoridad."},
{q:"A passenger on a local bus service claims late running caused them to miss an appointment, incurring €100 costs. What is the operator's liability?", options:["Not liable under any circumstances","Liable for the full €100","Governed by whatever is stated in the operator's Conditions of Carriage (subject to legal limits)","Determined by a loss adjuster"], correct:2, exp:"Depende de lo que digan las Conditions of Carriage (sujeto a límites legales)."},
{q:"Which TWO statements regarding the conduct of a driver on a one-person operated local bus service are correct? 1. The driver must ensure the correct route number and destination are displayed 2. At a changeover point, the driver may leave the vehicle unattended on a public road 3. It is not permissible for the driver to use force to remove an unruly passenger 4. If requested by an RSA examiner, the driver must provide the name and address of the operator", options:["1 and 4 only","2 and 3 only","1 and 3 only","2 and 4 only"], correct:0, exp:"1 y 4: mostrar bien ruta/destino, y dar nombre/dirección del operador si lo pide un examinador."},
{q:"A PSV driver arrives at a bus stop with a queue of passengers carrying pushchairs, but space allows for only some pushchairs to be stored safely. The driver should:", options:["Permit all passengers, storing pushchairs at the rear","Permit all passengers, storing pushchairs at the front","Permit only those passengers whose pushchairs fit in the designated storage space","Permit none of the passengers with pushchairs"], correct:2, exp:"Solo a los que quepan en el espacio designado."},
{q:"What is the status of PSV Conduct Regulations in Ireland?", options:["They apply to drivers, conductors, inspectors, and passengers, setting out rules of acceptable conduct and powers of crew","They apply only to private hire tour operators","They apply exclusively to international journeys","They are non-binding guidelines issued by trade unions"], correct:0, exp:"Aplican a conductores, cobradores, inspectores y pasajeros."},
{q:"Under PSV Conduct Regulations, can a bus driver use physical force to eject an unruly or disruptive passenger?", options:["Yes, drivers have full legal immunity to use force","No, drivers must not use physical force; they should request the passenger to leave or call An Garda Síochána","Yes, provided other passengers assist","Only on double-deck buses"], correct:1, exp:"No, debe pedirle que se baje o llamar a la Garda."},
{q:"Which of the following is a key advantage of relying on hired transport / carriers?", options:["Retaining 100% direct operational control over drivers","No capital tied up in vehicles, no need for operator licensing, and ability to adjust capacity quickly","Ability to claim vehicle depreciation tax write-offs","Guaranteed lowest market costs at all times"], correct:1, exp:"Sin capital inmovilizado, sin licencia propia, y ajuste rápido de capacidad."},
{q:"What is the main risk of relying heavily on 'spot hire' carriers for passenger transport?", options:["Loss of direct operational control and dependence on the contractor's standards and reliability","Mandatory registration with Revenue for each journey","Automatic forfeiture of the operator licence","Increased vehicle tax rates"], correct:0, exp:"Pérdida de control operativo y dependencia del contratista."},
{q:"A clause in a contract of carriage stating that Irish courts have exclusive jurisdiction to settle disputes relates to:", options:["Severability","Law and Jurisdiction","Data Protection","Force Majeure"], correct:1, exp:"'Law and Jurisdiction'."},
{q:"What happens if a specific clause in an operator's Conditions of Carriage is held by a court to be illegal or unenforceable?", options:["The entire contract becomes null and void","The illegal clause is severed/deleted, while the remainder of the carriage contract remains valid and unaffected","The operator must pay a fixed fine of €5,000 to the NTA","The passenger travels for free for 12 months"], correct:1, exp:"Se elimina esa cláusula (severability), el resto sigue válido."},
{q:"What is the legal term for a party appointing an agent to negotiate contracts on their behalf?", options:["The Sub-contractor","The Principal","The Bailee","The Beneficiary"], correct:1, exp:"El 'Principal'."},
{q:"When an operator displays a notice on bus tickets stating 'Passengers are carried subject to conditions', this serves to:", options:["Exempt the operator from all road safety laws","Draw the passenger's attention to the Conditions of Carriage, making them legally binding if available on request","Replace the need for commercial motor insurance","Cancel the passenger's right to a seat"], correct:1, exp:"Llama la atención sobre las Conditions of Carriage, haciéndolas vinculantes."}
]},
"17": { title: "Tema 17 - Electronic Data / Telematics / IT", questions: [
{q:"What is 'software' in relation to electronic data systems?", options:["The physical computers and screens","The silicon microchips contained within computers","The programs and applications that run on computers","The printed output produced by printers"], correct:2, exp:"Los programas y aplicaciones que corren en el ordenador."},
{q:"What is 'hardware' in computer and fleet telematics terminology?", options:["The operational procedures written by the manager","The physical equipment, computers, sensors, and wiring","The mobile network subscription contract","The databases storing driver hours"], correct:1, exp:"El equipo físico: ordenadores, sensores, cableado."},
{q:"Transport companies must comply with Data Protection legislation (GDPR / Data Protection Act 2018) if they store computer records containing:", options:["General financial budgets of the business","Registers of company shareholders","Personal information about living individuals (such as employees or passengers)","Non-personal vehicle technical specifications"], correct:2, exp:"Datos personales de personas vivas."},
{q:"What is the maximum time limit under GDPR for a data controller (employer) to respond to an employee's Subject Access Request (SAR)?", options:["7 days","14 days","30 days (1 month)","90 days"], correct:2, exp:"30 días (1 mes)."},
{q:"The term given to remote measurement of vehicle data using transmitters to send information back to a central base station is:", options:["Telephony","Telemetry","Psychometry","Numerology"], correct:1, exp:"Telemetry."},
{q:"The technology fitted to vehicles that uses satellites to enable operators to track real-time vehicle location is known as:", options:["Global Positioning System (GPS) / GNSS","Eurostat","Realtime Messaging","Ordnance Survey Mapping"], correct:0, exp:"GPS/GNSS."},
{q:"Modern passenger vehicles utilize an internal computer network connecting electronic control units, sensors, and actuators known as:", options:["Telemetry link","CANbus (Controller Area Network)","Electronic Data Interchange (EDI)","Internet Protocol (IP)"], correct:1, exp:"CANbus."},
{q:"Computer technologies that provide continuous streams of live operational data without delay are referred to as:", options:["Real-time systems","Batch processing systems","Barcode scanners","Offline archiving"], correct:0, exp:"Sistemas en tiempo real."},
{q:"Which TWO of the following technologies can be utilized by a bus operator to directly improve DRIVER security? 1. Closed Circuit Television (CCTV) on vehicles 2. Panic buttons / driver alert systems linked to telematics 3. Electronic arrival displays at bus stops 4. Off-bus ticketing applications", options:["1 and 2 only","3 and 4 only","2 and 3 only","1 and 4 only"], correct:0, exp:"CCTV en el vehículo + botones de pánico/alerta."},
{q:"In passenger transport, what is the primary operational advantage of Electronic Ticket Machines (ETMs) compared to manual ticket boxes?", options:["They completely eliminate the need for motor insurance","They reduce driver error/fraud, calculate correct fares automatically, and record passenger boarding data accurately","They increase the vehicle's top speed","They automatically pay vehicle motor tax online"], correct:1, exp:"Reducen fraude/error, calculan tarifas correctamente y registran datos de embarque."},
{q:"What is 'Telematics' in modern commercial vehicle fleet management?", options:["The use of traditional paper logbooks for recording vehicle mileage","The integration of telecommunications and informatics to send, receive, and store information relating to remote vehicles","A legal requirement to test vehicle emissions monthly","The manual process of calculating driver overtime"], correct:1, exp:"Integración de telecomunicaciones e informática para vehículos remotos."},
{q:"How does the CANbus system assist fleet managers in monitoring driver performance?", options:["By taking photographs of the driver's driving licence","By collecting data on engine revving, gear usage, harsh braking, acceleration, and cruise control usage","By automatically paying road tolls from the company bank account","By replacing the need for tachograph cards"], correct:1, exp:"Datos de revoluciones, uso de marchas, frenadas bruscas y aceleración."},
{q:"What feature of Smart Tachograph Version 2 (GEN2 V2) relies on satellite communication (GNSS) technology?", options:["Automatic recording of border crossings and vehicle position every 3 hours of accumulated driving","Remote engine shutdown by Gardai","Automatic washing of vehicle windshields","Wireless payment of passenger fares"], correct:0, exp:"Registro automático de cruces de frontera y posición cada 3h."},
{q:"How long must tachograph data and driver activity records generally be retained by operators under data protection and transport regulations?", options:["At least 1 year (2 years if used for Working Time Directive compliance)","30 days maximum","5 years","Indefinitely"], correct:0, exp:"Al menos 1 año (2 si se usan para Working Time)."},
{q:"What technology enables roadside enforcement officers (RSA/Gardai) to detect potential tachograph violations while the vehicle is in motion?", options:["DSRC (Dedicated Short-Range Communication)","Bluetooth Low Energy","FM Radio Broadcasting","Wi-Fi Hotspots"], correct:0, exp:"DSRC."},
{q:"How can mobile app-based electronic driver walkaround check systems benefit a passenger transport operator?", options:["They automatically fix mechanical defects on the road","They ensure daily checks are completed before use, transmit defects in real-time, and provide an auditable digital compliance trail for RSA inspections","They exempt the operator from annual CVRT testing","They allow drivers to bypass pre-trip checks when running late"], correct:1, exp:"Aseguran la revisión diaria, transmiten defectos y crean un rastro digital auditable."},
{q:"Under GDPR rules in Ireland, an employer holding driver performance and telematics data is legally categorized as a:", options:["Data Processor","Data Controller","Data Protection Officer","Data Subject"], correct:1, exp:"Data Controller."},
{q:"What is the main purpose of CCTV cameras installed inside passenger buses pointing towards the driver's cab?", options:["To monitor driver facial expressions for marketing purposes","To enhance driver safety, deter physical assaults/robberies, and provide evidence for incident investigations","To verify ticket prices charged to passengers","To check if the driver is complying with uniform policies"], correct:1, exp:"Mejorar la seguridad del conductor y aportar pruebas."},
{q:"Which system allows remote workshop technicians to diagnose vehicle engine fault codes without physically connecting diagnostic cables?", options:["Remote Diagnostics / Over-The-Air (OTA) diagnostics","Manual pressure testing","Analog telemetry","Automated weighbridges"], correct:0, exp:"Diagnóstico remoto/OTA."},
{q:"What is a key benefit of integrating fleet telematics with fuel management systems?", options:["Automatic reimbursement of VAT from Revenue","Tracking fuel consumption per vehicle/driver to identify inefficiencies, driver training needs, and fuel theft","Reducing diesel tax rates automatically","Eliminating the need for engine oil changes"], correct:1, exp:"Rastrear consumo por vehículo/conductor para detectar ineficiencias."},
{q:"What technology is used at passenger bus stops to display real-time arrival estimates to waiting passengers?", options:["Real-Time Passenger Information (RTPI) linked to vehicle GPS tracking","Static paper timetables updated yearly","Automated telephone answering machines","Manual radio broadcasts"], correct:0, exp:"RTPI ligado al GPS."},
{q:"Smart cards used in passenger transport (such as TFI Leap Card) operate primarily on which technology principle?", options:["Contactless RFID / NFC smartcard chip reading","Magnetic tape swipe only","Paper barcode stamping","Manual visual inspection by the conductor"], correct:0, exp:"RFID/NFC contactless."},
{q:"When deploying driver-facing inward cameras or AI-based fatigue monitoring tools, what extra GDPR requirement must operators satisfy?", options:["Written authorization from the European Parliament","Documented justification (Data Protection Impact Assessment - DPIA) and clear privacy safeguards due to monitoring personal/sensitive driver data","Exemption from all national privacy laws","Annual fees paid to the Data Protection Commission"], correct:1, exp:"Una DPIA documentada y garantías claras de privacidad."},
{q:"What type of software system integrates order entry, route planning, fleet tracking, invoicing, and compliance management into a single platform?", options:["Transport Management System (TMS)","Electronic Point of Sale (EPOS)","Computer Aided Design (CAD)","Electronic Data Interchange (EDI)"], correct:0, exp:"Transport Management System (TMS)."},
{q:"What cybersecurity measure should transport operators implement to protect cloud-based TMS and telematics portals from unauthorized access?", options:["Multi-Factor Authentication (MFA) and strong password policies","Storing all passwords on printed sticky notes","Disabling all firewall protection","Allowing open public Wi-Fi access to fleet servers"], correct:0, exp:"Autenticación multifactor (MFA)."},
{q:"Automatic Number-Plate Recognition (ANPR) cameras used by enforcement authorities can instantly check:", options:["The driver's personal bank balance","Whether a vehicle has a valid CVRT/CRW, motor tax, and its operator risk profile (CVORI)","The number of passengers on board","The remaining fuel level in the vehicle tank"], correct:1, exp:"CVRT/CRW, impuesto, y perfil de riesgo del operador."},
{q:"What is the function of an Electronic Data Interchange (EDI) system in commercial transport operations?", options:["Allowing different computer systems to exchange standardized business documents (invoices, orders) electronically without human intervention","Printing physical tachograph charts automatically","Measuring tire tread depth remotely","Regulating engine coolant temperature"], correct:0, exp:"Intercambio de documentos de negocio estandarizados sin intervención humana."},
{q:"In case study scenarios, if drivers fail to complete daily walkaround checks adequately leading to RSA warnings, what technology solution should the Transport Manager introduce?", options:["Paper defect books stored in the office","An app-based electronic driver walkaround check system with mandatory digital defect reporting","GPS tracking units on trailers only","Automated speed limiters"], correct:1, exp:"App de revisión diaria con reporte digital obligatorio."},
{q:"If a transport manager notices significant fuel economy differences between drivers operating identical vehicles, what system helps resolve the issue?", options:["Telematics linked to CANbus data and fuel management software to monitor driving behavior and target eco-drive training","Replacing all vehicle tires monthly","Increasing passenger fare prices","Installing larger fuel tanks"], correct:0, exp:"Telemática ligada al CANbus y software de gestión de combustible."},
{q:"Under Data Protection law, an individual whose personal data is collected and stored by a transport company is known as the:", options:["Data Controller","Data Processor","Data Subject","Data Protection Officer"], correct:2, exp:"Data Subject."},
{q:"How does real-time GPS tracking benefit traffic management offices during service disruptions or road closures?", options:["It automatically removes traffic congestion","It allows controllers to re-route vehicles dynamically and provide updated ETAs to passengers","It cancels all passenger ticket refunds","It resets driver tachograph driving hours"], correct:1, exp:"Redirigir vehículos dinámicamente y dar ETAs actualizadas."},
{q:"What is a key advantage of cloud-based fleet software over traditional local desktop software?", options:["Data can be accessed securely from any location with an internet connection and is backed up automatically","It eliminates the need for internet connectivity","It requires no passwords or security checks","It is completely exempt from GDPR rules"], correct:0, exp:"Acceso seguro desde cualquier lugar, con copia de seguridad automática."},
{q:"What feature of modern ETMs allows operators to update fare structures across an entire fleet rapidly?", options:["Centralized remote/overnight memory programming without manually reconfiguring each machine","Replacing physical ticket machines in every bus","Manual re-keying of fares by drivers at every bus stop","Sending paper fare charts by post to all drivers"], correct:0, exp:"Programación remota/centralizada."},
{q:"Video telematics systems combining forward-facing cameras and CANbus data are primarily used to:", options:["Provide evidence for insurance claims and assist driver safety coaching following incidents","Stream live entertainment to passengers","Measure vehicle unladen weight","Automatically issue traffic fines to other road users"], correct:0, exp:"Pruebas para reclamaciones de seguro y coaching de seguridad."},
{q:"What risk arises if an operator stores unencrypted employee personal data on unprotected laptop computers?", options:["Reduced fuel efficiency","Severe data breach risks leading to regulatory fines under GDPR and reputational damage","Loss of vehicle motor tax entitlement","Automatic tachograph failure"], correct:1, exp:"Riesgo grave de brecha de datos, multas GDPR y daño reputacional."},
{q:"In the context of zero-emission electric buses, telematics systems monitor:", options:["State of charge (SoC), battery health, energy consumption (kWh/km), and regenerative braking efficiency","Engine oil viscosity","Exhaust gas recirculation rates","Diesel fuel density"], correct:0, exp:"Estado de carga, salud de batería, consumo y frenado regenerativo."},
{q:"What is the legal obligation regarding data retention for employee HR and payroll records in Ireland?", options:["Records must be deleted immediately after payment","Retained for at least 6 years to satisfy Revenue and Employment Equality law requirements","Retained for 30 days only","Retained indefinitely without backup"], correct:1, exp:"Al menos 6 años."},
{q:"Why is 'Information for its own sake' considered a waste of time and money in fleet management?", options:["Technology is completely free of charge","Data must be captured, analyzed, and translated into actionable management decisions to add real business value","Data protection laws prohibit storing any data","Transport managers are not allowed to view vehicle data"], correct:1, exp:"Los datos deben traducirse en decisiones de gestión útiles."},
{q:"What type of card scanner technology is widely used in depot fuel dispensers to track fuel issued to specific vehicles and drivers?", options:["Smart card / RFID fob automated fuel issue systems","Manual paper signature pads only","Optical character readers for paper receipts","Coin-operated slot meters"], correct:0, exp:"Sistemas automáticos con tarjeta inteligente/llavero RFID."},
{q:"How does modern IT integration improve compliance with Operator Licensing requirements?", options:["By linking maintenance job cards, driver daily defect reports, and tachograph audit data into an auditable compliance dashboard","By allowing operators to run vehicles without valid CRWs","By eliminating the requirement to employ a Transport Manager","By automatically passing RSA premises audits without inspection"], correct:0, exp:"Uniendo fichas de mantenimiento, reportes de defectos y auditoría del tacógrafo en un panel."}
]},
"18": { title: "Tema 18 - Weights and Dimensions (incompleto)", questions: [
{q:"What is the maximum permissible weight transmitted by a single axle (whether with single or twin tyres) on a passenger or commercial vehicle in Ireland?", options:["8.5 tonnes","10.0 tonnes","11.5 tonnes","12.0 tonnes"], correct:1, exp:"10.0 toneladas."},
{q:"What is the maximum permissible weight for a sole driving axle fitted with twin tyres and air suspension (or an equivalent system)?", options:["10.0 tonnes","10.5 tonnes","11.5 tonnes","13.0 tonnes"], correct:2, exp:"11.5 toneladas."},
{q:"What is the maximum gross vehicle weight (GVW) for a standard two-axle bus in Ireland?", options:["18.0 tonnes","19.0 tonnes","19.5 tonnes","25.0 tonnes"], correct:2, exp:"19.5 toneladas."},
{q:"What is the maximum gross vehicle weight (GVW) for a standard three-axle bus?", options:["24.0 tonnes","25.0 tonnes (or up to 26 tonnes under specific conditions like air suspension/twin tyres)","28.0 tonnes","32.0 tonnes"], correct:1, exp:"25.0 toneladas (hasta 26 en condiciones específicas)."},
{q:"What is the maximum gross vehicle weight for a three-axle articulated bus?", options:["25.0 tonnes","26.0 tonnes","28.0 tonnes","30.0 tonnes"], correct:2, exp:"28.0 toneladas."},
{q:"What is the maximum length permitted for a two-axle bus?", options:["12.0 meters","13.5 meters","15.0 meters","18.75 meters"], correct:1, exp:"13.5 metros."},
{q:"What is the maximum length permitted for a bus having more than two axles?", options:["13.5 meters","15.0 meters","16.5 meters","18.75 meters"], correct:1, exp:"15.0 metros."},
{q:"What is the maximum length permitted for an articulated bus?", options:["15.0 meters","16.5 meters","18.75 meters","20.0 meters"], correct:2, exp:"18.75 metros."},
{q:"What is the maximum overall width permitted for passenger vehicles having a seating capacity for more than eight passengers (buses and coaches)?", options:["2.50 meters","2.55 meters","2.60 meters","2.75 meters"], correct:1, exp:"2.55 metros."},
{q:"What is the maximum overall height permitted for commercial vehicles and buses in Ireland?", options:["4.00 meters","4.20 meters","4.65 meters","There is no maximum height limit specified"], correct:2, exp:"4.65 metros."}
]},
"19": { title: "Tema 19 - Plating & Testing", questions: [
{q:"What is the primary objective of vehicle plating and statutory testing in Ireland?", options:["To determine motor tax rates and fuel efficiency","To ensure commercial vehicles are safe, roadworthy, and operated within design weight limits","To record vehicle ownership transfer with An Garda Síochána","To verify driver CPC qualification cards"], correct:1, exp:"Garantizar que los vehículos sean seguros y operen dentro de sus límites de peso de diseño."},
{q:"Which authority holds primary legal responsibility for commercial vehicle roadworthiness and testing in Ireland?", options:["National Transport Authority (NTA)","Road Safety Authority (RSA)","Department of Transport","Revenue Commissioners"], correct:1, exp:"RSA."},
{q:"What does 'Plating' certify on a commercial vehicle?", options:["The vehicle's insurance category","The official maximum permitted weights (GVW, GTW, Axle weights) certified by the manufacturer or RSA","The maximum passenger fare structure","The registration date of the imported chassis"], correct:1, exp:"Pesos máximos oficiales permitidos."},
{q:"Where is the manufacturer's weight plate typically located on a passenger coach or commercial vehicle?", options:["Displayed on the rear bumper","Located in the cab, passenger doorway, or engine bay","Attached to the driver's seat","On the roof next to the air conditioning unit"], correct:1, exp:"En la cabina, puerta de pasajeros o compartimento del motor."},
{q:"What maximum weight figures are mandatory on a vehicle weight plate?", options:["Gross Vehicle Weight (GVW), Gross Train Weight (GTW) where applicable, and Maximum permitted axle weights","Fuel tank capacity, engine displacement, and oil capacity","Vehicle length, width, and passenger seating capacity only","Purchase price, depreciation rate, and unladen weight"], correct:0, exp:"GVW, GTW y pesos máximos por eje."},
{q:"What is the legal consequence of operating a vehicle in excess of its plated weight limits?", options:["Minor warning only","Offences resulting in fines, penalty points, vehicle detention, prohibition, or prosecution","Temporary suspension of passenger fares","Mandatory free vehicle re-inspection"], correct:1, exp:"Multas, puntos, detención, prohibición o procesamiento."},
{q:"When is a re-plating certificate issued by the RSA required?", options:["Every time the vehicle passes its annual CVRT","When a vehicle is imported, structurally modified, or altered in a way that changes its weight or axle configuration","When changing the vehicle's paint colour or logo","Every 5 years upon operator licence renewal"], correct:1, exp:"Al importar, modificar estructuralmente o cambiar peso/ejes."},
{q:"If a passenger coach has extra luggage racks and passenger comfort equipment fitted, increasing its unladen weight, what action must the Transport Manager take?", options:["No action required as long as tyres are inflated","Have the vehicle re-weighed, checked, and properly re-plated/certified to reflect updated weight details","Reduce passenger seating by 5 seats automatically","Pay additional motor tax to the local council"], correct:1, exp:"Repesar y obtener el re-plating actualizado."},
{q:"What regime governs statutory roadworthiness testing for commercial vehicles in Ireland?", options:["National Car Test (NCT)","Commercial Vehicle Roadworthiness Test (CVRT)","RSA Maintenance Audit","Garda Vehicle Inspection Scheme"], correct:1, exp:"CVRT."},
{q:"Which passenger vehicles are subject to mandatory CVRT testing?", options:["Buses and coaches used for hire and reward, including all vehicles with more than 8 passenger seats","Private passenger cars used for commuting","Taxis under 4 passenger seats only","Motorcycles and light quadricycles"], correct:0, exp:"Buses/autocares de hire and reward de +8 asientos."},
{q:"How often must buses, coaches, and minibuses (more than 8 passenger seats) undergo CVRT testing?", options:["Every 6 months","Annually (every 12 months), starting when the vehicle is one year old","Every 2 years","Every 3 years"], correct:1, exp:"Anualmente, desde el año de edad."},
{q:"When is the FIRST statutory CVRT test required for a newly registered bus or commercial vehicle in Ireland?", options:["At 6 months of age","When the vehicle reaches 1 year (12 months) of age","At 2 years of age","Prior to its first registration"], correct:1, exp:"Al año de edad."},
{q:"What document is issued electronically and physically following a successful CVRT test?", options:["Certificate of Conformity","Certificate of Roadworthiness (CRW)","Operator Licence Disc","Vehicle Registration Certificate (VLC)"], correct:1, exp:"CRW."},
{q:"Is a valid Certificate of Roadworthiness (CRW) required to tax a commercial vehicle or bus in Ireland?", options:["No, CRW is completely independent of motor tax","Yes, a valid CRW is a mandatory legal pre-condition for motor taxation and lawful operation","Only for vehicles over 10 years old","Only for vehicles operating internationally"], correct:1, exp:"Sí, es requisito legal obligatorio."},
{q:"What are the key areas examined during a standard CVRT test?", options:["Braking systems, steering and suspension, tyres/wheels, lights, chassis condition, exhaust emissions, tachograph, and speed limiter","Passenger ticket prices and driver uniform cleanliness","Vehicle audio systems and interior upholstery colour","Company balance sheets and tax returns"], correct:0, exp:"Frenos, dirección/suspensión, neumáticos, luces, chasis, emisiones, tacógrafo y limitador."},
{q:"Does passing an annual CVRT test exempt the operator from maintaining the vehicle between tests?", options:["Yes, passing the test guarantees compliance for 12 months","No, the annual test represents a minimum legal standard; operators must maintain vehicles in a roadworthy condition continuously throughout the year","Yes, provided daily mileage is under 100 km","Only if the vehicle is covered by manufacturer warranty"], correct:1, exp:"Es solo un estándar mínimo periódico, no exime del mantenimiento continuo."},
{q:"How are CVRT test failures categorised?", options:["Low, Medium, High","Minor defects (pass with advisory notes), Major defects (fail, re-inspection required), and Dangerous defects (vehicle must not be driven until rectified)","Retest required, Scrap vehicle, Legal fine","Category A, Category B, Category C"], correct:1, exp:"Menores, mayores y peligrosos."},
{q:"What must be done if a vehicle receives a 'Dangerous Defect' result during a CVRT or roadside inspection?", options:["The vehicle may be driven back to base at low speed","The vehicle must NOT be driven on public roads under any circumstances until the defect is fully rectified","The driver can continue the journey if passengers agree","The defect must be repaired within 14 days while remaining in service"], correct:1, exp:"No puede conducirse hasta reparar el defecto."},
{q:"Who has legal responsibility for ensuring fleet vehicles remain continuously roadworthy and compliant with plating and testing rules?", options:["The RSA test center inspectors","The Transport Manager and the Transport Operator","The vehicle manufacturer","The insurance company"], correct:1, exp:"El Transport Manager y el operador."},
{q:"Under Regulation (EC) No 1071/2009, how can repeated failures in plating, testing, and vehicle maintenance affect a Transport Manager?", options:["It results in a small reduction in monthly salary","It can compromise the Transport Manager's 'good repute', leading to disqualification or loss of professional standing","It requires the Transport Manager to retake the driving test","It has no personal impact on the Transport Manager"], correct:1, exp:"Puede comprometer su buena reputación, con descalificación."},
{q:"Which enforcement bodies carry out roadside inspections of commercial passenger vehicles in Ireland?", options:["An Garda Síochána and RSA Vehicle Inspectors","Revenue Commissioners and Customs","Health and Safety Authority (HSA) only","Local County Council traffic wardens"], correct:0, exp:"An Garda Síochána y examinadores de la RSA."},
{q:"Who is legally authorised to stop a moving vehicle on a public road for a roadside compliance check?", options:["RSA Vehicle Inspectors acting alone","Members of An Garda Síochána","NTA Enforcement Officers","Workshop mechanics"], correct:1, exp:"Miembros de An Garda Síochána."},
{q:"What sanctions can be imposed for operating a vehicle without a valid CRW or in a dangerously defective condition?", options:["Fixed charge penalties/fines, penalty points, vehicle detention/prohibition notices, and court prosecution","Free mechanical servicing at an RSA facility","A mandatory 1-day suspension of driver CPC","Cancellation of vehicle motor insurance discount"], correct:0, exp:"Multas fijas, puntos, detención/prohibición y procesamiento."},
{q:"If two coaches in a fleet have Certificates of Roadworthiness expiring within the next month, what proactive step should the Transport Manager take?", options:["Wait until the exact day of expiry before booking the test","Book the CVRT tests immediately to prevent potential lapses in certification and operational downtime","Take the vehicles off the road for 6 months","Request a 3-month extension from the local Garda station"], correct:1, exp:"Reservar el CVRT de inmediato."},
{q:"If drivers report minor brake or lighting defects on daily walkaround check sheets, what action MUST be taken before placing the vehicle in service?", options:["Allow the vehicle to operate until the next scheduled 6-week service","Remove defective vehicles from service immediately and ensure repairs are carried out and recorded before vehicle use","Instruct drivers to drive slowly and avoid heavy braking","Ignore minor lighting defects during daylight hours"], correct:1, exp:"Retirar de servicio de inmediato y reparar antes de usarlo."},
{q:"Why are incomplete or missing maintenance records considered a serious compliance breach during an RSA audit?", options:["Because maintenance records are optional under Irish law","Because an operator must prove continuous control over fleet roadworthiness; incomplete records indicate weak internal control and breach operator licence conditions","Because incomplete records double the cost of annual motor tax","Because it invalidates the company's Certificate of Incorporation"], correct:1, exp:"Debe demostrar control continuo; faltar registros incumple la licencia."},
{q:"For how long must an operator retain vehicle inspection, repair, and maintenance records at the operating base?", options:["6 months","12 months","At least 15 months (or 2 years depending on specific guidelines)","10 years"], correct:2, exp:"Al menos 15 meses (o 2 años)."},
{q:"In a Case Study exam scenario involving an imported coach whose weight plate does not match Irish registration documents, what is the required compliance response?", options:["Scrape off the old plate and drive without one","Check vehicle plating immediately, obtain official weight certification/re-plating from RSA authorised sources before operating in service","Use the vehicle only on private hire routes","Apply for a temporary goods vehicle licence"], correct:1, exp:"Comprobar el plating y obtener certificación oficial antes de operar."},
{q:"What is the legal status of an operator licence if an undertaking repeatedly operates vehicles with expired CRWs and unrectified defects?", options:["The licence is automatically renewed for 5 years","The operator licence may be suspended, curtailed, or revoked by the licensing authority due to loss of good repute","The Department of Transport takes over vehicle repairs","The company is required to operate minibuses only"], correct:1, exp:"Puede suspenderse, restringirse o revocarse."},
{q:"How does vehicle plating interact with vehicle taxation regulations?", options:["Plating determines driver wages","Plating certifies design weights, which form the basis for tax classification (unladen weight for HGVs / seating capacity for PSVs) and legal weight compliance","Plating exempts vehicles from VAT reclaims","Plating is only used for calculating toll fees"], correct:1, exp:"Certifica pesos de diseño, base de la clasificación fiscal."},
{q:"Can an RSA inspector examine maintenance records during an unannounced premises audit at an operator's depot?", options:["No, premises audits require 30 days written notice","Yes, RSA inspectors have statutory powers to enter premises, inspect maintenance records, defect logs, and examine vehicles present","Only if accompanied by a judge","Only during national bank holidays"], correct:1, exp:"Sí, tiene potestad estatutaria para entrar e inspeccionar."},
{q:"What is a 'Prohibition Notice' issued during a roadside inspection?", options:["A notice prohibiting the driver from taking a lunch break","A legal order taking a defective or untested vehicle off the road immediately, prohibiting its movement until defects are repaired and cleared","A notification to change vehicle insurance companies","A permit allowing over-weight transport"], correct:1, exp:"Orden legal que retira de circulación un vehículo defectuoso."},
{q:"What document confirms that a vehicle modified with an additional axle meets structural safety standards?", options:["Manufacturer's declaration / RSA Re-plating Certificate","Tachograph Calibration Certificate","Driving licence Category D1","Commercial Insurance Policy endorsement"], correct:0, exp:"Declaración del fabricante / Certificado de Re-plating."},
{q:"Which Directive of the European Union sets standards for periodic roadworthiness testing of motor vehicles across Member States?", options:["EU Directive 2014/45/EU","EU Regulation 561/2006","GDPR Regulation 2016/679","EU Directive 2003/59/EC"], correct:0, exp:"Directiva 2014/45/UE."},
{q:"What is the primary purpose of displaying a valid CRW test disc on the vehicle windscreen?", options:["To show that motor tax is paid","To provide visible evidence to enforcement officers that the vehicle holds a valid Certificate of Roadworthiness","To identify the driver's name","To allow automatic gate access at bus stations"], correct:1, exp:"Dar evidencia visible de CRW válido."},
{q:"If a driver notices a crack in the windscreen in the driver's direct field of vision during a morning check, how is this defect classified?", options:["Advisory note only","Major / Safety-critical defect that must be rectified before the vehicle is driven on public roads","Cosmetic issue to be fixed at end of lease","Ignored if under 50 mm"], correct:1, exp:"Defecto mayor/crítico, debe repararse antes de circular."},
{q:"What role does planned preventive maintenance play in relation to annual CVRT testing?", options:["Planned maintenance replaces the need for CVRT","CVRT is only a periodic snapshot test; planned maintenance ensures continuous safety and roadworthiness between annual tests","CVRT testing is only required if planned maintenance fails","They are completely unrelated legal concepts"], correct:1, exp:"El CVRT es solo una foto periódica; el mantenimiento asegura continuidad."},
{q:"What information must be recorded on a vehicle maintenance inspection sheet?", options:["Vehicle registration/number, odometer reading, list of inspected items, defects found, rectification work details, date, and signature of competent inspector","Fuel price per litre and petrol station receipt number","Driver's home address and phone number","Passenger ticket revenue for the day"], correct:0, exp:"Matrícula, cuentakilómetros, elementos inspeccionados, defectos, reparación, fecha y firma."},
{q:"Who is responsible for ensuring that hired or leased coaches used in a fleet have valid CRWs and correct plating?", options:["The vehicle manufacturer only","The hiring/using operator operating the vehicle under their licence","The RSA inspector who approved the lease","The passengers booking the trip"], correct:1, exp:"El operador que los usa bajo su licencia."},
{q:"What is the conclusion required in a CILT Case Study answer regarding plating and testing compliance?", options:["State that vehicle testing is too expensive for small operators","Reiterate that continuous compliance with plating, CVRT testing, valid CRWs, daily walkaround checks, and meticulous record-keeping is vital to protect passenger safety and safeguard the operator licence","Recommend transferring all vehicles to third-party sub-contractors","Suggest delaying maintenance until annual profits are calculated"], correct:1, exp:"El cumplimiento continuo es vital para la seguridad y la licencia."}
]},
"20": { title: "Tema 20 - Fleet Inspection and Enforcement", questions: [
{q:"Which statutory body in Ireland administers the commercial vehicle fleet inspection and enforcement system under the Road Safety Authority (Commercial Vehicle Roadworthiness) Act 2012?", options:["National Transport Authority (NTA)","Road Safety Authority (RSA)","Department of Transport","Revenue Commissioners"], correct:1, exp:"RSA."},
{q:"The Commercial Vehicle Roadworthiness Test (CVRT) regime applies to which of the following EU vehicle categories?", options:["Passenger cars (M1) and light trailers (O1)","Goods vehicles (N1, N2, N3), passenger vehicles (M2, M3), and commercial trailers over 750 kg (O2, O3, O4)","Agricultural tractors only","Motorcycles and quadricycles only"], correct:1, exp:"N1-N3, M2-M3 y remolques comerciales +750kg."},
{q:"Which passenger vehicles are legally subject to mandatory CVRT testing in Ireland?", options:["All passenger cars with 4 seats","All buses and coaches with more than eight passenger seats used for commercial passenger transport","Private vehicles used exclusively for domestic family errands","Electric scooters and bicycles"], correct:1, exp:"Buses/autocares de +8 asientos comerciales."},
{q:"When is a commercial vehicle or bus required to undergo its FIRST mandatory CVRT test?", options:["At 6 months of age","When the vehicle is 1 year old (12 months from first registration)","When the vehicle reaches 3 years of age","Upon its first commercial journey"], correct:1, exp:"Al año de edad."},
{q:"Following its first CVRT test at 1 year of age, how often must a commercial bus or coach be re-tested?", options:["Every 6 months","Annually (every 12 months)","Every 2 years","Every 5 years"], correct:1, exp:"Anualmente."},
{q:"What document is issued to certify that a vehicle has successfully passed its CVRT inspection?", options:["Operator Transport Disc","Certificate of Roadworthiness (CRW)","Certificate of Conformity (CoC)","Vehicle Registration Certificate (VRC)"], correct:1, exp:"CRW."},
{q:"What physical item must be displayed on a commercial vehicle or bus windscreen as visible proof of roadworthiness compliance?", options:["A CVRT test disc","A driver CPC card","A tachograph calibration sticker on the bumper","A company business card"], correct:0, exp:"El disco de test del CVRT."},
{q:"Is the annual CVRT test considered a full engineering or disassembly examination of the vehicle?", options:["Yes, it involves dismantling the entire engine and gearbox","No, it is a roadworthiness test focusing on accessible and visible safety-critical components at the time of testing","Yes, it guarantees hidden structural defects will never occur","No, it only checks vehicle paintwork and seat fabric"], correct:1, exp:"Test de aptitud centrado en componentes accesibles y visibles."},
{q:"Which of the following items are tested during a statutory CVRT inspection?", options:["Braking systems, steering, and suspension","Tyres, wheels, wheel security, lights, and reflectors","Chassis condition, mirrors, glazing, visibility, tachograph functionality, and safety equipment","All of the above"], correct:3, exp:"Todo lo anterior."},
{q:"How are CVRT test failure outcomes officially categorised under Irish and EU roadworthiness regulations?", options:["Level 1, Level 2, and Level 3","Minor defects (pass with advisory notes), Major defects (fail requiring repair and re-test), and Dangerous defects (vehicle prohibited from use)","Soft fail, Medium fail, Hard fail","Category A, Category B, Category C"], correct:1, exp:"Menores, mayores y peligrosos."},
{q:"What is the legal consequence if a vehicle is identified with a 'Dangerous Defect' during an RSA inspection or CVRT test?", options:["The vehicle receives an advisory note allowing 14 days of continued driving","The vehicle is issued a Prohibition Notice and MUST NOT be driven on public roads until the defect is fully rectified","The driver receives a verbal warning from the tester","The operator must pay double motor tax"], correct:1, exp:"Prohibition Notice, no puede conducirse hasta reparar."},
{q:"Does passing an annual CVRT test relieve an operator of their legal duty to maintain fleet vehicles continuously?", options:["Yes, the CRW grants full legal immunity for 12 months","No, the annual CVRT is only a minimum periodic standard; operators must operate a continuous planned preventive maintenance system","Yes, provided the vehicle covers less than 50,000 km per year","Only if certified by an external garage contractor"], correct:1, exp:"Solo es un estándar mínimo periódico."},
{q:"What key daily procedure must drivers perform before operating a commercial vehicle on public roads?", options:["A complete engine oil replacement","A daily walkaround safety check and prompt defect reporting","A high-pressure exterior vehicle wash","A speed test on a highway"], correct:1, exp:"Revisión diaria y reporte inmediato de defectos."},
{q:"What typical items should be checked during a driver's pre-use daily walkaround inspection?", options:["Tyres and wheel security, lights, indicators, and reflectors","Fluid leaks, windscreen, and mirror condition","Load security or bodywork condition, wipers, horn, and safety equipment","All of the above"], correct:3, exp:"Todo lo anterior."},
{q:"What system is strongly recommended by the RSA Guide to Maintaining Roadworthiness for daily walkaround reporting?", options:["Verbal reporting only when breakdowns occur","A 'Nil' defect reporting system, where drivers record a report daily confirming checks were done even when no defects are found","End-of-month summary emails","Ignoring minor defects until annual CVRT"], correct:1, exp:"Sistema de reporte 'Nil defect'."},
{q:"Roadside compliance inspections in Ireland are carried out jointly by:", options:["RSA Vehicle Inspectors / Transport Officers and An Garda Síochána","Revenue Customs Officers and local teachers","NTA inspectors and parking wardens","Insurance adjusters and bank auditors"], correct:0, exp:"Inspectores de la RSA y An Garda Síochána."},
{q:"Who has the statutory legal authority to STOP a moving commercial vehicle on an Irish public road for a roadside inspection?", options:["RSA Vehicle Inspectors acting alone","Members of An Garda Síochána","Workshop mechanics","Any member of the public"], correct:1, exp:"Miembros de An Garda Síochána."},
{q:"What items may be checked by officers during an RSA roadside inspection?", options:["Vehicle roadworthiness and valid CRW display","Tachograph records and drivers' hours compliance","Operator licensing documentation and Driver CPC qualification cards","All of the above"], correct:3, exp:"Todo lo anterior."},
{q:"In addition to roadside checks, where else does the RSA conduct compliance inspections?", options:["At driver driving test centers only","At operator premises (depots/offices)","At local county council town halls","At fuel filling stations exclusively"], correct:1, exp:"En las instalaciones del operador."},
{q:"What documents and records may RSA officers examine during a depot/premises inspection?", options:["Maintenance systems and planned inspection schedules","Driver daily walkaround check sheets and defect reporting logs","Inspection and repair records (job cards) and vehicle history files","All of the above"], correct:3, exp:"Todo lo anterior."},
{q:"What action can RSA inspectors take if a vehicle present at an operator's premises during an audit is found to be dangerously defective?", options:["Issue a verbal caution and leave","Issue a Prohibition Notice preventing the vehicle from being used on public roads","Confiscate the driver's personal smartphone","Force the operator to sell the depot"], correct:1, exp:"Prohibition Notice."},
{q:"Under Irish fleet inspection law, what maximum fine can be imposed in court per offence for serious roadworthiness non-compliance?", options:["€500","€1,000","Fines of up to €5,000","€100,000"], correct:2, exp:"Hasta €5,000."},
{q:"In addition to fines, what penalties may be imposed by courts for severe or repeated vehicle maintenance breaches?", options:["Prosecution and possible imprisonment (up to 6 months)","Penalty points on driver/operator records","Vehicle detention or prohibition","All of the above"], correct:3, exp:"Todo lo anterior."},
{q:"If an operator hires a maintenance contractor to service fleet vehicles, who retains ultimate legal responsibility for the roadworthiness of those vehicles on public roads?", options:["The maintenance contractor / garage exclusively","The transport operator and the driver","The RSA inspector who tested the vehicle","The vehicle manufacturer"], correct:1, exp:"El operador y el conductor."},
{q:"What system rates transport operators based on risk and compliance findings (such as CVRT results, roadside checks, and premises audits)?", options:["Commercial Vehicle Risk Rating (CVRR)","Financial Standing Index","Driver CPC Points System","Revenue VAT Rating"], correct:0, exp:"CVRR."},
{q:"What happens to an operator who accumulates serious defects, failed CVRTs, or Prohibition Notices on their CVRR risk profile?", options:["Their risk rating moves to Amber or Red, leading to increased targeted RSA inspections and audits","They receive automatic tax rebates","Their vehicle speed limiters are removed","They are exempt from roadside inspections"], correct:0, exp:"Pasa a Amber/Red, con más inspecciones."},
{q:"How does poor maintenance compliance impact an operator's standing before the Licensing Authority (Traffic Area Office / Dept of Transport)?", options:["Prohibition notices and serious defects are recorded against the Operator Licence and may be used as grounds to object to licence renewals or expansion requests","It has no impact on operator licensing","It increases driver holiday entitlement","It automatically grants new vehicle additions"], correct:0, exp:"Quedan registradas contra la licencia."},
{q:"Under Regulation (EC) No 1071/2009, what disciplinary action can the Licensing Authority take against an operator with unacceptable maintenance standards?", options:["Suspend the Operator Licence","Curtail (reduce) the number of authorized vehicles on the licence","Revoke the Operator Licence entirely","All of the above"], correct:3, exp:"Todo lo anterior."},
{q:"What happens to a Transport Manager whose fleet repeatedly operates unroadworthy vehicles, lacks maintenance records, or ignores prohibition notices?", options:["The Transport Manager may lose their 'Good Repute' and be formally disqualified from acting as a transport manager","The Transport Manager is demoted to bus conductor automatically","The Transport Manager must pay motor tax out of personal funds","No action can be taken against the Transport Manager personally"], correct:0, exp:"Puede perder su Buena Reputación y ser descalificado."},
{q:"In Case Study 1, a vehicle on a Carlow to Limerick journey is stopped by the RSA and Gardaí, and an officer issues a prohibition for a defective suspension unit. Who is authorized to stop the vehicle?", options:["RSA Inspectors acting alone","Members of An Garda Síochána (or RSA inspectors accompanied by/in conjunction with Gardaí)","Local traffic wardens","National Transport Authority ticket checkers"], correct:1, exp:"An Garda Síochána (o inspectores de la RSA junto con ellos)."},
{q:"In Case Study 1, once the prohibited defective vehicle is recovered back to base, what THREE steps must be taken before returning it to active service?", options:["1. Repair the defect by a competent person; 2. Have the vehicle re-inspected / cleared (e.g., CVRT re-test / prohibition removal); 3. Update maintenance records and sign off rectification","1. Wash the vehicle; 2. Change the driver; 3. Continue journey immediately","1. Pay motor tax; 2. Replace all tyres; 3. Apply for a new licence disc","1. File an insurance claim; 2. Store vehicle for 6 months; 3. Sell the chassis"], correct:0, exp:"Reparar, re-inspeccionar y actualizar registros."},
{q:"In Case Study 1, who under current regulations may be liable for prosecution due to the unroadworthiness of the stopped vehicle?", options:["The driver, the Transport Manager, and the Transport Operator (undertaking)","The customer who booked the freight/passenger service only","The RSA inspector who conducted the check","The breakdown recovery truck driver"], correct:0, exp:"El conductor, el Transport Manager y el operador."},
{q:"In Case Study 2, a bus driver finds failed indicators and a truck driver finds tyre damage during morning walkaround checks. Can these vehicles be driven on public roads before repairs?", options:["Yes, provided drivers drive under 30 km/h","No, safety-critical defects must be reported and fully repaired BEFORE the vehicles are allowed onto public roads","Yes, provided the journey takes less than 1 hour","Yes, if approved by the office receptionist"], correct:1, exp:"No, deben repararse ANTES de circular."},
{q:"How long must an operator retain all vehicle safety inspection sheets, defect reports, and repair records at their operating base?", options:["6 months","12 months","At least 15 months (or 2 years for specific enforcement and working time compliance)","5 years"], correct:2, exp:"Al menos 15 meses (o 2 años)."},
{q:"What annual document must heavy commercial vehicle fleet operators submit to the RSA confirming compliance with maintenance and safety requirements?", options:["Annual Operator Self-Declaration","Annual Profit and Loss Account","Company Articles of Association","Driver CPC Renewal Form"], correct:0, exp:"Annual Operator Self-Declaration."},
{q:"If a driver identifies a minor defect during a daily check that does not render the vehicle unroadworthy (e.g., a minor interior cosmetic trim issue), what is the procedure?", options:["Record the defect on the defect sheet and schedule repair at the next planned maintenance window while continuing safe operation","Stop the bus on the highway immediately","Refuse to drive the bus for 30 days","Call An Garda Síochána to inspect the vehicle"], correct:0, exp:"Registrarlo y programar su reparación, continuando la operación."},
{q:"If an operator fails to maintain written records of daily driver walkaround checks and defect repairs, what is the legal position during an RSA audit?", options:["The RSA assumes maintenance was performed verbally","The operator fails to prove 'reasonable care', constituting a serious breach of operator licence obligations","The RSA issues an automatic 5-year licence extension","The operator is granted immunity from prosecution"], correct:1, exp:"No logra probar 'cuidado razonable', incumplimiento grave."},
{q:"Why is 'time-based' scheduling (e.g., every 4, 6, or 8 weeks) preferred over 'mileage-only' scheduling for preventive maintenance inspections?", options:["Time-based scheduling ensures low-mileage vehicles (which may suffer age-related degradation like tyre cracking or brake seizure) are inspected regularly","Time-based scheduling is cheaper for garage contractors","Mileage cannot be measured on digital tachographs","Irish law prohibits measuring vehicle distance in kilometres"], correct:0, exp:"Asegura inspeccionar también los de bajo kilometraje."},
{q:"What is the maximum recommended inspection interval for heavy commercial vehicles or buses over 12 years old, regardless of mileage?", options:["Every 12 weeks","Every 10 weeks","Every 6 weeks","Every 2 weeks"], correct:2, exp:"Cada 6 semanas."},
{q:"What is the ultimate goal of fleet inspection and enforcement regulations in Ireland?", options:["Protecting road safety, preventing fatal collisions caused by mechanical failure, ensuring fair competition, and maintaining vehicle integrity across the transport sector","Maximising revenue collected from court fines","Reducing the total number of licensed transport companies in Ireland","Forcing all operators to purchase electric vehicles immediately"], correct:0, exp:"Proteger la seguridad vial y garantizar competencia justa."}
]},
"22": { title: "Tema 22 - Driver Licensing & Driver CPC", questions: [
{q:"Which EU Directive governs the harmonised driving licence categories and mutual recognition across EU/EEA Member States?", options:["Directive 2003/59/EC","Directive 2006/126/EC","Directive 561/2006/EC","Directive 2014/45/EU"], correct:1, exp:"Directive 2006/126/EC."},
{q:"Under Irish law, driving licences for professional categories (Group 2: Category C, D, etc.) are valid for a maximum period of:", options:["1 year","5 years","10 years","15 years"], correct:1, exp:"5 años."},
{q:"How often must the photograph on an Irish photocard driving licence be updated?", options:["Every 3 years","Every 5 years","Every 10 years","Never, once issued it is permanent"], correct:2, exp:"Cada 10 años."},
{q:"What driving licence category entitlement is required to drive a passenger carrying vehicle (PCV) with up to 8 passenger seats (excluding the driver)?", options:["Category B","Category D1","Category D","Category C1"], correct:0, exp:"Categoría B."},
{q:"What driving licence category entitlement is required to drive a minibus carrying between 9 and 16 passenger seats (excluding the driver)?", options:["Category B","Category D1","Category D","Category C"], correct:1, exp:"Categoría D1."},
{q:"What is the basic driving licence category required to drive large passenger carrying vehicles with 17 or more passenger seats (including articulated buses)?", options:["Category B","Category D1","Category D","Category C"], correct:2, exp:"Categoría D."},
{q:"If a Category D bus driver wishes to tow a trailer with a Maximum Authorised Mass (MAM) NOT exceeding 750 kg, what additional entitlement is required?", options:["Category D+E entitlement must be obtained","No additional '+E' entitlement is required; a trailer up to 750 kg MAM can be towed on a standard Category D licence","Category B+E entitlement","Special permit from the NTA"], correct:1, exp:"No necesita entitlement adicional para hasta 750 kg."},
{q:"What entitlement must be added to a Category D licence to tow a trailer with a MAM EXCEEDING 750 kg?", options:["Category D1","Category D+E","Category C+E","Category B+E"], correct:1, exp:"Categoría D+E."},
{q:"Under EU rules, what is the standard minimum age for obtaining a full Category D driving entitlement without a Driver CPC?", options:["18 years","21 years","24 years","26 years"], correct:2, exp:"24 años."},
{q:"What is the reduced minimum age for a driver holding a full Driver CPC to drive a Category D bus on regular passenger services where the route does NOT exceed 50 km?", options:["18 years","21 years","23 years","24 years"], correct:0, exp:"18 años, con CPC completo."},
{q:"Under EU rules, a driver aged 21 holding a Category D entitlement and Driver CPC card can drive passenger vehicles on:", options:["Routes up to 50 km only","All domestic and international routes without restriction","Regular services exceeding 500 km","Night tours exclusively"], correct:1, exp:"Todas las rutas, sin restricción, a los 21 con CPC."},
{q:"A driver passed a Category B (car) driving test prior to 1st January 1997 in Ireland. What preserved entitlement did they automatically receive?", options:["Full Category D entitlement for unlimited passenger transport","A limited D1 entitlement (9-16 seats) plus a trailer up to 750 kg MAM, endorsed with Code 101 ('Not for hire or reward')","Unlimited Category D+E entitlement","No preserved entitlement"], correct:1, exp:"D1 limitado con Código 101 (no para alquiler/retribución)."},
{q:"A driver who passed Category B after 1st January 1997 wants to drive a 9-16 seat minibus for a non-commercial voluntary body on a Category B licence. What conditions must be met?", options:["Driver is over 21, held Cat B for at least 2 years, vehicle GVW <= 3,500 kg (or 4,250 kg with wheelchair equipment), no trailer towed, and no hire or reward","Any age driver can drive any minibus","Vehicle can weigh up to 7.5 tonnes","The driver must hold a Category D licence"], correct:0, exp:"Mayor de 21, Cat B 2+ años, ≤3,500kg (o 4,250kg con silla de ruedas), sin remolque ni cobro."},
{q:"Holders of a full Category D driving licence in Ireland are legally permitted to drive a recovery vehicle, provided its unladen weight does not exceed:", options:["3.5 tonnes","7.5 tonnes","10.2 tonnes","18.0 tonnes"], correct:2, exp:"10.2 toneladas."},
{q:"What does Driving Licence Information Code 101 signify?", options:["Restricted to automatic transmission vehicles","Not for hire or reward (non-commercial use only)","Subject to certificate of competence","Maximum vehicle length 5.5 metres"], correct:1, exp:"No para alquiler o retribución."},
{q:"What does Driving Licence Information Code 78 signify?", options:["Restricted to vehicles with automatic transmission","Limited to maximum 16 passenger seats","Not for hire or reward","Mandatory wearing of corrective glasses"], correct:0, exp:"Restringido a transmisión automática."},
{q:"What medical report form must be completed by a registered medical practitioner when applying for a Group 2 (Category D1/D/D+E) licence?", options:["Form D201","Form D501 (Medical Report Form)","Form RF111A","Form NDLS1"], correct:1, exp:"Formulario D501."},
{q:"What mandatory procedure must applicants for Category D / D1 licences fulfill regarding previous driving/traffic offences?", options:["Disclose all relevant convictions, driver hours breaches, or roadworthiness convictions on the application form","Submit tax clearance certificates from Revenue","No disclosure is required for driving offences","Provide bank statements for 3 years"], correct:0, exp:"Declarar todas las condenas relevantes."},
{q:"Which body in Ireland oversees driver testing, licensing, and Driver CPC requirements?", options:["National Transport Authority (NTA)","Road Safety Authority (RSA)","Department of Social Protection","Health and Safety Authority (HSA)"], correct:1, exp:"RSA."},
{q:"What are the four testing modules required for a new candidate to obtain Initial Driver CPC qualification for buses/coaches?", options:["Module 1: Theory Test; Module 2: CPC Case Studies; Module 3: Practical Driving Test; Module 4: CPC Practical Walk-Around Test","Written Essay, Oral Exam, Physical Fitness Test, First Aid Test","Mechanical Overhaul Test, Financial Audit, Road Test, Route Planning","City Driving Test, Motorway Test, Night Driving Test, Parking Test"], correct:0, exp:"Teoría, Casos prácticos, Examen práctico, Prueba práctica de revisión."},
{q:"What is the pass mark for the computer-based Passenger Vehicle Driver Theory Test (100 multiple choice questions)?", options:["70 out of 100","80 out of 100","85 out of 100","95 out of 100"], correct:2, exp:"85 sobre 100."},
{q:"Once passed, how long is the Driver Theory Test qualification valid for the candidate to complete the practical test?", options:["6 months","1 year","2 years","5 years"], correct:2, exp:"2 años."},
{q:"What is the pass mark for the Driver CPC Case Studies test (Part 2), which contains 7 scenarios with 50 total marks?", options:["30 out of 50","35 out of 50","40 out of 50","45 out of 50"], correct:2, exp:"40 sobre 50."},
{q:"What is the minimum vehicle specification required for taking a Category D practical driving test?", options:["A passenger vehicle (PCV) with a minimum length of 10 metres and a seating capacity of at least 24 seated passengers (excluding driver)","Any 16-seat minibus","A double-deck bus over 12 metres","An articulated bus with 50 seats"], correct:0, exp:"Vehículo de al menos 10m y 24 asientos."},
{q:"What is the minimum vehicle specification for taking a Category D1 practical driving test?", options:["Gross Vehicle Weight (MAM) of at least 4,000 kg","Gross Vehicle Weight of 2,500 kg","Any 8-seat passenger car","Minimum length of 12 metres"], correct:0, exp:"MMA de al menos 4,000 kg."},
{q:"What minimum trailer specification is required when conducting a Category D+E practical driving test?", options:["A loaded box trailer with a MAM of at least 1,250 kg and a minimum real weight of 800 kg","An empty unladen trailer of 500 kg MAM","Any single-axle trailer over 250 kg","A semi-trailer with air suspension"], correct:0, exp:"Remolque cargado, MMA ≥1,250kg, peso real ≥800kg."},
{q:"What core areas are examined during the Driver CPC Practical Walk-Around Test (Module 4)?", options:["Daily walkaround checks, safe loading, securing passengers/luggage, preventing illegal immigration, and assessing emergency situations","Engine rebuild procedures and gearbox repair","Calculating passenger ticket tariffs","Driving at 100 km/h on motorways"], correct:0, exp:"Revisión diaria, carga segura, seguridad de pasajeros y emergencias."},
{q:"How long is a Driver Qualification Card (DQC / Driver CPC Card) valid once issued by the RSA?", options:["1 year","3 years","5 years","10 years"], correct:2, exp:"5 años."},
{q:"How must a professional bus/coach driver maintain Periodic Driver CPC qualification over each 5-year cycle?", options:["By taking a comprehensive written exam every 5 years","By completing 35 hours of periodic training (5 modules of 7 hours each, 1 module per year) at RSA-approved training centres","By driving 100,000 km without accident","By attending a 1-day refresher course at NDLS"], correct:1, exp:"35 horas de formación periódica."},
{q:"Is a professional bus driver permitted to complete all 35 hours of Driver CPC training in the final week of the 5-year cycle?", options:["Yes, but RSA guidelines strongly recommend completing 1 day (7 hours) per year to keep knowledge updated","No, completing 35 hours in one year is strictly illegal under Irish law","Yes, provided it is done online only","No, training must be spread across 10 years"], correct:0, exp:"Sí, aunque se recomienda 1 día por año."},
{q:"If a driver holds both Category C (Truck) and Category D (Bus) entitlements, how many hours of Periodic Driver CPC training must they complete every 5 years?", options:["70 hours (35 hours for truck and 35 hours for bus)","35 hours total (covering shared and specific modules across the 5-year cycle)","50 hours total","105 hours total"], correct:1, exp:"35 horas en total."},
{q:"What physical document must a professional driver carry while driving a commercial passenger vehicle to prove CPC compliance?", options:["Driver CPC Qualification Card (DQC) or photocard driving licence with Code 95 endorsed","Original Certificate of Incorporation","Paper training certificate from the training centre","Transport Manager's CPC certificate"], correct:0, exp:"La tarjeta DQC o el carné con Código 95."},
{q:"What information code on an EU photocard driving licence indicates that the holder satisfies professional Driver CPC requirements?", options:["Code 101","Code 78","Code 95","Code 50"], correct:2, exp:"Código 95."},
{q:"A driver who holds Category D entitlement and CPC card is aged 18. What operation are they legally permitted to drive?", options:["Registered local bus service under 50 km length","International express route across Europe","53-seat coach on Irish day tours over 200 km","Night-time tour from Dublin to Cork"], correct:0, exp:"Servicio local registrado de menos de 50 km."},
{q:"A driver aged 21 holds Category D entitlement and Driver CPC card. Which of the following operations can they legally drive? 1. Registered local bus service of 45 km 2. Private hire journey of 40 km 3. Private hire journey of 80 km 4. School contract of 30 km", options:["1 only","2 and 3 only","2, 3, and 4 only","All of the above (1, 2, 3, and 4)"], correct:3, exp:"A los 21 con CPC completo, ya no hay restricción de distancia."},
{q:"An employer hires a French national residing in Ireland for 9 months who holds an EU Category D licence. What is the legal status of their driving licence?", options:["They can continue to drive on their valid EU Category D entitlement without taking a test in Ireland (mutual EU recognition)","They must re-take an Irish Category D driving test immediately after 6 months","Their licence expired upon moving to Ireland","They can only drive Category B passenger cars"], correct:0, exp:"Reconocimiento mutuo UE, sin examen en Irlanda."},
{q:"What is the minimum age for a driver holding Category D and CPC to operate a 49-seat coach on multi-day Irish tours (exceeding 50 km)?", options:["18 years","21 years","24 years","25 years"], correct:1, exp:"21 años."},
{q:"What category of entitlement is required for a driver operating a 16-seat minibus towing a 1-tonne (1,000 kg) trailer for school trips?", options:["Category D1","Category D1+E","Category D","Category B+E"], correct:1, exp:"Categoría D1+E."},
{q:"What is the penalty for an operator who knowingly employs a driver to operate a PSV without a valid driving licence or Driver CPC card?", options:["Verbal caution from local council","Severe fines, prosecution, potential vehicle prohibition, and threat to the operator's Good Repute / Operator Licence","Double motor tax for 1 year","Mandatory free CPC training provided by RSA"], correct:1, exp:"Multas graves, procesamiento y riesgo a la licencia."},
{q:"In Case Study 21P, Lax Travel Ltd operates minibuses, 53-seat buses (<50 km), 72-seat school buses, and 49-seat tour coaches. What is the minimum age required for drivers passing tests after Sept 2020 for the 49-seat ROI tour coach?", options:["18 years","21 years","24 years","25 years"], correct:1, exp:"21 años."}
]},
"23": { title: "Tema 23 - Drivers' Hours & Tachographs", questions: [
{q:"Which EU Regulation governs driving times, breaks, and rest periods for professional drivers across Member States?", options:["Regulation (EC) No 1071/2009","Regulation (EC) No 561/2006","Regulation (EU) No 165/2014","Directive 2003/59/EC"], correct:1, exp:"Reglamento (CE) 561/2006."},
{q:"Which EU Regulation governs the technical standards, installation, use, and testing of tachographs in road transport?", options:["Regulation (EC) No 561/2006","Regulation (EU) No 165/2014","Directive 2002/15/EC","Regulation (EC) No 1072/2009"], correct:1, exp:"Reglamento (UE) 165/2014."},
{q:"What is the standard maximum daily driving limit under EU Regulation 561/2006?", options:["8 hours","9 hours","10 hours","11 hours"], correct:1, exp:"9 horas."},
{q:"How many times in any single fixed week may the daily driving limit be extended to 10 hours?", options:["Once","Twice","Three times","Four times"], correct:1, exp:"Dos veces."},
{q:"What is the maximum permitted cumulative driving time in any single fixed week (00:00 Monday to 24:00 Sunday)?", options:["48 hours","56 hours","60 hours","90 hours"], correct:1, exp:"56 horas."},
{q:"What is the maximum permitted cumulative driving time in any two consecutive fixed weeks?", options:["80 hours","90 hours","100 hours","112 hours"], correct:1, exp:"90 horas."},
{q:"After driving for 4.5 hours (4 hours and 30 minutes), a driver MUST take an uninterrupted break of at least:", options:["30 minutes","45 minutes","60 minutes","15 minutes"], correct:1, exp:"45 minutos."},
{q:"If a driver splits their required 45-minute break into two periods, how MUST those periods be taken?", options:["First a 15-minute break, followed later by a 30-minute break","First a 30-minute break, followed later by a 15-minute break","Two equal breaks of 22.5 minutes each","Three 15-minute breaks"], correct:0, exp:"15 min primero, 30 min después."},
{q:"What is the standard regular daily rest period required within every 24-hour period after the end of the previous rest?", options:["9 hours","10 hours","at least 11 hours","12 hours"], correct:2, exp:"Al menos 11 horas."},
{q:"If a regular daily rest period is split into two separate parts, how must it be structured and what is the minimum total duration?", options:["First part at least 3 hours, second part at least 9 hours (total 12 hours)","First part at least 2 hours, second part at least 10 hours (total 12 hours)","Two equal parts of 5.5 hours (total 11 hours)","First part at least 4 hours, second part at least 8 hours (total 12 hours)"], correct:0, exp:"1ª parte ≥3h, 2ª parte ≥9h (total 12h)."},
{q:"To what minimum duration may a daily rest period be reduced ('reduced daily rest') without needing compensation?", options:["8 hours","9 hours","9.5 hours","10 hours"], correct:1, exp:"9 horas."},
{q:"How many times between any two weekly rest periods may a driver take a reduced daily rest period (less than 11 hours, but at least 9 hours)?", options:["Maximum 2 times","Maximum 3 times","Maximum 4 times","Unlimited if approved by the operator"], correct:1, exp:"Máximo 3 veces."},
{q:"Under multi-manning (double-manning) operations, within what period must each driver take a daily rest period of at least 9 hours?", options:["Within 24 hours","Within 27 hours","Within 30 hours","Within 36 hours"], correct:2, exp:"Dentro de 30 horas."},
{q:"What is the minimum duration of a regular weekly rest period?", options:["24 hours","36 hours","45 hours","60 hours"], correct:2, exp:"45 horas."},
{q:"To what minimum duration can a weekly rest period be reduced ('reduced weekly rest') in any two consecutive weeks?", options:["12 hours","18 hours","24 hours","36 hours"], correct:2, exp:"24 horas."},
{q:"In any two consecutive weeks, a driver must take at least:", options:["Two regular weekly rest periods (45h + 45h) OR one regular and one reduced weekly rest period (45h + 24h)","Two reduced weekly rest periods of 24 hours","One 45-hour rest every 14 days","90 hours of continuous rest"], correct:0, exp:"Dos regulares (45+45) O uno regular+uno reducido (45+24)."},
{q:"When must any reduction taken in a weekly rest period (below 45 hours down to 24 hours) be compensated?", options:["Within 1 week en bloc","En bloc before the end of the third week following the week in question, attached to another rest period of at least 9 hours","Spread over the next 6 months","Reduction does not require compensation for passenger transport"], correct:1, exp:"En bloque antes de la 3ª semana siguiente, junto a otro descanso de ≥9h."},
{q:"What special concession applies to international coach drivers performing a single international passenger service (the '12-day rule')?", options:["Weekly rest can be postponed up to the end of 12 consecutive 24-hour periods","Drivers can drive 15 hours every day without breaks","Daily rest can be reduced to 6 hours","No tachograph is required during the 12 days"], correct:0, exp:"Descanso semanal pospuesto hasta 12 periodos de 24h."},
{q:"Which condition MUST be met to utilise the international passenger 12-day rule concession?", options:["The service must last at least 24 consecutive hours in another EU/non-EU state and the driver took a regular 45h rest prior to the trip","After the trip, the driver must take two regular weekly rests (90h) or one regular + one reduced (69h) with full compensation","The vehicle must be fitted with a digital tachograph (and if driving between 22:00 and 06:00, multi-manned or driving limited to 3h before break)","All of the above"], correct:3, exp:"Todas las condiciones deben cumplirse."},
{q:"When a driver accompanies a vehicle carried by ferry or train, how may a regular daily rest period (11h) be interrupted?", options:["Interrupted maximum twice for other activities, total interruptions not exceeding 1 hour, with access to a sleeper cabin/bunk","Interrupted up to 4 times for a total of 2 hours","Cannot be interrupted under any circumstances","Interrupted only by order of the ship captain"], correct:0, exp:"Máximo 2 veces, sin superar 1h, con acceso a litera."},
{q:"Under Irish domestic rules (Transport Act 1961/1968) for out-of-scope local passenger services, what is the maximum continuous driving limit before a break?", options:["4.5 hours","5.5 hours","6.0 hours","8.0 hours"], correct:1, exp:"5.5 horas."},
{q:"What is the maximum daily driving time under Irish Domestic Regulations for out-of-scope transport?", options:["8 hours","9 hours","10 hours","11 hours"], correct:2, exp:"10 horas."},
{q:"What is the maximum length of the working day (spreadover) permitted under Irish Domestic Regulations?", options:["12 hours","14 hours","16 hours","18 hours"], correct:2, exp:"16 horas."},
{q:"Under Irish Domestic Regulations, what is the standard minimum daily rest period?", options:["8 hours","9 hours","10 hours","11 hours"], correct:2, exp:"10 horas."},
{q:"To what duration may the domestic daily rest period (10 hours) be reduced up to 3 times per week under Domestic Regulations?", options:["7.5 hours","8 hours","8.5 hours","9 hours"], correct:2, exp:"8.5 horas."},
{q:"What passenger service operations are legally EXEMPT from EU Regulation 561/2006 (and tachograph requirements)?", options:["Regular passenger services where the route length does NOT exceed 50 km","Vehicles with 9 to 16 passenger seats used exclusively for non-commercial carriage of passengers","Specialised breakdown vehicles operating within a 100 km radius of base","All of the above"], correct:3, exp:"Todas están exentas."},
{q:"When a driver performs mixed driving (part under EU rules and part under Irish domestic rules), how must time spent driving under domestic rules be recorded on the EU tachograph?", options:["As Rest / Break","As 'Other Work'","As Period of Availability (POA)","It must not be recorded at all"], correct:1, exp:"Como 'Other Work'."},
{q:"Can time spent driving under Domestic rules be counted as a break or rest period under EU Regulation 561/2006?", options:["Yes, provided it is recorded in a logbook","No, domestic driving constitutes work and cannot be counted as break or rest under EU rules","Yes, if driving speed was under 30 km/h","Only on Sundays"], correct:1, exp:"No, nunca puede contarse como pausa o descanso UE."},
{q:"How long must an operator retain completed tachograph charts, digital driver card download files, and printouts?", options:["At least 6 months","At least 12 months (and at least 2 years if used for Working Time Directive compliance)","At least 3 years","5 years"], correct:1, exp:"Al menos 12 meses (2 si son para Working Time)."},
{q:"Within how many days must a driver return completed analogue tachograph record sheets to their employer?", options:["Within 7 days","Within 14 days","Within 28 days","Within 42 days"], correct:3, exp:"42 días."},
{q:"How often MUST data from a driver's digital tachograph card be downloaded by the operator?", options:["At least every 14 days","At least every 28 days","At least every 56 days","At least every 90 days"], correct:1, exp:"Al menos cada 28 días."},
{q:"How often MUST data from the digital tachograph vehicle unit (VU) be downloaded by the operator?", options:["At least every 28 days","At least every 56 days","At least every 90 days","Annually"], correct:2, exp:"Al menos cada 90 días."},
{q:"How many preceding calendar days of tachograph records must a driver carry and be able to produce for inspection at the roadside?", options:["Current day plus the preceding 7 days","Current day plus the preceding 14 days","Current day plus the preceding 28 calendar days","Current day plus the preceding 56 days"], correct:2, exp:"El día actual más los 28 días naturales anteriores."},
{q:"What information must a driver enter manually on the centre field of an analogue tachograph chart at the BEGINNING of the day?", options:["Driver's surname and forename, place where record begins, date, vehicle registration number, and opening odometer reading","Employer's tax registration number","Fuel tank level and tyre pressure","Driver's CPC card number"], correct:0, exp:"Nombre, lugar y fecha, matrícula, y cuentakilómetros inicial."},
{q:"What information must a driver enter on the centre field of an analogue chart at the END of the working day?", options:["Place where record ends, date record ends, and closing odometer reading (and total km driven)","Total revenue collected from fares","Reason for any traffic jams encountered","Signature of the workshop manager"], correct:0, exp:"Lugar y fecha de fin, y cuentakilómetros final."},
{q:"Under EU Regulation 561/2006 (Article 12), what action must a driver take if an unexpected emergency prevents reaching a planned stopping place?", options:["Abandon the vehicle immediately","Depart from hours rules only to the extent necessary to reach a suitable stopping place, and state the reason manually on the chart/printout upon arrival","Continue driving up to 15 hours without recording anything","Phone the Minister for Transport for verbal exemption"], correct:1, exp:"Desviarse solo lo necesario y anotar el motivo al llegar."},
{q:"What does EU Regulation 561/2006 prohibit regarding driver pay and bonus schemes?", options:["Paying overtime rates for weekend work","Paying drivers performance bonuses or distance-related pay that endangers road safety or encourages breaches of driving hours","Paying fixed monthly salaries","Offering free driver uniform items"], correct:1, exp:"Bonos que pongan en riesgo la seguridad vial."},
{q:"Within how many days must an operator produce requested tachograph records when formally demanded by Gardaí or RSA examiners?", options:["Within 24 hours","Within 7 days","Within 10 days","Within 28 days"], correct:2, exp:"10 días."},
{q:"What is the maximum statutory fine per offence for serious tachograph or drivers' hours record-keeping breaches in court?", options:["€1,000","€2,500","Up to €5,000 per offence (with potential for imprisonment or loss of Operator Licence)","€20,000"], correct:2, exp:"Hasta €5,000 por infracción."},
{q:"How often must a digital tachograph system undergo full recalibration and inspection at an approved workshop?", options:["Every 1 year","Every 2 years","Every 3 years","Every 6 years"], correct:1, exp:"Cada 2 años."}
]},
"24": { title: "Tema 24 - Working Time Directive (WTD)", questions: [
{q:"Which EU Directive regulates working time specifically for mobile workers in road transport activities?", options:["Directive 2003/88/EC","Directive 2002/15/EC","Directive 2006/126/EC","Regulation (EC) No 561/2006"], correct:1, exp:"Directive 2002/15/EC."},
{q:"Statutory Instrument No. 36 of 2012 (European Communities Road Transport Working Time Regulations 2012) in Ireland applies to:", options:["Full-time mobile drivers only","Mobile workers (drivers, conductors, crew members) and self-employed drivers involved in road transport activities","Office administration staff exclusively","Mechanics working in static workshops only"], correct:1, exp:"Trabajadores móviles y conductores autónomos en transporte por carretera."},
{q:"Under Directive 2002/15/EC, what is the maximum average weekly working time permitted over the standard reference period?", options:["40 hours per week","48 hours per week","56 hours per week","60 hours per week"], correct:1, exp:"48 horas/semana de media."},
{q:"What is the absolute maximum working time permitted in any single week under the Road Transport Working Time Directive?", options:["48 hours","56 hours","60 hours","72 hours"], correct:2, exp:"60 horas."},
{q:"Under Directive 2002/15/EC, what is the standard length of the reference period used to calculate the 48-hour average weekly working time?", options:["4 weeks","12 weeks","4 months (or up to 6 months if agreed by collective agreement)","12 months"], correct:2, exp:"4 meses (hasta 6 por acuerdo colectivo)."},
{q:"What activities are officially defined as 'Working Time' for mobile workers under the directive?", options:["Driving time and loading / unloading passengers or freight","Vehicle cleaning, daily maintenance checks, and administrative work related to transport operations","Waiting times where the exact duration is NOT known in advance by the driver","All of the above"], correct:3, exp:"Todo lo anterior."},
{q:"Which of the following time periods is EXCLUDED from the definition of Working Time (classified as Period of Availability - POA)?", options:["Time spent driving in heavy traffic","Waiting time at terminals/borders where the expected duration is known in advance by the driver before departure","Time spent conducting morning walkaround checks","Time spent securing passenger wheelchairs"], correct:1, exp:"Espera de duración conocida de antemano."},
{q:"When a mobile worker works between 6 hours and 9 hours in a single shift, what is the mandatory minimum total break duration required under WTD?", options:["15 minutes","30 minutes","45 minutes","60 minutes"], correct:1, exp:"30 minutos."},
{q:"If total working time exceeds 9 hours in a single shift, what is the mandatory minimum total break duration required under WTD?", options:["30 minutes","45 minutes","60 minutes","90 minutes"], correct:1, exp:"45 minutos."},
{q:"How can WTD breaks (30 min or 45 min) be broken down into smaller periods during the shift?", options:["Into periods of at least 15 minutes each","Into 5-minute increments","Breaks cannot be broken down under any circumstances","Into one 10-minute and two 20-minute periods"], correct:0, exp:"En periodos de al menos 15 minutos cada uno."},
{q:"Under Directive 2002/15/EC, what is the definition of 'Night Time'?", options:["Any period of at least 7 hours between 22:00 and 07:00","A period of at least 4 hours between 00:00 (midnight) and 07:00 as defined by national law (00:00 to 04:00 in Ireland)","Any period between sunset and sunrise","20:00 to 06:00"], correct:1, exp:"Al menos 4h entre medianoche y las 07:00 (en Irlanda: 00:00-04:00)."},
{q:"If a mobile worker performs ANY work during the defined 'Night Time' period (00:00 to 04:00), what is the maximum permitted working time in that 24-hour period?", options:["8 hours maximum","10 hours maximum (unless extended by collective agreement)","12 hours maximum","14 hours maximum"], correct:1, exp:"10 horas máximo (salvo acuerdo colectivo)."},
{q:"Under EU Working Time Regulations, how many weeks of paid annual leave are mobile workers entitled to per year?", options:["2 weeks","3 weeks","4 weeks (20 working days)","6 weeks"], correct:2, exp:"4 semanas (20 días laborables)."},
{q:"Are statutory breaks or rest periods allowed to be counted as part of a driver's 4-week paid annual leave entitlement?", options:["Yes, breaks are part of leave","No, paid annual leave is separate and must not be replaced by financial compensation except on termination of employment","Only if agreed verbally","Only during winter months"], correct:1, exp:"No, las vacaciones son independientes."},
{q:"How long must a transport employer retain records of mobile workers' working time (including tachograph downloads and working pattern logs)?", options:["6 months","1 year","At least 2 years (24 months)","5 years"], correct:2, exp:"Al menos 2 años."},
{q:"What is the legal obligation of an operator regarding mobile workers who work for MULTIPLE employers?", options:["The operator must request in writing a statement of working time performed for other employers, and the worker must provide it","Employers are forbidden from knowing about work for other companies","Second jobs are strictly illegal under all circumstances","Only the main employer keeps records"], correct:0, exp:"Debe pedir por escrito una declaración del tiempo trabajado para otros empleadores."},
{q:"Does time spent traveling to take charge of a vehicle located away from the base count as Working Time or Period of Availability?", options:["It counts as Rest","It counts as Working Time (or Period of Availability depending on whether the driver is driving or traveling as a passenger on train/ferry)","It is completely ignored","It counts as annual leave"], correct:1, exp:"Cuenta como Working Time o POA, según el caso."},
{q:"What is a 'Self-employed driver' under Directive 2002/15/EC?", options:["Anyone driving a taxi","A driver whose main employment is transport, who holds an operator licence, has freedom to organize work, and whose income depends directly on profits","A driver employed by an agency","A part-time driver working weekends"], correct:1, exp:"Ocupación principal el transporte, licencia propia, libertad de organización e ingresos ligados al beneficio."},
{q:"Are self-employed drivers subject to the maximum average 48-hour working week and night work limits under Irish WTD law?", options:["No, self-employed drivers are totally exempt","Yes, self-employed drivers are fully within the scope of Directive 2002/15/EC and must comply with working time limits","Only if operating international routes","Only if driving vehicles over 18 tonnes"], correct:1, exp:"Sí, plenamente dentro del ámbito de la Directiva."},
{q:"Which statutory authority in Ireland is responsible for enforcing Working Time Directive compliance for mobile workers in road transport?", options:["National Transport Authority (NTA)","Workplace Relations Commission (WRC) in conjunction with the Road Safety Authority (RSA)","Revenue Commissioners","Health and Safety Authority (HSA) exclusively"], correct:1, exp:"WRC junto con la RSA."},
{q:"What happens if an employer fails to maintain accurate working time records for mobile workers for at least 2 years?", options:["They receive a verbal reminder","It is an offence under Statutory Instrument No. 36 of 2012, punishable by court fines of up to €5,000 per offence","The company's tax rate increases by 5%","Drivers automatically receive 10 extra days of leave"], correct:1, exp:"Delito bajo el S.I. 36/2012, con multas de hasta €5,000."},
{q:"What mode must a digital tachograph be set to while a driver is performing manual loading, cleaning, or administrative work?", options:["Rest / Break (Bed symbol)","Other Work (Crossed hammers symbol)","Availability (Square symbol with diagonal line)","Driving (Steering wheel symbol)"], correct:1, exp:"Other Work (martillos cruzados)."},
{q:"When a driver is waiting at a terminal for a ferry departure and has been informed in advance that the delay will last 2 hours, how should this time be logged?", options:["Working Time ('Other Work')","Period of Availability (POA - 'Square/Envelope' symbol)","Driving Time","Annual Leave"], correct:1, exp:"Period of Availability (POA)."},
{q:"Is a driver permitted to perform 'Other Work' for a non-transport employer (e.g., bartending or security) during their off-duty hours without informing their transport employer?", options:["Yes, private work is unmonitored","No, all work performed for any employer constitutes 'Other Work' and must be declared to ensure overall 48-hour weekly limits and rest rules are respected","Yes, provided it pays cash","Only if conducted on public holidays"], correct:1, exp:"Debe declararse para respetar el límite de 48h."},
{q:"If a driver works 50 hours in Week 1, 55 hours in Week 2, 45 hours in Week 3, and 42 hours in Week 4, what is their average weekly working time over this 4-week period?", options:["45.0 hours","48.0 hours","49.0 hours","52.0 hours"], correct:1, exp:"(50+55+45+42)÷4 = 48.0 horas."},
{q:"What is the maximum permitted working time in a single week if a driver works 60 hours in Week 1?", options:["60 hours is legal provided the average over the 4-month reference period does not exceed 48 hours per week","60 hours is strictly illegal under all circumstances","60 hours is only allowed for international trips","60 hours requires written permission from the Gardaí"], correct:0, exp:"Legal si la media del periodo de referencia no supera 48h/semana."},
{q:"Under WTD rules, if a shift involves 5 hours of total working time, how much break time is legally required?", options:["0 minutes (breaks are only compulsory after 6 hours of work)","15 minutes","30 minutes","45 minutes"], correct:0, exp:"0 minutos (obligatorio solo a partir de 6h)."},
{q:"Under WTD rules, if a shift involves 7 hours of total working time, what is the minimum break required?", options:["15 minutes","30 minutes","45 minutes","60 minutes"], correct:1, exp:"30 minutos."},
{q:"Under WTD rules, if a shift involves 9.5 hours of total working time, what is the minimum break required?", options:["30 minutes","45 minutes","60 minutes","90 minutes"], correct:1, exp:"45 minutos."},
{q:"Does a 45-minute driving break taken under Regulation 561/2006 also satisfy the break requirements of the Working Time Directive?", options:["No, WTD breaks are separate and additional","Yes, a break that satisfies Regulation 561/2006 also satisfies the WTD break requirement for that working period","Only if taken in a hotel","Only if approved by the WRC"], correct:1, exp:"Sí, la misma pausa cuenta para ambas normas."},
{q:"Can a driver extend the 10-hour night work limit to 12 hours if a formal collective agreement or workforce agreement is in place?", options:["No, night work limits can never be extended","Yes, night work limits may be extended by collective or workforce agreements provided health and safety principles are respected","Yes, but only for drivers under 25 years old","Only during national emergencies"], correct:1, exp:"Sí, con acuerdo colectivo respetando la salud/seguridad."},
{q:"What is the reference period default framework in Ireland if no collective agreement specifies otherwise?", options:["Standard rolling 4-month calendar periods (Jan-Apr, May-Aug, Sep-Dec)","Fixed 52-week periods","1-week periods","2-year periods"], correct:0, exp:"Periodos de 4 meses (ene-abr, may-ago, sep-dic)."},
{q:"How does the Working Time Directive define 'mobile worker'?", options:["Any worker employed as a member of traveling staff (driver, conductor, attendant) by an undertaking engaged in road passenger or goods transport","Office clerks using mobile phones","Mechanics fixing vehicles in the depot workshop","Security guards at depot gates"], correct:0, exp:"Personal itinerante de una empresa de transporte."},
{q:"What record must an employer provide to a mobile worker upon request regarding their working time history?", options:["A written copy of their recorded working hours for the previous 2 years","A copy of company tax returns","The Transport Manager's personal logbook","Vehicle repair bills"], correct:0, exp:"Copia escrita de sus horas de los últimos 2 años."},
{q:"What is the primary purpose of the Road Transport Working Time Directive 2002/15/EC?", options:["To prevent driver fatigue, protect mobile workers' health and safety, improve road safety, and ensure fair competition in transport","To increase revenue from speed limiters","To replace digital tachographs with paper logs","To eliminate driver overtime pay"], correct:0, exp:"Prevenir la fatiga, proteger la salud/seguridad y mejorar la seguridad vial."},
{q:"In Case Study calculations, if a driver completes 4 hours of driving, 2 hours of loading ('Other Work'), and 1 hour of POA in a day, what is their total 'Working Time' for WTD purposes?", options:["4 hours","6 hours (4h driving + 2h loading; POA is excluded)","7 hours","5 hours"], correct:1, exp:"6 horas (el POA se excluye)."},
{q:"If a mobile worker works from 01:00 to 09:00 (including 01:00 to 04:00 night time), what is the maximum total working time allowed for that shift unless covered by a collective agreement?", options:["8 hours","10 hours","12 hours","15 hours"], correct:1, exp:"10 horas."},
{q:"Are agency drivers covered by the Road Transport Working Time Regulations?", options:["No, agency drivers are exempt","Yes, both the employment agency and the hirer (operator) share responsibility to ensure WTD limits are monitored and respected","Agency drivers can work unlimited hours","Only if driving vehicles under 3.5 tonnes"], correct:1, exp:"Sí, agencia y operador comparten responsabilidad."},
{q:"What symbol represents 'Period of Availability' (POA) on digital tachograph displays and printouts?", options:["Steering wheel","Crossed hammers","Square / Envelope box symbol","Bed / Chair symbol"], correct:2, exp:"Cuadrado/sobre."},
{q:"What is the role of a Transport Manager regarding Working Time Directive compliance?", options:["Establishing systems to track, record, and audit mobile workers' total working hours, ensuring average 48h limits, break rules, and night work limits are strictly enforced","Paying driver fines out of personal funds","Forcing drivers to work 70 hours every week","Ignoring multi-job declarations by drivers"], correct:0, exp:"Establecer sistemas de rastreo y auditoría del cumplimiento del WTD."}
]},
"25": { title: "Tema 25 - Driver Rest Rules & Exemptions", questions: [
{q:"Under EU Regulation (EC) No 561/2006, what is the default legal classification for a passenger transport service operating on a route where the distance does NOT exceed 50 km?", options:["Exempt from EU Drivers' Hours rules and tachograph requirements (subject to national domestic rules)","Subject to full EU driving time and break limits","Exempt from all speed limits","Covered by international AETR rules exclusively"], correct:0, exp:"Exenta de reglas UE, sujeta a normativa doméstica."},
{q:"Under Irish national law, what legislation governs passenger transport operations that fall OUT OF SCOPE of EU Regulation 561/2006 (e.g. regular services under 50 km)?", options:["Road Transport Act 1933 and Transport Regulations (Irish Domestic Drivers' Hours Rules)","Companies Act 2014","Working Time Act 1997","Safety, Health and Welfare at Work Act 2005"], correct:0, exp:"Road Transport Act 1933 y las reglas domésticas."},
{q:"Under Irish domestic drivers' hours rules for out-of-scope bus operations, what is the maximum continuous driving limit before a mandatory break?", options:["4.5 hours","5.5 hours","6.0 hours","8.0 hours"], correct:1, exp:"5.5 horas."},
{q:"What is the minimum break required after 5.5 hours of continuous driving under Irish domestic bus rules?", options:["15 minutes","30 minutes","45 minutes","60 minutes"], correct:1, exp:"30 minutos."},
{q:"Under Irish domestic bus rules, what is the absolute maximum daily driving time permitted for a driver?", options:["8 hours","9 hours","10 hours","11 hours"], correct:2, exp:"10 horas."},
{q:"What is the maximum permitted daily spreadover (working day duration) under Irish domestic rules for out-of-scope passenger transport?", options:["12 hours","14 hours","16 hours","18 hours"], correct:2, exp:"16 horas."},
{q:"What is the standard minimum daily rest period required within a 24-hour period under Irish domestic bus rules?", options:["8 hours","9 hours","10 hours","11 hours"], correct:2, exp:"10 horas."},
{q:"To what duration may the domestic daily rest period (10 hours) be reduced, and how many times per week?", options:["Reduced to 8.5 hours up to 3 times per week","Reduced to 8.0 hours twice per week","Reduced to 9.0 hours once per week","No reductions are permitted under domestic rules"], correct:0, exp:"8.5 horas, hasta 3 veces/semana."},
{q:"Is a driver who drives a bus for LESS than 4 hours on any day required to comply with domestic daily rest rules for that day?", options:["Yes, rest rules apply regardless of driving time","No, drivers who drive for less than 4 hours in a day are exempt from domestic rest requirements for that day","Only if driving double-deck buses","Only on weekends"], correct:1, exp:"No, exento ese día."},
{q:"What special exemption applies to regular passenger services where the route length does NOT exceed 50 km under EU Regulation 561/2006?", options:["Exemption from fitting or using tachographs and compliance with EU driving limits (Article 3(a))","Exemption from holding a driving licence","Exemption from vehicle motor tax","Exemption from passenger fare tariffs"], correct:0, exp:"Exención de tacógrafo y límites UE (Artículo 3(a))."},
{q:"Which of the following passenger transport operations is ALSO exempt from EU Regulation 561/2006?", options:["Vehicles with a maximum seating capacity of 9 to 16 seats used exclusively for non-commercial carriage of passengers","Specialized breakdown vehicles operating within 100 km of base","Vehicles used by armed forces, civil defence, fire services, and emergency services","All of the above"], correct:3, exp:"Todas las anteriores."},
{q:"If a passenger transport operator uses a vehicle carrying 12 passengers for a non-commercial community trip, is a digital tachograph legally required?", options:["Yes, tachographs are mandatory for all vehicles with over 8 seats","No, non-commercial carriage of passengers in vehicles up to 16 passenger seats is exempt from EU tachograph rules","Yes, if driving on motorways","Only if the driver is paid overtime"], correct:1, exp:"No, exento hasta 16 asientos no comercial."},
{q:"What is the legal requirement when a driver operates a mixed schedule (driving part of the day on an exempt 30 km route and part on a non-exempt 150 km tour)?", options:["The entire day must be recorded on the digital tachograph, with domestic driving logged as 'Other Work'","The driver removes the tachograph card during the domestic route","The driver is exempt from all driving hours rules for the rest of the week","Domestic driving is logged as 'Break/Rest'"], correct:0, exp:"Todo el día en el tacógrafo, ruta doméstica como 'Other Work'."},
{q:"Can time spent driving on an exempt local bus route (under 50 km) be counted as a Break or Daily Rest under EU rules?", options:["Yes, local driving is considered rest","No, driving an exempt route constitutes 'Other Work' under EU rules and cannot count as break or rest","Yes, if average speed is under 20 km/h","Only if the driver holds a part-time contract"], correct:1, exp:"No, es 'Other Work', nunca cuenta como pausa/descanso."},
{q:"What is the '12-Day Rule' (Article 8(6a) of Regulation 561/2006) in international road passenger transport?", options:["A concession allowing international coach drivers on a single passenger trip to postpone their weekly rest period for up to 12 consecutive 24-hour periods","A rule allowing drivers to work 12 weeks without a holiday","A requirement to stay in a hotel every 12 days","A rule restricting international tours to a maximum of 12 passengers"], correct:0, exp:"Posponer el descanso semanal hasta 12 periodos de 24h."},
{q:"Which of the following conditions MUST be satisfied to legally use the International 12-Day Rule?", options:["The service must be a single international passenger service (crossing at least one border) lasting at least 24 consecutive hours","The driver took a regular weekly rest (at least 45 hours) immediately prior to the journey","Following the 12 days, the driver takes two regular weekly rest periods (45h + 45h) OR one regular and one reduced weekly rest (45h + 24h with full compensation)","All of the above"], correct:3, exp:"Todas las condiciones deben cumplirse."},
{q:"What additional safety/technical requirement applies under the 12-Day Rule if driving occurs between 22:00 and 06:00?", options:["The vehicle must be multi-manned OR the continuous driving period before a break is reduced from 4.5 hours to 3 hours","Night driving is strictly forbidden","The vehicle speed limiter must be set to 80 km/h","Passengers must remain awake"], correct:0, exp:"Doble tripulación O reducir a 3h la conducción continua."},
{q:"Since 1st January 2014, what tachograph requirement must vehicles satisfy to utilize the 12-Day Rule?", options:["Analog tachographs only","The vehicle must be fitted with a digital tachograph / smart tachograph","No tachograph is required","Hand-written logbooks only"], correct:1, exp:"Tacógrafo digital/inteligente."},
{q:"Can the 12-Day Rule concession be used on purely DOMESTIC Irish passenger tours (e.g., Dublin to Kerry tour)?", options:["Yes, all tours qualify","No, the 12-Day Rule applies strictly to INTERNATIONAL passenger transport (crossing at least one border)","Yes, if approved by the RSA","Only during summer bank holidays"], correct:1, exp:"No, solo internacional."},
{q:"What is the rules framework for driving hours when transporting passengers on international journeys between Ireland and non-EU AETR countries (e.g., Switzerland, UK, Turkey)?", options:["AETR Agreement rules (which align closely with EU Regulation 561/2006)","Irish domestic rules","US Federal Highway rules","United Nations Maritime law"], correct:0, exp:"El Acuerdo AETR."},
{q:"When a driver accompanies a coach carried on a ferry or train, how may a regular daily rest period (at least 11 hours) be interrupted?", options:["Interrupted maximum twice for other activities, with total interruptions not exceeding 1 hour, provided the driver has access to a sleeper cabin or bunk","Interrupted up to 5 times for 3 hours total","Interrupted only if the vehicle is unloaded by harbour staff","Regular daily rest cannot be taken on a ferry"], correct:0, exp:"Máximo 2 veces, sin superar 1h, con litera."},
{q:"Does the ferry interruption concession apply to REDUCED daily rest periods (9 hours)?", options:["Yes, all daily rest periods qualify","No, the ferry interruption rule applies strictly to REGULAR daily rest periods (11 hours) or regular weekly rest periods under specific conditions","Only if the ferry journey takes over 12 hours","Only on domestic ferries within Ireland"], correct:1, exp:"Solo al descanso diario REGULAR (11h)."},
{q:"Under EU Regulation 561/2006, what is the rule regarding taking REGULAR weekly rest (45 hours) inside the vehicle cab?", options:["Permitted if the cab has a comfortable bunk","Strictly prohibited; regular weekly rest and any weekly rest of more than 45 hours taken as compensation MUST be taken in suitable, gender-friendly accommodation with adequate sleeping and sanitary facilities (paid by employer)","Permitted only in designated motorway service areas","Mandatory for international drivers"], correct:1, exp:"Prohibido; debe tomarse en alojamiento adecuado."},
{q:"Can REDUCED weekly rest (24 hours to 44 hours) be taken in the vehicle cab?", options:["Yes, provided the vehicle has suitable sleeping facilities for each driver and is stationary","No, reduced weekly rest must also be taken in a hotel","Only if authorized by Gardaí","Never under any circumstances"], correct:0, exp:"Sí, con literas adecuadas y vehículo parado."},
{q:"What is the penalty for an operator who forces drivers to take regular weekly rest periods (45 hours) inside the vehicle cab?", options:["Minor administrative warning","Severe enforcement fines, court prosecution, and potential suspension or revocation of the Operator Licence by the Department of Transport","Exemption from toll charges","Reduced motor tax rates"], correct:1, exp:"Multas graves, procesamiento y riesgo de suspensión de licencia."},
{q:"What is the maximum continuous driving limit allowed under EU Regulation 561/2006 before a mandatory 45-minute break?", options:["4.0 hours","4.5 hours (4 hours 30 minutes)","5.0 hours","5.5 hours"], correct:1, exp:"4.5 horas."},
{q:"If a driver takes a 15-minute break after 2 hours of driving, how long must the second break be to satisfy the split break requirement under EU rules?", options:["15 minutes","30 minutes","45 minutes","60 minutes"], correct:1, exp:"30 minutos."},
{q:"Under EU rules, is it legal to take a 30-minute break first, followed by a 15-minute break later?", options:["Yes, the order does not matter","No, under EU Regulation 561/2006 split breaks MUST be taken as 15 minutes first, followed by 30 minutes (15m + 30m)","Only on international routes","Only for minibus drivers"], correct:1, exp:"No, el orden correcto es 15 min primero, 30 min después."},
{q:"What is the legal status of an emergency departure from driving hours rules under Article 12 of Regulation 561/2006?", options:["Drivers may exceed driving limits to enable the vehicle to reach a suitable stopping place to ensure safety of persons, vehicle, or load, provided road safety is not endangered","Drivers must indicate the reason manually on the tachograph chart/printout upon arrival at the stopping place","It cannot be used for known or predictable delays (such as scheduled traffic jams)","All of the above"], correct:3, exp:"Todo lo anterior aplica."},
{q:"In Case Study calculations, an operator runs an urban bus service on a 25 km route. What hours regime applies to this service?", options:["EU Regulation 561/2006","Irish Domestic Regulations (out-of-scope of EU rules because route <= 50 km)","AETR rules","No driving hours rules apply"], correct:1, exp:"Reglas domésticas irlandesas."},
{q:"In Case Study calculations, a driver on a domestic 25 km bus route drives 5 hours continuously without a break. Is this legal under Irish domestic rules?", options:["Yes, domestic rules permit up to 5.5 hours continuous driving before a 30-minute break","No, continuous driving is limited to 4.5 hours under all laws","Yes, domestic rules allow unlimited driving","No, domestic rules require a break after 3 hours"], correct:0, exp:"Sí, hasta 5.5h continuas."},
{q:"If a driver on an exempt route works a 15-hour spreadover day with 9 hours driving under domestic rules, is this legal under Irish domestic regulations?", options:["No, maximum spreadover is 12 hours","Yes, domestic rules permit a maximum spreadover of up to 16 hours and daily driving up to 10 hours","No, daily driving cannot exceed 8 hours","Only with written permission from the RSA"], correct:1, exp:"Sí, dentro de los límites domésticos (16h spreadover, 10h conducción)."},
{q:"What record-keeping mechanism must be used by drivers operating domestic out-of-scope bus services if no tachograph is fitted?", options:["Domestic driver logbook / duty roster sheets recording start, finish, driving hours, and rest periods","Verbal notes to dispatchers","Mobile phone text messages","No records are required for domestic transport"], correct:0, exp:"Libro de registro/hoja de turnos doméstica."},
{q:"How long must an operator retain domestic driver logbooks and duty rosters for RSA inspection?", options:["6 months","At least 12 months (or 2 years under Working Time compliance)","3 years","5 years"], correct:1, exp:"Al menos 12 meses (2 bajo Working Time)."},
{q:"What is the definition of 'Multi-manning' (double-manning) under EU Regulation 561/2006?", options:["During each period of driving between two consecutive daily rest periods, or between a daily rest and a weekly rest, there are at least two drivers on board to drive","For the first hour of multi-manning, the presence of the second driver is optional, but compulsory for the remainder","Both A and B","Two drivers operating separate buses on the same route"], correct:2, exp:"A y B: al menos 2 conductores, con la primera hora opcional para el segundo."},
{q:"Under multi-manning, what daily rest requirement must each driver fulfill within a 30-hour period?", options:["A daily rest period of at least 9 hours","A daily rest period of at least 11 hours","A daily rest period of at least 12 hours","No daily rest is required while traveling as passenger"], correct:0, exp:"Al menos 9 horas."},
{q:"Is time spent by Driver B sitting in the passenger seat while Driver A drives under multi-manning counted as Rest or Break?", options:["It is counted as Rest","It is counted as Period of Availability (POA), except for a 45-minute break portion which can count as a break if Driver B is not assisting Driver A","It is counted as Driving Time","It is counted as Other Work"], correct:1, exp:"POA, salvo la porción de 45 min como pausa."},
{q:"What is the impact of failing to comply with rest rules and drivers' hours on the Transport Manager's status?", options:["Loss of Good Repute, leading to disqualification as a Transport Manager under Regulation (EC) 1071/2009","Fine paid by the insurance company","Automatic conversion of Operator Licence to private status","No personal impact on the manager"], correct:0, exp:"Pérdida de Buena Reputación, con descalificación."},
{q:"What is the legal requirement for driver rest compensation when a reduced weekly rest (e.g. 24 hours) is taken?", options:["The reduction (21 hours) must be compensated by an equivalent period of rest taken en bloc before the end of the third week following the week in question, attached to another rest period of at least 9 hours","Compensation can be paid as financial bonus","Compensation is waived for passenger operators","Compensation must be taken within 48 hours"], correct:0, exp:"Compensación en bloque antes de la 3ª semana siguiente."},
{q:"What is the primary objective of enforcing strict driver rest rules, bus driver rules, and exemptions across Ireland and the EU?", options:["Ensuring driver alertness, preventing fatigue-related road collisions, protecting worker health, and maintaining fair competition in the passenger transport sector","Maximizing passenger fare revenues for private companies","Eliminating the use of digital tachographs","Encouraging single-driver long-distance travel"], correct:0, exp:"Alerta del conductor, prevenir colisiones por fatiga y competencia justa."}
]},
"26": { title: "Tema 26 - Tachograph Calibration & Operation", questions: [
{q:"Which EU Regulation sets the technical standards, installation, calibration, and operational rules for digital and smart tachographs?", options:["Regulation (EC) No 561/2006","Regulation (EU) No 165/2014","Directive 2003/59/EC","Regulation (EC) No 1071/2009"], correct:1, exp:"Reglamento (UE) 165/2014."},
{q:"How often MUST a commercial vehicle tachograph system undergo full recalibration and inspection at an approved workshop?", options:["Every 1 year","Every 2 years (24 months)","Every 3 years","Every 6 years"], correct:1, exp:"Cada 2 años."},
{q:"In addition to the bi-annual (2-year) recalibration, under what other circumstances MUST a tachograph be recalibrated immediately?", options:["If the vehicle registration number changes","If the effective circumference of the tyres (tyre size) changes or repairs affect the calibration parameters","If the vehicle's speed limiter or gearbox is repaired/replaced","All of the above"], correct:3, exp:"Todo lo anterior."},
{q:"What physical proof must be affixed to the vehicle near or on the tachograph following a successful calibration?", options:["A green RSA sticker on the bumper","A Tachograph Calibration Plaque / Certificate showing the characteristic coefficient (w), effective tyre circumference (l), workshop details, and date","The driver's CPC card","A copy of the motor tax disc"], correct:1, exp:"Placa/certificado de calibración con coeficientes y datos del taller."},
{q:"Who is legally authorised to calibrate, seal, and issue calibration plaques for tachographs in Ireland?", options:["Any licensed commercial bus driver","The Transport Manager using a smartphone app","An authorised tachograph workshop / approved technician certified by the Road Safety Authority (RSA)","Local Garda stations"], correct:2, exp:"Un taller/técnico autorizado por la RSA."},
{q:"How long is an analogue tachograph chart designed to record data?", options:["12 hours","24 hours","48 hours","7 days"], correct:1, exp:"24 horas."},
{q:"What color is the trace made by the stylus on an analogue tachograph chart paper?", options:["Blue ink","Red ink","Black / grey trace on pressure-sensitive wax-coated paper","Pencil lead"], correct:2, exp:"Trazo negro/gris sobre papel encerado sensible a la presión."},
{q:"On an analogue tachograph chart, what information MUST a driver write manually on the centre field BEFORE starting their duty?", options:["Driver's surname and first name, location where record begins, date, vehicle registration number, and starting odometer reading","Fuel price and weather condition","Employer's tax registration number","Passenger ticket count"], correct:0, exp:"Nombre, lugar y fecha de inicio, matrícula y cuentakilómetros inicial."},
{q:"On an analogue tachograph chart, what information MUST a driver write manually on the centre field at the END of their duty?", options:["Total fare revenue collected","Location where record ends, date record ends, and closing odometer reading (calculating total km driven)","Next day's weather forecast","Workshop technician signature"], correct:1, exp:"Lugar y fecha de fin, y cuentakilómetros final."},
{q:"If a driver changes vehicles during a working day, how is this recorded on an analogue tachograph chart?", options:["A new chart must be used for each vehicle","The driver writes the details of the second vehicle (registration, time of change, odometer reading) on the reverse side of the existing chart","Vehicle changes cannot be recorded manually","The driver logs off until the next day"], correct:1, exp:"Anota los datos del segundo vehículo en el reverso del disco."},
{q:"What are the four operational mode symbols displayed on digital and analogue tachographs?", options:["Steering Wheel (Driving), Crossed Hammers (Other Work), Square/Envelope (Availability - POA), Bed/Chair (Rest/Break)","Car, Truck, Bus, Taxi","Speed, Distance, Time, Fuel","Red, Amber, Green, Blue"], correct:0, exp:"Volante, martillos cruzados, cuadrado/sobre y cama/silla."},
{q:"Which mode is automatically selected by a digital tachograph as soon as the vehicle begins moving?", options:["Other Work","Availability (POA)","Driving Mode","Rest / Break"], correct:2, exp:"Modo Conducción."},
{q:"When a vehicle comes to a complete standstill, what mode does a digital tachograph default to (unless changed manually by the driver)?", options:["Driving Mode","Other Work (or Availability depending on configuration)","Rest / Break","Power off"], correct:1, exp:"Other Work (u Availability según configuración)."},
{q:"What are the four different types of Smart Tachograph / Digital Tachograph Cards used in the EU system?", options:["Driver Card, Workshop Card, Control Card, and Company Card","Fuel Card, Toll Card, Maintenance Card, and Driver Card","Bronze, Silver, Gold, and Platinum Cards","RSA Card, Garda Card, NTA Card, and Revenue Card"], correct:0, exp:"Tarjeta de Conductor, Taller, Control y Empresa."},
{q:"What is the validity period of a Digital Tachograph Driver Card issued by the RSA in Ireland?", options:["1 year","2 years","5 years","10 years"], correct:2, exp:"5 años."},
{q:"What is the validity period of a Tachograph Workshop Card?", options:["1 year","2 years","3 years","5 years"], correct:0, exp:"1 año."},
{q:"How long is a Tachograph Company Card valid once issued to an operator?", options:["1 year","3 years","5 years","10 years"], correct:2, exp:"5 años."},
{q:"What is the primary function of a Tachograph Company Card?", options:["To allow drivers to drive without inserting their driver card","To lock / protect company tachograph data, authorise downloads of vehicle unit (VU) data, and prevent unauthorized access by competitors","To pay road tolls on motorways automatically","To calibrate the speed limiter"], correct:1, exp:"Bloquear/proteger datos, autorizar descargas de la VU."},
{q:"Under EU Regulation 165/2014, how often MUST an operator download data from a driver's digital tachograph card?", options:["At least every 7 days","At least every 14 days","At least every 28 days","At least every 90 days"], correct:2, exp:"Al menos cada 28 días."},
{q:"How often MUST an operator download data from the digital tachograph Vehicle Unit (VU)?", options:["At least every 28 days","At least every 56 days","At least every 90 days","Annually"], correct:2, exp:"Al menos cada 90 días."},
{q:"What action must a driver take if their digital tachograph card is lost, stolen, or damaged while away from base?", options:["Stop driving immediately and wait for a new card to be delivered","Continue driving without making any records","Print out a daily report at the beginning and end of each journey, write personal details and signature on the printouts, and apply to the RSA for a replacement card within 7 calendar days","Borrow another driver's card temporarily"], correct:2, exp:"Impresiones diarias con datos y firma, y solicitar reemplazo en 7 días."},
{q:"Within how many days must a driver apply to the RSA for a replacement digital tachograph card if it is lost, stolen, or malfunctioning?", options:["Within 3 calendar days","Within 7 calendar days","Within 14 calendar days","Within 28 calendar days"], correct:1, exp:"7 días naturales."},
{q:"What is the maximum period a driver is legally permitted to continue driving without a digital tachograph card (using manual daily printouts) while awaiting a replacement?", options:["7 calendar days","15 calendar days (or longer if necessary to return the vehicle to base, provided proof of replacement application is available)","30 calendar days","Unlimited time"], correct:1, exp:"15 días naturales (o más si es necesario volver a la base)."},
{q:"What mandatory feature was introduced with Smart Tachographs Version 1 (GEN2 V1) enforced on new vehicles since August 2019?", options:["Automated satellite positioning (GNSS) recording position at start/end of day and every 3 hours of accumulated driving, plus DSRC remote enforcement communication","Voice recording of driver conversations","Facial recognition cameras in the cab","Automatic speed reduction on corners"], correct:0, exp:"Posición GNSS al inicio/fin del día y cada 3h, más DSRC."},
{q:"Smart Tachographs Version 2 (GEN2 V2), mandatory on new registered vehicles since August 2023, includes which additional capability?", options:["Automatic recording of international border crossings and automated loading/unloading position registration","Remote engine cutoff by police","Automated passenger headcounts","Tire pressure auto-inflation"], correct:0, exp:"Registro automático de cruces de frontera y carga/descarga."},
{q:"What technology allows roadside enforcement officers (RSA/Gardaí) to read basic tachograph compliance data from a moving vehicle without stopping it?", options:["DSRC (Dedicated Short-Range Communication) wireless technology","Satellite radar imaging","Infrared thermal cameras","Bluetooth audio broadcasting"], correct:0, exp:"DSRC."},
{q:"Can a roadside officer issue a fine solely based on data transmitted via DSRC from a moving vehicle?", options:["Yes, fines are issued automatically by DSRC","No, DSRC data is used only to screen and select vehicles for stopping; physical inspection is required before issuing penalties","DSRC is used exclusively for toll payments","Yes, penalty points are added to the licence instantly"], correct:1, exp:"Solo para filtrar vehículos; requiere inspección física."},
{q:"If a driver forgets to insert their driver card into the tachograph at the start of a shift and drives for 2 hours, what is recorded on the Vehicle Unit (VU)?", options:["Nothing is recorded","An 'Unauthorised Driving' / 'Driving without appropriate card' event is recorded in the VU memory","The VU automatically deletes the driving log","The engine locks automatically"], correct:1, exp:"Evento de 'conducción sin tarjeta apropiada'."},
{q:"How must a driver record activities performed away from the vehicle (such as administrative work or training) before inserting their card into a digital tachograph?", options:["By performing a manual entry on the tachograph display upon card insertion","By writing a note on a piece of paper and leaving it in the glovebox","Manual entries are not permitted on digital tachographs","By calling the RSA call centre"], correct:0, exp:"Entrada manual en la pantalla al insertar la tarjeta."},
{q:"If a digital tachograph unit breaks down or malfunctions during a journey, within how many days must it be repaired by an approved workshop?", options:["Within 24 hours","Within 7 calendar days of the breakdown","Within 14 calendar days","At the next annual CVRT test"], correct:1, exp:"Dentro de 7 días naturales."},
{q:"While traveling with a broken tachograph unit during the 7-day grace period, how must the driver record their driving and rest activities?", options:["On temporary paper printouts or on the reverse of analogue charts/printout rolls, making manual entries","No records are required until the unit is fixed","Verbal notes to the transport manager","Using a smartphone stopwatch"], correct:0, exp:"Impresiones temporales de papel con entradas manuales."},
{q:"How long must an operator retain all downloaded digital tachograph files, printouts, and analogue charts at their operating base?", options:["At least 6 months","At least 12 months (and 2 years if used for Working Time Directive compliance)","At least 3 years","5 years"], correct:1, exp:"Al menos 12 meses (2 si son para Working Time)."},
{q:"How many preceding days of tachograph records must a driver carry on board the vehicle and present to enforcement officers upon request?", options:["Current day plus preceding 7 days","Current day plus preceding 14 days","Current day plus preceding 28 calendar days","Current day plus preceding 56 calendar days"], correct:2, exp:"El día actual más los 28 días naturales anteriores."},
{q:"What is the legal outcome if an operator fails to lock-in their company card before placing a new digital tachograph vehicle into service?", options:["The vehicle unit cannot record driving time","Company data is not protected, allowing subsequent users or downloaders to view un-encrypted operational data, and risking audit failure","The vehicle motor tax becomes invalid","The driver card is destroyed automatically"], correct:1, exp:"Datos sin proteger, riesgo de fallar una auditoría."},
{q:"What is the requirement regarding spare printer paper rolls for digital tachographs?", options:["Spare rolls are optional","Drivers MUST carry a sufficient supply of approved spare printer paper rolls in the vehicle at all times to produce printouts on request","Printer rolls are only needed at workshop inspections","Paper rolls are provided free by Gardaí at roadside checks"], correct:1, exp:"El conductor DEBE llevar suficiente papel de repuesto siempre."},
{q:"Under EU Regulation 165/2014, what is the penalty for tampering with a tachograph (e.g. using magnets, cheat devices, or modified software)?", options:["Minor administrative warning","Criminal prosecution, severe court fines up to €5,000, potential imprisonment, vehicle impoundment, and loss of Good Repute / Operator Licence","1-day suspension of driving licence","Re-taking the driver CPC theory test"], correct:1, exp:"Procesamiento penal, multas hasta €5,000, posible prisión."},
{q:"What information is stored on a digital tachograph Driver Card?", options:["Driver identity, driving licence details, vehicle registration numbers driven, dates/times of driving, other work, availability, rest, and fault/event logs","Personal bank account details","Passenger home addresses","Vehicle fuel consumption rates"], correct:0, exp:"Identidad, datos de licencia, matrículas conducidas, actividad y eventos."},
{q:"Can a driver hold more than one valid digital tachograph Driver Card at any time?", options:["Yes, one for each employer","No, a driver may hold ONLY ONE valid driver card; holding multiple cards or using another driver's card is a serious criminal offence","Yes, one for domestic and one for international routes","Only if authorized by the Transport Manager"], correct:1, exp:"Solo UNA — tener varias es delito grave."},
{q:"What is the role of the Transport Manager regarding tachograph compliance?", options:["Downloading driver cards every 28 days and VUs every 90 days, auditing records for infringements, issuing written warnings to non-compliant drivers, and retaining auditable files for 12+ months","Driving all fleet vehicles personally to test tachographs","Paying driver speeding fines from personal accounts","Changing tachograph clock times manually during daylight saving transitions"], correct:0, exp:"Descargar tarjetas/VUs periódicamente, auditar y conservar archivos."},
{q:"How often must the internal clock (UTC time) of a digital tachograph be verified against standard time?", options:["Automatically via satellite (GNSS) on smart tachographs, or verified during bi-annual calibration checks at authorised workshops","Manually by the driver every morning","Every 5 years","Clock verification is not required"], correct:0, exp:"Vía satélite en los inteligentes, o en la recalibración bianual."}
]},
"28": { title: "Tema 28 - Bus and Coach Operations", questions: [
{q:"Under Irish law, what requirement applies if a passenger transport vehicle carrying 8 or fewer passenger seats is used to carry passengers at separate fares?", options:["No licence is required under any circumstances","It requires a Road Passenger Transport Operator Licence unless all passengers pre-book and agree the fare structure in advance and the vehicle is not providing a public passenger service","It must automatically be registered as a heavy goods vehicle (HGV)","It requires an international maritime permit"], correct:1, exp:"Necesita licencia salvo reserva/tarifa acordada de antemano sin ser servicio público."},
{q:"How is 'Hire or Reward' legally defined in passenger transport operations in Ireland?", options:["Any payment made directly or indirectly for travel, or payment permitting a person to travel (including employee travel paid by employers)","Payments made strictly in cash to the driver","Payments exceeding €1,000 per journey","Transporting family members free of charge"], correct:0, exp:"Cualquier pago directo o indirecto por el viaje."},
{q:"If an employer operates a bus to transport employees to and from work and deducts money from their pay or requires a contribution, what is the legal requirement?", options:["The operation is exempt from all licensing","The operation constitutes 'hire or reward' and requires a Road Passenger Transport Operator Licence and Large Public Service Vehicle (LPSV) licensing","The driver only needs a Category B licence","The bus is exempt from annual CVRT testing"], correct:1, exp:"Es 'hire or reward', requiere licencia de operador y LPSV."},
{q:"If an employer contracts a specialized travel firm to transport employees to work at no charge to the employees, which entity is operating for hire or reward?", options:["The employer","The specialized travel firm contracted to provide the service","The employees","The local county council"], correct:1, exp:"La empresa de viajes contratada."},
{q:"Under Irish law, who is the statutory licensing authority for commercial public bus passenger services (scheduled routes) under the Public Transport Regulation Act 2009?", options:["Road Safety Authority (RSA)","National Transport Authority (NTA)","An Garda Síochána","Revenue Commissioners"], correct:1, exp:"NTA."},
{q:"Who issues the Large Public Service Vehicle (LPSV) licence required for vehicles carrying more than 8 passengers for hire or reward in Ireland?", options:["A PSV Officer of An Garda Síochána","The Department of Transport (RTOL Division)","The National Transport Authority (NTA)","The Health and Safety Authority (HSA)"], correct:0, exp:"Un PSV Officer de An Garda Síochána."},
{q:"For how long is a Large Public Service Vehicle (LPSV) licence issued by An Garda Síochána valid?", options:["1 year","3 years","5 years","10 years"], correct:1, exp:"3 años."},
{q:"For how long is a standard Road Passenger Transport Operator Licence (National or International) valid in Ireland?", options:["1 year","3 years","5 years","10 years"], correct:2, exp:"5 años."},
{q:"What four core criteria must an undertaking satisfy to obtain and maintain a Road Passenger Transport Operator Licence under Regulation (EC) No 1071/2009?", options:["Good repute, appropriate financial standing, professional competence, and a stable and effective establishment in Ireland","Minimum fleet of 10 coaches, annual turnover of €1M, tax exemption, and Irish ownership","ISO 9001 certification, 5 years trading history, local depot planning permission, and clean driving record","Commercial building ownership, zero debt, driver CPC exemption, and private insurance cover"], correct:0, exp:"Buena reputación, solvencia financiera, competencia profesional, establecimiento estable."},
{q:"What financial standing capital reserve must an operator demonstrate for a Road Passenger Transport Operator Licence?", options:["€5,000 for the first vehicle and €2,500 for each additional vehicle","€9,000 for the first vehicle and €5,000 for each additional vehicle","€12,000 for the first vehicle and €6,000 for each additional vehicle","Flat rate of €50,000 regardless of fleet size"], correct:1, exp:"€9,000 primer vehículo, €5,000 por cada adicional."},
{q:"What additional document is issued to an international passenger operator alongside their International Operator Licence to be kept at base?", options:["Community Licence","Journey Form Booklet","Route Authorisation Permit","Cabotage Certificate"], correct:0, exp:"Community Licence."},
{q:"What document must be carried on board EVERY vehicle operating internationally within the EU under an International Operator Licence?", options:["Original Community Licence","Certified True Copy of the Community Licence (and Certified Copy of Operator Licence with detachable Transport Disc)","Company balance sheet","Original birth certificates of all passengers"], correct:1, exp:"Copia auténtica certificada de la Community Licence."},
{q:"What defines a 'Regular International Passenger Service'?", options:["Ad-hoc charter trips carrying private sports clubs","Services providing carriage of passengers at specified intervals along a specified route with predetermined stopping points, open to all","School trips contract services","Point-to-point carriage within another Member State only"], correct:1, exp:"Intervalos fijos, ruta y paradas predeterminadas, abierto a todos."},
{q:"What authorization document is required to operate a Regular International Passenger Service across EU borders?", options:["EU Route Authorisation issued by the competent authority (NTA in Ireland) in agreement with transited Member States","Journey Form / Waybill","Simple local council permit","Customs declarations form"], correct:0, exp:"EU Route Authorisation."},
{q:"What is the maximum validity period for an EU Regular International Service Route Authorisation?", options:["1 year","3 years","5 years","10 years"], correct:2, exp:"5 años."},
{q:"How long do consulted Member State authorities have to notify their decision upon receiving an application for a Regular International Service Authorisation?", options:["1 month","2 months","4 months","6 months"], correct:1, exp:"2 meses."},
{q:"What happens if a consulted Member State authority fails to reply within the 2-month statutory limit for a Regular International Service application?", options:["The application is automatically rejected","The authority is deemed to have given its agreement","The application is referred to the European Court of Justice","The operator must re-submit the application with extra fees"], correct:1, exp:"Se considera que da su conformidad."},
{q:"What defines an 'Occasional International Passenger Service'?", options:["Services carrying groups of passengers assembled on the initiative of the customer or carrier (e.g. closed group tours), not meeting the definition of a regular service","Daily scheduled interurban routes","Shuttle services carrying workers daily","Urban commuter bus services"], correct:0, exp:"Grupos formados por iniciativa del cliente/transportista."},
{q:"What specific document MUST cover an Occasional International Passenger Service within the EU?", options:["Route Authorisation Certificate","Journey Form (Waybill) booklet issued by the NTA","Special Regular Contract","Cabotage Permit"], correct:1, exp:"Journey Form (Waybill)."},
{q:"Within how many days must a completed Journey Form for an occasional international trip be returned to the NTA in Ireland?", options:["7 days","14 days","30 days","60 days"], correct:2, exp:"30 días."},
{q:"What defines a 'Special Regular International Service'?", options:["Scheduled services open to the general public","Services providing for the carriage of specific categories of passengers (e.g., workers to work, students to school) under a contract, to the exclusion of other passengers","One-off tourist excursion tours","Taxi services at airport terminals"], correct:1, exp:"Categorías específicas de pasajeros bajo contrato."},
{q:"What document must be carried on board a vehicle operating a Special Regular International Service?", options:["A book of blank Journey Forms","A copy of the contract concluded between the organizer/client and the carrier (or equivalent document)","Individual tickets for every passenger","A letter from the Department of Education"], correct:1, exp:"Copia del contrato entre el organizador y el transportista."},
{q:"How is 'Bus Cabotage' defined in European passenger transport law?", options:["Transporting passengers from Dublin to Belfast","The point-to-point carriage of passengers within a host Member State by a non-resident operator, allowed only in the context of international passenger services","Domestic passenger transport within Ireland","Driving empty coaches across EU borders"], correct:1, exp:"Transporte punto a punto dentro de un Estado anfitrión."},
{q:"Under what conditions is passenger cabotage permitted within an EU host Member State?", options:["Unlimited domestic carriage without restrictions","Temporary carriage in the course of an authorised international regular service or occasional service, using a valid Community Licence","Restricted to vehicles under 3.5 tonnes only","Prohibited under all circumstances"], correct:1, exp:"Temporal, en el contexto de un servicio internacional autorizado."},
{q:"What requirement applies to foreign operators carrying out cabotage operations in France for more than 8 days?", options:["They must register employees and make a pre-declaration to the French General Inspectorate of Labour","They must re-register all vehicles on French registration plates","They must pay double motor tax to the French government","They must employ French national drivers"], correct:0, exp:"Pre-declaración a la Inspección de Trabajo francesa."},
{q:"What defines an 'Own Account' passenger transport operation?", options:["Commercial tour operators selling individual tickets","Non-commercial and non-profit passenger carriage carried out by a natural/legal person where transport is an ancillary activity, using owned/leased vehicles driven by staff","Sub-contracted school transport operations","Taxi services operating under private hire"], correct:1, exp:"No comercial y sin ánimo de lucro, actividad accesoria."},
{q:"Are 'Own Account' passenger transport operations required to hold a Road Passenger Transport Operator Licence?", options:["Yes, all passenger transport requires an operator licence","No, pure own-account non-commercial passenger operations are exempt from operator licensing requirements","Only if operating international routes","Only if the bus has more than 50 seats"], correct:1, exp:"No, están exentas."},
{q:"Under PSV Conduct Regulations in Ireland, what is a driver of a Large Public Service Vehicle legally required to do when picking up or setting down passengers?", options:["Stop the vehicle as close as possible to the kerb","Stop in the middle of the driving lane to block traffic","Sound the horn to alert passengers","Request passengers to jump onto the moving vehicle"], correct:0, exp:"Parar lo más cerca posible del bordillo."},
{q:"Under PSV Conduct Regulations, can a driver of an omnibus enter into conversation with passengers while the vehicle is moving or stopped in traffic?", options:["Yes, drivers are encouraged to chat with passengers","No, the driver shall not enter into conversation with any person while the vehicle is moving or stopped in traffic (except as necessary for safety/operational reasons)","Only on weekend journeys","Only if using a loudspeaker"], correct:1, exp:"No, salvo que sea necesario por seguridad/operativa."},
{q:"Under PSV Conduct Regulations, what power does a bus driver or Garda have regarding an unruly or offensive passenger?", options:["Power to issue on-the-spot cash fines","Power to exclude or request the passenger to leave the vehicle (and use reasonable force if necessary, or seek Garda assistance)","Power to impound the passenger's personal luggage permanently","Power to revoke the passenger's driving licence"], correct:1, exp:"Excluirlo o pedirle que se baje."},
{q:"Can a bus driver use physical force to eject a disruptive passenger from a vehicle?", options:["Yes, drivers have unlimited legal rights to use force","Drivers must refrain from physical violence; they should request the passenger to leave, use reasonable force only as permitted by law/Garda assistance, or call An Garda Síochána","Yes, provided other passengers assist in the ejection","Only on double-deck buses"], correct:1, exp:"Debe evitar la violencia; pedirle que se baje o llamar a la Garda."},
{q:"How must lost property found on a passenger bus be handled under Irish law?", options:["Sold immediately by the driver for cash","Dealt with according to company policy and statutory regulations under the Road Traffic Act 1961 (lodged at designated lost property office)","Kept by the finder after 24 hours","Destroyed at the end of the shift"], correct:1, exp:"Según la política de la empresa y el Road Traffic Act 1961."},
{q:"When an operator sub-contracts a passenger journey to another operator, who remains legally liable to the customer for full contract performance?", options:["The sub-contractor only","The original operator (main contractor) remains wholly liable to the customer","Neither operator, liability is canceled","The driver assigned on that day"], correct:1, exp:"El operador original."},
{q:"Does a main operator have a legal duty to disclose to a sub-contractor the exact price charged to the end customer?", options:["Yes, total financial disclosure is required","No, the main operator has no legal obligation to reveal the customer price to the sub-contractor","Only if the contract exceeds €10,000","Only if requested by the Gardaí"], correct:1, exp:"No tiene obligación legal."},
{q:"What is the definition of an 'Agent' in transport contracts?", options:["A person employed to drive passenger coaches","A person who possesses authority to act on behalf of another person (the principal) to establish contractual relationships with third parties","An inspector from the RSA","A vehicle maintenance garage"], correct:1, exp:"Persona con autoridad para actuar en nombre de otra."},
{q:"If an agent acts outside their delegated authority when making a contract with a third party, is the principal bound by the contract?", options:["Yes, the principal must honour all contracts made by agents","No, the principal is NOT bound by unauthorized contracts, and the agent may be sued for breach of warranty of authority","The contract transfers to the NTA","The third party receives compensation from the State"], correct:1, exp:"No, el principal no queda obligado."},
{q:"If an agent makes 'secret profits' without the principal's knowledge while acting on their behalf, what legal remedy does the principal have?", options:["None, secret profits are legal bonuses","The principal may sue the agent to recover the secret profits","The agent is awarded extra commission","The third party contract becomes void"], correct:1, exp:"Puede demandarlo para recuperarlos."},
{q:"What is the purpose of an operator's 'Conditions of Carriage'?", options:["To set out the legal terms and conditions governing the transport contract between operator and passenger, binding if brought to customer attention prior to booking","To exempt the operator from all statutory road safety laws","To override driver tachograph limits","To set vehicle motor tax rates"], correct:0, exp:"Fijar los términos legales del contrato de transporte."},
{q:"Can an operator exclude liability for personal injury or death caused to passengers in their Conditions of Carriage?", options:["Yes, by printing an exclusion clause on tickets","No, operators cannot legally exclude or restrict liability for death or personal injury resulting from negligence","Yes, if approved by local councils","Only on international routes"], correct:1, exp:"No, no puede excluir esa responsabilidad."},
{q:"What is a 'Closed Door Tour' in international passenger transport?", options:["A journey where the same vehicle carries the same group of passengers throughout the entire trip and returns them to the place of departure without picking up or setting down passengers en route","A tour operated with bus doors locked from the outside","A private charter service operating exclusively at night","A local urban bus route with no stops"], correct:0, exp:"Mismo vehículo, mismo grupo, sin recoger/dejar por el camino."}
]},
"29": { title: "Tema 29 - Competition Rules", questions: [
{q:"Which organization in Ireland has statutory responsibility for enforcing Irish and EU competition law across the transport sector under the Competition and Consumer Protection Act 2014?", options:["Road Safety Authority (RSA)","National Transport Authority (NTA)","Competition and Consumer Protection Commission (CCPC)","Chartered Institute of Logistics and Transport (CILT)"], correct:2, exp:"CCPC."},
{q:"What are the two principal sources of competition law that govern passenger transport operators in Ireland?", options:["Irish Competition Act 2002 (as amended) and Articles 101/102 of the Treaty on the Functioning of the European Union (TFEU)","Road Traffic Act 1961 and Transport Act 1933","EU Directive 2006/126/EC and Regulation 561/2006","Consumer Rights Act 2022 and Data Protection Act 2018"], correct:0, exp:"Competition Act 2002 y Arts. 101/102 TFUE."},
{q:"Does the Competition and Consumer Protection Commission (CCPC) act as a transport regulator that sets passenger fares or bus timetables?", options:["Yes, the CCPC sets all bus fare tariffs in Ireland","No, the CCPC enforces competition law; it does NOT set fares, timetables, fleet standards, or issue operator licences (functions managed by NTA/Dept of Transport)","Yes, but only for international coach services","Yes, for school transport contracts only"], correct:1, exp:"No, aplica la ley de competencia, no fija tarifas."},
{q:"Under Section 4 of the Competition Act 2002 and Article 101 TFEU, which of the following practices between independent transport operators is strictly PROHIBITED?", options:["Agreements to fix, harmonise, or coordinate fares (Price-fixing)","Agreements to divide or share customers, territories, routes, or tenders (Market-sharing)","Agreements to limit output or coordinate fleet deployment to reduce competition","All of the above"], correct:3, exp:"Todas están prohibidas."},
{q:"What is 'Bid-Rigging' in commercial passenger transport tendering (e.g., School Transport Scheme tenders)?", options:["Submitting a bid lower than the cost of fuel","Collusive agreements or understandings between operators not to bid against each other or to allocate specific routes to specific operators","Offering discounts for online ticket bookings","Buying secondhand buses to enter a tender"], correct:1, exp:"Acuerdos colusorios para no competir entre sí."},
{q:"How is bid-rigging treated under Irish competition law?", options:["As a minor administrative oversight","As a serious criminal cartel offence, potentially leading to High Court administrative fines, civil actions, or criminal prosecution with the Director of Public Prosecutions (DPP)","As an acceptable commercial practice for local operators","As a civil dispute resolved by the NTA"], correct:1, exp:"Delito de cartel grave."},
{q:"What enforcement powers does the CCPC possess under the Competition Act 2002 (as amended by the Competition (Amendment) Act 2022)?", options:["Investigating suspected anti-competitive behavior and conducting unannounced 'dawn raids' on business premises","Imposing administrative fines on companies (subject to High Court approval) and issuing prohibition orders","Referring serious criminal cartel cases to the Director of Public Prosecutions (DPP)","All of the above"], correct:3, exp:"Todo lo anterior."},
{q:"Under Irish and EU competition law, when can enforcement authorities categorise an operator as holding a 'Dominant Position' in a market?", options:["When the firm controls more than 50% of national transport","When the firm is able to act independently of normal competitive pressures without needing to consider the reaction of customers or rivals","When the firm is a semi-state enterprise like Bus Éireann","When the firm owns more than 100 coaches"], correct:1, exp:"Puede actuar con independencia de las presiones competitivas normales."},
{q:"Is holding a dominant position in a transport market illegal in itself under Irish law?", options:["Yes, dominance is strictly prohibited","No, being dominant is NOT unlawful in itself; what is prohibited is the ABUSE of a dominant position","Yes, if the market share exceeds 30%","Only on intercity express routes"], correct:1, exp:"Lo prohibido es el ABUSO, no la dominancia en sí."},
{q:"Which Section of the Competition Act 2002 and Article of the TFEU prohibit the ABUSE of a dominant position?", options:["Section 4 Competition Act 2002 and Article 101 TFEU","Section 5 Competition Act 2002 and Article 102 TFEU","Section 12 Companies Act 2014","Article 8 Regulation 561/2006"], correct:1, exp:"Sección 5 y Art. 102 TFUE."},
{q:"What is 'Predatory Pricing' in public passenger transport markets?", options:["Charging fares below cost with the specific intention of eliminating a competitor from a route","Offering free travel to senior citizens under government schemes","Charging high fares during peak holiday seasons","Offering group discounts for sea anglers"], correct:0, exp:"Precios por debajo del coste para eliminar a un competidor."},
{q:"Under Irish and EU law, what TWO conditions must be proven for pricing to be legally classified as abusive 'predatory pricing'?", options:["1. Fares are set below cost; and 2. The strategy is specifically intended to eliminate or drive a competitor out of the market","1. Fares are advertised on social media; and 2. Tickets are sold online","1. Fares are higher than train tickets; and 2. Drivers are paid overtime","1. Vehicles are leased; and 2. Routes exceed 50 km"], correct:0, exp:"Precio bajo coste + intención de eliminar a un competidor."},
{q:"Are all loss-making bus services automatically unlawful predatory pricing under competition law?", options:["Yes, any route running at a loss breaches competition law","No, operators (especially on socially important routes) may have legitimate commercial or public-service reasons for temporary losses, provided there is no intent to eliminate rivals","Yes, unless subsidized by the CCPC","Only if operated by private companies"], correct:1, exp:"No, mientras no haya intención de eliminar rivales."},
{q:"What is 'Excessive Pricing' by a dominant transport operator?", options:["Charging fares that are unfairly high relative to the cost of service delivery because passengers have no meaningful alternative","Charging €2 for an urban bus trip","Increasing fares in line with diesel price inflation","Charging higher fares for luxury leather seating"], correct:0, exp:"Tarifas injustamente altas frente al coste, sin alternativa real."},
{q:"What is 'Cross-Subsidisation' in transport network operations?", options:["Using profits from one profitable route or service to support another less profitable or socially necessary route","Borrowing capital from an international bank","Paying driver wages from vehicle sale proceeds","Claiming VAT refunds on diesel fuel"], correct:0, exp:"Usar beneficios de una ruta para sostener otra."},
{q:"Is cross-subsidisation generally permitted under Irish competition law?", options:["No, it is strictly illegal in all circumstances","Yes, it is generally permitted across transport networks, provided it is NOT used as an exclusionary tool solely to drive out a competitor","Only if approved by the Revenue Commissioners","Only for rail transport"], correct:1, exp:"Sí, salvo uso exclusionario."},
{q:"Can two independent bus operators run connecting services (e.g. Route A to B and Route B to C) and coordinate timetables legally under competition law?", options:["No, any coordination between competitors is illegal","Yes, coordinating timetables for connecting services enhances efficiency, improves passenger transfers, and benefits consumers without breaching competition law","Yes, but only if they merge into a single limited company","Only if authorized by An Garda Síochána"], correct:1, exp:"Sí, coordinar horarios de conexión beneficia al consumidor."},
{q:"What THREE conditions must a cooperative agreement between transport operators satisfy to qualify for an exemption under Section 4(5) of the Competition Act 2002?", options:["1. Improves production/distribution or promotes technical/economic progress; 2. Gives consumers a fair share of the resulting benefit; 3. Imposes no unnecessary restrictions and does not eliminate competition for a substantial part of services","1. Written in Irish; 2. Approved by CILT; 3. Valid for 10 years","1. Fleet size over 50 buses; 2. Operating under 50 km; 3. Zero ticket discounts","1. Certified by RSA; 2. Drivers hold CPC; 3. Vehicles tested annually"], correct:0, exp:"Mejora, beneficio justo al consumidor, sin eliminar competencia."},
{q:"Unlike the UK, does Ireland use 'block exemptions' for multi-operator bus ticketing schemes?", options:["Yes, Ireland uses identical UK block exemption regulations","No, Ireland does NOT use block exemptions for multi-operator ticketing; the National Transport Authority (NTA) manages integrated ticketing (like TFI Leap Card) under separate legislation","Yes, block exemptions are issued by the CCPC annually","Only for international cross-border routes to Northern Ireland"], correct:1, exp:"No, la NTA gestiona el billete integrado bajo otra legislación."},
{q:"What entity plans, regulates, and procures public bus services and Public Service Obligation (PSO) contracts in Ireland?", options:["Competition and Consumer Protection Commission (CCPC)","National Transport Authority (NTA) under the Dublin Transport Authority Act 2008 and Public Transport Regulation Act 2009","Department of Enterprise, Trade and Employment","Road Safety Authority (RSA)"], correct:1, exp:"NTA."},
{q:"Does NTA planning and procurement of PSO bus services require a specific 'competition test' approval from the CCPC?", options:["Yes, the CCPC must approve all NTA timetables","No, NTA carries out functions under statutory obligations for efficiency and public interest, though general competition law still applies to prevent collusive tendering or abuse","Yes, every 6 months","Only for private hire tours"], correct:1, exp:"No, actúa bajo obligaciones estatutarias, aunque la ley de competencia sigue aplicando."},
{q:"What happens if two local bus companies enter into an informal verbal agreement to divide tourist excursion markets in Munster ('territory sharing')?", options:["It is a valid commercial understanding","It is a serious breach of Section 4 of the Competition Act 2002 and Article 101 TFEU (market-sharing cartel), unlawful even if unwritten","It is permitted if passenger numbers are low","It is governed by local county council bylaws"], correct:1, exp:"Infracción grave, aunque sea verbal."},
{q:"Which of the following cooperative activities between tour operators is PERMITTED under competition law?", options:["Jointly marketing a wider range of tours that they could not offer individually","Sharing back-office costs or coordinating certain logistics","Establishing a separate jointly-owned company to run and market tours collectively (provided competition is not eliminated)","All of the above"], correct:3, exp:"Todo lo anterior está permitido."},
{q:"In Case Study 29P (Lax Bus Services Ltd), Lax is approached by a competitor to develop a mutual multi-operator ticketing scheme. Is such a scheme legal under competition law?", options:["No, all multi-operator ticketing is illegal","Yes, competition law permits multi-operator ticketing schemes provided strict rules are followed to ensure fair competition and consumer benefit","Only if Lax buys out the competitor","Only if authorized by the Minister for Transport"], correct:1, exp:"Sí, con reglas estrictas de competencia justa."},
{q:"According to the official CILT Case Study marking scheme for Lax Bus Services Ltd, Rule 1 for a legal multi-operator ticketing scheme is:", options:["Participation must be voluntary and non-exclusive (neither operator forced to join or prevented from leaving; open to others on reasonable terms)","All operators must charge identical single fares on all routes","Fares must be raised by 20% annually","Tickets can only be sold at bus stations"], correct:0, exp:"Participación voluntaria y no exclusiva."},
{q:"Why must a multi-operator ticketing scheme satisfy the 'voluntary and non-exclusive' requirement?", options:["To prevent restriction of competition or market foreclosure against third operators","To reduce VAT payments to Revenue","To allow drivers to work without tachographs","To extend vehicle motor tax validity"], correct:0, exp:"Evitar restringir la competencia o excluir a terceros."},
{q:"According to Case Study 29P, Rule 2 regarding fares in a multi-operator ticketing scheme states:", options:["Operators must fix all individual route fares together","No fixing of fares outside the joint ticket (operators may agree the price of the joint ticket, but MUST remain free to set their own individual fares independently)","Individual fares must be banned","The NTA must set driver hourly wages"], correct:1, exp:"Pueden acordar el precio del billete conjunto, pero deben fijar sus tarifas individuales por separado."},
{q:"According to Case Study 29P, Rule 3 regarding revenue sharing in a multi-operator ticketing scheme requires:", options:["A transparent and fair revenue sharing mechanism based on objective, verifiable usage data","Splitting all revenue 50/50 regardless of passenger usage","Giving all ticket proceeds to the largest operator","Paying cash directly to drivers"], correct:0, exp:"Mecanismo transparente basado en datos objetivos de uso."},
{q:"Why is a transparent, objective revenue-sharing mechanism required in a multi-operator ticketing scheme?", options:["It avoids hidden subsidies or unfair commercial advantage between operators","It eliminates the need for financial auditing","It qualifies the fleet for free diesel","It replaces the Transport Manager CPC requirement"], correct:0, exp:"Evita subsidios ocultos o ventajas injustas."},
{q:"According to Case Study 29P, Rule 4 regarding information exchange between participating operators prohibits:", options:["The exchange of commercially sensitive information (such as individual costs, profit margins, future pricing strategies, or competitive expansion plans)","Exchanging route map leaflets","Printing joint timetables","Displaying bus stop signs"], correct:0, exp:"Intercambio de información comercialmente sensible."},
{q:"Why is the exchange of commercially sensitive information strictly forbidden between competitors in a ticketing scheme?", options:["It prevents collusion and preserves independent market competition","It violates copyright law","It increases mobile phone bills","It causes bus delays"], correct:0, exp:"Previene la colusión y preserva la competencia independiente."},
{q:"According to Case Study 29P, Rule 5 states that the ticketing scheme MUST:", options:["Directly benefit passengers (improving customer convenience, ticket choice, or value through simpler journeys or network integration)","Increase operator profit margins by at least 30%","Force passengers to buy monthly passes only","Exclude student and child discounts"], correct:0, exp:"Beneficiar directamente al pasajero."},
{q:"According to Case Study 29P, Rule 6 regarding third-party operators requires:", options:["No exclusion of other operators (the scheme must not be designed to exclude, disadvantage, or prevent future participation of rival operators on reasonable terms)","Blocking new entrants from joining the local market","Forcing third operators to pay double entry fees","Restricting ticket sales to existing company customers"], correct:0, exp:"No excluir a otros operadores."},
{q:"What is the maximum score awarded for answering all six rules correctly in the CILT Case Study 29P question?", options:["20 marks","50 marks","84 marks (14 marks per rule & reason)","100 marks"], correct:2, exp:"84 puntos (14 por regla)."},
{q:"When an operator hires a vehicle to cover extra work, what licensing procedure MUST be completed before the vehicle is used on public roads?", options:["The hired vehicle must be formally added to the operator's Road Transport Operator Licence via RTOL (Dept of Transport)","The vehicle must be painted in company colors","The driver must take a new driving test","No licensing changes are needed for hired vehicles"], correct:0, exp:"Añadirlo formalmente a la licencia vía RTOL."},
{q:"If an operator sub-contracts transport work to another licensed operator, who retains ultimate legal responsibility for compliance with drivers' hours, tachographs, and vehicle roadworthiness?", options:["The sub-contractor only","The primary operator (main contractor) remains fully responsible to enforcement bodies (RSA/Dept of Transport)","Neither operator","The vehicle leasing company"], correct:1, exp:"El operador principal sigue siendo totalmente responsable."},
{q:"What risk does an operator face if their Transport Manager knowingly participates in anti-competitive cartel conduct or bid-rigging?", options:["Serious legal prosecution, administrative fines, and loss of 'Good Repute' leading to Operator Licence revocation","A minor verbal reprimand from the CILT","Free legal representation from the CCPC","Automatic 2-year licence extension"], correct:0, exp:"Procesamiento legal, multas y pérdida de Buena Reputación."},
{q:"If two local bus companies merge, and a rival operator believes the merger will substantially lessen competition to the detriment of passengers, to which body should the complaint be submitted?", options:["Competition and Consumer Protection Commission (CCPC)","Road Safety Authority (RSA)","Chartered Institute of Logistics and Transport (CILT)","Workplace Relations Commission (WRC)"], correct:0, exp:"CCPC."},
{q:"Under the Competition Act 2002, can informal 'understandings' or verbal 'gentlemen's agreements' between transport managers breach competition law?", options:["No, only signed written contracts can breach competition law","Yes, informal understandings and verbal agreements are fully unlawful if they prevent, restrict, or distort market competition","Only if recorded on video","Only if witnessed by a solicitor"], correct:1, exp:"Sí, los acuerdos verbales también son ilegales."},
{q:"What is the ultimate objective of competition rules in the Irish road passenger transport sector?", options:["To protect fair market competition, prevent cartel abuse and predatory behavior, encourage efficiency and innovation, and ensure passengers enjoy genuine choice, quality, and fair pricing","To force small operators out of business","To maximize government revenue from ticket taxes","To restrict passenger travel between counties"], correct:0, exp:"Proteger la competencia justa y garantizar elección/calidad/precios justos."}
]},
"30": { title: "Tema 30 - International Transport Documentation", questions: [
{q:"Which document serves as evidence of an operator's authorization to carry passengers for hire and reward across EU Member States and must have a certified true copy carried in every vehicle?", options:["National Road Passenger Transport Operator Licence","EU Community Licence","Certificate of Conformity","Interbus Authorisation"], correct:1, exp:"EU Community Licence."},
{q:"What document must be carried on board an authorised vehicle operating an international passenger service within the EU?", options:["The original EU Community Licence","A Certified True Copy of the EU Community Licence (and Certified Copy of Operator Licence with Transport Disc)","Company annual accounts","Transport Manager's personal passport only"], correct:1, exp:"Copia auténtica certificada de la Community Licence."},
{q:"What is the standard validity period for an EU Community Licence issued in Ireland by the Department of Transport?", options:["1 year","3 years","5 years","10 years"], correct:2, exp:"5 años."},
{q:"Which international agreement governs occasional road passenger transport services (closed door tours, outward laden/return unladen) between the EU and certain non-EU countries (such as the UK, Switzerland, Montenegro, Western Balkans)?", options:["ASOR Agreement","Interbus Agreement","CMR Convention","TIR Convention"], correct:1, exp:"Interbus Agreement."},
{q:"Under the Interbus Agreement, how is a 'Closed Door Tour' defined?", options:["A journey where the same group of passengers is carried on the same vehicle throughout the entire trip and returned to the place of departure within a maximum of 90 days","A journey with vehicle doors locked during transit","A private charter service operating exclusively at night","A local city tour service"], correct:0, exp:"Mismo grupo/vehículo, vuelta al punto de partida en máximo 90 días."},
{q:"What control document MUST be carried on board a coach operating an Occasional International Passenger Service within the EU?", options:["EU Journey Form (EU Waybill / Carnet de Feuilles de Route)","CMR Consignment Note","ATA Carnet","Bill of Lading"], correct:0, exp:"EU Journey Form (Waybill)."},
{q:"Who issues official Journey Form (Waybill) booklets for occasional international passenger services to operators in Ireland?", options:["Road Safety Authority (RSA)","National Transport Authority (NTA)","Department of Foreign Affairs (DFA)","An Garda Síochána"], correct:1, exp:"NTA."},
{q:"Within how many days must completed duplicate Journey Form books for occasional international trips be returned to the NTA in Ireland?", options:["7 days","14 days","30 days","60 days"], correct:2, exp:"30 días."},
{q:"How long must a transport operator retain top copies / records of completed EU Journey Forms (Waybills) at their operating base?", options:["At least 6 months","At least 12 months from the completion of the service","At least 2 years","5 years"], correct:1, exp:"Al menos 12 meses."},
{q:"What document must be carried on board a vehicle operating a Regular International Passenger Service across EU Member States?", options:["EU Route Authorisation document (printed on pink paper with timetable and fare structure)","Interbus Waybill","ATA Carnet","Green Card only"], correct:0, exp:"EU Route Authorisation (papel rosa)."},
{q:"What is the maximum validity period for an EU Regular International Passenger Service Route Authorisation?", options:["1 year","3 years","5 years","10 years"], correct:2, exp:"5 años."},
{q:"What document covers an 'Own Account' international passenger transport operation (e.g. non-commercial transport by a school or local authority using their own bus and driver)?", options:["EU Community Licence","International Own Account Certificate (issued by IRFO / Dept of Transport)","Interbus Waybill","Standard Taxi Permit"], correct:1, exp:"International Own Account Certificate."},
{q:"Under EU Directive 98/41/EC and SOLAS Convention requirements, what passenger document MUST be compiled for ferry crossings over 20 miles from an EU port?", options:["Passenger List / Passenger Manifest (containing family name, first name, sex, age/age group, and optional special needs)","Copy of passenger driving licences","Tax clearance certificate for each passenger","Passenger employment contracts"], correct:0, exp:"Lista/Manifiesto de pasajeros."},
{q:"What certificate is required for a coach to operate at the maximum legal speed of 100 km/h on French motorways?", options:["Tempo 100","Vitesse 100","Autoroute 100","Eurovignette 100"], correct:1, exp:"Vitesse 100."},
{q:"What certificate is required for an Irish passenger coach to travel at 100 km/h on German autobahns?", options:["Tempo 100 Certificate","Vitesse 100 Certificate","German Speed Permit","Autobahn Pass"], correct:0, exp:"Tempo 100."},
{q:"If a driver has been absent from work due to illness or annual leave for 2 months prior to an international journey, what document should be carried to explain incomplete tachograph records?", options:["EU Community Licence","Form / Letter of Attestation of Activities (EU Attestation Form)","Certificate of Roadworthiness","GHIC card"], correct:1, exp:"Formulario de Atestación de Actividades."},
{q:"What international vehicle registration identifier must be displayed on the rear of an Irish coach travelling outside Ireland?", options:["GB sticker","IRL nationality plate or EU format registration plate incorporating the IRL country code and EU flag","UK sticker","No badge required within Europe"], correct:1, exp:"Placa IRL o matrícula formato UE con código IRL."},
{q:"What is the minimum recommended passport validity period required for Irish drivers travelling to non-EU destination countries?", options:["No minimum validity required","At least 3 months validity beyond the intended date of departure (or 6 months for certain Middle Eastern/Asian/African states)","Exactly 10 years","1 month from departure"], correct:1, exp:"Al menos 3 meses (6 para algunos países)."},
{q:"Which document provides evidence of motor insurance cover for international road passenger operations abroad?", options:["International Motor Insurance Certificate (Green Card) or proof of valid EU motor insurance cover","Certificate of Incorporation","Driver CPC Qualification Card","Vehicle Registration Certificate (V5C / VRC)"], correct:0, exp:"Carta Verde o prueba de seguro UE."},
{q:"When an Irish driver operates in Germany under minimum wage legislation (Mindestlohngesetz - MiLoG), what proof must be available?", options:["Proof / declaration that the driver is paid at least the applicable statutory minimum wage for hours worked in Germany","Certificate of Irish Citizenship","Local German tax registration number","Bank guarantee of €50,000"], correct:0, exp:"Prueba de pago del salario mínimo alemán."},
{q:"What requirement applies to transport operators under French law regarding posted drivers carrying out passenger transport or cabotage in France?", options:["Pre-declaration of posted workers to the French Labour Inspectorate (SIPSAP portal) and certificate of posting carried on board","Registration with French Police within 2 hours","Driver must hold a French driving licence","Mandatory employment of a French co-driver"], correct:0, exp:"Pre-declaración vía portal SIPSAP."},
{q:"Following Brexit, how are passenger transport operations between Ireland (EU) and Great Britain (England, Scotland, Wales) governed?", options:["Under EU-UK Trade and Cooperation Agreement (TCA) and Interbus Agreement rules","Under Irish Domestic Regulations only","Transport between Ireland and GB is completely banned","Under UN Maritime rules only"], correct:0, exp:"TCA UE-UK y reglas del Interbus Agreement."},
{q:"Are separate non-EU route authorisations required for international regular bus services operating between Ireland and Northern Ireland post-Brexit?", options:["Yes, complex non-EU permits are required","No, services between Ireland and Northern Ireland generally continue under EU international transport frameworks without non-EU authorisation hurdles","No transport is permitted across the border","Requires approval from US Customs"], correct:1, exp:"No, siguen bajo el marco UE sin trámites no-UE."},
{q:"What is the status of the Common Travel Area (CTA) between Ireland and the UK for professional coach drivers who are Irish or British citizens?", options:["CTA allows free movement without visas, but valid passports remain strongly recommended for professional drivers to prove identity at ports and customs","CTA allows travel without any identity documents","CTA requires work visas for every trip","CTA applies only to air travel"], correct:0, exp:"Sin visado, pero se recomienda llevar pasaporte."},
{q:"What is the legal requirement for drivers regarding passenger documentation checks on international trips?", options:["Transport managers and drivers should ensure passengers hold valid passports and necessary visas before departure to prevent frontier delays and carrier liability fines","Drivers must physically hold all passenger passports in the driver's cab safe","Drivers have zero responsibility for passenger entry documents","Drivers must issue passports to passengers"], correct:0, exp:"Asegurarse de que los pasajeros tengan pasaporte/visado válido."},
{q:"Under Irish Immigration law (Illegal Immigrants Act), what penalties can be imposed on a carrier/operator if undocumented passengers or illegal immigrants are found concealed in a vehicle?", options:["Fines of up to €3,000 per undocumented passenger, or up to 10 years imprisonment and unlimited court fines for intentional smuggling offences","Verbal reprimand from port officials","Immediate cancellation of all driver CPC cards","Impoundment of fuel tanks only"], correct:0, exp:"Hasta €3,000 por pasajero, o hasta 10 años de prisión."},
{q:"What constitutes a valid legal defense for a transport operator if an illegal immigrant is discovered hidden on board their coach at a border crossing?", options:["Demonstrating that an effective security system was in place to prevent unauthorised access, the system was operated correctly, and the driver had no knowledge or reason to suspect concealment","Stating that the bus doors were left open intentionally","Proving that the vehicle passed a CVRT test","Showing that the driver was running behind schedule"], correct:0, exp:"Sistema de seguridad eficaz + sin conocimiento ni sospecha."},
{q:"What international convention administered by the International Maritime Organization (IMO) regulates safety of life at sea, passenger manifests, and public address systems on passenger ferries?", options:["CMR Convention","SOLAS Convention (Safety of Life at Sea)","ADR Agreement","TIR Convention"], correct:1, exp:"SOLAS."},
{q:"Under the Package Travel, Package Holidays and Package Tours Regulations 1992, what combination defines a statutory 'Package Tour'?", options:["A pre-arranged combination of at least two elements (Transport, Accommodation, or Other tourist services accounting for a significant proportion) sold at an inclusive price lasting over 24 hours","Any single bus ticket purchase","Day trip under 50 km with no meals","Hiring a taxi for 2 hours"], correct:0, exp:"Al menos 2 elementos, a precio conjunto, +24h."},
{q:"In Case Study 1 (EOS Coach Travel Ltd), the company plans a scheduled weekly coach service from Dublin to Paris (stopping in UK, Belgium, France). What primary licence and document are required?", options:["International Road Passenger Transport Operator Licence + EU Community Licence (with Certified True Copy on board and EU Route Authorisation)","National Operator Licence + Taxi Disc","Interbus Waybill only","Local Dublin Bus Permit"], correct:0, exp:"Licencia internacional + Community Licence + Route Authorisation."},
{q:"In Case Study 1, EOS Coach Travel Ltd plans a private tourist coach trip from Cork to France for 5 days. What document MUST be carried on board the vehicle for this occasional service?", options:["EU Journey Form (Waybill) completed prior to departure","Regular Service Route Authorisation","Special Regular Contract","Bill of Lading"], correct:0, exp:"EU Journey Form (Waybill)."},
{q:"In Case Study 1, EOS Coach Travel Ltd plans a contracted service transporting Irish students to a college event in Belgium under a written contract. What document is required on board?", options:["EU Waybill and a certified copy of the contract concluded between the college and the carrier (Special Regular Service)","Single urban bus ticket","International Driving Permit","Green Card only"], correct:0, exp:"EU Waybill y copia certificada del contrato."},
{q:"In Case Study 1, EOS Coach Travel Ltd plans short passenger journeys between two French cities while the coach is in France. What is this operation legally called, and what are the conditions?", options:["Bus Cabotage; allowed only on a temporary basis in the context of an international service, provided a Community Licence copy and Journey Form are carried","Internal transit; prohibited under all circumstances","Domestic express; requires French operator licence","Own Account transport"], correct:0, exp:"Bus Cabotage, temporal, dentro de un servicio internacional."},
{q:"In Case Study 2 (International Transport Documentation - Dublin to London coach service via Dublin-Liverpool ferry), what FIVE vehicle/service documents must be carried on board?", options:["1. Certified True Copy of Community Licence; 2. Service Authorisation / Permit; 3. Vehicle Registration Certificate (VRC); 4. Certificate of Insurance; 5. Certificate of Roadworthiness (CRW / CVRT)","1. Driver birth certificate; 2. Bank statements; 3. Fuel receipts; 4. Office lease; 5. Tax return","1. Tachograph calibration certificate only; 2. Driver CPC; 3. Passport; 4. EHIC; 5. Ticket stub","1. Local parking permit; 2. NTA disc; 3. Driver logbook; 4. Toll tag; 5. Repair bill"], correct:0, exp:"Community Licence, autorización, VRC, seguro y CRW."},
{q:"According to the CILT Case Study marking scheme for international transport documentation, what additional documents should be available for border/ferry compliance on a Dublin to London route?", options:["Passenger Manifest / Passenger List (SOLAS / EU Directive 98/41), Tachograph records, and LPSV Licence","Customs declaration for commercial goods","Drivers' personal tax clearance","Import duty exemption certificates"], correct:0, exp:"Manifiesto de pasajeros, tacógrafo y licencia LPSV."},
{q:"Which international customs channel at Irish points of entry is used for intra-EU passenger/goods movements with no banned or restricted goods?", options:["Red Channel","Green Channel","Blue Channel","Yellow Channel"], correct:2, exp:"Canal Azul."},
{q:"What international driving document may be required for an Irish driver travelling through non-EU / non-EEA countries (e.g. Ukraine, Albania, or Russia)?", options:["International Driving Permit (IDP) issued by AA / RAC / Green Flag","Irish Provisional Permit","Local Council Driving Badge","Driver CPC Card only"], correct:0, exp:"Permiso Internacional de Conducir (IDP)."},
{q:"What medical document is strongly recommended for Irish drivers travelling in EU Member States to access healthcare?", options:["European Health Insurance Card (EHIC / GHIC)","Private dental insurance policy","Life insurance certificate","First aid completion badge"], correct:0, exp:"Tarjeta Sanitaria Europea (EHIC/GHIC)."},
{q:"What is the role of the Transport Manager regarding international transport documentation?", options:["Establishing an international compliance checklist, verifying driver passports/visas, issuing EU/Interbus waybills, ensuring Community Licence copies are on board, and monitoring foreign labor/posting rules","Personally driving every international route","Paying passenger hotel bills from personal funds","Granting custom clearance exemptions to passengers"], correct:0, exp:"Checklist de cumplimiento internacional y verificación de documentos."},
{q:"What is the ultimate objective of international transport regulations and documentation compliance?", options:["Facilitating smooth cross-border passenger movements, ensuring vehicle and operational safety, combating illegal immigration, and maintaining regulatory compliance across borders","Maximizing customs duties collected from tourists","Eliminating international bus travel in Europe","Restricting coach transport to domestic routes only"], correct:0, exp:"Facilitar el movimiento fronterizo y combatir la inmigración ilegal."}
]},
"31": { title: "Tema 31 - Fares, Revenue Collection and Tenders", questions: [
{q:"Which organization in Ireland is responsible for administering and regulating Public Service Obligation (PSO) tendered bus contracts under Regulation (EC) No 1370/2007?", options:["Competition and Consumer Protection Commission (CCPC)","National Transport Authority (NTA)","Road Safety Authority (RSA)","Department of Social Protection (DSP)"], correct:1, exp:"NTA."},
{q:"In Ireland, which government department administers the Free Travel Scheme for eligible passengers?", options:["Department of Transport","Department of Social Protection (DSP)","National Transport Authority (NTA)","Revenue Commissioners"], correct:1, exp:"Department of Social Protection."},
{q:"What system is widely used on Irish urban and interurban bus networks for contactless, stored-value fare collection?", options:["TFI Leap Card","Oyster Card","Navigo Pass","Express Transit Pass"], correct:0, exp:"TFI Leap Card."},
{q:"What is the primary function of an Electronic Ticket Machine (ETM) fitted on a modern bus?", options:["Issuing valid tickets, recording passenger boarding data automatically, reducing driver fraud/error, and supporting NTA reporting compliance","Measuring tire tread depth","Controlling engine cooling systems","Automatically renewing vehicle motor tax"], correct:0, exp:"Emitir billetes, registrar embarques y reducir fraude/error."},
{q:"What risk is associated with traditional 'Cash on Bus' fare collection in One-Person-Operated (OPO) bus services?", options:["Increased vehicle speed","Potential driver fraud, cash handling security risks, and journey delays while change is issued","Reduced fuel efficiency","Tachograph calibration failure"], correct:1, exp:"Fraude, riesgo de seguridad y retrasos."},
{q:"How do modern Irish PSO bus operators mitigate cash handling risks on OPO vehicles?", options:["Drivers keep cash in their personal pockets","Using sealed cash safes integrated with ETMs where drivers do not manually count or reconcile cash","Banning all cash payments completely","Requiring passengers to pay with exact change only"], correct:1, exp:"Cajas fuertes selladas integradas con la ETM."},
{q:"What is the main commercial advantage of 'Pre-payment' ticketing systems (e.g. season tickets, period passes, multi-journey tickets) for transport operators?", options:["Improves cash flow, generates passenger loyalty, and reduces the risk of fraud","Eliminates the need for motor insurance","Reduces driver CPC training requirements","Allows buses to bypass speed limiters"], correct:0, exp:"Mejora flujo de caja, fidelidad y reduce fraude."},
{q:"What feature is often incorporated into pre-paid period tickets or smartcards to prevent fraudulent misuse or sharing?", options:["Driver signature line","Uniquely numbered tickets and matching numbered photocards / embedded passenger identity photo","Magnetic tape recording","Scratch-off security panels"], correct:1, exp:"Billetes numerados y tarjetas con foto numeradas a juego."},
{q:"Which of the following is NOT a primary function of a bus ticket issued to a passenger?", options:["Authorisation to travel","Receipt for monies paid","Source of market research and revenue protection data","Exemption from wearing seatbelts"], correct:3, exp:"Eximir de llevar cinturón — no es función del billete."},
{q:"What is a 'Graduated or Tapered Fare' scale?", options:["A fare scale where the further a passenger travels the more they pay, but the rate per kilometre DECREASES as distance increases (longer distance passengers pay less per km)","A flat rate charged regardless of distance","A fare scale that doubles during rainy weather","A free travel pass for students"], correct:0, exp:"El precio por km disminuye a medida que aumenta la distancia."},
{q:"On a tapered fare scale, if a 1 km journey costs 50 cents (50c/km) and a 4 km journey costs €1.30, what is the effective cost per km for the 4 km passenger?", options:["50 cents / km","40 cents / km","32.5 cents / km","25 cents / km"], correct:2, exp:"1.30÷4 = 32.5c/km."},
{q:"What is a 'Coarse Scale Taper' in bus fare structures?", options:["A fare structure with a large difference in price per kilometre as travel distance increases","A fare structure with zero price differences","A fare structure applied exclusively to school buses","A flat fare charged across an entire city"], correct:0, exp:"Gran diferencia de precio por km."},
{q:"What is a 'Flat Rate Fare'?", options:["A fare structure where a single fixed price is charged regardless of the distance travelled on the route","A fare that increases by 10c for every kilometre","A fare charged only on flat terrain","A discounted fare for night shifts"], correct:0, exp:"Precio único fijo, sin importar la distancia."},
{q:"What feature of smartcard ticketing (like TFI Leap Card) stops a passenger from being charged further once they reach a defined daily or weekly spend limit?", options:["Fare capping (daily/weekly capping)","Overdraft protection","Automatic refund","Distance reset"], correct:0, exp:"Fare capping."},
{q:"What is a 'Zonal Fare' structure?", options:["A structure where flat fares apply within defined geographic zones, centrally defined by the transport authority (NTA)","A fare based on vehicle seating capacity","A fare negotiated between driver and passenger","A ticket valid only in airport zones"], correct:0, exp:"Tarifas planas dentro de zonas geográficas definidas."},
{q:"What operational challenge arises from 'Peak Requirements' in commuter bus services?", options:["High passenger demand during morning and evening rush hours requiring additional fleet and crew, leading to off-peak fleet underutilization","Engine overheating during summer","High fuel prices at night","Reduced tachograph driving limits"], correct:0, exp:"Alta demanda en hora punta con infrautilización fuera de ella."},
{q:"How can operators mitigate the financial impact of peak fleet requirements?", options:["Offering off-peak discounted fares to spread demand, or sub-contracting during peak hours","Charging double fares during off-peak hours","Cancelling all off-peak services","Restricting buses to carrying standing passengers only"], correct:0, exp:"Tarifas reducidas fuera de hora punta o subcontratar en horas punta."},
{q:"What are 'Concessionary Fares'?", options:["Discounted or free fares offered to specific passenger categories (such as DSP Free Travel pass holders, young adults, students, children)","Fares charged exclusively to foreign tourists","Fares paid by drivers to operate buses","Fares charged during weekend bank holidays"], correct:0, exp:"Tarifas descontadas/gratuitas para categorías específicas."},
{q:"Which concessionary fare categories are compulsory under Irish legislation/NTA rules?", options:["DSP Free Travel Pass holders, Companion Pass holders, TFI Young Adult (19-25 & 26-30), and TFI Child/Student categories","Corporate executive discounts","Airline crew passes","Hotel guest passes"], correct:0, exp:"Free Travel, Companion Pass, Young Adult, Child/Student."},
{q:"How are operators reimbursed for carrying DSP Free Travel scheme passengers on PSO routes in Ireland?", options:["Through DSP/NTA formulas based on recorded passenger boardings and verified ETM data","Cash payments handed directly to drivers by inspectors","Fuel tax rebates from Revenue","Free vehicle maintenance provided by the council"], correct:0, exp:"Fórmulas DSP/NTA basadas en embarques registrados."},
{q:"What EU Regulation governs Public Service Obligations (PSO) and the tendering of public passenger transport services by rail and road?", options:["Regulation (EC) No 561/2006","Regulation (EC) No 1370/2007","Regulation (EU) No 165/2014","Directive 2006/126/EC"], correct:1, exp:"Reglamento (CE) 1370/2007."},
{q:"What is the standard maximum contract duration for a local bus service PSO contract awarded by the NTA?", options:["3 years","5 years (up to 10 years depending on asset investment)","15 years","25 years"], correct:1, exp:"5 años (hasta 10 según inversión)."},
{q:"Under Irish tendering rules, what is the absolute legal maximum length permitted for a local bus service contract?", options:["5 years","8 years","12 years","20 years"], correct:1, exp:"8 años."},
{q:"What is a 'Gross Cost Contract' in public transport tendering?", options:["A contract where the operator is paid a fixed contract fee by the authority, while the authority retains all fare revenue and sets fare levels","A contract where the operator keeps all revenue and receives no subsidy","A contract where the operator sets ticket prices freely","A contract based on fuel consumption"], correct:0, exp:"El operador cobra tarifa fija, la autoridad se queda con los ingresos."},
{q:"What is a 'Net Cost Contract' in public transport tendering?", options:["A contract where the operator retains all fare revenue and receives an agreed balancing subsidy/subvention from the authority","A contract where the authority keeps all fare revenue","A contract where no subsidy is paid under any circumstances","A contract with zero financial risk for the operator"], correct:0, exp:"El operador se queda con los ingresos y recibe una subvención de balance."},
{q:"Under a Gross Cost Contract, who bears the commercial revenue/traffic risk?", options:["The transport operator","The tendering authority (NTA)","The bus drivers","The vehicle manufacturer"], correct:1, exp:"La autoridad licitadora."},
{q:"Under a Net Cost Contract, who bears the revenue risk (including competition risk)?", options:["The transport operator","The tendering authority (NTA)","The Department of Social Protection","The passengers"], correct:0, exp:"El operador de transporte."},
{q:"Under Irish procurement law, must the NTA automatically accept the lowest financial bid when awarding a public service contract?", options:["Yes, the lowest price bid must always be selected","No, the authority considers tenders on the basis of 'Best Value for Money', taking into account service quality, operational standards, and vehicle specifications","Yes, unless the bidder is a foreign company","No, tenders are awarded by random lottery"], correct:1, exp:"Mejor relación calidad-precio, no solo el precio más bajo."},
{q:"What is a key duty of tendering authorities (NTA/local authorities) to ensure fair competition during public bus service tenders?", options:["Ensuring tender requirements do not restrict competition or favor large operators unnaturally (e.g., splitting route packages so smaller operators can bid)","Banning small operators from entering tenders","Forcing all bidders to use the same depot","Fixing driver wages across all companies"], correct:0, exp:"No restringir la competencia ni favorecer artificialmente a grandes operadores."},
{q:"Under Regulation (EC) 1370/2007 (Article 5), what is the 'De Minimis' direct-award contract limit for standard public passenger transport contracts?", options:["Average annual value under €1,000,000 OR less than 300,000 kilometres of public passenger transport services per year","Average annual value under €5,000,000","Less than 50,000 kilometres per year","Flat rate of €100,000 per contract"], correct:0, exp:"Bajo €1M O menos de 300,000 km/año."},
{q:"For small and medium-sized operators (SMEs operating not more than 23 vehicles), to what threshold can the De Minimis direct-award limits be increased?", options:["Average annual value less than €2,000,000 OR less than 600,000 kilometres per year","Average annual value less than €10,000,000","Up to 1,500,000 kilometres per year","No increase is permitted for SMEs"], correct:0, exp:"Bajo €2M O menos de 600,000 km/año."},
{q:"Does operating under a De Minimis direct-award contract exempt an operator from vehicle licensing and safety rules?", options:["Yes, de minimis contracts are completely unregulated","No, the operator MUST still comply fully with operator licensing, vehicle roadworthiness, driver rules, fares/ticketing, and NTA monitoring","Only if operating minibus services","Only during the first year of operation"], correct:1, exp:"No, debe cumplir íntegramente todas las reglas."},
{q:"Under what circumstances can the NTA directly award a bus service contract without a full competitive tendering process?", options:["Emergency situations (e.g. sudden operator insolvency or licence revocation), unforeseen demand, where no suitable tender is received, or under De Minimis rules","Whenever an operator requests extra funding","During national election years only","For all international coach tours"], correct:0, exp:"Emergencias, demanda imprevista, sin ofertas adecuadas, o De Minimis."},
{q:"What information must tendering authorities publish following the award of a public service contract?", options:["Contract scope, winning supplier name, award justification, and amounts of the highest and lowest tenders received","Personal bank account details of the operator's directors","Names and home addresses of all bus drivers","Exact fuel purchase prices paid by the operator"], correct:0, exp:"Alcance, ganador, justificación e importes de las ofertas."},
{q:"What document records all ticket sales, boarding stages, and cash collected by a driver at the start and end of a shift?", options:["Running Board","Waybill (Revenue / Duty Waybill)","Driver Logbook","Tachograph Chart"], correct:1, exp:"Waybill de ingresos/turno."},
{q:"In Stage Test questions, which system is considered the most secure against fraudulent misuse of pre-paid period tickets?", options:["Uniquely numbered tickets and matching numbered photocards","Unnumbered tickets with unnumbered cards","Verbal passenger declarations","Plain paper receipts"], correct:0, exp:"Billetes numerados con tarjetas foto numeradas a juego."},
{q:"Why is 'Cross-Subsidisation' used within public transport networks?", options:["Highly profitable urban routes generate surplus revenue to support commercially unviable but socially necessary feeder/rural routes","To avoid paying corporate tax","To reduce vehicle maintenance costs","To eliminate driver overtime pay"], correct:0, exp:"Rutas rentables sostienen rutas rurales necesarias."},
{q:"What type of contract fee arrangement is used when an operator is paid a fixed sum per kilometre or per day to operate a service regardless of passenger numbers?", options:["Gross Cost Contract","Net Cost Contract","Spot Hire Agreement","Open Book Management Contract"], correct:0, exp:"Gross Cost Contract."},
{q:"What state support in Ireland provides financial funding to operators upgrading fleets to low-emission or zero-emission electric buses?", options:["SEAI (Sustainable Energy Authority of Ireland) supports / NTA procurement frameworks","Revenue Commissioners VAT rebate scheme only","Local County Council grants exclusively","Road Safety Authority grants"], correct:0, exp:"Apoyos de SEAI / marcos de contratación de la NTA."},
{q:"What is the ultimate objective of fare regulation, revenue collection auditing, and competitive tendering in Irish public transport?", options:["Ensuring financial transparency, preventing fraud, delivering best value for public money, and providing high-quality, sustainable passenger services","Maximizing ticket prices for private operators","Eliminating small bus companies from the market","Reducing the total number of bus routes in Ireland"], correct:0, exp:"Transparencia financiera, prevenir fraude y dar buen valor al dinero público."}
]},
"32": { title: "Tema 32 - Route Planning, Timetabling & Frontier Crossings", questions: [
{q:"What is the first essential tool required by a transport manager when planning a new bus or coach route?", options:["A tachograph calibration sheet","A clear map showing starting points, destinations, ferry terminals, trunk roads, and population centres","A list of local hotels","A fuel price comparison app"], correct:1, exp:"Un mapa claro con puntos de origen/destino, terminales de ferry y vías principales."},
{q:"Why might taking the shortest geographic route sometimes take the longest travel time for a passenger coach?", options:["Toll fees are higher on shorter routes","Short routes may pass through congested urban areas, steep mountain gradients, or roads with strict weight/height restrictions","Satellite navigation systems do not work on short routes","Drivers are required to take extra breaks on short routes"], correct:1, exp:"Puede pasar por zonas congestionadas o con restricciones."},
{q:"Which of the following physical road restrictions MUST be checked before dispatching a vehicle on an international or domestic route?", options:["Height restrictions on tunnels, hotel canopies, and terminal buildings","Weight restrictions on bridges and access roads","Vehicle manoeuvrability restrictions in historic inner cities or accommodation complexes","All of the above"], correct:3, exp:"Todas las anteriores."},
{q:"What vehicle technical specifications must be matched to steep mountain gradients on alpine or hilly routes?", options:["Seat fabric quality","Engine power, gearbox ratios, and secondary braking systems (retarders / engine brakes)","Wi-Fi router speed","Paint color"], correct:1, exp:"Potencia del motor, relaciones de caja de cambios y frenado secundario."},
{q:"What equipment is legally required when travelling through mountainous areas or designated winter zones under adverse weather conditions ('équipements spéciaux')?", options:["Air conditioning units","Approved snow chains or winter tyres","Spare seating cushions","Extra ticket rolls"], correct:1, exp:"Cadenas de nieve homologadas o neumáticos de invierno."},
{q:"Which major alpine tunnel links France and Italy directly through the Alps?", options:["Channel Tunnel","Fréjus Tunnel and Mont Blanc Tunnel","Øresund Link","St Gotthard Tunnel"], correct:1, exp:"Túnel de Fréjus y Túnel del Mont Blanc."},
{q:"What is the length of the shuttle train journey through the Channel Tunnel (Le Shuttle) between Folkestone (UK) and Calais (France)?", options:["30 minutes","45 minutes","80 minutes (from leaving Folkestone to arriving in Calais)","120 minutes"], correct:2, exp:"80 minutos."},
{q:"What are the maximum vehicle dimensions accepted on Le Shuttle passenger trains in the Channel Tunnel?", options:["Up to 12 metres long, 2.5 metres wide, and 3.8 metres high","Up to 18 metres long, 2.6 metres wide, and 4.2 metres high","Unlimited length, width, and height","Up to 15 metres long, 2.55 metres wide, and 4.0 metres high"], correct:1, exp:"18m largo, 2.6m ancho, 4.2m alto."},
{q:"Which major European link consists of a tunnel, a bridge, and a man-made island connecting Copenhagen (Denmark) and Malmö (Sweden)?", options:["Øresund Link (16 km total link with a 3.7 km tunnel element)","Mont Blanc Tunnel","Channel Tunnel","Somport Tunnel"], correct:0, exp:"Øresund Link."},
{q:"What international road numbering system was developed under the United Nations Economic Commission for Europe (UNECE) using the 'E' prefix?", options:["AGR route numbering system (European Agreement on Main International Traffic Arteries)","TEN-T network","Schengen System","INTERBUS Network"], correct:0, exp:"Sistema AGR."},
{q:"Under the AGR European route numbering system, how are main North-South routes identified?", options:["Route numbers ending with a 0","Route numbers ending with a 5","Route numbers ending with an odd digit","Route numbers prefixed with the letter 'N'"], correct:0, exp:"Números terminados en 0."},
{q:"Under the AGR European route numbering system, how are principal East-West routes identified?", options:["Route numbers ending with a 0","Route numbers ending with a 5","Route numbers ending with an even digit","Route numbers prefixed with 'M'"], correct:1, exp:"Números terminados en 5."},
{q:"What is the EU initiative developed to build upon UNECE work to ensure speedy movement of goods and passengers across Europe?", options:["Trans-European Transport Networks (TEN-T)","SOLAS Convention","Schengen Agreement","AETR Agreement"], correct:0, exp:"TEN-T."},
{q:"How can transport operators utilize ferry journeys to optimize driver productivity and compliance with EU Regulation 561/2006?", options:["Drivers can take their mandatory daily or weekly rest periods aboard the ferry (provided suitable cabins/bunks are available)","Drivers must keep driving while on the ferry deck","Drivers do not record ferry time on tachographs","Ferry travel does not count toward any rest"], correct:0, exp:"Pueden tomar su descanso diario/semanal a bordo, con camarotes adecuados."},
{q:"What is the definition of 'Headway' in bus timetabling terminology?", options:["The total time taken for a round trip","The time interval between consecutive buses operating on the same route (e.g. a bus every 15 minutes)","The maximum speed achieved by a coach","The layover time at the terminus"], correct:1, exp:"Intervalo entre buses consecutivos."},
{q:"What is the definition of 'Frequency' in bus timetabling?", options:["The number of vehicles in one direction passing a point within a given time period (e.g. 4 buses per hour)","The distance between bus stops","The time spent cleaning the vehicle","The total driver shift duration"], correct:0, exp:"Nº de vehículos por hora."},
{q:"What is the mathematical relationship between a 20-minute Headway and Frequency?", options:["A 20-minute headway is equivalent to a frequency of 3 buses per hour","A 20-minute headway is equivalent to 5 buses per hour","A 20-minute headway equals 2 buses per hour","Headway and frequency are completely unrelated"], correct:0, exp:"60÷20 = 3 buses/hora."},
{q:"What is 'Layover Time' (or 'Stand Time') at a bus terminus?", options:["Time allowed at terminals for crews to change route blinds, complete waybills, inspect for lost property/damage, and take mandatory breaks","Time spent driving in heavy traffic","Time spent refueling at depot pumps","Time spent in workshop maintenance"], correct:0, exp:"Tiempo para cambiar destino, completar waybill y tomar descansos."},
{q:"What is 'Recovery Time' in bus scheduling?", options:["Time built into a timetable schedule to absorb unpredictable traffic delays and ensure the subsequent journey starts on time","Time allowed to repair a broken engine","Time spent resting in a hotel overnight","Time taken to recover unpaid ticket fares"], correct:0, exp:"Tiempo para absorber retrasos imprevistos."},
{q:"What is 'Running Time'?", options:["The total time allocated for a bus to make a single journey between two termini","The time spent idling in a garage","The total hours worked by a driver in a week","The time taken to fill the diesel tank"], correct:0, exp:"Tiempo total para un trayecto entre dos terminales."},
{q:"What is the standard formula used to calculate the Number of Vehicles required to operate a scheduled bus service?", options:["[(Running Time + Stand Time at one terminal) x 2] / Headway (in minutes)","Running Time x Frequency","Distance / Speed","Total Passengers / Vehicle Seating Capacity"], correct:0, exp:"[(Running Time + Stand Time) × 2] ÷ Headway."},
{q:"Using the standard formula, if a single journey Running Time is 45 minutes, Stand Time is 15 minutes, and Headway is 15 minutes, how many buses are required?", options:["4 buses","6 buses","8 buses [(45 + 15) x 2 / 15 = 120 / 15 = 8]","10 buses"], correct:2, exp:"(45+15)×2÷15 = 120÷15 = 8 buses."},
{q:"What formula is used to calculate the time taken between bus stops?", options:["(Distance x 60) / Average Speed","(Distance / 60) x Speed","Headway / Frequency","Running Time + Layover Time"], correct:0, exp:"(Distancia × 60) ÷ Velocidad media."},
{q:"What formula is used to calculate the number of driver duties required to operate a bus service?", options:["(Number of buses x Working time of each bus) / Length of shift","Distance / Speed","Total revenue / Fare tariff","Total fleet size x 2"], correct:0, exp:"(Nº de buses × horas de operación) ÷ duración del turno."},
{q:"What historical agreement created a 29-country borderless area across Europe where internal border checks were abolished?", options:["Schengen Agreement","Interbus Agreement","SOLAS Convention","CMR Convention"], correct:0, exp:"Acuerdo Schengen."},
{q:"Did Ireland sign the Schengen Agreement to abolish border checks?", options:["Yes, Ireland was one of the founding members","No, Ireland did NOT sign the Schengen Agreement, maintaining border control checks primarily due to security grounds and the Common Travel Area with the UK","Yes, Ireland joined in 2020","Ireland is an associate member with zero border controls"], correct:1, exp:"No, Irlanda mantiene controles fronterizos por seguridad y la CTA con UK."},
{q:"What minimum remaining validity is required on a passport for Irish drivers travelling to non-EU destination countries?", options:["No minimum validity required","At least 3 months validity beyond the intended date of departure (or 6 months for certain Middle Eastern, Asian, or African states)","Exactly 5 years","12 months minimum"], correct:1, exp:"Al menos 3 meses (6 para algunos países)."},
{q:"Which customs channel at Irish points of entry must be selected when travelling from a country outside the EU with no banned/restricted goods within allowance?", options:["Red Channel","Green Channel","Blue Channel","Yellow Channel"], correct:1, exp:"Canal Verde."},
{q:"Which customs channel at points of entry is selected when travelling within the EU with no banned or restricted goods?", options:["Red Channel","Green Channel","Blue Channel","Yellow Channel"], correct:2, exp:"Canal Azul."},
{q:"Under Irish immigration law, what maximum penalties can be imposed on both driver and operator if illegal immigrants are discovered hidden in a coach?", options:["Fines of up to €3,000 per illegal immigrant or up to 10 years imprisonment and unlimited court fines","A verbal warning from port officials","Immediate revocation of vehicle registration","€100 fine per passenger"], correct:0, exp:"Hasta €3,000 por persona, o hasta 10 años de prisión."},
{q:"What are the THREE legal defenses available to an operator or driver facing conviction for carrying concealed illegal immigrants?", options:["1. Driver was unaware and had no reason to suspect concealment; 2. An effective security system was in place; 3. The security system was operated correctly","1. Vehicle passed CVRT; 2. Driver was on time; 3. Fuel tank was full","1. Passengers paid cash; 2. Vehicle was leased; 3. Route was under 50 km","1. Weather was poor; 2. Traffic was heavy; 3. Bus was double-decked"], correct:0, exp:"Sin conocimiento/sospecha, sistema de seguridad eficaz y funcionando correctamente."},
{q:"What technology facility deployed at ferry ports uses passive millimetric waves to detect stowaways in moving vehicles up to 10 mph (16 km/h)?", options:["Passive Millimetric Wave Facility (PMMW)","DSRC Transponder","Tachograph Sensor","GPS Tracker"], correct:0, exp:"PMMW."},
{q:"What international convention administered by the International Maritime Organization (IMO) governs passenger lists, life-saving appliances, and public address systems on ferries?", options:["SOLAS Convention (Safety of Life at Sea)","Interbus Agreement","AGR Agreement","Package Travel Regulations"], correct:0, exp:"Convenio SOLAS."},
{q:"Under the Package Holidays and Travel Trade Act 1995 (Package Travel Regulations), what defines a statutory 'Package Tour'?", options:["A pre-arranged combination of at least two elements (Transport, Accommodation, or Other tourist services accounting for a significant proportion) sold at an inclusive price lasting over 24 hours","Any standard bus ticket purchase","Day trip under 24 hours with no accommodation","Private taxi hire for 3 hours"], correct:0, exp:"Al menos 2 elementos, precio conjunto, +24h."},
{q:"In Case Study 32P (Manchester Excursions), Excursion A leaves Dublin at 11:00 for a rock concert at 20:00, departs Manchester at 00:00, and returns to Dublin at 07:00. Is Excursion A a 'Package Tour'?", options:["Yes, because it includes concert tickets","No, Excursion A is NOT a Package Tour because it lasts under 24 hours and does NOT include accommodation","Yes, all ferry trips are packages","Only if passengers buy food on board"], correct:1, exp:"No, dura menos de 24h y no incluye alojamiento."},
{q:"In Case Study 32P, Excursion B leaves Dublin at 07:00 with theatre tickets, an overnight stay in a hotel, and returns to Dublin at 15:00 the next day. Is Excursion B a 'Package Tour'?", options:["Yes, Excursion B IS a Package Tour because it lasts over 24 hours and combines Transport, Accommodation (hotel), and Tourist Services (theatre tickets)","No, because it is under 48 hours","No, theatre tickets cancel package rules","Only if operated by a foreign company"], correct:0, exp:"Sí, dura más de 24h y combina transporte, alojamiento y servicio turístico."},
{q:"According to Case Study 32P, what TWO major consumer protection requirements MUST an operator provide under Package Travel Regulations?", options:["1. Security for clients' money (e.g. bonding, insurance, or trust account); 2. A detailed brochure/contract outlining destinations, transport, hotels, prices, and compensation rules","1. Free passenger meals; 2. Guaranteed sunny weather","1. Unlimited luggage allowances; 2. Free taxi transfers","1. Cash refunds for delayed ferries; 2. Double seating"], correct:0, exp:"Garantía del dinero del cliente y folleto/contrato detallado."},
{q:"What rule applies to price increases for an agreed package tour under Package Travel Regulations?", options:["Price increases are strictly prohibited within 30 days of departure, and any permitted increase must be provided for in the contract with clear calculation details","Prices can be doubled at any time without notice","Prices must be reduced if fuel gets cheaper","Prices are set by the NTA"], correct:0, exp:"Prohibidas en los 30 días previos, y deben estar previstas en el contrato."},
{q:"What action must an operator take if a driver encounters unexpected tunnel height restrictions or road closures on a route?", options:["Force the vehicle through regardless of height","Utilize pre-planned alternative routes, contact traffic management, and advise passengers of updated ETAs","Cancel the journey mid-route and abandon the vehicle","Exceed vehicle speed limiters to make up time"], correct:1, exp:"Usar rutas alternativas preplanificadas y avisar del nuevo ETA."},
{q:"What is the ultimate objective of effective route planning, timetabling, and frontier crossing management?", options:["Ensuring passenger safety, operational efficiency, regulatory compliance, seamless border transit, and protecting client rights under package travel laws","Maximizing toll payments","Eliminating driver break periods","Restricting coach operations to single cities"], correct:0, exp:"Seguridad, eficiencia, cumplimiento normativo y protección del cliente."}
]},
// ---- Simulacros de examen (40 preguntas, temas mezclados) ----
"101": { title: "Simulacro 1 - Marketing, Industrial Relations \u0026 Business Law", questions: [{"q":"What happens to sales and profitability during the \u0027Maturity\u0027 stage of a product life cycle?","options":["Sales increase more slowly as initial demand is met, and profits begin to decline","Development costs are incurred for the first time","Profits rise exponentially with zero competition","Sales reach zero immediately"],"correct":0,"exp":"- Opción Correcta (A): En la fase de madurez, las ventas se ralentizan porque ya se ha cubierto la demanda inicial del mercado, y los beneficios empiezan a bajar debido al aumento de la competencia.\n- Opciones Incorrectas: (B) Ocurre en la fase de \u0027Development\u0027 (desarrollo). (C) Ocurre en la fase de \u0027Growth\u0027 (crecimiento). (D) Ocurre en la fase de \u0027Decline\u0027 (declive)."},{"q":"What does \u0027Market share\u0027 measure?","options":["The physical weight capacity of a vehicle fleet","The ratio of fixed assets to current liabilities","The percentage of the total national or regional market that a business currently holds","The proportion of share capital owned by directors"],"correct":2,"exp":"- Opción Correcta (C): La cuota de mercado (Market share) es el porcentaje de ventas o clientes que tiene una empresa en relación con el total del mercado en su sector y región.\n- Opciones Incorrectas: (A) Mide la capacidad operativa, no el mercado. (B) Es un ratio financiero de liquidez/solvencia. (D) Se refiere a la estructura de propiedad (acciones), no al mercado comercial."},{"q":"Why is face-to-face selling primarily reserved for large contracts?","options":["Because travelling salesmen are legally required for retail shops","Because phone selling is prohibited by the WRC","Because direct mail has a 100% conversion rate","Because it is an expensive operation and only viable for high-value negotiations"],"correct":3,"exp":"- Opción Correcta (D): La venta presencial implica gastos de viaje, dietas y tiempo del comercial, por lo que es una estrategia muy cara que solo compensa económicamente cuando se negocian contratos de alto valor.\n- Opciones Incorrectas: (A) No existe tal requisito legal. (B) La venta telefónica es legal y común. (C) El correo directo tiene, de hecho, una tasa de conversión muy baja."},{"q":"How is market segmentation defined?","options":["Dividing an overall potential market into smaller, identifiable sub-markets with similar service requirements","Splitting company shares among shareholders","Calculating the total national turnover of a company","Merging competing transport firms into a single conglomerate"],"correct":0,"exp":"- Opción Correcta (A): La segmentación consiste en dividir el mercado global en grupos más pequeños (nichos) que comparten necesidades similares (ej. transporte escolar, turismo de lujo).\n- Opciones Incorrectas: (B) Es reparto de dividendos o acciones. (C) Es calcular la facturación. (D) Es una fusión o adquisición de empresas."},{"q":"What is the primary purpose of conducting marketing research?","options":["To eliminate all company taxes","To ensure marketing decisions are based on as much fact and as little guesswork as possible","To recruit qualified truck drivers","To establish trade union agreements"],"correct":1,"exp":"- Opción Correcta (B): El objetivo de la investigación de mercado es recopilar datos reales para tomar decisiones comerciales informadas, reduciendo la incertidumbre y las suposiciones.\n- Opciones Incorrectas: (A) Los impuestos se gestionan con contabilidad/asesoría. (C) Es tarea de Recursos Humanos. (D) Es tarea de Relaciones Laborales."},{"q":"What is secondary data in marketing research?","options":["Information collected via brand-new postal surveys","Information that already exists internally or externally that needs to be extracted","Confidential data stored exclusively by the Revenue Commissioners","Unverified rumors about competitors"],"correct":1,"exp":"- Opción Correcta (B): Los datos secundarios son aquellos que ya han sido recopilados previamente (ej. informes de ventas pasadas, censos gubernamentales) y solo hay que extraerlos.\n- Opciones Incorrectas: (A) Sería investigación primaria (Primary data). (C) No es accesible para marketing. (D) Los rumores no son datos de investigación válidos."},{"q":"What does General Transit Feed Specification (GTFS) data provide for public transport operators?","options":["Financial balance sheet audits for the Revenue Commissioners","Driver tachograph calibration logs","Accurate schedule and route data feeds so third-party mapping apps show correct travel options","Direct debit mandates for fuel purchases"],"correct":2,"exp":"- Opción Correcta (C): El formato GTFS permite a las empresas de transporte compartir sus horarios y rutas en tiempo real con aplicaciones de terceros (como Google Maps).\n- Opciones Incorrectas: (A) Es un tema financiero. (B) Es normativa de tiempos de conducción. (D) Es un tema de compras y contabilidad."},{"q":"What does \u0027Physical evidence\u0027 refer to when marketing a service like road transport?","options":["The physical delivery receipt signed by the consignee","All tangible, visible touch points a customer encounters before purchasing, such as reception areas and corporate logos","The physical weight limits of a vehicle bridge","The mechanical condition of brake pads"],"correct":1,"exp":"- Opción Correcta (B): En la mezcla de marketing de servicios (7 Ps), la \"evidencia física\" es todo lo que el cliente puede ver o tocar y que le da confianza (uniformes, limpieza de los autobuses, logo, web).\n- Opciones Incorrectas: (A) Es un albarán. (C y D) Son especificaciones técnicas y de mantenimiento."},{"q":"Dismissal of an employee on what grounds is automatically deemed \u0027unfair\u0027 by the WRC, regardless of length of service?","options":["Redundancy through a fair selection process","Incompetence after training","Trade union membership and activities","Retirement at age 65 with objective justification"],"correct":2,"exp":"- Opción Correcta (C): Despedir a alguien por pertenecer a un sindicato es una \"razón inadmisible\" y se considera despido improcedente automático desde el primer día de trabajo.\n- Opciones Incorrectas: (A, B y D) Son causas legales y justas de despido (fair dismissals) si se sigue el procedimiento correcto."},{"q":"What is the minimum threshold of proposed redundancies over a 30-day period that triggers collective redundancy rules in an establishment of 50 to 99 employees?","options":["3 or more redundancies","5 or more redundancies","30 or more redundancies","10 or more redundancies"],"correct":3,"exp":"- Opción Correcta (D): Por ley, si una empresa tiene entre 50 y 99 empleados, planear 10 o más despidos en 30 días activa las normas de despido colectivo.\n- Opciones Incorrectas: (A) No es un umbral legal. (B) Es el umbral para empresas de 21-49 empleados. (C) Es el umbral para empresas de más de 300 empleados."},{"q":"Within how many days must an employer notify a new employee of their core terms of employment via the \u0027Day 5 Statement\u0027?","options":["Within 14 days","Within 5 days of commencement","Within 1 month","Within 3 months"],"correct":1,"exp":"- Opción Correcta (B): La ley exige que los 5 términos esenciales (puesto, salario, horario, etc.) se entreguen en los primeros 5 días.\n- Opciones Incorrectas: (A y D) No son plazos legales. (C) Es el plazo máximo para entregar el contrato completo (Written Statement of Terms), no los términos básicos iniciales."},{"q":"What is the maximum duration generally permitted for successive fixed-term contracts before objective justification is required?","options":["1 year","2 years","4 years","5 years"],"correct":2,"exp":"- Opción Correcta (C): En Irlanda, los contratos temporales encadenados están limitados a un máximo de 4 años. Tras esto, el trabajador pasa a ser indefinido o se requiere justificación objetiva.\n- Opciones Incorrectas: (A, B y D) Son plazos incorrectos según la Fixed-Term Work Act 2003."},{"q":"A driver has been employed by a transport company for 15 years. How much notice must they give as a minimum if they wish to resign?","options":["One week","Twelve weeks","Fifteen weeks","None"],"correct":0,"exp":"- Opción Correcta (A): El preaviso mínimo legal que debe dar el EMPLEADO al dimitir es siempre de 1 semana (después de 13 semanas de trabajo), independientemente de sus años de antigüedad.\n- Opciones Incorrectas: (B, C y D) Las 8 semanas aplicarían si fuera la EMPRESA la que despide al trabajador con más de 15 años de antigüedad."},{"q":"Which of the following items must be submitted to the Companies Registration Office (CRO) when forming a limited company?","options":["Name of accountants and Corporation Tax registration","Statement of compliance, statement of capital, memorandum and articles of association","Driver CPC certificates","Vehicle logbooks"],"correct":1,"exp":"- Opción Correcta (B): Para registrar una empresa en la CRO se requiere el Formulario A1 (que incluye declaraciones de cumplimiento y capital) y los estatutos (Memorandum \u0026 Articles).\n- Opciones Incorrectas: (A) El registro de impuestos va a Revenue, no a la CRO. (C y D) Son documentos operativos de transporte, no corporativos."},{"q":"When distributing money raised by the disposal of assets during a liquidation, which of the following has the highest priority for payment?","options":["Preferential debts (wages)","Liquidator\u0027s fees and expenses","Unsecured debts","Fixed-Charge (secured) creditors"],"correct":3,"exp":"- Opción Correcta (D): Los acreedores con garantía real sobre bienes específicos (Fixed-charge) son los primeros en cobrar.\n- Opciones Incorrectas: (A) Las deudas preferentes van después de los gastos del liquidador. (B) Son los segundos en cobrar. (C) Los acreedores sin garantía son los últimos."},{"q":"A statement confirming that shareholders have limited liability can be found in the company\u0027s:","options":["Memorandum of Association","Statement of Capital","Certificate of Incorporation","Articles of Association"],"correct":3,"exp":"- Opción Correcta (D): Los Articles of Association contienen las normas internas y la cláusula expresa que limita la responsabilidad de los accionistas a lo que hayan invertido.\n- Opciones Incorrectas: (A) Solo expresa el deseo de fundar la empresa. (B y C) Certifican el capital y la creación, pero no contienen las reglas internas de responsabilidad."},{"q":"What is the fundamental difference between a debenture holder and a shareholder?","options":["Shareholders receive fixed interest","Debenture holders vote at the AGM","Debenture holders are paid interest, not dividends, and have no voting rights","Debenture holders own the company"],"correct":2,"exp":"- Opción Correcta (C): Un \u0027debenture holder\u0027 es un prestamista (acreedor), por lo que cobra intereses fijos y no tiene derecho a voto.\n- Opciones Incorrectas: (A) Los accionistas reciben dividendos variables. (B y D) Los accionistas son los que votan y los verdaderos dueños de la empresa."},{"q":"For a valid contract to exist, which of the following factors must be present?","options":["Written offer, acceptance, consideration","Offer, acceptance and consideration","Verbal offer and written acceptance","Two directors signatures"],"correct":1,"exp":"- Opción Correcta (B): Los tres elementos legales obligatorios de un contrato son oferta, aceptación y \"consideration\" (intercambio de valor).\n- Opciones Incorrectas: (A y C) Un contrato no tiene por qué ser por escrito para ser válido; puede ser verbal. (D) No es un requisito legal básico."},{"q":"What is the key rule regarding dividend payments for ordinary and preference shares?","options":["Ordinary shareholders are paid first","Both are paid equally","Ordinary shareholders will not receive any dividend until preference shareholders have been paid","Preference shares do not receive dividends"],"correct":2,"exp":"- Opción Correcta (C): Las acciones preferentes (preference shares) tienen prioridad de cobro sobre las ordinarias al repartir los beneficios.\n- Opciones Incorrectas: (A, B y D) Contradicen la definición legal de prioridad de las acciones preferentes."},{"q":"Which of the following must be included on the business letters (headed stationery) of a limited company?","options":["The address of the company\u0027s registered office","The name of the Company Secretary","The home address of all directors","The bank account details"],"correct":0,"exp":"- Opción Correcta (A): La ley exige que el papel membretado incluya la dirección registrada de la empresa, el número de CRO y el país de registro.\n- Opciones Incorrectas: (B) El secretario no es obligatorio. (C) Las direcciones personales no se incluyen. (D) No es un requisito legal de la CRO."},{"q":"For what period is a Road Passenger Transport Operator Licence normally valid?","options":["3 years","5 years","Indefinitely","10 years"],"correct":1,"exp":"- Opción Correcta (B): La licencia de operador de transporte de pasajeros es válida normalmente por un periodo de 5 años.\n- Opciones Incorrectas: Las licencias no son indefinidas ni duran 3 o 10 años por estándar europeo."},{"q":"Where a Transport Manager ceases to act in that role, what is the maximum period allowed to appoint a new one?","options":["1 year","3 months","1 month","6 months"],"correct":3,"exp":"- Opción Correcta (D): La autoridad competente puede otorgar un máximo de 6 meses de margen para sustituir al Gestor de Transporte.\n- Opciones Incorrectas: (A, B y C) No reflejan el periodo de gracia estipulado por la regulación (Regulation EC 1071/2009)."},{"q":"In the case of a contracted Transport Manager, what are the restrictions regarding the undertakings and vehicles they can manage?","options":["4 transport undertakings with a maximum combined fleet of 50 vehicles","2 transport undertakings with a maximum combined fleet of 50 vehicles","4 transport undertakings with a maximum combined fleet of 100 vehicles","5 transport undertakings with a maximum combined fleet of 100 vehicles"],"correct":0,"exp":"- Opción Correcta (A): Un gestor de transporte externo (contratado) puede gestionar como máximo 4 empresas diferentes que sumen una flota total combinada de hasta 50 vehículos.\n- Opciones Incorrectas: Exceden los límites legales establecidos para evitar que un gestor abarque más de lo que puede controlar eficazmente."},{"q":"Which one of the following is exempt from the requirement to have a Road Passenger Transport Operator Licence?","options":["Transport for hire or reward of school students","Private hire transport for one-off events","Transport for hire or reward of passengers to charity events","Transport of employees to or from work in vehicles owned by their employers"],"correct":3,"exp":"- Opción Correcta (D): El transporte por cuenta propia (own-account), como un empleador transportando a sus propios empleados en sus propios vehículos, está exento.\n- Opciones Incorrectas: (A, B y C) Cualquier transporte de pasajeros por \"hire or reward\" (alquiler o recompensa) requiere licencia comercial."},{"q":"An operator is proposing to run a local bus service with a single journey time of 40 minutes and 5 minutes stand time at each end. How many vehicles are required if the frequency is every 5 minutes?","options":["9 vehicles","10 vehicles","18 vehicles","20 vehicles"],"correct":2,"exp":"- Opción Correcta (C): El viaje de ida son 40m + 5m de espera = 45m. El viaje de vuelta son otros 45m. El tiempo total de rotación (Round trip) = 90 minutos. Si sale un autobús cada 5 minutos: 90 / 5 = 18 vehículos necesarios.\n- Opciones Incorrectas: (A, B y D) Son cálculos matemáticos erróneos para esta ruta."},{"q":"When a fare scale is tapered, the longer distance passenger is charged:","options":["Less per mile than the short distance passenger","The same per mile as the short distance passenger","More per mile than the short distance passenger","A flat rate per mile irrespective of distance travelled"],"correct":0,"exp":"- Opción Correcta (A): Una tarifa decreciente (tapered) significa que el precio total aumenta, pero el coste por kilómetro o milla se va reduciendo cuanto más largo es el viaje.\n- Opciones Incorrectas: (B) Sería una tarifa estándar lineal. (C) Perjudicaría los viajes largos. (D) Es una tarifa plana irreal."},{"q":"Which one of the following is likely to be the most secure system of pre-paid tickets to prevent fraud?","options":["Unnumbered tickets and unnumbered photocards","Uniquely numbered tickets and matching numbered photocards","Uniquely numbered tickets and unnumbered photocards","Unnumbered tickets and uniquely numbered photocards"],"correct":1,"exp":"- Opción Correcta (B): Para evitar fraude, tanto el billete como la tarjeta de identificación con foto (photocard) deben tener números únicos que coincidan entre sí, impidiendo que varias personas usen el mismo abono.\n- Opciones Incorrectas: (A, C y D) Dejan vacíos de seguridad al no vincular el billete directamente a la identidad del portador."},{"q":"Jack Smith worked for Bloggs Ltd for ten years. Bloggs Ltd is bought by Lax Transport plc. Jack\u0027s continuous employment service will be calculated from when:","options":["Lax Transport took control","Lax Transport issued a new contract","Bloggs Ltd was removed from the register","He started work for Bloggs Ltd"],"correct":3,"exp":"- Opción Correcta (D): Según la normativa de Traspaso de Empresas (TUPE), los derechos y la antigüedad del trabajador se mantienen y se calculan desde su fecha de inicio original con la primera empresa.\n- Opciones Incorrectas: (A, B y C) Reiniciarían injustamente la antigüedad del trabajador, lo cual es ilegal."},{"q":"A pregnant employee employed for six months is entitled to:","options":["Take maternity leave for up to a maximum of 42 weeks","Maternity benefit irrespective of PRSI","Take maternity leave for only 26 weeks","52 weeks of paid leave"],"correct":0,"exp":"- Opción Correcta (A): Tiene derecho a 26 semanas de baja estándar más 16 semanas adicionales no pagadas (total 42 semanas máximo).\n- Opciones Incorrectas: (B) El beneficio estatal exige cotizaciones PRSI. (C) Omite las 16 semanas extras. (D) No existe ese derecho en Irlanda."},{"q":"What legal status does industrial action have if it is lawfully organized by a trade union following a proper ballot?","options":["It is classed as a \u0027wildcat strike\u0027 and unprotected","It converts employee contracts into fixed-term agreements","It is automatically prohibited by the WRC","It is regarded as \u0027protected\u0027 under the Unfair Dismissals Acts"],"correct":3,"exp":"- Opción Correcta (D): Si la huelga es legal y se votó en secreto (proper ballot), los trabajadores tienen inmunidad legal y no pueden ser despedidos por participar en ella (\"acción protegida\").\n- Opciones Incorrectas: (A) Las huelgas salvajes (wildcat) son ilegales. (B y C) No tienen sentido jurídico en este contexto."},{"q":"What is the general continuous service requirement for an employee to bring an ordinary claim of unfair dismissal to the WRC?","options":["6 months","1 month","1 year","2 years"],"correct":2,"exp":"- Opción Correcta (C): Por regla general, se exige 1 año (52 semanas) de servicio continuo para poder reclamar por despido improcedente ordinario.\n- Opciones Incorrectas: (A y B) Son insuficientes. (D) El requisito es 1 año, no 2."},{"q":"Which document is essential for international bus or coach services within the EU?","options":["National Transport Authority permit","Community Licence","CVRT certificate","Driver CPC card"],"correct":1,"exp":"- Opción Correcta (B): La Licencia Comunitaria (Community Licence) es el documento operativo fundamental que autoriza a las empresas a realizar transportes internacionales de pasajeros por toda la UE.\n- Opciones Incorrectas: (A) Es solo para Irlanda. (C) Es el certificado técnico del vehículo (ITV), no un permiso de rutas. (D) Es el título del conductor, no la autorización de la empresa."},{"q":"\"Closed Door Tours\" must be completed within a time limit of no more than:","options":["21 days","30 days","60 days","90 days"],"correct":1,"exp":"- Opción Correcta (B): Los servicios ocasionales conocidos como \u0027Closed Door Tours\u0027 (el mismo autobús lleva al mismo grupo durante todo el viaje y vuelve al punto de partida) deben completarse en un máximo de 30 días.\n- Opciones Incorrectas: (A, C y D) No son los plazos estipulados por la normativa europea de servicios ocasionales."},{"q":"Which of the following international conventions deals with the creation and maintenance of a network of key road systems?","options":["Schengen Agreement","AGR","SOLAS","Interbus"],"correct":1,"exp":"- Opción Correcta (B): El Acuerdo AGR (European Agreement on Main International Traffic Arteries) rige la construcción y numeración de la red principal de carreteras europeas (las rutas \"E\").\n- Opciones Incorrectas: (A) Trata sobre fronteras y visados. (C) Trata sobre seguridad marítima. (D) Trata sobre transporte internacional ocasional de pasajeros."},{"q":"What is the purpose of the Schengen Agreement?","options":["To permit vehicles to circulate freely within the EU","To harmonise tax free goods borders","To allow travellers to cross internal EU borders without passport checks","To allow temporary importation of vehicles"],"correct":2,"exp":"- Opción Correcta (C): El Espacio Schengen abolió los controles fronterizos sistemáticos en las fronteras interiores de los países firmantes, permitiendo viajar sin control de pasaporte.\n- Opciones Incorrectas: (A, B y D) Mezclan normativas de aduanas, mercado común y vehículos, no tránsito de personas."},{"q":"Which document permits a coach to travel at up to 100 km/h on motorways in Germany?","options":["Community Licence","Vitesse 100 certificate","Eurovignette","Tempo 100 certificate"],"correct":3,"exp":"- Opción Correcta (D): El certificado Tempo 100 es una homologación alemana que certifica que el autobús cumple con estándares de seguridad para circular a 100 km/h.\n- Opciones Incorrectas: (B) Es el equivalente francés. (A) Es la licencia europea. (C) Es el sistema de peaje para camiones pesados."},{"q":"In France, the road sign \"equipements speciaux obligatoires\" requires drivers to:","options":["Give way to traffic approaching from the right","Beware of melting snow","Reduce speed in adverse weather conditions","Fit snow chains to the vehicle"],"correct":3,"exp":"- Opción Correcta (D): \"Equipamientos especiales obligatorios\" en las zonas de montaña francesas indica la obligación legal de montar cadenas de nieve o llevar neumáticos de invierno.\n- Opciones Incorrectas: (A, B y C) No reflejan la orden imperativa del equipamiento."},{"q":"In Germany, the LKW Maut electronic tolling system is applicable to goods vehicles exceeding a gross weight threshold of:","options":["3,500 kg","7,500 kg","12,000 kg","15,000 kg"],"correct":1,"exp":"- Opción Correcta (B): El sistema de peajes Maut en Alemania se aplica actualmente a vehículos comerciales que exceden los 7,500 kg (7.5 toneladas). (Nota de estudio: Revisa las actualizaciones legislativas recientes, ya que este límite se ha reducido a 3.5t en julio de 2024, pero basándose en los textos clásicos de examen y transiciones, suele evaluarse el tramo de pesados tradicional. En tu material histórico, la respuesta marcada suele ser 7.5t)."},{"q":"Commercial goods vehicles over one year old must generally undergo:","options":["Annual Commercial Vehicle Roadworthiness Testing (CVRT)","A driving test every two years","Emissions testing only","No testing requirements once insured"],"correct":0,"exp":"- Opción Correcta (A): Los vehículos comerciales pesados en Irlanda requieren pasar la inspección CVRT (la ITV irlandesa para comerciales) anualmente desde su primer año.\n- Opciones Incorrectas: (B, C y D) Las revisiones no son cada dos años ni se limitan solo a emisiones."},{"q":"On which of the following pieces of Irish road infrastructure are charges made to road haulage vehicles? 1. M50 Motorway 2. Dublin Port Tunnel 3. Jack Lynch Tunnel 4. M1 Motorway 5. Limerick Tunnel","options":["1 and 2 only","2, 3 and 4 only","1, 2, 4 and 5 only","1, 2, 3, 4 and 5"],"correct":2,"exp":"- Opción Correcta (C): En Irlanda hay peajes comerciales en la M50 (barrera libre), en el Túnel del Puerto de Dublín (gratis para camiones pesados en algunos horarios, pero sujetos a estructura de peaje), la M1 y el Túnel de Limerick. El Jack Lynch Tunnel en Cork NO tiene peaje.\n- Opciones Incorrectas: (A, B y D) Incluyen el Jack Lynch Tunnel o excluyen autopistas de peaje clave de la red."}]},
"102": { title: "Simulacro 2 - Licensing, Operations \u0026 Vehicle Costing", questions: [{"q":"For what period is a Road Passenger Transport Operator Licence normally valid?","options":["3 years","5 years","Indefinitely","10 years"],"correct":1,"exp":"- Opción Correcta (B): La licencia de operador de transporte de pasajeros en Irlanda (y en la UE) se emite normalmente por un periodo de 5 años.\n- Opciones Incorrectas: (A, C, D) No son los plazos estándar de renovación fijados por la NTA y la normativa europea."},{"q":"Where a Transport Manager ceases to act in that role for a road passenger transport undertaking, what is the maximum period allowed for the undertaking to appoint a new Transport Manager?","options":["1 year","3 months","1 month","6 months"],"correct":3,"exp":"- Opción Correcta (D): Si un Gestor de Transporte dimite, fallece o deja de ejercer, la autoridad competente puede conceder un periodo de gracia máximo de 6 meses para que la empresa contrate a uno nuevo.\n- Opciones Incorrectas: (A, B, C) Son plazos incorrectos según el Reglamento (CE) 1071/2009."},{"q":"In the case of a contracted Transport Manager, certain restrictions apply regarding the total number of undertakings and vehicles that he/she is allowed to manage. Which one of the following describes these restrictions?","options":["4 transport undertakings with a maximum combined fleet of 50 vehicles","2 transport undertakings with a maximum combined fleet of 50 vehicles","4 transport undertakings with a maximum combined fleet of 100 vehicles","5 transport undertakings with a maximum combined fleet of 100 vehicles"],"correct":0,"exp":"- Opción Correcta (A): Un Gestor de Transporte externo solo puede gestionar hasta 4 empresas diferentes, siempre y cuando la suma total de los vehículos de todas ellas no supere los 50.\n- Opciones Incorrectas: (B, C, D) No reflejan el límite legal establecido para asegurar que el gestor pueda ejercer un control real y efectivo."},{"q":"Which one of the following is exempt from the requirement to have a Road Passenger Transport Operator Licence for national operations?","options":["Transport for hire or reward of school students","Private hire transport for one-off events","Transport for hire or reward of passengers to charity events","Transport of employees to or from work in vehicles owned by their employers"],"correct":3,"exp":"- Opción Correcta (D): El transporte de empleados en vehículos propiedad de la empresa (Own-account transport) no tiene fines comerciales directos (hire or reward), por lo que está exento de la licencia de operador.\n- Opciones Incorrectas: (A, B, C) Cualquier transporte donde haya un pago u obtención de beneficio (alquiler o recompensa) exige licencia."},{"q":"In Ireland, motor tax for buses and coaches is primarily based on:","options":["Engine size","CO2 emissions","Seating capacity","Gross vehicle weight"],"correct":2,"exp":"- Opción Correcta (C): A diferencia de los coches (CO2/motor) o los camiones (peso bruto), el impuesto de circulación (motor tax) para autobuses en Irlanda se calcula en tramos según la capacidad de asientos (seating capacity).\n- Opciones Incorrectas: (A, B, D) Son bases imponibles para otro tipo de vehículos, no para autobuses de pasajeros."},{"q":"Which body issues PSV (Public Service Vehicle) licences in Ireland?","options":["Revenue Commissioners","Road Safety Authority (RSA)","National Transport Authority (NTA)","Department of Transport"],"correct":2,"exp":"- Opción Correcta (C): La NTA (National Transport Authority) es el organismo encargado de regular el transporte público y emitir las licencias PSV en Irlanda.\n- Opciones Incorrectas: (A) Recauda impuestos. (B) Se encarga de la seguridad vial y test de conductores (CVRT). (D) Es el ministerio gubernamental, pero no emite la licencia operativa directamente."},{"q":"Interworking is the name given to which of the following activities?","options":["Using a driver to cover more than one route","Using a vehicle to cover more than one route","Two or more operators providing vehicles for one route","Two or more operators providing drivers for one route"],"correct":1,"exp":"- Opción Correcta (B): El \"Interworking\" en la planificación de horarios se refiere a utilizar un mismo autobús (vehículo) para operar en más de una ruta durante el día, optimizando así el uso de la flota.\n- Opciones Incorrectas: (A, C, D) Son definiciones incorrectas para este término técnico de planificación."},{"q":"A local bus service operator runs two services. Both operate every 15 minutes. Service X has a single journey time of 44 minutes and 4 minutes stand time at the end. Service Y has a single journey time of 29 minutes and 4 minutes stand time. What is the minimum number of buses needed to operate these two services combined?","options":["10 buses","11 buses","12 buses","13 buses"],"correct":2,"exp":"- Opción Correcta (C): Servicio X: (44+4) = 48m por trayecto x 2 = 96m viaje redondo. A 15m de frecuencia, 96/15 = 6.4 (se necesitan 7 buses). Servicio Y: (29+4) = 33m x 2 = 66m viaje redondo. 66/15 = 4.4 (se necesitan 5 buses). Total: 7 + 5 = 12 buses.\n- Opciones Incorrectas: (A, B, D) Son cálculos matemáticos erróneos."},{"q":"An operator offering a \u0027package tour\u0027 must provide evidence of security for the refund of money and repatriation in the event of insolvency. Which of the following would be an acceptable means? 1. Bonding 2. Putting money into a subsidiary 3. Putting money into the control of a trustee","options":["1 and 3 only","1, 2 and 3","1 and 2 only","2 and 3 only"],"correct":0,"exp":"- Opción Correcta (A): La ley de viajes combinados exige que el dinero del cliente esté protegido mediante una fianza/seguro (Bonding) o depositado en un fideicomiso independiente (Trustee).\n- Opciones Incorrectas: (2) Ponerlo en una empresa subsidiaria del mismo dueño no protege el dinero en caso de quiebra corporativa."},{"q":"Which type of passenger service normally requires an EU route authorisation?","options":["Occasional service","Special regular service under contract","Regular scheduled service","Private non commercial transport"],"correct":2,"exp":"- Opción Correcta (C): Los servicios regulares internacionales (con horarios y paradas fijas para el público general) son los que exigen una Autorización de Ruta de la UE.\n- Opciones Incorrectas: (A, B) Suelen estar cubiertos simplemente con la Licencia Comunitaria y una hoja de ruta (Waybill) o contrato. (D) No es transporte comercial."},{"q":"Cabotage in passenger transport is best described as:","options":["Permanent domestic passenger services in another Member State","Limited passenger services carried out within another Member State under EU rules","Own account passenger transport","Domestic services within Ireland only"],"correct":1,"exp":"- Opción Correcta (B): El Cabotaje permite a un operador realizar transportes nacionales temporales y limitados dentro de las fronteras de otro país de la UE distinto al de su establecimiento.\n- Opciones Incorrectas: (A) Si es permanente, requiere establecer una empresa en ese país. (C y D) No son definiciones de cabotaje."},{"q":"From which organisation may an operator obtain waybills for an occasional international service?","options":["Coach Tourism \u0026 Transport Council of Ireland (CTTC)","National Driver Licence Service (NDLS)","Interbus, Geneva","National Transport Authority (NTA)"],"correct":3,"exp":"- Opción Correcta (D): En Irlanda, la NTA es la autoridad competente que suministra los libros de hojas de ruta (waybills) necesarios para los viajes ocasionales internacionales bajo la Licencia Comunitaria.\n- Opciones Incorrectas: Ninguna de las otras organizaciones emite estos documentos oficiales."},{"q":"Which of the following links would facilitate coach travel between France and Italy? 1. St Gotthard Tunnel 2. St Bernard Tunnel 3. Frejus Tunnel 4. Mont Blanc Tunnel","options":["1 only","2 and 3 only","3 and 4 only","1, 2 and 4 only"],"correct":2,"exp":"- Opción Correcta (C): Los túneles de Fréjus y Mont Blanc conectan directamente Francia con Italia.\n- Opciones Incorrectas: St Gotthard y St Bernard conectan principalmente con Suiza, no son pasos directos Francia-Italia."},{"q":"An Irish driver would need a visa to enter which of the following countries?","options":["Ukraine","Poland","Romania","Bulgaria"],"correct":0,"exp":"- Opción Correcta (A): Históricamente (y según los manuales del CPC para este examen), al no pertenecer Ucrania a la UE ni al espacio Schengen, se requiere visado para entrar.\n- Opciones Incorrectas: (B, C, D) Son países de la Unión Europea, por lo que los ciudadanos irlandeses tienen libertad de movimiento sin visado."},{"q":"Which authority administers the Commercial Vehicle Roadworthiness Test (CVRT) in Ireland?","options":["National Transport Authority","Road Safety Authority (RSA)","Department of Transport","Revenue Commissioners"],"correct":1,"exp":"- Opción Correcta (B): La Road Safety Authority (RSA) es el organismo estatal que gestiona y supervisa las pruebas de ITV para vehículos comerciales (CVRT).\n- Opciones Incorrectas: La NTA (A) regula licencias. Revenue (D) recauda impuestos. El ministerio (C) hace las leyes."},{"q":"When is a commercial passenger vehicle generally required to undergo its first CVRT?","options":["When it reaches 6 months old","When it is first taxed","When it is 1 year old","After 3 years in service"],"correct":2,"exp":"- Opción Correcta (C): A diferencia de los coches privados que tardan 4 años, los vehículos comerciales de pasajeros (autobuses) deben pasar su primera ITV (CVRT) al cumplir su primer año de antigüedad.\n- Opciones Incorrectas: (A, B, D) Son plazos incorrectos según la ley irlandesa de vehículos comerciales."},{"q":"VAT related records must be kept for a minimum period specified by law. This minimum period is:","options":["1 year","3 years","5 years","6 years"],"correct":3,"exp":"- Opción Correcta (D): La normativa de los Revenue Commissioners en Irlanda obliga a conservar todos los registros relacionados con impuestos (incluido el IVA/VAT) durante un mínimo de 6 años.\n- Opciones Incorrectas: Tiempos inferiores (A, B, C) exponen a la empresa a sanciones en caso de auditoría."},{"q":"A vehicle is designed to carry 15 passengers. Which classification is most likely to apply?","options":["Motor car","Minibus","Large bus","Heavy motor car"],"correct":1,"exp":"- Opción Correcta (B): Un vehículo con capacidad para más de 8 pasajeros pero no superior a las dimensiones de un bus de gran tamaño, como este de 15 plazas, se clasifica como Minibús (categoría D1).\n- Opciones Incorrectas: (A y D) Los coches llevan un máximo de 8 pasajeros. (C) \"Large bus\" suele ser de más de 22 plazas o vehículos pesados."},{"q":"A two-part passenger vehicle allows passengers to move between the connected sections. Which classification best fits this description?","options":["Dual purpose vehicle","Articulated bus","Motor car","Long distance coach"],"correct":1,"exp":"- Opción Correcta (B): Un autobús articulado (Articulated bus) es aquel que consta de dos secciones unidas por un mecanismo articulado por el cual los pasajeros pueden caminar libremente.\n- Opciones Incorrectas: (A) Se refiere a vehículos de carga/pasajeros tipo furgoneta. (D) Los autocares no suelen ser articulados."},{"q":"Operators must keep copies of all maintenance records relating to licensed vehicles for a minimum period of:","options":["6 months","12 months","15 months","3 years"],"correct":2,"exp":"- Opción Correcta (C): La ley de transporte en Irlanda establece que los registros de mantenimiento (inspecciones, defectos, reparaciones) de vehículos comerciales deben guardarse durante 15 meses.\n- Opciones Incorrectas: Cuidado, los tacógrafos se guardan 12 meses y los impuestos 6 años, pero el mantenimiento son 15 meses exactos."},{"q":"Vehicles above a prescribed gross weight threshold must be fitted with a mirror giving the driver a view across the front of the vehicle. This threshold is:","options":["3.5 tonnes","7.5 tonnes","12 tonnes","18 tonnes"],"correct":1,"exp":"- Opción Correcta (B): Por normativas de seguridad para proteger a peatones y ciclistas, los vehículos pesados a partir de 7.5 toneladas deben llevar un espejo frontal para evitar ángulos muertos.\n- Opciones Incorrectas: (A, C, D) Son pesos límite incorrectos para esta normativa específica de espejos retrovisores."},{"q":"A driver has been ill and absent from work for two months. When starting back to work on a journey to France, which document should they carry to explain their incomplete tachograph records?","options":["Community Licence","Digital tachograph card","GHIC","Letter of attestation"],"correct":3,"exp":"- Opción Correcta (D): La \"Carta de Atestación de Actividades\" (Letter of attestation) es el formulario estandarizado de la UE que el empleador firma para justificar que un conductor no tiene registros de conducción por haber estado de baja, vacaciones o haciendo otro trabajo.\n- Opciones Incorrectas: (B) La tarjeta no explica por sí sola un hueco de dos meses. (C) Es la tarjeta sanitaria. (A) Es para la empresa."},{"q":"A vehicle is equipped with 6 tyres costing €300 each. The trailer has 4 tyres costing €510 each. All tyres have a life of 80,000 km. What is the running cost of tyres per kilometre?","options":["0.048 c","4.80 c","5.10 c","20.83 c"],"correct":1,"exp":"- Opción Correcta (B): Coste de neumáticos de la tractora: 6 x 300€ = 1,800€. Neumáticos del remolque: 4 x 510€ = 2,040€. Total coste = 3,840€. Dividido por 80,000 km = 0.048 euros por km. Para pasarlo a céntimos (cents), multiplicas por 100 = 4.80 céntimos.\n- Opciones Incorrectas: (A) Está en euros, no en céntimos. (C y D) Son errores de cálculo."},{"q":"Which of the following vehicle costs are both direct and fixed? 1. Vehicle Tax 2. Lubricants 3. Insurance 4. Tyres 5. Maintenance","options":["1 and 3 only","2 and 5 only","1, 4 and 5 only","2, 3 and 4 only"],"correct":0,"exp":"- Opción Correcta (A): El impuesto de circulación (Tax) y el Seguro (Insurance) se pagan anualmente sí o sí (costes fijos) y se asignan a un vehículo específico (directos).\n- Opciones Incorrectas: Neumáticos, lubricantes y mantenimiento (2, 4 y 5) son costes VARIABLES, porque dependen directamente de cuántos kilómetros ruede el autobús."},{"q":"Which organisation has responsibility under Competition laws to ensure fair and open competition in the bus industry in Ireland?","options":["The Chartered Institute of Logistics and Transport","The Department for Transport","The Road Safety Authority","Competition and Consumer Protection Commission (CCPC)"],"correct":3,"exp":"- Opción Correcta (D): La CCPC es el organismo estatal que vigila los monopolios, los acuerdos de fijación de precios y protege los derechos de los consumidores en todos los sectores, incluido el transporte.\n- Opciones Incorrectas: El resto de entidades se dedican a logística, legislación de infraestructuras o seguridad vial, no a la competencia económica."},{"q":"A passenger on a local bus service claims that due to the late running of a journey, they missed an appointment and incurred costs of €100. What is the liability of the bus operator?","options":["The operator is not liable for the costs incurred by the passenger","The operator is liable for the whole costs incurred","Whatever is stated in the operator\u0027s conditions of carriage","A loss adjuster will determine liability"],"correct":0,"exp":"- Opción Correcta (A): En el transporte público, los operadores están exentos de responsabilidad civil por daños consecuenciales (como perder una cita o un vuelo) debidos a retrasos, ya que esto se excluye en las condiciones de servicio.\n- Opciones Incorrectas: (B, C, D) Contradicen el principio legal de limitación de responsabilidad de los operadores de transporte regular."},{"q":"The driver of a PSV operating a local service arrives at a stop with a queue including passengers with pushchairs. There is not enough room on the vehicle to store all pushchairs, and they cannot be placed on seats. What action should the driver take?","options":["Permit all passengers to travel, provided pushchairs are at the rear","Permit all passengers, provided pushchairs are at the front","Permit only those passengers whose pushchairs can be safely placed in the space provided","Permit none of the pushchairs to travel to avoid discrimination"],"correct":2,"exp":"- Opción Correcta (C): Por motivos de seguridad vial y evacuación, los pasillos no pueden estar bloqueados. El conductor solo puede admitir los cochecitos que quepan en las zonas de almacenamiento designadas.\n- Opciones Incorrectas: (A y B) Sería ilegal e inseguro viajar con carritos sueltos. (D) Negar el acceso a los primeros es injustificado e inapropiado."},{"q":"For hire and reward passenger services, which of the following must be in place?","options":["Road Passenger Transport Operator Licence","Appropriate driver licence category","Compliance with EU drivers\u0027 hours rules","All of the above"],"correct":3,"exp":"- Opción Correcta (D): Realizar transporte comercial de pasajeros exige cumplir todos estos requisitos: licencia de empresa, carnet de conducir tipo D y uso del tacógrafo (leyes de horas de conducción).\n- Opciones Incorrectas: Marcar A, B o C excluiría requisitos legales obligatorios."},{"q":"If an employer agrees to pay drivers a nightly subsistence rate in excess of the Revenue civil service rates:","options":["The excess is regarded as emoluments, is considered income, and taxable","The rate must be agreed in advance and employees taxed on the excess","Neither the employer nor drivers have any additional tax liability","The drivers must repay any excess into a pension"],"correct":0,"exp":"- Opción Correcta (A): El estado permite pagar dietas (subsistence) libres de impuestos hasta un tope oficial. Todo lo que el jefe pague por encima de ese tope se considera parte del salario (emoluments) y paga impuestos (IRPF, PRSI).\n- Opciones Incorrectas: (C) Es falso, hay que tributarlo. (B y D) No son los procedimientos dictados por Hacienda (Revenue)."},{"q":"An international service which carries passengers along specified routes, picking up and setting down at predetermined points, and is available to the general public is an:","options":["Open door service","International special regular service","International regular service","Occasional service"],"correct":2,"exp":"- Opción Correcta (C): Esta es la definición legal exacta de un \"Servicio Regular Internacional\" (como un bus de Dublín a Londres con paradas fijas).\n- Opciones Incorrectas: (D) Los servicios ocasionales son para grupos cerrados (tours). (B) Los servicios regulares especiales transportan solo a una categoría de personas (ej. trabajadores)."},{"q":"Once passed, the Driver CPC Theory Test qualification is \"live\" for what maximum period of time before the practical test must be completed?","options":["6 months","1 year","2 years","5 years"],"correct":2,"exp":"- Opción Correcta (C): El certificado de haber aprobado el examen teórico tiene una validez de 2 años. Si no apruebas el examen práctico de conducir en ese tiempo, tienes que volver a examinarte de la teoría.\n- Opciones Incorrectas: (A, B, D) No corresponden con la norma de la RSA."},{"q":"Which of the following countries require drivers engaged on tour operations to carry proof that they are being paid at least the minimum wage?","options":["Germany","Netherlands","Portugal","Belgium"],"correct":0,"exp":"- Opción Correcta (A): Bajo la ley \u0027MiLoG\u0027, Alemania fue de las primeras (junto a Francia) en exigir a transportistas extranjeros llevar pruebas documentales en el bus de que sus conductores cobran, al menos, el salario mínimo alemán mientras transitan por su territorio.\n- Opciones Incorrectas: Los otros países no aplican esta estricta normativa de inspección en cabina de la misma forma histórica."},{"q":"Assessment of a company\u0027s Corporation Tax is based on which of the following?","options":["Adjusted net profit","Capital gains","Fixed assets","Adjusted gross profit"],"correct":0,"exp":"- Opción Correcta (A): El Impuesto de Sociedades (12.5% en Irlanda) se paga sobre los beneficios netos de la empresa una vez que se han hecho los ajustes por deducciones o subsidios (Adjusted net profit).\n- Opciones Incorrectas: (B) Se pagan impuestos de plusvalías separados. (C) Son propiedades de la empresa. (D) El beneficio bruto no descuenta todos los gastos."},{"q":"Under EU drivers\u0027 hours rules, what is the maximum permitted weekly driving time?","options":["45 hours","48 hours","56 hours","90 hours"],"correct":2,"exp":"- Opción Correcta (C): Un conductor puede manejar un máximo de 56 horas en una sola semana (ej: 4 días de 9 horas y 2 días de 10 horas).\n- Opciones Incorrectas: (A y B) Son límites de descanso o directiva de tiempo de trabajo, no de conducción. (D) 90 horas es el límite de conducción para DOS semanas consecutivas."},{"q":"Under EU drivers\u0027 hours rules, what is the maximum accumulated driving time allowed in any two consecutive weeks?","options":["90 hours","100 hours","112 hours","56 hours"],"correct":0,"exp":"- Opción Correcta (A): Aunque el límite de una semana sea 56, en dos semanas consecutivas no se puede superar las 90 horas. Si haces 56 en la semana 1, en la semana 2 solo podrás conducir 34.\n- Opciones Incorrectas: (C) Sería 56x2, lo cual está prohibido para evitar la fatiga crónica."},{"q":"What is the regular daily rest period a driver must take in a 24-hour period under EU rules?","options":["9 hours","11 hours","24 hours","45 hours"],"correct":1,"exp":"- Opción Correcta (B): El descanso diario normal (regular daily rest) debe ser ininterrumpido de al menos 11 horas.\n- Opciones Incorrectas: (A) 9 horas es el descanso diario \"reducido\". (D) 45 horas es el descanso semanal normal."},{"q":"If a local bus service has a single journey time of 40 minutes, with a 5 minute stand time at each end, which frequency (headway) will make the BEST use of resources without extending standing time?","options":["Every 20 minutes","Every 25 minutes","Every 30 minutes","Every 40 minutes"],"correct":2,"exp":"- Opción Correcta (C): Un viaje redondo (Round Trip) dura 90 min (40+5+40+5). Para optimizar, la frecuencia debe dividir a 90 de forma exacta. 90/30 = 3 buses trabajando continuamente sin añadir tiempos muertos innecesarios.\n- Opciones Incorrectas: 90 no se divide exactamente por 20, 25 ni 40, lo que obligaría a los conductores a esperar más tiempo inactivos en las paradas."},{"q":"Under the Package Travel Regulations, a service is considered a \u0027package\u0027 if it pre-arranges transport and combines it with:","options":["Nothing else, just transport","A concert ticket returning the same day under 24 hours","Accommodation or lasts for more than 24 hours","A hot meal served on board"],"correct":2,"exp":"- Opción Correcta (C): La ley define un \"viaje combinado\" (Package) cuando se venden dos o más elementos turísticos (transporte, hotel, evento) a un precio global y dura más de 24 horas O incluye alojamiento nocturno.\n- Opciones Incorrectas: Las excursiones de menos de 24 horas sin hotel no se consideran viajes combinados."},{"q":"\"Closed Door Tours\" must be completed within a time limit of no more than:","options":["21 days","30 days","60 days","90 days"],"correct":1,"exp":"- Opción Correcta (B): En los servicios ocasionales internacionales, un \"Closed Door Tour\" (mismos pasajeros, mismo bus durante todo el viaje) está limitado a un máximo de 30 días continuos.\n- Opciones Incorrectas: Son plazos falsos en la normativa europea."},{"q":"The Competition laws, as it applies to bus services, permits which of the following agreements between bus operators? 1. Agreeing to pool revenue 2. Agreeing to charge identical fares 3. Agreeing to participate in an area-wide ticketing scheme 4. Agreeing to display the same service numbers","options":["2 only","3 and 4 only","1 and 4 only","1, 2 and 3 only"],"correct":1,"exp":"- Opción Correcta (B): Los operadores sí pueden acordar tener un sistema de billetes conjunto (para beneficiar al usuario) o usar la misma numeración de líneas para evitar confusión.\n- Opciones Incorrectas: Pactar para repartirse el dinero (1) o acordar poner el mismo precio (2) se consideran cárteles de fijación de precios, lo cual es ilegal y penalizado por la CCPC."}]},
"103": { title: "Simulacro 3 - Finance, Business Law \u0026 Drivers\u0027 Hours", questions: [{"q":"Which financial statement shows a company\u0027s financial position at a specific point in time?","options":["Cash Flow Statement","Profit and Loss Account","Balance Sheet","Operating Budget"],"correct":2,"exp":"- Opción Correcta (C): El Balance Situacional (Balance Sheet) refleja los activos, pasivos y patrimonio neto de la empresa en una fecha determinada.\n- Opciones Incorrectas: (A) Mide las entradas y salidas de efectivo durante un periodo. (B) Mide los ingresos y gastos durante un ejercicio contable. (D) Es una estimación de presupuesto interno."},{"q":"Which of the following is classified as a variable (running) cost in vehicle operation?","options":["Vehicle road tax","Driver\u0027s basic salary","Fuel consumption","Annual vehicle insurance premium"],"correct":2,"exp":"- Opción Correcta (C): El consumo de combustible varía en función directa de los kilómetros recorridos por el autobús (running cost).\n- Opciones Incorrectas: (A, B y D) Son costes fijos (standing costs), ya que se deben abonar de forma periódica independientemente de la distancia recorrida."},{"q":"In Ireland, what is the standard rate of VAT applicable to most taxable goods and services?","options":["13.5%","23%","0%","9%"],"correct":1,"exp":"- Opción Correcta (B): El tipo general del Impuesto sobre el Valor Añadido (VAT) en Irlanda es del 23%.\n- Opciones Incorrectas: (A) Es el tipo reducido (aplica a sectores como construcción o combustible doméstico). (C y D) Son tipos superreducidos o exentos."},{"q":"What is the primary advantage of debt factoring for a transport operator?","options":["It eliminates the need to pay Corporation Tax","It provides immediate cash flow by selling unpaid invoices to a third party","It guarantees 100% profit margins on all routes","It reduces vehicle depreciation rates"],"correct":1,"exp":"- Opción Correcta (B): El factoraje de deudas (Debt Factoring) permite obtener efectivo inmediato vendiendo las facturas pendientes de cobro a una entidad financiera.\n- Opciones Incorrectas: (A) No altera las obligaciones fiscales de la empresa. (C) No afecta a los márgenes de beneficio operativos. (D) La depreciación es un cálculo contable del vehículo."},{"q":"What is a major advantage of operating a transport business as a Private Limited Company (LTD) compared to a Sole Trader?","options":["The company pays no taxes","Shareholders have limited liability for company debts","Directors are exempt from EU drivers\u0027 hours rules","No annual financial returns are required"],"correct":1,"exp":"- Opción Correcta (B): En una sociedad limitada (LTD), la responsabilidad de los socios ante deudas se limita al capital aportado, blindando sus bienes personales.\n- Opciones Incorrectas: (A) Paga Impuesto de Sociedades (Corporation Tax). (C) Las normas de conducción aplican a todos por igual. (D) Es obligatorio presentar cuentas anuales en la CRO."},{"q":"Which element is essential for a contract to be legally binding under Irish law?","options":["It must be registered with the CRO","Consideration must be present","It must be signed in front of a Garda","It must involve at least €10,000"],"correct":1,"exp":"- Opción Correcta (B): La \"Consideration\" (intercambio de valor real o contraprestación) es indispensable para la validez de un contrato junto a la oferta y la aceptación.\n- Opciones Incorrectas: (A, C y D) No son requisitos indispensables ni exigidos por el Derecho de Contratos."},{"q":"What is the statutory minimum level of motor insurance required for a passenger transport vehicle operating on Irish public roads?","options":["Comprehensive cover","Third Party, Fire and Theft","Third Party cover","Fleet liability cover"],"correct":2,"exp":"- Opción Correcta (C): La ley exige como mínimo la cobertura a terceros (Third Party cover), que responde por daños corporales o materiales causados a terceros.\n- Opciones Incorrectas: (A y B) Son ampliaciones comerciales voluntarias, no el mínimo exigido por la ley de tráfico."},{"q":"Which form must be submitted annually by a limited company to the Companies Registration Office (CRO)?","options":["Form A1","Annual Return (Form B1)","VAT3 Return","P45 Form"],"correct":1,"exp":"- Opción Correcta (B): El Formulario B1 es la declaración anual (Annual Return) que toda sociedad debe presentar ante la CRO.\n- Opciones Incorrectas: (A) Es el formulario para constituir la empresa. (C) Es para la liquidación del IVA en Revenue. (D) Es un documento tributario de retención salarial."},{"q":"Under Irish Safety, Health and Welfare at Work legislation, who has the primary duty of care to ensure workplace safety?","options":["The HSA inspector","The employer","The trade union representative","The vehicle manufacturer"],"correct":1,"exp":"- Opción Correcta (B): La ley atribuye la responsabilidad principal (duty of care) al empleador para garantizar la seguridad de sus trabajadores.\n- Opciones Incorrectas: (A) La HSA se encarga de vigilar e inspeccionar. (C y D) No son los responsables legales del centro de trabajo."},{"q":"An accident at work resulting in an employee being absent from work for more than how many consecutive days must be reported to the Health and Safety Authority (HSA)?","options":["1 day","3 consecutive days","7 consecutive days","14 consecutive days"],"correct":1,"exp":"- Opción Correcta (B): Todo accidente que cause una baja médica laboral de más de 3 días consecutivos (sin incluir el día del suceso) debe notificarse obligatoriamente a la HSA.\n- Opciones Incorrectas: (A, C y D) No coinciden con el umbral legal de notificación establecido."},{"q":"Under Irish statutory provisions, Statutory Sick Pay (SSP) requires employers to pay sick pay for up to how many days per calendar year?","options":["1 day","5 days","10 days","20 days"],"correct":1,"exp":"- Opción Correcta (B): La ley de retribución por baja médica (Statutory Sick Pay) en Irlanda fija el derecho legal mínimo en 5 días al año por empleado elegible.\n- Opciones Incorrectas: (A, C y D) Son duraciones no acordes al mínimo legal de la normativa."},{"q":"What is the maximum compensation the Workplace Relations Commission (WRC) can award for an unfair dismissal claim based on financial loss?","options":["6 months\u0027 remuneration","1 year\u0027s remuneration","2 years\u0027 remuneration","5 years\u0027 remuneration"],"correct":2,"exp":"- Opción Correcta (C): El WRC puede conceder una indemnización máxima de hasta 2 años de sueldo (104 semanas) si el trabajador demuestra pérdida financiera por despido improcedente.\n- Opciones Incorrectas: (A, B y D) Son límites incorrectos según la Unfair Dismissals Act."},{"q":"What is the minimum statutory redundancy payment for an eligible employee in Ireland?","options":["1 week\u0027s pay per year of service plus 1 bonus week","2 weeks\u0027 pay per year of service plus 1 bonus week","4 weeks\u0027 pay per year of service","Half a week\u0027s pay per year of service"],"correct":1,"exp":"- Opción Correcta (B): La indemnización legal por despido objetivo (Redundancy) son 2 semanas de sueldo por año trabajado más 1 semana adicional (bonus week).\n- Opciones Incorrectas: (A, C y D) No respetan la fórmula legal estipulada en la Redundancy Payments Act."},{"q":"Under the Organization of Working Time Act, what is the maximum average weekly working hours limit for employees?","options":["39 hours","48 hours","56 hours","60 hours"],"correct":1,"exp":"- Opción Correcta (B): La ley establece que el tiempo de trabajo semanal medio no puede superar las 48 horas.\n- Opciones Incorrectas: (A) Es una jornada contractual estándar, no el máximo legal. (C) Es el límite semanal de conducción del tacógrafo, no de tiempo de trabajo global."},{"q":"To satisfy the requirement of \u0027professional competence\u0027, a passenger transport undertaking must:","options":["Own at least 10 brand-new coaches","Employ at least one qualified Transport Manager holding a recognized Certificate of Professional Competence (CPC)","Be registered as a public limited company (PLC)","Have an annual turnover exceeding €1,000,000"],"correct":1,"exp":"- Opción Correcta (B): La competencia profesional se acredita únicamente contando con un Gestor de Transporte capacitado que tenga el título oficial de CPC.\n- Opciones Incorrectas: (A, C y D) No son condiciones exigidas por el Reglamento (CE) 1071/2009."},{"q":"To meet the \u0027Financial Standing\u0027 requirement for a Road Passenger Transport Operator Licence, an operator must demonstrate available capital/reserves of how much for the first vehicle and for each additional vehicle?","options":["€9,000 for the first vehicle and €5,000 for each additional vehicle","€5,000 for the first vehicle and €2,500 for each additional vehicle","€15,000 for the first vehicle and €10,000 for each additional vehicle","€1,000 per vehicle regardless of fleet size"],"correct":0,"exp":"- Opción Correcta (A): Se deben acreditar reservas financieras de 9,000 € para el primer autobús y 5,000 € por cada autobús adicional.\n- Opciones Incorrectas: (B, C y D) Son cantidades erróneas e insuficientes según la regulación europea."},{"q":"Which body in Ireland has the authority to revoke an Operator\u0027s Licence if the operator loses their \u0027Good Repute\u0027?","options":["The Garda Síochána","The Licensing Authority of the Department of Transport","The Health and Safety Authority","The Workplace Relations Commission"],"correct":1,"exp":"- Opción Correcta (B): El Departamento de Transporte (Department of Transport) es el organismo emisor con potestad para retirar o revocar la licencia de operador.\n- Opciones Incorrectas: (A) Ejecuta controles de tráfico. (C y D) Supervisan aspectos de seguridad e inspección de trabajo."},{"q":"A Large Public Service Vehicle (LPSV) licence issued by An Garda Síochána to a passenger vehicle is valid for how long?","options":["1 year","3 years","5 years","10 years"],"correct":1,"exp":"- Opción Correcta (B): Tal como figura explícitamente en las diapositivas de Módulo 10 de tu temario, la licencia de vehículo LPSV expedida por la Garda tiene una validez de 3 años.\n- Opciones Incorrectas: (A) Es la validez del CVRT. (C) Es la validez de la Licencia de Operador."},{"q":"Under the Public Transport Regulation Act 2009, which authority regulates commercial bus service routes and issues Public Bus Passenger Service Licences in Ireland?","options":["RSA","National Transport Authority (NTA)","Revenue Commissioners","CILT"],"correct":1,"exp":"- Opción Correcta (B): La NTA es la autoridad responsable de regular las rutas de autobús urbano e interurbano y de otorgar las licencias de servicios públicos.\n- Opciones Incorrectas: (A) La RSA se encarga de la seguridad vial e inspecciones técnicas. (C) Es la Agencia Tributaria. (D) Es el instituto certificador del examen."},{"q":"Under EU Regulation 561/2006, after how many hours of continuous driving must a driver take an uninterrupted break of at least 45 minutes?","options":["3.5 hours","4.5 hours","5 hours","9 hours"],"correct":1,"exp":"- Opción Correcta (B): Tras 4.5 horas de conducción continuada, el conductor debe hacer una pausa ininterrumpida de al menos 45 minutos.\n- Opciones Incorrectas: (A, C y D) No se corresponden con los límites legales del tacógrafo."},{"q":"When a 45-minute driving break is split into two parts under EU rules, what is the correct order and minimum duration of these breaks?","options":["First break at least 30 mins, second break at least 15 mins","First break at least 15 mins, second break at least 30 mins","Two equal breaks of 22.5 mins","First break at least 20 mins, second break at least 25 mins"],"correct":1,"exp":"- Opción Correcta (B): Si la pausa se fracciona, debe hacerse obligatoriamente en este orden: primero un bloque de mínimo 15 minutos, seguido de un bloque de mínimo 30 minutos.\n- Opciones Incorrectas: (A) Invertir los bloques (30+15) está prohibido por ley. (C y D) Son distribuciones ilegales."},{"q":"Under EU drivers\u0027 hours rules, a reduced weekly rest period must be at least how many hours?","options":["24 hours","36 hours","45 hours","11 hours"],"correct":0,"exp":"- Opción Correcta (A): El descanso semanal reducido exige un mínimo ininterrumpido de 24 horas (frente a las 45 horas del descanso semanal normal).\n- Opciones Incorrectas: (C) Es el descanso semanal normal. (D) Es el descanso diario normal."},{"q":"How often must a digital tachograph system in a commercial vehicle be recalibrated and inspected by an authorized workshop?","options":["Every 6 months","Every 1 year","Every 2 years","Every 5 years"],"correct":2,"exp":"- Opción Correcta (C): La inspección y recalibración de un tacógrafo digital en taller autorizado se exige cada 2 años.\n- Opciones Incorrectas: (A, B y D) Son plazos incorrectos para las revisiones periódicas del tacógrafo."},{"q":"What is the maximum validity period of a Driver Tachograph Card issued in Ireland?","options":["1 year","2 years","5 years","10 years"],"correct":2,"exp":"- Opción Correcta (C): La tarjeta digital de conductor (Driver Card) emitida por la RSA es válida por 5 años.\n- Opciones Incorrectas: (A, B y D) No coinciden con el periodo de vigencia legal."},{"q":"Which driving licence category is required to drive a minibus designed to carry up to 16 passengers in addition to the driver?","options":["Category B","Category C1","Category D1","Category CE"],"correct":2,"exp":"- Opción Correcta (C): La categoría D1 autoriza a conducir minibuses diseñados para transportar de 9 a 16 pasajeros.\n- Opciones Incorrectas: (A) Permite hasta 8 pasajeros. (B y D) Son licencias de camiones de carga."},{"q":"How long is a Pass Statement/CVRT Certificate valid for a commercial passenger vehicle over one year old?","options":["6 months","1 year","2 years","3 years"],"correct":1,"exp":"- Opción Correcta (B): La prueba de aptitud e inspección técnica comercial (CVRT) debe pasarse anualmente (validez de 1 año).\n- Opciones Incorrectas: (A, C y D) Los vehículos comerciales no tienen inspecciones bianuales ni trianuales."},{"q":"Buses and coaches (Category D vehicles) must have speed limiters fitted and set to a maximum speed of:","options":["80 km/h","90 km/h","100 km/h","110 km/h"],"correct":2,"exp":"- Opción Correcta (C): Los limitadores de velocidad para autobuses y autocares (Categoría D) están calibrados legalmente a 100 km/h.\n- Opciones Incorrectas: (B) 90 km/h es el ajuste para vehículos de mercancías (camiones)."},{"q":"Who bears the immediate daily responsibility for conducting a pre-journey walkaround inspection of a commercial passenger vehicle?","options":["The Transport Manager","The Workshop Mechanic","The Driver","The RSA Inspector"],"correct":2,"exp":"- Opción Correcta (C): El conductor tiene la obligación diaria de revisar el vehículo (walkaround check) antes de salir a la carretera.\n- Opciones Incorrectas: (A) El gestor supervisa los sistemas globales de mantenimiento. (B) El mecánico efectúa las reparaciones."},{"q":"What does \u0027Gross Vehicle Weight\u0027 (GVW) refer to?","options":["The weight of the vehicle when empty without fuel","The maximum permissible total weight of the vehicle, including its body, payload, fuel, driver, and passengers","The total weight of the luggage compartment only","The weight exerted on the front axle only"],"correct":1,"exp":"- Opción Correcta (B): El Peso Máximo Autorizado (GVW) es la masa total máxima permitida del vehículo cargado con pasaje, carga, combustible y conductor.\n- Opciones Incorrectas: (A) Es el peso en vacío (Unladen Weight). (C y D) Son pesos parciales o de componentes."},{"q":"In Ireland, what is a primary advantage of stored-value smartcards like the TFI Leap Card for bus operators?","options":["It eliminates all vehicle maintenance costs","It reduces dwell times at bus stops and minimizes cash handling risks","It grants drivers exemption from CPC training","It allows vehicles to exceed national speed limits"],"correct":1,"exp":"- Opción Correcta (B): Las tarjetas inteligentes aceleran el proceso de cobro, reduciendo el tiempo de detención en las paradas (dwell time) y minimizando el riesgo de manejar efectivo.\n- Opciones Incorrectas: (A, C y D) No tienen ninguna relación con las tarjetas de transporte."},{"q":"In public transport operations, \u0027Cross-subsidisation\u0027 occurs when:","options":["Revenue from a profitable route is used to support an unprofitable but socially necessary route","Drivers work for two competing companies simultaneously","Fuel taxes are refunded by the government","Passengers pay for two tickets but receive three"],"correct":0,"exp":"- Opción Correcta (A): El \"subsidio cruzado\" (Cross-subsidisation) emplea las ganancias de rutas comerciales muy rentables para financiar otras líneas deficitarias de interés público.\n- Opciones Incorrectas: (B, C y D) Son conceptos ajenos al equilibrio de ingresos entre rutas."},{"q":"In passenger transport scheduling, what does the term \u0027Headway\u0027 mean?","options":["The maximum speed of a coach on a motorway","The time interval between consecutive vehicles operating on the same route","The total distance of a bus journey","The height clearance required under a bridge"],"correct":1,"exp":"- Opción Correcta (B): El \"Headway\" es la frecuencia o intervalo de tiempo transcurrido entre dos autobuses consecutivos en una misma línea.\n- Opciones Incorrectas: (A, C y D) Confunden el término de planificación con velocidad, longitud de ruta o gálibo."},{"q":"In the service marketing mix (7 Ps), which \u0027P\u0027 relates to the physical environment and tangible elements where the service is delivered?","options":["Process","People","Physical Evidence","Promotion"],"correct":2,"exp":"- Opción Correcta (C): \"Physical Evidence\" engloba todo lo tangible que el cliente ve y percibe (autobuses limpios, uniforme, diseño de la estación).\n- Opciones Incorrectas: (A) Se refiere al flujo de trabajo/procesos. (B) Es el factor humano. (D) Es la publicidad."},{"q":"Conducting a customer satisfaction survey among passengers onboard a coach is an example of:","options":["Primary market research","Secondary market research","Financial auditing","Predatory pricing"],"correct":0,"exp":"- Opción Correcta (A): Obtener información de primera mano preguntando a los clientes directos es Investigación Primaria (Primary research).\n- Opciones Incorrectas: (B) La investigación secundaria recurre a estudios previamente existentes. (C y D) Son auditorías contables o tácticas ilegales de precios."},{"q":"The Interbus Agreement governs which type of international passenger transport services between contracting states?","options":["Scheduled urban bus routes","Unscheduled (occasional) coach services","Freight transport only","Domestic cabotage in Ireland"],"correct":1,"exp":"- Opción Correcta (B): El Acuerdo Interbus rige el transporte internacional ocasional (discrecional/turístico) de pasajeros en autocar entre la UE y terceros países firmantes.\n- Opciones Incorrectas: (A) Son servicios regulares fijados. (C) Es para mercancías. (D) El cabotaje es transporte interno."},{"q":"What document must be carried on board an international coach performing an occasional service under the Interbus Agreement or EU rules?","options":["A Waybill / Journey Form (Feuille de Route) book","A Carnet de Passages","A CMR consignment note","An NTA Local Service Permit"],"correct":0,"exp":"- Opción Correcta (A): Todo viaje ocasional internacional exige llevar a bordo la Hoja de Ruta (Waybill / Feuille de Route).\n- Opciones Incorrectas: (B) Es un pasaporte aduanero de vehículos. (C) Es la carta de pago de transporte internacional de mercancías."},{"q":"When crossing an international border with customs controls, what does selecting the \u0027Red Channel\u0027 signify?","options":["Carrying no goods to declare","Carrying goods that are subject to duty, tax, or restrictions requiring declaration","Emergency medical vehicle status","Carrying zero passengers"],"correct":1,"exp":"- Opción Correcta (B): En la aduana, el Canal Rojo indica que se transportan bienes o mercancías sujetas a impuestos, aranceles o restricciones de declaración.\n- Opciones Incorrectas: (A) Corresponde al Canal Verde (Green Channel). (C y D) Son situaciones inconexas."},{"q":"Under the Package Travel Regulations, a package tour combining transport and accommodation must span a minimum duration of:","options":["12 hours","24 hours (or include overnight accommodation)","48 hours","7 days"],"correct":1,"exp":"- Opción Correcta (B): Para ser considerado legalmente \"Viaje Combinado\" (Package Tour), la oferta debe durar más de 24 horas O incluir alojamiento nocturno.\n- Opciones Incorrectas: Las excursiones de ida y vuelta en el mismo día (sin noche de hotel) están exentas de esta ley."},{"q":"Passenger cabotage carried out in another EU Member State by an Irish operator must be:","options":["Permanent and unlimited","Temporary in nature and compliant with EU rules","Fully tax-exempt in all jurisdictions","Conducted without an Operator Licence"],"correct":1,"exp":"- Opción Correcta (B): El cabotaje permite prestar servicios de transporte de viajeros en otro país de forma estrictamente temporal.\n- Opciones Incorrectas: (A) Si es permanente exige constituir empresa en ese país. (C y D) Exige contar con la Licencia Comunitaria."},{"q":"According to Irish Competition Law (enforced by the CCPC), what is \u0027predatory pricing\u0027?","options":["Charging high prices during peak holiday periods","Deliberately setting prices below cost with the intention of eliminating a competitor","Offering group discounts on weekend trips","Charging identical fares across all urban routes"],"correct":1,"exp":"- Opción Correcta (B): Los precios depredadores (Predatory pricing) consisten en vender de forma deliberada por debajo del coste operativo para expulsar o arruinar a la competencia, lo cual es un delito bajo las leyes de competencia (CCPC).\n- Opciones Incorrectas: (A) Es tarificación según demanda. (C) Es un descuento comercial legítimo. (D) Es una estructura estándar de precios."}]},
"104": { title: "Simulacro 4 - Industrial Relations, Finance \u0026 VAT", questions: [{"q":"What is the main role of the Workplace Relations Commission (WRC)?","options":["To prosecute criminal driving offences","To issue road transport operator licences","To promote and maintain good workplace practices, providing support to employers and employees","To collect Corporation Tax"],"correct":2,"exp":"La WRC se encarga de promover buenas prácticas laborales y de dar apoyo y guía tanto a empleadores como a empleados."},{"q":"Which body provides a forum for the adjudication of industrial disputes and offers resolutions for effective industrial relations?","options":["The Labour Court (LC)","The Revenue Commissioners","The Road Safety Authority (RSA)","The National Transport Authority (NTA)"],"correct":0,"exp":"El Tribunal Laboral (Labour Court) es el foro encargado de adjudicar en disputas industriales y ofrecer resoluciones y sentencias laborales."},{"q":"Within how many days must an employer provide a written statement of reasons for dismissal after receiving a valid request from a qualifying employee?","options":["7 days","14 days","21 days","30 days"],"correct":1,"exp":"Por ley, si un empleado lo solicita, el empleador tiene un plazo estricto de 14 días para entregarle por escrito los motivos de su despido."},{"q":"How many consecutive hours of daily rest is each worker entitled to within every 24-hour period under working time legislation?","options":["8 consecutive hours","9 consecutive hours","11 consecutive hours","12 consecutive hours"],"correct":2,"exp":"La normativa general de tiempo de trabajo establece un derecho mínimo de 11 horas consecutivas de descanso diario."},{"q":"What mandatory rest break must be provided to a worker scheduled for a shift lasting 6 hours or more?","options":["15 minutes","20 minutes","30 minutes","45 minutes"],"correct":2,"exp":"Un trabajador tiene derecho a una pausa obligatoria de 30 minutos cuando su turno de trabajo alcanza las 6 horas de duración."},{"q":"What is the statutory deadline for an employer to provide the full written statement of terms of employment to a new employee?","options":["Within 5 days","Within 14 days","Within 1 month","Within 6 months"],"correct":2,"exp":"Aunque los términos básicos deben darse en 5 días (Day 5 Statement), el contrato o declaración escrita completa de las condiciones laborales debe entregarse dentro del primer mes."},{"q":"Which of the following statements regarding Statutory Sick Pay (SSP) in Ireland is correct?","options":["It is payable for a maximum of 10 days per calendar year","It is payable at 100% of normal daily earnings","It requires an employee to have at least 13 weeks of continuous service","It is only applicable to managers"],"correct":2,"exp":"Para tener derecho al SSP, el trabajador debe llevar al menos 13 semanas continuas en la empresa. Actualmente se paga un máximo de 5 días al año al 70% del salario."},{"q":"What percentage of normal daily earnings is paid under Statutory Sick Pay (SSP), subject to a daily cap?","options":["50%","60%","70%","100%"],"correct":2,"exp":"El pago estatutario por enfermedad (SSP) es del 70% del salario diario normal del empleado, con un tope máximo de 110 € diarios."},{"q":"How many weeks of statutory Parent\u0027s Leave are available to each relevant parent within the first two years of a child\u0027s life?","options":["2 weeks","5 weeks","9 weeks","26 weeks"],"correct":2,"exp":"La ley otorga actualmente 9 semanas de baja parental (Parent\u0027s Leave) para cada progenitor en los primeros dos años."},{"q":"Under Irish employment legislation, how many weeks of standard statutory maternity leave are qualifying employees entitled to?","options":["16 weeks","24 weeks","26 weeks","42 weeks"],"correct":2,"exp":"La baja estándar por maternidad es de 26 semanas. (Las madres pueden solicitar 16 semanas extra no remuneradas, pero la base legal estándar son 26)."},{"q":"What is the minimum continuous service required for an employee to qualify for statutory redundancy payments?","options":["6 months","1 year","2 years","5 years"],"correct":2,"exp":"Un empleado debe tener un mínimo de 2 años de servicio continuo con el empleador para calificar para el pago legal por despido objetivo (redundancy)."},{"q":"Dismissal of an employee on what grounds is automatically deemed \u0027unfair\u0027 by the WRC, regardless of length of service?","options":["Incompetence after training","Trade union membership and activities","Redundancy through a fair selection process","Gross misconduct"],"correct":1,"exp":"Despedir a un empleado por su afiliación o actividad en un sindicato es una \"razón inadmisible\" y el despido se considera automáticamente improcedente."},{"q":"What is the maximum compensation limit if an unfairly dismissed employee incurred NO financial loss?","options":["No compensation can be awarded","1 week\u0027s remuneration","4 weeks\u0027 remuneration","10 weeks\u0027 remuneration"],"correct":2,"exp":"Si un empleado es despedido injustamente pero encuentra trabajo inmediatamente y no sufre pérdida económica, la compensación máxima es de 4 semanas de salario."},{"q":"Are employees entitled to paid time off for ante-natal care medical appointments regardless of their length of service?","options":["No, ante-natal care is entirely unpaid","No, they require at least 12 months of continuous service","Yes, all pregnant employees are entitled to paid time off regardless of length of service","Only if approved by the WRC"],"correct":2,"exp":"El derecho a tiempo libre remunerado para citas médicas prenatales (ante-natal care) aplica a todas las empleadas embarazadas desde el primer día, sin requisito de antigüedad."},{"q":"How many days of paid domestic violence leave is an employee legally entitled to take in any 12-month period?","options":["1 day","3 days","5 days","10 days"],"correct":2,"exp":"Los trabajadores tienen derecho legal a disfrutar de hasta 5 días de permiso remunerado al año por motivos de violencia de género/doméstica."},{"q":"Once an employee has completed 13 weeks of service, what is the statutory minimum notice they must give to their employer if they intend to leave?","options":["None","1 week","2 weeks","4 weeks"],"correct":1,"exp":"El empleado solo está obligado legalmente a dar 1 semana de preaviso para renunciar, y este plazo no aumenta independientemente de cuántos años lleve en la empresa."},{"q":"An employee has 15 years of continuous service. What is the statutory minimum notice period the employer must give them before termination?","options":["2 weeks","4 weeks","6 weeks","8 weeks"],"correct":3,"exp":"Según la escala de preavisos, los empleados con 15 años o más de servicio tienen derecho a un preaviso mínimo de 8 semanas por parte de la empresa."},{"q":"What is the maximum permitted working week for employees, averaged out over a 4-month period?","options":["39 hours","40 hours","48 hours","56 hours"],"correct":2,"exp":"La Directiva de Tiempo de Trabajo marca un máximo legal de 48 horas semanales de trabajo en promedio (normalmente calculado en un periodo de referencia de 4 meses)."},{"q":"Under Industrial Action rules, how soon must industrial action be commenced after the date of the ballot?","options":["Within 1 week","Within 2 weeks","Within 4 weeks","Within 6 months"],"correct":2,"exp":"Una vez que el sindicato realiza la votación (ballot), la huelga o acción industrial debe iniciarse obligatoriamente dentro de las siguientes 4 semanas."},{"q":"Which of the following is legally entitled to picket at the premises of an employer other than their own?","options":["Any member of the main trade union","A trade union official accompanying employees from that workplace","A trade union member from a different works in the same town","Anyone who sympathizes with the strike"],"correct":1,"exp":"Los piquetes solo pueden hacerse cerca del lugar de trabajo propio. Sin embargo, los funcionarios del sindicato (union officials) tienen permiso para acompañar a sus miembros en las líneas de piquete."},{"q":"What does \u0027Cash Flow\u0027 specifically measure in a business?","options":["The depreciation of fixed assets over time","Money received into and paid out by a business","The market share of the company","The number of active bank accounts"],"correct":1,"exp":"El flujo de caja (Cash Flow) mide exclusivamente el dinero que entra (ingresos) y el dinero que sale (pagos) de una empresa."},{"q":"What is \u0027Debt Factoring\u0027?","options":["Buying vehicles on a hire purchase agreement","A way of improving immediate cash flow by selling invoices to a bank or factoring organization","Declaring bankruptcy to avoid paying creditors","Calculating the interest rate on a bank loan"],"correct":1,"exp":"El factoraje de deuda consiste en \"vender\" tus facturas pendientes de cobro a una entidad financiera para conseguir dinero en efectivo de manera inmediata y mejorar el flujo de caja."},{"q":"A transport manager budgets £6,150 for tyres, but the actual cost is £6,500. How is the percentage variance calculated?","options":["Budgeted amount divided by actual cost","Variance divided by budgeted amount x 100","Actual cost multiplied by budgeted amount","Variance divided by actual cost x 100"],"correct":1,"exp":"La fórmula para calcular la variación porcentual del presupuesto es: (Variación / Cantidad Presupuestada) x 100."},{"q":"In the marketing mix, the \u00274 core Ps\u0027 stand for:","options":["Package, Price, Presentation, People","Product, Price, Place, Promotion","Product, Performance, Place, Profit","Price, Process, Promotion, Public Relations"],"correct":1,"exp":"Los cuatro elementos centrales del marketing mix clásico son: Producto (el servicio ofrecido), Precio, Plaza o Lugar (Place) y Promoción."},{"q":"Marketing objectives should be SMART. What does \u0027SMART\u0027 stand for?","options":["Specific, Measurable, Achievable, Relevant, Time-bound","Sales, Marketing, Advertising, Research, Targeting","Simple, Modern, Attractive, Reliable, Tangible","Strategic, Meaningful, Actionable, Realistic, Timely"],"correct":0,"exp":"SMART es un acrónimo para definir objetivos eficaces: Specific (Específico), Measurable (Medible), Achievable (Alcanzable), Relevant (Relevante) y Time-bound (Limitado en el tiempo)."},{"q":"Which of the following is a method of gathering \u0027Primary data\u0027 for market research?","options":["Reading government statistics","Reviewing old company reports","Conducting personal and telephone interviews","Looking at trade directories"],"correct":2,"exp":"Los datos primarios son aquellos que recopilas tú mismo de primera mano. Las entrevistas personales, telefónicas o encuestas directas son métodos de investigación primaria."},{"q":"What is the standard rate of VAT applicable to most goods and services in Ireland?","options":["9%","13.5%","21%","23%"],"correct":3,"exp":"El impuesto sobre el valor añadido (VAT/IVA) general para la mayoría de los bienes y servicios en Irlanda es del 23%."},{"q":"At what turnover threshold for the supply of SERVICES is VAT registration compulsory in Ireland?","options":["€10,000","€37,500","€42,500","€85,000"],"correct":2,"exp":"El umbral obligatorio para registrarse en el IVA si tu empresa provee servicios (como el transporte de pasajeros) es facturar más de 42,500 €."},{"q":"If an Irish transport operator provides an international journey for a business customer based in another EU country, what is the correct VAT procedure?","options":["Charge VAT at the standard Irish rate","No VAT is charged; the customer organises VAT payment in their own country","Charge VAT at 0% and pay it to the Irish Revenue","The Irish operator must register for VAT in the customer\u0027s country"],"correct":1,"exp":"En operaciones B2B transfronterizas dentro de la UE, no se cobra el IVA en la factura. El cliente europeo aplica el mecanismo de \"autoliquidación\" y declara el IVA en su propio país."},{"q":"For how long must VAT records be kept by a business?","options":["At least 1 year","At least 3 years","At least 6 years","Indefinitely"],"correct":2,"exp":"La Agencia Tributaria (Revenue) exige que todos los registros y libros contables relacionados con el IVA se conserven durante un mínimo de 6 años."},{"q":"Which Irish motorway operates a barrier-free electronic toll system (eFlow)?","options":["M1 (Gormanston)","M4 (Kilcock)","M50 Orbital Motorway","M8 (Rathcormac)"],"correct":2,"exp":"La autopista M50 de Dublín es famosa por su sistema eFlow, que no tiene barreras físicas y lee las matrículas o etiquetas electrónicas de los vehículos sin que deban detenerse."},{"q":"On the Dublin Port Tunnel, how are Heavy Goods Vehicles (HGVs) tolled?","options":["They pay peak hour rates only","They are permitted to use the tunnel toll-free at all times","They pay a flat rate of €10","They cannot use the tunnel"],"correct":1,"exp":"Para aliviar la congestión del tráfico en la ciudad, los vehículos de mercancías pesadas (HGVs) tienen permitido el uso del túnel del puerto de Dublín de manera gratuita a todas horas."},{"q":"Which of the following is one of the four main criteria required to hold a Road Passenger Transport Operator Licence?","options":["Good Repute","Minimum fleet size of 10 vehicles","100% Market Share","Registration as a Public Limited Company"],"correct":0,"exp":"Los cuatro pilares para tener la licencia de operador son: Buena Honorabilidad (Good Repute), Capacidad Financiera (Financial Standing), Competencia Profesional y un Establecimiento real en Irlanda."},{"q":"When assessing an operator\u0027s \u0027Good Repute\u0027, the Minister will consider convictions relating to serious offences within what time frame?","options":["The previous 1 year","The previous 3 years","The previous 5 years","The previous 10 years"],"correct":2,"exp":"Para mantener la buena reputación, el Ministerio revisará si el operador o gestor ha cometido infracciones graves en los últimos 5 años."},{"q":"To meet the \u0027Financial Standing\u0027 requirement, how much reserves must an operator demonstrate for their first vehicle?","options":["€1,500","€5,000","€9,000","€15,000"],"correct":2,"exp":"La capacidad financiera exige demostrar un colchón económico de 9,000 € para el primer vehículo autorizado."},{"q":"To meet the \u0027Financial Standing\u0027 requirement, how much reserves must an operator demonstrate for EACH ADDITIONAL vehicle after the first?","options":["€2,000","€3,000","€5,000","€9,000"],"correct":2,"exp":"Por cada autobús adicional que se añada a la licencia (después del primero), la empresa debe demostrar 5,000 € adicionales de reservas financieras."},{"q":"If a driver receives a serious conviction while employed, what are their obligations regarding the operator?","options":["They must resign immediately","They must disclose the conviction to the operator","They do not need to say anything unless asked by the Gardaí","They must pay a fine to the transport manager"],"correct":1,"exp":"Las normas de Buena Reputación exigen que el conductor informe (divulgue) obligatoriamente a su empleador (el operador) si recibe una condena seria."},{"q":"Within how many days must an employer notify a new employee of their core terms of employment (like job title and pay) via the \u0027Day 5 Statement\u0027?","options":["Within 1 day","Within 5 days of commencement","Within 14 days","Within 1 month"],"correct":1,"exp":"Como su propio nombre indica, los 5 términos principales básicos del contrato deben entregarse por escrito dentro de los primeros 5 días de trabajo."},{"q":"What is the minimum threshold of proposed redundancies over a 30-day period that triggers collective redundancy rules in an establishment of 50 to 99 employees?","options":["5 or more redundancies","10 or more redundancies","20 or more redundancies","30 or more redundancies"],"correct":1,"exp":"En una plantilla de entre 50 y 99 trabajadores, planificar 10 o más despidos en un plazo de 30 días activa las leyes de consulta por despido colectivo."},{"q":"For how many minimum days must an employer engage in an information and consultation process with employee representatives during collective redundancies?","options":["14 days","21 days","30 days","60 days"],"correct":2,"exp":"Si se activa un despido colectivo, la empresa está obligada por ley a abrir un periodo mínimo de 30 días de consulta e información con los representantes sindicales o de los trabajadores antes de hacer efectivo ningún despido."}]},
"105": { title: "Simulacro 5 - Costing, Tachographs \u0026 Timetabling", questions: [{"q":"An operator buys a new vehicle for €90,000. The value of the original tyre equipment is €2,500. The vehicle has an expected life of 5 years and an estimated residual value of €22,500. If the reducing balance method of depreciation is used at a rate of 20%, the amount allocated for depreciation in the first year of the vehicle\u0027s life will be:","options":["€20,000","€18,000","€17,500","€13,000"],"correct":2,"exp":"Para calcular la depreciación del vehículo, primero debes restar el coste de los neumáticos originales (ya que los neumáticos son un coste de rodaje variable, no un activo fijo). €90,000 - €2,500 = €87,500. El 20% de €87,500 es €17,500."},{"q":"An operator has annual standing costs of €60,000, running costs of 40 cents per kilometre and a profit mark up on costs of 20%. A customer has asked the operator to quote an \"all in\" price per kilometre covering 50,000 kilometres per year. What price per kilometre should the operator quote?","options":["€1.92","€1.60","€1.48","€1.20"],"correct":0,"exp":"1. Coste fijo por km = €60,000 / 50,000 km = €1.20 por km.\n2. Coste total por km = €1.20 (fijo) + €0.40 (variable/running) = €1.60.\n3. Margen de beneficio (20%) = 20% de €1.60 = €0.32.\n4. Precio a presupuestar = €1.60 + €0.32 = €1.92."},{"q":"Which of the following vehicle costs are both direct and fixed?\n1. Vehicle Tax 2. Lubricants 3. Insurance 4. Tyres 5. Maintenance","options":["1 and 3 only","2 and 5 only","1, 4 and 5 only","2, 3 and 4 only"],"correct":0,"exp":"El impuesto de circulación (Tax) y el seguro (Insurance) son costes fijos (se pagan por tiempo, no por uso) y directos (se asignan a un vehículo concreto). Los lubricantes, neumáticos y mantenimiento son costes variables (running costs)."},{"q":"Under the Road Passenger Transport Operator Licensing system, a vehicle is classified as a Public Service Vehicle (PSV) if it is operated for hire and reward and carries how many passengers?","options":["5 or more passengers","8 or more passengers, not including the driver","12 or more passengers","16 or more passengers"],"correct":1,"exp":"Un vehículo requiere licencia de PSV y de operador cuando transporta a 8 o más pasajeros (sin contar al conductor) con fines comerciales (hire and reward)."},{"q":"A Large Public Service Vehicle (LPSV) Licence issued by the PSV Officer of An Garda Síochána is valid for what period?","options":["1 year","2 years","3 years","5 years"],"correct":2,"exp":"La licencia de vehículo LPSV expedida por la Garda Síochána tiene una validez de 3 años. (No confundir con la Licencia de Operador de la empresa, que dura 5 años)."},{"q":"What specific licence is required to operate a regular public passenger service between specified terminals or a specified route?","options":["A standard Community Licence only","A Public Bus Passenger Service Licence issued by the National Transport Authority (NTA)","An Interbus authorisation","A CVRT Certificate"],"correct":1,"exp":"Para operar una ruta regular nacional (con horarios y terminales fijas) en Irlanda, se necesita una licencia de servicio público de autobús expedida por la NTA."},{"q":"Operators must download/copy data from their drivers\u0027 digital tachograph cards at intervals not exceeding:","options":["14 days","21 days","28 days","90 days"],"correct":2,"exp":"La normativa europea exige que los datos de la tarjeta digital del conductor se descarguen como máximo cada 28 días para evitar la pérdida o sobrescritura de información de conducción."},{"q":"If the digital tachograph breaks down on a journey, it must be repaired \u0027en route\u0027 if the vehicle is unable to return to its base within:","options":["2 days of the breakdown","5 days of the breakdown","1 week of the breakdown","2 weeks of the breakdown"],"correct":2,"exp":"La ley permite un plazo máximo de 1 semana. Si el vehículo no puede regresar a su base en el plazo de una semana desde que el tacógrafo se averió, debe ser reparado en ruta en un taller autorizado."},{"q":"Digital tachographs must be recalibrated at intervals of not more than:","options":["1 year","2 years","5 years","6 years"],"correct":1,"exp":"Todos los tacógrafos instalados en vehículos comerciales deben ser inspeccionados y recalibrados por un taller homologado cada 2 años."},{"q":"A company card to be used in connection with digital tachographs has a maximum validity of:","options":["1 year","2 years","3 years","5 years"],"correct":3,"exp":"Al igual que la tarjeta del conductor, la tarjeta de empresa (Company Card) que se inserta en el tacógrafo para bloquear y descargar datos tiene una validez de 5 años."},{"q":"When asked by an Irish enforcement official at the roadside, drivers using an analogue or digital tachograph must be able to produce records for the current day and how many preceding days?","options":["7 days","15 days","21 days","28 days"],"correct":3,"exp":"Por ley, el conductor debe poder mostrar los registros de conducción (discos analógicos, tarjeta digital o impresiones) del día en curso y de los 28 días naturales anteriores."},{"q":"Under EU Regulation 165/2014, operators are legally obliged to retain completed tachograph records (charts and digital data) at their premises for at least:","options":["6 months","12 months","2 years","3 years"],"correct":1,"exp":"Las empresas de transporte deben conservar los registros del tacógrafo (discos analógicos y descargas digitales) en orden cronológico durante un mínimo de 12 meses (1 año) tras su uso."},{"q":"Which document permits a coach to travel at up to 100 km/h on motorways in Germany?","options":["Community Licence","Vitesse 100 certificate","Eurovignette","Tempo 100 certificate"],"correct":3,"exp":"El certificado \"Tempo 100\" es la homologación técnica alemana que autoriza a un autobús a circular a 100 km/h por sus autopistas (el límite general para buses pesados suele ser 80 km/h sin este certificado)."},{"q":"In many European countries, the typical speed limit for commercial vehicles in built-up (urban) areas is:","options":["30 km/h","40 km/h","50 km/h","60 km/h"],"correct":2,"exp":"Como norma general armonizada en Europa, el límite de velocidad estándar en zonas urbanizadas o poblados es de 50 km/h."},{"q":"Which statement best summarises Irish motorway speed limits for the listed vehicle types?","options":["All buses and coaches are limited to 100 km/h","All goods vehicles are limited to 80 km/h","Vehicles towing are limited to 80 km/h","Standing passenger buses may travel at 90 km/h"],"correct":0,"exp":"En Irlanda, los autobuses y autocares (vehículos de pasajeros de categoría D) tienen un límite máximo legal de velocidad en autopista de 100 km/h."},{"q":"On which of the following pieces of Irish road infrastructure are charges made to road haulage and commercial vehicles via a barrier-free electronic system?","options":["M1 Motorway","Dublin Port Tunnel","M50 Motorway","Limerick Tunnel"],"correct":2,"exp":"La autopista M50 en Dublín utiliza el sistema eFlow, un sistema de peaje electrónico sin barreras físicas que lee las matrículas o etiquetas."},{"q":"Assessment of a company\u0027s corporation tax is based on which of the following?","options":["Adjusted net profit","Capital gains","Fixed assets","Adjusted gross profit"],"correct":0,"exp":"El impuesto de sociedades (Corporation Tax) del 12.5% en Irlanda se aplica sobre los beneficios netos ajustados (Adjusted net profit) tras aplicar las deducciones y gastos permitidos por ley."},{"q":"Which document is essential for international bus or coach services within the EU?","options":["National Transport Authority permit","Community Licence","CVRT certificate","Driver CPC card"],"correct":1,"exp":"La Licencia Comunitaria es el documento base que otorga el derecho de acceso al mercado europeo y permite realizar transportes internacionales de pasajeros en la UE."},{"q":"Which type of passenger service normally requires an EU route authorisation?","options":["Occasional service","Special regular service under contract","Regular scheduled service","Private non commercial transport"],"correct":2,"exp":"Los servicios regulares internacionales (los que siguen una ruta, calendario y paradas fijas para el público) necesitan una autorización de ruta específica de la UE, además de la Licencia Comunitaria."},{"q":"Cabotage in passenger transport is best described as:","options":["Permanent domestic passenger services in another Member State","Limited passenger services carried out within another Member State under EU rules","Own account passenger transport","Domestic services within Ireland only"],"correct":1,"exp":"El cabotaje permite a un transportista extranjero realizar servicios de transporte nacional de manera temporal dentro de las fronteras de otro Estado miembro."},{"q":"\"Closed Door Tours\" must be completed within a time limit of no more than:","options":["21 days","30 days","60 days","90 days"],"correct":1,"exp":"En el transporte internacional, los circuitos a puerta cerrada (el mismo autobús lleva al mismo grupo todo el viaje) tienen una duración máxima legal estipulada de 30 días."},{"q":"What type of passenger fare scale does the following represent? (Distance increases, but the cost per km decreases incrementally)","options":["Standard fare scale","Zonal fare scale","Flat fare scale","Tapered fare scale"],"correct":3,"exp":"Una tarifa \"tapered\" (decreciente) significa que, aunque el billete total es más caro, el coste cobrado al pasajero por cada kilómetro adicional va disminuyendo a medida que el viaje es más largo."},{"q":"As a deterrent to fraudulent use, which one of the following is likely to be the most secure system of pre-paid tickets?","options":["Uniquely numbered tickets and matching numbered photocards","Uniquely numbered tickets and unnumbered photocards","Unnumbered tickets and uniquely numbered photocards","Unnumbered tickets and unnumbered photocards"],"correct":0,"exp":"Emparejar un número único en el abono o billete con el mismo número único en la tarjeta de identidad fotográfica del pasajero evita que varias personas compartan fraudulentamente el mismo pase."},{"q":"In a gross cost (supply side) tendering system, the fares are set by the:","options":["Office of Fair Trading","Operator","Tendering Authority","Traffic Warden"],"correct":2,"exp":"En un contrato de licitación de \"coste bruto\" (gross cost), la Autoridad Licitadora (ej. NTA) asume el riesgo de los ingresos, fija el precio de los billetes y se queda con la recaudación, pagando al operador una cantidad fija por proveer el autobús y el conductor."},{"q":"An operator is proposing to run a local bus service that has a single journey time of 40 minutes, and will have five minutes stand time at each end of the route. How many vehicles will be required for the service, if the frequency (headway) is every five minutes?","options":["9 vehicles","10 vehicles","18 vehicles","20 vehicles"],"correct":2,"exp":"1. Tiempo del viaje de ida = 40 min + 5 min de espera = 45 min.\n2. Ida y vuelta (Round trip) = 45 + 45 = 90 minutos.\n3. Frecuencia exigida = 1 autobús cada 5 minutos.\n4. Total de buses = 90 / 5 = 18 vehículos."},{"q":"Interworking is the name given to which of the following activities?","options":["Using a driver to cover more than one route","Using a vehicle to cover more than one route","Two or more operators providing vehicles for one route","Two or more operators providing drivers for one route"],"correct":1,"exp":"El \"Interworking\" en la planificación de flotas (timetabling) consiste en asignar un mismo autobús para que cubra más de una ruta distinta a lo largo del día, maximizando su uso."},{"q":"If a local bus service has a single journey time of 40 minutes, with stand time at each end of five minutes, which one of the following frequencies (headways) will make the best use of resources, without extending the standing time?","options":["Every 20 minutes","Every 25 minutes","Every 30 minutes","Every 40 minutes"],"correct":2,"exp":"El viaje redondo (Round Trip) dura 90 minutos. Para que los recursos cuadren perfectamente sin tiempos muertos, la frecuencia debe ser un divisor exacto del viaje redondo. 90 dividido entre 30 minutos = 3 autobuses rotando perfectamente. (90 no se divide de forma exacta por 20, 25 ni 40)."},{"q":"The WRC has the power to hear cases connected with which of the following work-place issues?\n1. Employees\u0027 rights to time off work to carry out trade union duties\n2. Alleged discrimination on the basis of sexual orientation\n3. PAYE contributions\n4. Failure to report an accident to the HSA\n5. Equal pay complaints","options":["1 and 4 only","2 and 3 only","1, 2 and 5 only","3, 4 and 5 only"],"correct":2,"exp":"La Workplace Relations Commission (WRC) juzga casos de derechos sindicales, discriminación e igualdad salarial. (Los problemas de PAYE son de Hacienda/Revenue, y no reportar a la HSA es un delito de seguridad y salud, no laboral de la WRC)."},{"q":"What is the legal definition of \u0027night work\u0027 under Irish working time regulations?","options":["Work performed on weekends and public holidays","Work done between midnight and 7:00 AM","Work done between 8:00 PM and 4:00 AM","Any shift exceeding 10 hours in length"],"correct":1,"exp":"La ley irlandesa de tiempo de trabajo define estrictamente el \"trabajo nocturno\" como aquel que se realiza entre la medianoche (12:00 AM) y las 7:00 AM."},{"q":"How many statutory public holidays are employees in Ireland generally entitled to receive?","options":["7 public holidays","9 public holidays","10 public holidays","12 public holidays"],"correct":2,"exp":"Tras la introducción del festivo de St Brigid\u0027s Day en 2023, los trabajadores en Irlanda tienen derecho legal a 10 días festivos públicos remunerados al año."},{"q":"What is the maximum duration generally permitted for successive fixed-term contracts before objective justification is required?","options":["1 year","2 years","4 years","5 years"],"correct":2,"exp":"Para evitar el abuso, la ley limita el encadenamiento de contratos temporales sucesivos a un máximo de 4 años. Tras ese periodo, el contrato se considera indefinido (salvo justificación objetiva)."},{"q":"Changes to an employee\u0027s terms and conditions of employment must be confirmed in writing by the employer no later than:","options":["1 month before the changes come into effect","No later than the date of when the changes come into effect","3 months of when the changes come into effect","4 months of when the changes come into effect"],"correct":1,"exp":"Si se modifican las condiciones del contrato, el empleador debe notificarlo por escrito como muy tarde el mismo día en que dichos cambios entren en vigor."},{"q":"What are the sequential stages of the product life cycle in marketing?","options":["Introduction, Expansion, Peak, Decline","Design, Testing, Launch, Retirement","Development, Growth, Maturity, Saturation, Decline","Growth, Maturity, Profit, Loss"],"correct":2,"exp":"El ciclo de vida de un servicio o producto tiene 5 etapas formales en marketing: Desarrollo (Development), Crecimiento (Growth), Madurez (Maturity), Saturación (Saturation) y Declive (Decline)."},{"q":"Why is a \u0027pilot study\u0027 conducted prior to launching a full market research survey?","options":["To calculate the company\u0027s annual profit and loss account","To test questions and format on a small sample to remove misunderstandings and ensure the survey works","To train drivers in vehicle maintenance","To register the company with the Companies Registration Office"],"correct":1,"exp":"Un estudio piloto es un \"ensayo\" que se hace con un grupo pequeño de personas para comprobar que las preguntas de la encuesta se entienden bien antes de gastar dinero en lanzarla masivamente."},{"q":"How is marketing officially defined in business management?","options":["The administration of transport logistics and routing","The management process responsible for identifying, anticipating and satisfying customer requirements profitably","The process of maximizing retail prices","The department responsible for filing tax returns with Revenue"],"correct":1,"exp":"La definición clásica del Chartered Institute of Marketing (CIM) establece que el marketing es el proceso de gestión que identifica, anticipa y satisface las necesidades del cliente de forma rentable."},{"q":"What does SEO stand for in the context of digital marketing for transport operators?","options":["Social Employee Organisation","Secure Earnings Operation","Search Engine Optimisation","Standard Economic Outlay"],"correct":2,"exp":"SEO (Search Engine Optimisation) son las técnicas utilizadas para que la página web de la empresa de transporte aparezca lo más arriba posible en los resultados gratuitos de Google u otros buscadores."},{"q":"A driver has been employed by the Ace Transport Company for 15 years. How much notice must they give AS A MINIMUM if they wish to leave to take up another job?","options":["None","One week","Twelve weeks","Fifteen weeks"],"correct":1,"exp":"Atención al enunciado: pregunta cuánto preaviso debe dar EL CONDUCTOR (empleado) para irse. La ley exige un mínimo de 1 semana para el empleado, sin importar cuántos años lleve trabajando. (Las 8 o más semanas aplicarían si fuera la empresa la que lo despidiera)."},{"q":"Under the general Working Time Regulations, what is the maximum average weekly working hours limit for non-driving employees?","options":["39 hours","40 hours","48 hours","56 hours"],"correct":2,"exp":"La Directiva Europea y la ley irlandesa establecen que la semana laboral no debe superar un promedio de 48 horas."},{"q":"Jack Smith has worked for Bloggs Limited for ten years. Bloggs Limited is then bought by Lax Transport plc. With regard to the legal provisions concerning continuous employment (TUPE), Jack\u0027s service will be calculated from when:","options":["Lax Transport took control","Bloggs Limited was officially removed from the register","Lax Transport issued him with a new contract","He started work for Bloggs Limited"],"correct":3,"exp":"Bajo la normativa TUPE (Transfer of Undertakings), cuando una empresa es comprada por otra, los empleados mantienen todos sus derechos y su antigüedad se sigue contando desde el primer día que empezaron en la empresa original."},{"q":"Under Irish statutory provisions, Statutory Sick Pay (SSP) requires employers to pay sick pay for a maximum of how many days per calendar year?","options":["3 days","5 days","7 days","10 days"],"correct":1,"exp":"Actualmente, el límite legal de pago por baja por enfermedad a cargo de la empresa (SSP) está fijado en 5 días por año natural."}]},
"106": { title: "Simulacro 6 - Operator \u0026 Driver Licensing (+ repaso)", questions: [{"q":"For what period is a Road Passenger Transport Operator Licence normally valid?","options":["3 years","5 years","Indefinitely","10 years"],"correct":1,"exp":"La licencia de Operador de Transporte de Pasajeros por Carretera es válida normalmente por un periodo de 5 años."},{"q":"Where a Transport Manager ceases to act in that role for a road passenger transport undertaking, what is the maximum period allowed for the undertaking to appoint a new Transport Manager?","options":["1 year","3 months","1 month","6 months"],"correct":3,"exp":"Si el Gestor de Transporte deja de ejercer sus funciones, la autoridad competente puede conceder a la empresa un periodo de gracia de un máximo de 6 meses para nombrar a un sustituto."},{"q":"In the case of a contracted Transport Manager, certain restrictions apply regarding the total number of undertakings and vehicles that he/she is allowed to manage. Which one of the following describes these restrictions?","options":["4 transport undertakings with a maximum combined fleet of 50 vehicles","2 transport undertakings with a maximum combined fleet of 50 vehicles","4 transport undertakings with a maximum combined fleet of 100 vehicles","5 transport undertakings with a maximum combined fleet of 100 vehicles"],"correct":0,"exp":"Un gestor de transporte externo (contratado) está limitado por ley a gestionar un máximo de 4 empresas de transporte, cuya flota combinada no supere los 50 vehículos."},{"q":"Which one of the following is exempt from the requirement to have a Road Passenger Transport Operator Licence for national operations?","options":["Transport for hire or reward of school students","Private hire transport for one-off events","Transport for hire or reward of passengers to charity events","Transport of employees to or from work in vehicles owned by their employers"],"correct":3,"exp":"El transporte de empleados hacia o desde el trabajo en vehículos que son propiedad de su propio empleador (transporte por cuenta propia) está exento de requerir licencia de operador."},{"q":"To obtain a National or International Road Passenger Transport Operator Licence, an applicant must satisfy four main criteria. These are Professional Competence, a Stable and Effective Establishment, Financial Standing, and:","options":["Good Repute","Minimum 10 years of driving experience","Public Limited Company status","A fleet of at least 5 buses"],"correct":0,"exp":"Los cuatro pilares exigidos por la UE para obtener la licencia son: Buena Honorabilidad (Good repute), Capacidad Financiera, Competencia Profesional y un Establecimiento estable y efectivo."},{"q":"When determining if an operator satisfies the requirement of \u0027Good Repute\u0027, the Minister will generally consider offences and convictions that occurred within the previous:","options":["1 year","3 years","5 years","10 years"],"correct":2,"exp":"Para evaluar la buena reputación, el Ministerio revisa si el operador o gestor ha sido condenado por infracciones graves en los últimos 5 años."},{"q":"In relation to \u0027Hire or Reward\u0027, if an employer operates a bus to convey staff to work and deducts money from their pay for this service, how is this classified?","options":["Free travel exemption","Private non-commercial transport","Operating for hire and reward, requiring a PSV licence if over 8 passenger seats","A charity operation"],"correct":2,"exp":"Si el empleador deduce dinero del salario de los trabajadores para el transporte, el servicio pasa a considerarse \"alquiler o recompensa\" (Hire or Reward). Si el vehículo tiene más de 8 asientos, requerirá licencia PSV."},{"q":"An operator of a public scheduled service wishing to change a registered service timetable for holiday periods (e.g., Bank Holidays) must:","options":["Inform the passengers only","Inform the National Transport Authority (NTA) in advance","Inform the Garda Síochána","Pay a holiday tax to the Revenue Commissioners"],"correct":1,"exp":"Cualquier modificación en los horarios de las rutas regulares por motivos de festivos debe ser notificada y aprobada por la National Transport Authority (NTA) con antelación."},{"q":"Under the Public Transport Regulation Act 2009, which body is responsible for licensing commercial bus services, addressing routes, stopping places, and service frequency?","options":["The Road Safety Authority (RSA)","Local County Councils","The National Transport Authority (NTA)","The Department of Transport"],"correct":2,"exp":"La NTA es la autoridad oficial en Irlanda encargada de otorgar las licencias para los servicios comerciales de autobuses y de regular sus rutas y paradas."},{"q":"To demonstrate a \u0027Stable and Effective Establishment\u0027, an operator must have a fixed place of business in Ireland, suitable operating premises, core business documents retained there, and:","options":["A minimum of 3 directors","Availability of at least one compliant vehicle (taxed, insured, and roadworthy)","A registered trademark","A mechanical workshop on-site"],"correct":1,"exp":"Para cumplir el requisito de establecimiento, la empresa debe contar con al menos un vehículo que cumpla todas las normativas (impuestos, seguro, ITV) a su disposición."},{"q":"What is a key distinguishing feature of \u0027Public Scheduled Coach Operators\u0027 compared to private hire?","options":["They can only transport tourists","Their services are open to all members of the public for a fare on a regular, published basis","They do not require a Road Passenger Transport Operator License","They only operate during the summer"],"correct":1,"exp":"Los servicios regulares públicos se diferencian en que están abiertos a todo el público en general, siguen un horario publicado y requieren una licencia específica de ruta de la NTA."},{"q":"In international passenger transport, excursions that carry passengers from one or more places and back generally operate:","options":["Only with a regular service route licence","Without any formalities, based purely on passenger bookings","Exclusively under bilateral treaties with non-EU countries","With a mandatory Garda escort"],"correct":1,"exp":"La gran mayoría de excursiones y tours ocasionales se operan sin grandes formalidades; el operador los anuncia y, en función de las reservas, realiza o cancela el viaje."},{"q":"Which of the following is typically required when taxing a commercial goods or passenger vehicle in Ireland?\n1. Vehicle Registration Certificate 2. Goods-only / PSV declaration 3. A valid insurance certificate 4. Certificate of Roadworthiness (CVRT) where required","options":["1 only","2 and 3 only","1, 2 and 3 only","1, 2, 3, and 4"],"correct":3,"exp":"Para pagar el impuesto de circulación (Motor Tax) de un vehículo comercial, se exigen todos esos documentos: Certificado de registro, declaración de uso, seguro válido y la ITV (CVRT) en vigor."},{"q":"Commercial vehicles over one year old must generally undergo:","options":["Annual Commercial Vehicle Roadworthiness Testing (CVRT)","A driving test every two years","Emissions testing only, with no roadworthiness certificate","No testing requirements once the vehicle is insured"],"correct":0,"exp":"Todos los vehículos comerciales pesados o de pasajeros (autobuses) con más de un año de antigüedad están obligados por ley a pasar la inspección CVRT anualmente."},{"q":"A Category D1 driving licence entitlement allows the holder to drive Passenger Carrying Vehicles (PCVs) having:","options":["No more than 8 passenger seats","More than 8 but not more than 16 passenger seats","Up to 30 passenger seats","Any number of passenger seats"],"correct":1,"exp":"La categoría D1 es una subcategoría específica para minibuses que permite transportar a más de 8 pasajeros, pero con un límite máximo de 16 asientos."},{"q":"Under EU rules, what is the standard minimum age at which a driver may obtain a full Category D entitlement (without CPC exemptions for restricted routes)?","options":["18","21","24","25"],"correct":2,"exp":"La edad estándar para obtener el carnet completo de autobús (Categoría D) es 24 años. (Puede rebajarse a 21 si se posee el CPC y se limita a rutas regulares de menos de 50 km)."},{"q":"When is a \"+E\" entitlement required to be added to a Category D or D1 driving licence?","options":["Whenever luggage is carried in the side lockers","If the driver wishes to tow a trailer exceeding 750kg Maximum Authorised Mass (MAM)","When driving at night","When crossing international borders"],"correct":1,"exp":"El permiso \"+E\" (ej. D+E) solo es obligatorio si se va a remolcar un tráiler pesado cuyo peso máximo autorizado (MAM) exceda los 750 kg."},{"q":"A driver who passed their Category B (car) test AFTER 1 January 1997 may drive a minibus with 9-16 seats on that entitlement ONLY IF specific conditions are met. Which of the following is ONE of those conditions?","options":["The vehicle is used for hire and reward","The driver is under 21 years of age","The vehicle is used by a non-commercial body for social purposes","The GVW of the vehicle exceeds 4,250kg without specialist equipment"],"correct":2,"exp":"Los conductores con carnet de coche posterior a 1997 pueden conducir minibuses de hasta 16 plazas de forma excepcional si es para uso social no comercial, tienen más de 21 años, 2 años de experiencia y el vehículo pesa menos de 3.500 kg."},{"q":"Which one of the following is a core Transport Manager responsibility relating to vehicle taxation?","options":["Repairing the suspension units personally","Monitoring expiry dates for motor tax, insurance and roadworthiness certification","Testing drivers\u0027 eyesight","Designing the company website"],"correct":1,"exp":"Es responsabilidad directa del Gestor de Transporte llevar el control de las fechas de caducidad de impuestos, seguros e inspecciones técnicas para garantizar que la flota sea siempre legal."},{"q":"In Ireland, the term \"separate fares\" covers payments made by individual passengers even if not made directly to the driver. Vehicles of 8 passenger seats or less can be used at separate fares (exempt from full PSV licensing) PROVIDED THAT:","options":["They pick up passengers randomly at bus stops","Passengers book in advance and all agree to share the cost","The journey is under 10 kilometres","The vehicle is a tractor"],"correct":1,"exp":"Un coche o furgoneta de hasta 8 plazas puede cobrar a los pasajeros por separado sin ser considerado un servicio público de bus regular SOLO si todos los pasajeros reservan con antelación y acuerdan compartir el coste del viaje."},{"q":"The basic category of driving entitlement for driving large PCVs (buses/coaches with over 16 seats) is:","options":["Category B","Category C","Category D","Category D1"],"correct":2,"exp":"La Categoría D es el carnet fundamental y general para conducir vehículos grandes de transporte de pasajeros sin límite de asientos."},{"q":"What does \u0027Cash Flow\u0027 specifically measure in a business?","options":["The depreciation of fixed assets over time","Money received into and paid out by a business","The market share of the company","The number of active bank accounts"],"correct":1,"exp":"El flujo de caja (Cash Flow) mide el dinero real que entra (ingresos) y el dinero real que sale (pagos) de una empresa en un periodo de tiempo."},{"q":"What is the primary advantage of debt factoring for a transport operator?","options":["It eliminates the need to pay Corporation Tax","It provides immediate cash flow by selling unpaid invoices to a third party","It guarantees 100% profit margins on all routes","It reduces vehicle depreciation rates"],"correct":1,"exp":"El factoraje permite obtener liquidez inmediata vendiendo las facturas pendientes a una entidad financiera, en lugar de esperar a que el cliente pague."},{"q":"Under the Organization of Working Time Act, what is the maximum average weekly working hours limit for employees?","options":["39 hours","40 hours","48 hours","60 hours"],"correct":2,"exp":"La ley irlandesa establece que el tiempo de trabajo semanal medio (incluyendo todas las tareas laborales, no solo conducir) no puede superar las 48 horas."},{"q":"Under EU Regulation 561/2006, after how many hours of continuous driving must a driver take an uninterrupted break of at least 45 minutes?","options":["3.5 hours","4.5 hours","5.5 hours","9 hours"],"correct":1,"exp":"La regla básica del tacógrafo prohíbe conducir más de 4.5 horas seguidas. Tras este tiempo, es obligatoria una pausa de 45 minutos."},{"q":"When a 45-minute driving break is split into two parts under EU rules, what is the correct order and minimum duration of these breaks?","options":["First break at least 30 mins, second break at least 15 mins","First break at least 15 mins, second break at least 30 mins","Two equal breaks of 22.5 mins","First break at least 20 mins, second break at least 25 mins"],"correct":1,"exp":"Si fraccionas la pausa de 4.5h, la ley exige estrictamente que el primer descanso sea de al menos 15 minutos y el segundo de al menos 30 minutos, SIEMPRE en ese orden."},{"q":"Under EU drivers\u0027 hours rules, what is the maximum permitted weekly driving time?","options":["45 hours","48 hours","56 hours","90 hours"],"correct":2,"exp":"El tiempo máximo que un chófer puede pasar al volante (conduciendo) en una única semana es de 56 horas."},{"q":"Under EU drivers\u0027 hours rules, what is the maximum accumulated driving time allowed in any TWO consecutive weeks?","options":["90 hours","100 hours","112 hours","56 hours"],"correct":0,"exp":"Aunque en una semana puedes conducir 56 horas, la suma total de horas de conducción en dos semanas consecutivas nunca puede superar las 90 horas."},{"q":"What is the regular daily rest period a driver must take in a 24-hour period under EU rules?","options":["9 hours","11 hours","12 hours","45 hours"],"correct":1,"exp":"El descanso diario normal (ininterrumpido) que debe tomar un conductor dentro de un periodo de 24 horas es de 11 horas."},{"q":"How often must a digital tachograph system in a commercial vehicle be recalibrated and inspected by an authorized workshop?","options":["Every 6 months","Every 1 year","Every 2 years","Every 5 years"],"correct":2,"exp":"Los tacógrafos digitales deben pasar una revisión y calibración oficial en un taller autorizado cada 2 años."},{"q":"Which driving licence category is required to drive a minibus designed to carry up to 16 passengers in addition to the driver?","options":["Category B","Category C1","Category D1","Category CE"],"correct":2,"exp":"Como vimos antes en la teoría, la licencia D1 es la categoría específica para minibuses (entre 9 y 16 asientos)."},{"q":"Who bears the immediate daily responsibility for conducting a pre-journey walkaround inspection of a commercial passenger vehicle?","options":["The Transport Manager","The Workshop Mechanic","The Driver","The RSA Inspector"],"correct":2,"exp":"El conductor es el principal responsable de realizar el chequeo visual diario (walkaround check) antes de arrancar el vehículo para asegurar que es seguro para circular."},{"q":"In passenger transport scheduling, what does the term \u0027Headway\u0027 mean?","options":["The maximum speed of a coach on a motorway","The time interval between consecutive vehicles operating on the same route","The total distance of a bus journey","The height clearance required under a bridge"],"correct":1,"exp":"\"Headway\" o frecuencia es el tiempo que transcurre entre el paso de dos autobuses consecutivos de la misma línea (por ejemplo, un bus cada 15 minutos)."},{"q":"In the service marketing mix (7 Ps), which \u0027P\u0027 relates to the physical environment and tangible elements where the service is delivered?","options":["Process","People","Physical Evidence","Promotion"],"correct":2,"exp":"\"Physical Evidence\" (Evidencia física) abarca todo lo que el cliente puede ver o tocar, como la limpieza del autobús, el uniforme del conductor o el diseño de los billetes."},{"q":"What document must be carried on board an international coach performing an occasional service under the Interbus Agreement or EU rules?","options":["A Waybill / Journey Form (Feuille de Route) book","A Carnet de Passages","A CMR consignment note","An NTA Local Service Permit"],"correct":0,"exp":"Para los servicios internacionales ocasionales (como un tour turístico), es obligatorio llevar a bordo la hoja de ruta o Waybill (Feuille de Route)."},{"q":"What is the maximum compensation the Workplace Relations Commission (WRC) can award for an unfair dismissal claim based on financial loss?","options":["6 months\u0027 remuneration","1 year\u0027s remuneration","2 years\u0027 remuneration (104 weeks)","5 years\u0027 remuneration"],"correct":2,"exp":"El tribunal laboral de la WRC puede sancionar a una empresa a pagar hasta un máximo de 2 años de salario (104 semanas) al trabajador si se demuestra que el despido fue improcedente y causó pérdida financiera."},{"q":"Which form must be submitted annually by a limited company to the Companies Registration Office (CRO)?","options":["Form A1","Annual Return (Form B1)","VAT3 Return","P45 Form"],"correct":1,"exp":"El Formulario B1 (Annual Return) es el documento anual de obligado cumplimiento que toda empresa debe presentar en el registro mercantil (CRO)."},{"q":"What is a major advantage of operating a transport business as a Private Limited Company (LTD) compared to a Sole Trader?","options":["The company pays no taxes","Shareholders have limited liability for company debts","Directors are exempt from EU drivers\u0027 hours rules","No annual financial returns are required"],"correct":1,"exp":"La principal ventaja de constituirse como sociedad limitada (LTD) es que los socios no responden con su patrimonio personal ante las deudas de la empresa (responsabilidad limitada)."},{"q":"In Ireland, what is the standard rate of VAT applicable to most taxable goods and services?","options":["13.5%","23%","0%","9%"],"correct":1,"exp":"La tasa estándar del Impuesto sobre el Valor Añadido (IVA/VAT) en Irlanda es del 23%."},{"q":"An accident at work resulting in an employee being absent from work for more than how many consecutive days must be reported to the Health and Safety Authority (HSA)?","options":["1 day","3 consecutive days","7 consecutive days","14 consecutive days"],"correct":1,"exp":"La ley de salud laboral exige que cualquier accidente que cause una baja médica superior a 3 días consecutivos (sin contar el día del accidente) debe reportarse a la HSA."}]},
"107": { title: "Simulacro 7 - Drivers\u0027 Hours, Speed \u0026 International", questions: [{"q":"Under EU drivers\u0027 hours rules, what is the maximum permitted daily driving time?","options":["8 hours, which can never be exceeded","9 hours, which can be extended to 10 hours twice in any week","10 hours every single day of the week","12 hours including other work"],"correct":1,"exp":"El tiempo máximo de conducción diario es de 9 horas, el cual puede ampliarse excepcionalmente hasta 10 horas un máximo de dos veces por semana."},{"q":"Under EU rules, what is the maximum continuous driving period allowed before a mandatory break must be taken?","options":["3 hours","4 hours","4.5 hours","6 hours"],"correct":2,"exp":"Tras un máximo de 4 horas y media de conducción continua, el conductor debe realizar una pausa ininterrumpida de al menos 45 minutos."},{"q":"When a 45-minute driving break is split into two parts under EU rules, what is the correct sequence of durations?","options":["30 minutes followed by 15 minutes","15 minutes followed by 30 minutes","Two equal parts of 22.5 minutes","20 minutes followed by 25 minutes"],"correct":1,"exp":"Si se fracciona la pausa, el primer tramo debe ser de al menos 15 minutos y el segundo de al menos 30 minutos, obligatoriamente en ese orden."},{"q":"What is the maximum weekly driving time permitted under EU rules?","options":["45 hours","48 hours","56 hours","90 hours"],"correct":2,"exp":"El límite máximo de tiempo al volante en una semana aislada es de 56 horas."},{"q":"What is the maximum accumulated driving time allowed in any two consecutive weeks?","options":["56 hours","90 hours","112 hours","120 hours"],"correct":1,"exp":"En dos semanas consecutivas de conducción, el total acumulado no puede superar las 90 horas (por ejemplo, 56 horas en la semana 1 y 34 horas en la semana 2)."},{"q":"What is the standard regular daily rest period required within a 24-hour period?","options":["9 hours","11 hours","12 hours","24 hours"],"correct":1,"exp":"El descanso diario normal debe ser de al menos 11 horas continuas (puede reducirse a 9 horas un máximo de tres veces por semana)."},{"q":"How often must an operator download data from a driver\u0027s digital tachograph card?","options":["Every 14 days","Every 21 days","Every 28 days","Every 3 months"],"correct":2,"exp":"Las empresas están obligadas a volcar y respaldar los datos de la tarjeta del conductor al menos cada 28 días para evitar sobreescritura de datos."},{"q":"How long must a transport undertaking retain completed tachograph charts, printouts, and downloaded digital files?","options":["6 months","12 months","2 years","5 years"],"correct":1,"exp":"Los registros físicos y digitales del tacógrafo deben conservarse ordenadamente en la empresa durante un periodo mínimo de 12 meses (1 año)."},{"q":"At what maximum interval must a digital tachograph system be inspected and recalibrated by an approved workshop?","options":["Every 1 year","Every 2 years","Every 3 years","Every 5 years"],"correct":1,"exp":"Los tacógrafos digitales requieren una revisión de calibración oficial en un taller autorizado cada 2 años."},{"q":"If a digital tachograph breaks down on a journey, how long does the operator have to get it repaired if the vehicle cannot return to base?","options":["24 hours","48 hours","1 week from the breakdown","1 month from the breakdown"],"correct":2,"exp":"Si el aparato falla y el vehículo no regresa a su base en el plazo de 1 semana, debe repararse de inmediato en ruta."},{"q":"When requested by roadside enforcement authorities (like the RSA or Gardaí), how many days of records must a driver be able to produce?","options":["Current day and the previous 7 days","Current day and the previous 14 days","Current day and the previous 28 days","Current day and the previous 56 days"],"correct":2,"exp":"El conductor debe mostrar en la inspección los datos del día en curso y los 28 días anteriores (ampliado a 56 días en controles generales de normativa comunitaria de control). Nota: En las preguntas clásicas de test de este manual, el estándar de 28 días sigue muy presente para la tarjeta."},{"q":"Which document permits a coach to travel at speeds up to 100 km/h on motorways in Germany?","options":["Community Licence","Tempo 100 certificate","Eurovignette","Vitesse 100 permit"],"correct":1,"exp":"El certificado especial Tempo 100 es la homologación técnica alemana que permite a un autocar circular a 100 km/h en autopistas."},{"q":"What is the typical general speed limit for commercial vehicles in built-up (urban) areas across many European countries?","options":["30 km/h","50 km/h","60 km/h","80 km/h"],"correct":1,"exp":"El límite estándar genérico en zonas urbanas o poblados en Europa es de 50 km/h."},{"q":"Which statement best summarises Irish motorway speed limits for buses and coaches?","options":["All buses and coaches are limited to a maximum of 100 km/h","Buses are limited to 80 km/h on all roads","Coaches may travel at 120 km/h like cars","Standing passenger buses can travel at 110 km/h"],"correct":0,"exp":"En Irlanda, los autobuses y autocares (categoría D) tienen un límite máximo de velocidad en autopista fijado legalmente en 100 km/h."},{"q":"In France, what does the road sign stating \"équipements spéciaux obligatoires\" instruct drivers to do?","options":["Give way to traffic approaching from the right","Turn back due to road closure","Fit snow chains to the vehicle tyres","Switch off headlights in tunnels"],"correct":2,"exp":"Esta señal de montaña francesa indica la obligatoriedad absoluta de colocar cadenas para la nieve o neumáticos de invierno adecuados."},{"q":"Which of the following countries requires drivers engaged in international transport or tours to carry proof of minimum wage compliance (such as the Loi Macron or MiLoG)?","options":["Germany and France","Ireland and UK only","Spain only","Poland exclusively"],"correct":0,"exp":"Países como Alemania (MiLoG) y Francia (Loi Macron) exigen a las empresas extranjeras aportar documentación que pruebe que el chófer cobra al menos el salario mínimo de dichos países durante su tránsito."},{"q":"Which international agreement governs the main network of international traffic arteries (E-roads)?","options":["AETR","AGR (European Agreement on Main International Traffic Arteries)","Interbus Agreement","Schengen Agreement"],"correct":1,"exp":"El acuerdo europeo AGR regula la denominación y características técnicas de la red de carreteras principales internacionales (las famosas rutas \"E\")."},{"q":"What is the primary purpose of the Schengen Agreement regarding travel?","options":["To standardise commercial vehicle fuel taxes","To eliminate systematic passport controls at internal borders between participating countries","To regulate driver tachograph working hours","To set vehicle dimensions and weights"],"correct":1,"exp":"El espacio Schengen abolió los controles fronterizos en las fronteras interiores de los estados firmantes para facilitar el libre tránsito de personas."},{"q":"Which document is absolutely essential for an Irish operator performing international scheduled or regular passenger transport services within the EU?","options":["National Transport Authority Local Permit","Community Licence and Route Authorisation","CMR consignment note","National CVRT pass sheet"],"correct":1,"exp":"Para operar servicios regulares internacionales de pasajeros en la UE se requiere obligatoriamente la Licencia Comunitaria y una autorización oficial de ruta."},{"q":"What is \u0027Cabotage\u0027 in the context of international passenger transport?","options":["Transporting goods across maritime borders without customs","Performing temporary domestic passenger transport services within another EU Member State by a non-resident carrier","Operating a transport business without a registered office","Transporting employees to work in company-owned vehicles"],"correct":1,"exp":"El cabotaje consiste en realizar servicios de transporte nacional de forma temporal dentro de otro país de la Unión Europea distinto al de origen de la empresa."},{"q":"What is the maximum duration permitted for a \"Closed Door Tour\" (occasional international service where the same group travels together)?","options":["7 days","14 days","30 days","90 days"],"correct":2,"exp":"Los tours cerrados (Closed Door Tours) bajo las normativas de servicios ocasionales internacionales tienen un límite máximo de duración de 30 días continuos."},{"q":"From which organization must an Irish operator obtain official Waybills (Journey Forms / Feuille de Route) for international occasional passenger services?","options":["The Road Safety Authority (RSA)","The National Transport Authority (NTA)","The Revenue Commissioners","An Garda Síochána"],"correct":1,"exp":"En Irlanda, la NTA es la autoridad competente que suministra los libros oficiales de hojas de ruta (waybills) para los viajes ocasionales internacionales."},{"q":"Which of the following mountain tunnels provides a direct road link between France and Italy?","options":["Gotthard Tunnel","Brenner Pass","Mont Blanc Tunnel","Eurotunnel"],"correct":2,"exp":"El túnel del Mont Blanc (y el de Fréjus) conecta directamente las redes de carreteras de Francia e Italia a través de los Alpes."},{"q":"An Irish driver would need a visa or entry clearance to drive into which of the following countries?","options":["France","Ukraine","Germany","Spain"],"correct":1,"exp":"Al no formar parte de la Unión Europea ni del espacio Schengen comunitario, Ucraina exige visado y trámites fronterizos especiales a los conductores profesionales externos."},{"q":"When crossing an international border with customs control channels, what does entering the \u0027Green Channel\u0027 signify?","options":["Carrying goods subject to heavy import tariffs","Transporting hazardous materials","Having nothing to declare that is subject to duty, tax, or restrictions","Carrying cash in excess of €50,000"],"correct":2,"exp":"El canal verde en las aduanas está destinado a los viajeros o transportes que no transportan mercancías sujetas a impuestos ni restricciones de declaración."},{"q":"Under EU drivers\u0027 hours rules, what is the definition of a \u0027Break\u0027?","options":["Any period of time spent sleeping in a sleeper cab","Any period during which a driver may not carry out any driving or other work, used exclusively for recuperation","Time spent doing office paperwork for the transport manager","Driving at speeds under 30 km/h in city traffic"],"correct":1,"exp":"Una pausa (break) es un intervalo de tiempo en el que el conductor no puede realizar ninguna tarea de conducción ni otro trabajo, destinado única y exclusivamente a su descanso."},{"q":"Can a driver take their mandatory daily or weekly rest period inside a moving vehicle?","options":["Yes, if they are sleeping on a proper mattress","Yes, provided the second driver is steering","No, a regular daily or weekly rest period cannot be taken in a moving vehicle","Yes, if operating under emergency exemptions"],"correct":2,"exp":"Está prohibido terminantemente tomar los periodos de descanso diario o semanal mientras el vehículo está en movimiento."},{"q":"Under EU rules, what is the minimum duration of a \u0027Reduced Weekly Rest\u0027 period?","options":["9 hours","11 hours","24 hours","45 hours"],"correct":2,"exp":"El descanso semanal reducido permite acortar el descanso hasta un mínimo ininterrumpido de 24 horas (exigiendo compensaciones posteriores)."},{"q":"If a multi-manning crew operates a coach, what is the maximum continuous driving period before a changeover or break under EU rules?","options":["3 hours","4.5 hours","9 hours","10 hours"],"correct":1,"exp":"Incluso en régimen de tripulación múltiple (multi-manning), el límite de conducción continua antes de una pausa de 45 minutos sigue siendo de 4.5 horas para cada conductor."},{"q":"What is the main objective of the AETR agreement?","options":["To harmonize vehicle weights and dimensions across the globe","To apply international rules equivalent to EU tachograph and drivers\u0027 hours regulations for countries outside the EU","To regulate air quality standards in European cities","To provide free medical insurance for international drivers"],"correct":1,"exp":"El acuerdo AETR regula las horas de conducción y descanso de las tripulaciones de vehículos que realizan transporte internacional por carretera en los países extracomunitarios firmantes, alineándolos con la normativa UE."},{"q":"What is the minimum age requirement to drive a regular scheduled bus route exceeding 50 km with a full Category D licence (assuming completion of Driver CPC)?","options":["18 years old","21 years old","23 years old","24 years old"],"correct":1,"exp":"Con la cualificación del Driver CPC inicial, la edad mínima para conducir autobuses de categoría D en rutas regulares de más de 50 km se reduce a los 21 años (en lugar de los 24 generales)."},{"q":"Which authority in Ireland is responsible for issuing Driver CPC Qualification Cards?","options":["National Transport Authority (NTA)","Road Safety Authority (RSA)","Department of Transport","Revenue Commissioners"],"correct":1,"exp":"La RSA gestiona y expide las tarjetas de cualificación del conductor (Driver CPC) en Irlanda."},{"q":"How often must professional drivers undergo periodic CPC training (Continuing Training) to maintain their vocational qualification?","options":["Every 1 year","Every 3 years","Every 5 years","Every 10 years"],"correct":2,"exp":"El reciclaje del Driver CPC exige completar 35 horas de formación periódica cada 5 años."},{"q":"Under what circumstances is a driver exempt from the EU drivers\u0027 hours rules while operating a passenger vehicle?","options":["If driving on a motorway at night","If operating vehicles used for scheduled passenger services where the route length does not exceed 50 km","If carrying passengers on international tours","If the vehicle is painted red"],"correct":1,"exp":"Los servicios regulares de pasajeros cuya ruta no supere los 50 kilómetros están exentos de cumplir el Reglamento europeo 561/2006 de tiempos de conducción y descanso."},{"q":"What type of tachograph recording equipment must be fitted in all newly registered commercial vehicles since June 2019 / August 2023?","options":["Analogue paper charts only","Smart Tachographs (version 1 and version 2)","Magnetic cassette tapes","Digital tachographs without GPS tracking"],"correct":1,"exp":"Los vehículos nuevos de transporte comercial deben incorporar obligatoriamente tacógrafos inteligentes de última generación con geolocalización vía satélite."},{"q":"Who is legally responsible for ensuring that drivers comply with EU rules on driving hours and rest periods?","options":["The vehicle manufacturer","The transport undertaking (operator) and the driver","The roadside traffic warden","The fuel station attendant"],"correct":1,"exp":"La responsabilidad legal recae conjuntamente sobre ambas partes: el operador (empresa) debe organizar el trabajo de forma legal y supervisarlo, y el conductor debe cumplirlo de manera individual."},{"q":"What is the maximum permitted weight on a single non-driving steering axle for standard heavy commercial vehicles in Ireland?","options":["6 tonnes","7.5 tonnes","10 tonnes","11.5 tonnes"],"correct":2,"exp":"El límite de peso legal por defecto para un eje de dirección simple no motorizado en Irlanda suele ser de 10 toneladas (y de hasta 11.5 toneladas para ejes motores simples en determinadas configuraciones)."},{"q":"What is the primary purpose of vehicle \u0027Plating\u0027?","options":["To determine the insurance premium category","To certify the maximum design weights and maximum permissible weights authorised for the vehicle","To record the exact purchase price of the chassis","To show the name of the vehicle\u0027s financial leasing company"],"correct":1,"exp":"La placa de características o Plating oficial certifica los pesos máximos autorizados y de diseño permitidos legalmente para el vehículo."},{"q":"When an operator replaces an existing vehicle on their licence, within what timeframe must they notify the licensing authority (Department of Transport)?","options":["Immediately / within statutory notification windows specified in licensing conditions","Within 5 years","Only when renewing the operator licence","There is no requirement to notify vehicle changes"],"correct":0,"exp":"Cualquier cambio o modificación en la composición de la flota vinculada a la licencia debe notificarse a la autoridad competente dentro de los plazos reglamentarios establecidos."},{"q":"What is a \u0027Multimanning\u0027 operation in relation to drivers\u0027 hours?","options":["Operating a vehicle with two or more drivers available for driving during each period of driving between two consecutive daily rest periods, or between a daily rest period and a weekly rest period","Having mechanics travel on board every bus","Using multiple transport managers for one branch","Sharing a single tachograph card between three drivers"],"correct":0,"exp":"La tripulación múltiple (multi-manning) ocurre cuando hay al menos dos conductores en el vehículo para turnarse en la conducción durante los periodos de descanso diario."}]}
};
